-- 码上记 CodeInterview · 题库扩容批次（500 道）
-- 前置：已执行 db/init.sql 与 db/migration-v1-expansion.sql。
-- 幂等：固定 id 401-900 + INSERT IGNORE，重复执行不产生重复行；
--       question_tag 靠 uk_question_tag(question_id, tag_id) 幂等。
-- 范围：只 INSERT IGNORE `question`（12 列）与 `question_tag`（2 列），
--       不改表结构、不含 UPDATE/DELETE，不触碰存量数据。
-- 执行："D:\Develop\MySQL\MySQLServer8.0\bin\mysql.exe" -uroot -p \
--         --default-character-set=utf8mb4 -e "source .../db/seed-extra-500.sql"
-- ============================================================
USE `codeinterview`;

   `view_count`, `practice_count`, `published_at`, `created_by`)
VALUES
  (401, 1, 'LinkedHashMap 的 accessOrder 与 LRU 缓存实现', '`LinkedHashMap` 继承自 `HashMap`，内部额外维护一条双向链表。请说明：\n\n1. 插入顺序与访问顺序分别如何开启；\n2. `afterNodeAccess`、`afterNodeInsertion` 两个钩子何时被 `HashMap` 回调；\n3. 基于它实现 LRU 缓存的关键一行代码，以及为什么它默认线程不安全。\n\n```java\nMap<String, Integer> cache = new LinkedHashMap<>(16, 0.75f, true);\n```', '**结论**：`LinkedHashMap` 的链表默认按插入顺序串联；构造参数 `accessOrder=true` 时，每次 `get` 或 `put` 命中已有 key 都把该节点移到链表尾部，于是链表头就是最久未使用元素，天然构成 LRU 顺序。\n\n**两个钩子的分工**：\n\n| 钩子 | 触发时机 | 默认行为 |\n|---|---|---|\n| `afterNodeAccess` | 访问到已存在的节点 | accessOrder 为 true 时把节点移到尾部 |\n| `afterNodeInsertion` | 插入新节点之后 | 回调 `removeEldestEntry`，返回 true 就删表头 |\n\n`HashMap` 在 `getNode`、`putVal` 里显式调用这些空方法，`LinkedHashMap` 重写它们，这是典型的模板方法扩展点。\n\n**最小 LRU 实现**：继承并重写 `removeEldestEntry`，容量超过阈值就返回 true，插入路径自动淘汰表头节点，无需自己排序或扫描。\n\n**注意**：`LinkedHashMap` 非线程安全，`get` 在 accessOrder 模式下会修改链表结构，并发下必须外加锁或用 `Collections.synchronizedMap` 包装；高并发缓存应考虑 Caffeine 或 `ConcurrentHashMap` 加淘汰策略。遍历时同样有 fail-fast 风险。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 1 MINUTE), 1),
  (402, 1, 'TreeMap 的红黑树实现与 NavigableMap 区间视图', '`TreeMap` 的底层数据结构与排序依据是什么？`put`、`get`、`ceilingKey` 的时间复杂度如何？`subMap` 返回的视图修改会不会影响原 map？请说明它与 `HashMap` 的选型边界。', '**结论**：`TreeMap` 基于**红黑树**（自平衡二叉搜索树），按 key 的 `compareTo` 或构造传入的 `Comparator` 维持有序，单点操作 `put`、`get`、`remove`、`ceilingKey` 均为 O(log n)；`HashMap` 平均 O(1) 但无序。\n\n**红黑树要点**：节点非红即黑，根与叶子（NIL）为黑，红节点的子节点必黑，任一节点到其叶子的黑节点数相同。插入删除后靠左旋、右旋与变色恢复平衡，最长路径不超过最短路径两倍，因此树高稳定在 O(log n)。\n\n**区间视图**：`subMap(from, to)`、`headMap`、`tailMap` 返回**视图**而非拷贝，读写会穿透到原 map，遍历成本与区间大小成正比。视图受原 map 的 modCount 校验，外部结构性修改后再用视图会抛 `ConcurrentModificationException`。\n\n**选型**：需要排序、范围查询、取前驱后继、维护排行榜时用 `TreeMap`；只做键值查找用 `HashMap`。`TreeMap` 不允许 null key（自然序比较会 NPE），可用 Comparator 放宽。\n\n**并发场景**：对应 `ConcurrentSkipListMap`，用跳表换红黑树，代价是 `size()` 需要遍历统计、返回值可能不精确。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 2 MINUTE), 1),
  (403, 1, 'CopyOnWriteArrayList 的写时复制与迭代器快照', '`CopyOnWriteArrayList` 为什么能做到遍历时不加锁、也不抛 `ConcurrentModificationException`？它的写操作代价是什么？请说明适合与不适合的场景，以及与 `Collections.synchronizedList` 的差异。', '**结论**：写操作（`add`、`set`、`remove`）在 `ReentrantLock` 保护下复制整个数组，改完再替换内部 `array` 引用；读操作无锁，直接读当前数组。因此迭代器拿到的是创建时刻数组的**快照**，遍历期间的写对它不可见，也就不会 fail-fast。\n\n**代价**：每次写都要 `Arrays.copyOf`，内存与时延随元素数量线性增长；写期间瞬时占用两倍内存，容易触发 GC；只保证最终一致，读不到刚写入的数据。\n\n**适用**：读多写极少、元素个数小、白名单、监听器列表、配置快照这类场景。\n\n**不适用**：频繁写或大集合，应改用 `ConcurrentHashMap` 按 key 分段，或 `ConcurrentLinkedQueue` 承担队列语义。\n\n**与 synchronizedList 对比**：后者读写都加同一把锁，遍历必须由调用方自己 `synchronized (list)` 保护，否则仍可能抛异常；`CopyOnWriteArrayList` 把锁限制在写路径，读吞吐明显更好。\n\n**陷阱**：迭代器的 `remove`、`set` 都会抛 `UnsupportedOperationException`；`addIfAbsent` 虽线程安全，但仍是 O(n) 扫描，不适合大集合。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 3 MINUTE), 1),
  (404, 1, 'ArrayDeque 的环形数组实现，以及它为何比 LinkedList 更适合做栈', '`ArrayDeque` 用什么结构实现双端队列？`head`、`tail` 指针如何移动、何时扩容？为什么官方推荐用它替代 `Stack` 和 `LinkedList` 作为栈与队列？为什么它不允许 null 元素？', '**结论**：`ArrayDeque` 用**循环数组**（容量为 2 的幂）加 `head`、`tail` 两个下标实现双端操作，两端插入删除均摊 O(1)，且不为每个元素创建节点对象，缓存局部性远好于 `LinkedList`。\n\n**下标移动**：`head = (head - 1) & (length - 1)`、`tail = (tail + 1) & (length - 1)`，用位与代替取模，因此容量必须保持 2 的幂；扩容时 `doubleCapacity` 把两段数据复制到新数组并重置 `head = 0`。\n\n**为什么推荐**：\n\n| 对比项 | ArrayDeque | LinkedList |\n|---|---|---|\n| 内存 | 连续数组，无节点开销 | 每个元素一个 Node，三个引用 |\n| 两端操作 | O(1) 且无对象分配 | O(1) 但有节点分配 |\n| 中间插入 | 不支持 | 定位仍要 O(n) |\n\n`Stack` 继承 `Vector`，方法全加 `synchronized`，单线程下纯属浪费；`ArrayDeque` 非线程安全但更快，并发场景用 `ConcurrentLinkedDeque` 或 `LinkedBlockingDeque`。\n\n**不允许 null**：null 被用作「队列为空」的哨兵返回值，若允许存 null，`poll()` 返回 null 时无法区分空队列与元素本身，因此直接禁止，`offer(null)` 抛 NPE。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 4 MINUTE), 1),
  (405, 1, 'HashSet 的去重原理与初始容量的正确算法', '`HashSet` 内部如何存储元素？`add` 返回 false 的条件是什么？要把 100 万个元素放进 `HashSet`，初始容量该给多少？为什么 `new HashSet<>(collection)` 的容量推导与 `new HashSet<>(int)` 不同？', '**结论**：`HashSet` 内部就是一个 `HashMap`，元素作 key，一个静态 `PRESENT` 对象作 value。`add(e)` 实际调用 `map.put(e, PRESENT)`，返回 false 表示该 key 已存在。\n\n**去重判定**：先比 hash（经扰动函数后定位桶），桶内再比 `==` 或 `equals`。因此自定义对象必须同时正确重写 `hashCode` 与 `equals`，否则两个逻辑相等的对象会被当成不同元素。\n\n**容量设置**：`HashMap` 的阈值是 `容量 × 0.75`，为避免扩容，初始容量应取 `预期元素数 / 0.75 + 1` 后向上取到 2 的幂。100 万元素约需 1.33M，向上取 2 的幂为 2097152（`1 << 21`）。直接 `new HashSet<>(1000000)` 会被 `tableSizeFor` 拉成 1048576，阈值仅 78 万，仍会扩容一次。\n\n**构造差异**：`HashSet(int)` 直接把参数当 `HashMap` 的容量；`HashSet(Collection)` 用 `max((int)(size / 0.75f) + 1, 16)` 反推，因为入参是元素个数而不是容量。\n\n**补充**：`HashSet` 无序，需要插入顺序用 `LinkedHashSet`，需要排序用 `TreeSet`；三者都非线程安全，并发场景用 `ConcurrentHashMap.newKeySet()`。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 5 MINUTE), 1),
  (406, 1, 'Collections.unmodifiableList 与 List.of 的不可变差异', '`Collections.unmodifiableList`、`List.of`、`Arrays.asList` 三者返回的列表有何本质区别？谁是视图、谁是拷贝？各自对 null、结构修改、序列化的支持如何？', '**结论**：`unmodifiableList` 是**只读视图**，原列表变了它跟着变；`List.of` 是**真正不可变**的独立实现，且拒绝 null；`Arrays.asList` 是**固定长度视图**，可 `set` 不可增删，底层就是原数组。\n\n| 特性 | unmodifiableList | List.of | Arrays.asList |\n|---|---|---|---|\n| 底层 | 包装原 list | 内部数组拷贝 | 直接引用原数组 |\n| 结构修改 | 抛 UnsupportedOperationException | 抛异常 | 抛异常 |\n| set | 抛异常 | 抛异常 | 允许，会写回原数组 |\n| null 元素 | 允许 | 抛 NPE | 允许 |\n| 原集合变化 | 可见 | 不可见 | 可见 |\n\n**坑点**：\n1. 对 `Arrays.asList` 的结果 `add` 会抛异常，想改结构必须包一层 `new ArrayList<>(...)`；\n2. `List.of` 的不可变是浅层的，元素对象自身仍可变，需要深拷贝自己实现；\n3. JDK 9 起 `List.copyOf` 在入参已是不可变列表时直接返回自身，零拷贝，做防御性拷贝优先用它；\n4. `Collections.emptyList()` 与 `List.of()` 都是共享单例，不要往里塞元素。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 6 MINUTE), 1),
  (407, 1, 'for-each 的编译展开与 Iterator.remove 的边界', '增强 for 循环编译后是什么样子？为什么遍历时调用集合自身的 `remove` 会抛异常，而 `Iterator.remove` 不会？`Iterable` 与 `Iterator` 的职责如何划分？请给出安全的批量删除写法。', '**结论**：for-each 编译后是 `Iterator it = c.iterator(); while (it.hasNext()) { E e = it.next(); ... }`，数组则展开为普通下标循环。它只能用于 `Iterable` 或数组。\n\n**为什么抛异常**：`ArrayList.Itr` 创建时保存 `expectedModCount = modCount`，每次 `next()` 校验两者是否相等。直接调用 `list.remove()` 让 `modCount++`，下一轮 `next()` 发现不等就抛 `ConcurrentModificationException`。\n\n**Iterator.remove 为何安全**：它删的是 `lastRet` 记录的元素，删完执行 `expectedModCount = modCount` 同步版本号，校验自然通过；但必须先 `next()` 再 `remove()`，否则 `lastRet = -1` 会抛 `IllegalStateException`。\n\n**安全写法**（按推荐度）：\n1. `list.removeIf(predicate)`，内部就是迭代器删除，最简洁；\n2. 显式 `Iterator` 加 `it.remove()`；\n3. 并发场景换 `CopyOnWriteArrayList`，或先收集待删元素再批量删除。\n\n**职责划分**：`Iterable` 表示「可被遍历」，只提供 `iterator()`；`Iterator` 承载遍历状态与删除能力。一个 Iterable 可产出多个独立 Iterator，因此不要把业务状态存在 Iterator 上，也不要在 for-each 里对同一集合做结构修改。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 7 MINUTE), 1),
  (408, 1, 'EnumSet 的位向量实现与 EnumMap 的数组存储', '`EnumSet` 为什么比 `HashSet` 快很多？它内部用什么表示元素集合？`EnumMap` 又如何做到常数级查找且天然有序？两者在使用上有哪些硬性限制？', '**结论**：`EnumSet` 用**位向量**表示集合，`RegularEnumSet` 里就是一个 `long` 的 `elements` 字段，每个枚举常量占一位，`add`、`contains` 都是一次位运算；`EnumMap` 用**按 ordinal 索引的数组**存值，查找即 `vals[key.ordinal()]`，天然有序且没有哈希计算。\n\n**为什么快**：操作是常数级位运算或数组下标访问，没有哈希与链表；内存极小，64 个枚举只占 8 字节；遍历按位扫描，顺序与枚举声明一致。\n\n**硬性限制**：\n1. 构造时必须显式传入枚举 Class（`EnumSet.noneOf(Color.class)`、`new EnumMap<>(Color.class)`），因为运行期需要枚举类型来分配位宽或数组长度；\n2. `EnumSet` 不允许 null 元素，`EnumMap` 不允许 null key 但允许 null value；\n3. 元素超过 64 个时 `EnumSet` 退化为 `JumboEnumSet`，用 `long[]` 数组承载。\n\n**典型用法**：权限位、已选标签、状态机允许的迁移集合；`EnumMap` 适合按枚举维度做统计计数或策略分派。两者都不是线程安全的，需要并发时自行加锁或用 `ConcurrentHashMap<Enum, V>`。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 8 MINUTE), 1),
  (409, 1, 'ConcurrentSkipListMap 的跳表结构与 TreeMap 的取舍', '既然有了 `TreeMap`，JDK 为什么还要提供 `ConcurrentSkipListMap`？跳表的结构与查找过程是怎样的？为什么并发容器选择跳表而不是红黑树？它的 `size()` 为什么也不精确？', '**结论**：`ConcurrentSkipListMap` 是**线程安全的有序 Map**，用**跳表**替代红黑树。红黑树插入删除后需要旋转，影响范围大，难以做无锁并发；跳表只改动局部指针，可用 CAS 完成，天然适合并发。\n\n**结构**：最底层链表包含全部元素；上层按概率（通常二分之一）抽取索引节点。查找从最高层头节点出发，能向右就向右，不能就降一层，期望 O(log n)，实现比红黑树简单很多，也更容易做范围查询。\n\n**对比 TreeMap**：\n\n| 维度 | TreeMap | ConcurrentSkipListMap |\n|---|---|---|\n| 线程安全 | 否 | 是，读无锁 |\n| 结构 | 红黑树 | 跳表 |\n| 空间 | 每节点固定 | 期望两倍指针开销 |\n| size | 精确 O(1) | 需遍历统计 |\n\n**size 不精确**：没有全局计数器，`size()` 遍历计数，并发期间结果只是近似值，且是 O(n) 操作，不要放在热点路径。\n\n**选型**：并发下需要有序视图、范围查询、`ceilingKey`、`floorKey` 时使用；单线程或可整体加锁且读多写少时，`TreeMap` 更省内存。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 9 MINUTE), 1),
  (410, 1, 'BlockingQueue 家族选型：Array、Linked、Synchronous 与 Priority', '`ArrayBlockingQueue`、`LinkedBlockingQueue`、`SynchronousQueue`、`PriorityBlockingQueue` 各自的结构与特性是什么？为什么 `newFixedThreadPool` 用 `LinkedBlockingQueue` 反而有 OOM 风险？`SynchronousQueue` 在什么场景下是正解？', '**结论**：四种队列的差别集中在**是否有界**、**锁的粒度**与**排序能力**上。\n\n| 队列 | 结构 | 容量 | 锁 | 特点 |\n|---|---|---|---|---|\n| ArrayBlockingQueue | 数组 | 必须指定 | 一把锁加两个 Condition | 有界、内存紧凑、可设公平 |\n| LinkedBlockingQueue | 链表 | 默认 Integer.MAX_VALUE | 存取两把锁 | 吞吐高，默认等于无界 |\n| SynchronousQueue | 无存储 | 0 | 栈或队列 | 直接移交，必须有人接 |\n| PriorityBlockingQueue | 二叉堆 | 无界 | 一把锁 | 按优先级出队 |\n\n**OOM 风险**：`newFixedThreadPool` 用无界 `LinkedBlockingQueue`，任务生产速度超过消费速度时队列无限增长直到 OOM；`maximumPoolSize` 也形同虚设，因为队列永远不满，线程数不会超过 core。\n\n**SynchronousQueue**：`newCachedThreadPool` 用它，提交即为任务寻找空闲线程或新建线程，适合短任务高吞吐；消费者不足时会不断建线程，必须配最大线程数限制。\n\n**实践**：生产环境用 `ArrayBlockingQueue` 或指定容量的 `LinkedBlockingQueue`，容量按「峰值速率 × 可接受延迟」估算，并配套拒绝策略与队列深度监控，绝不能让队列无界。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 10 MINUTE), 1),
  (411, 1, 'Arrays.asList 的三个经典陷阱', '`Arrays.asList` 返回的到底是什么类型？为什么 `add` 会抛 `UnsupportedOperationException`？为什么 `Arrays.asList(new int[]{1,2,3})` 的 size 是 1？`list.remove(1)` 又会发生什么？', '**结论**：`Arrays.asList` 返回的是 `java.util.Arrays` 的私有静态内部类 `ArrayList`，注意它不是 `java.util.ArrayList`。它持有原数组引用，**长度固定**，只支持 `set`，不支持增删。\n\n**三个陷阱**：\n1. **结构修改抛异常**：`add`、`remove`、`clear` 继承自 `AbstractList`，默认抛 `UnsupportedOperationException`。需要可变列表时写 `new ArrayList<>(Arrays.asList(...))`。\n2. **基本类型数组不会自动装箱**：泛型参数是 `T`，`int[]` 整体作为一个对象匹配 `T`，得到的是 `List<int[]>`，size 为 1。应使用 `IntStream.of(arr).boxed().collect(...)`。\n3. **与原数组共享存储**：`list.set(0, x)` 会写回原数组，反过来改原数组也会反映到列表，容易产生隐蔽副作用。\n\n**remove 的重载歧义**：`list.remove(1)` 走 `remove(int index)` 按下标删；要按值删除 `Integer` 必须写 `list.remove(Integer.valueOf(1))`。\n\n**替代**：JDK 9 起只读场景优先 `List.of(...)`，它做拷贝且拒绝 null；需要可变就显式 `new ArrayList<>()` 再 `addAll`。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 11 MINUTE), 1),
  (412, 1, 'Stream 的惰性求值与短路操作如何生效', 'Stream 的中间操作与终端操作分别是什么？为什么说中间操作是惰性的？`limit`、`findFirst`、`anyMatch` 这类短路操作能带来什么收益？一个 Stream 为什么只能消费一次？', '**结论**：Stream 由**数据源、零个或多个中间操作、一个终端操作**组成。中间操作只记录流水线（返回新的 Stream，底层是 `AbstractPipeline` 链表），不执行任何计算；只有终端操作触发时，才把整条链一次性遍历求值。\n\n**惰性的意义**：多次 `filter`、`map` 不会产生中间集合，遍历只发生一次，元素逐个流经整条链（循环融合），避免了多次分配与多次遍历。\n\n**短路操作**：`limit`、`takeWhile`、`findFirst`、`findAny`、`anyMatch`、`allMatch` 在满足条件时立即停止上游遍历。对无限流 `Stream.iterate` 或大集合，配合 `limit` 能把 O(n) 降为 O(k)，这是惰性最实际的收益。\n\n**只能消费一次**：Stream 内部有 `linkedOrConsumed` 标志，终端操作后置位，再次使用会抛 `IllegalStateException`。需要复用就把结果 `collect` 成集合，或传入 `Supplier<Stream>` 每次新建。\n\n**注意**：没有短路也没有 `limit` 的 `parallelStream` 全量处理，反而可能因切分与合并开销变慢；小集合不要并行。另外流内不要修改外部可变状态，否则并行下结果不可预期。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 12 MINUTE), 1),
  (413, 1, 'Collectors.toMap 的重复键异常与 groupingBy 的下游收集器', '`Collectors.toMap` 在 key 重复时会发生什么？如何规避？`groupingBy` 的三个重载分别是什么？如何用下游收集器一次完成分组再统计？请给出把 List 转成 Map 的安全写法。', '**结论**：`toMap` 的两参版本内部用 `HashMap::new` 加 `merge`，遇到重复 key 时抛 `IllegalStateException: Duplicate key`；三参版本必须显式提供合并函数，这才是生产写法。\n\n**安全写法**：\n```java\nMap<Long, User> m = list.stream().collect(\n    Collectors.toMap(User::getId, u -> u, (a, b) -> b));\n```\n合并函数决定保留前者还是后者。若 value 可能为 null，`toMap` 内部的 `merge` 会 NPE，应先过滤或改用 `forEach` 手工 put。\n\n**groupingBy 三个重载**：\n1. `groupingBy(classifier)`：默认下游是 `toList`；\n2. `groupingBy(classifier, downstream)`：如 `counting()`、`summingInt()`；\n3. `groupingBy(classifier, mapFactory, downstream)`：可指定 `TreeMap` 让 key 有序。\n\n**典型组合**：分组计数用 `groupingBy(..., counting())` 比 `toMap` 加 merge 更直观；分组取最大用 `groupingBy(..., collectingAndThen(maxBy(...), Optional::get))`。\n\n**注意**：`groupingBy` 结果默认 `HashMap`、value 是 `ArrayList`，对内存敏感的大分组应先 `filter`，或直接用 `EnumMap` 承载按枚举维度的统计。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 13 MINUTE), 1),
  (414, 1, 'Comparator 契约被违反时，为什么排序会抛异常', '`Collections.sort` 为什么有时抛 `IllegalArgumentException: Comparison method violates its general contract`？`Comparator` 必须满足哪三条契约？为什么 JDK 7 之后才暴露这个问题？给出一个典型的错误比较器与正确替代。', '**结论**：JDK 7 起对象排序改用 **TimSort**（归并加二分插入），它依赖比较结果的**传递性**来划分有序段。若比较器违反契约，TimSort 可能推断出矛盾区间并抛 `IllegalArgumentException`。JDK 6 的旧归并排序不做该检查，问题被掩盖了。\n\n**三条契约**：\n1. **反对称**：`compare(a, b) == -compare(b, a)`；\n2. **传递性**：`a < b` 且 `b < c` 则 `a < c`；\n3. **一致性**：比较结果不随调用次数变化，不能依赖外部可变状态。\n\n**典型错误**：用减法 `(a, b) -> a.getAge() - b.getAge()`，极端值时溢出导致正负翻转，破坏反对称；把 boolean 直接转 int；比较器里混用多个字段却没按字典序短路。\n\n**正确写法**：`Comparator.comparingInt(User::getAge).thenComparing(User::getName)`，或用 `Integer.compare`、`Long.compare` 显式比较，null 用 `Comparator.nullsFirst` 前置处理。\n\n**排查**：异常信息不含具体元素，可先缩小数据量二分定位；`reversed()` 要放在链尾，否则只反转最后一段。生产上还应加单测覆盖极端值，避免上线后才发现。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 14 MINUTE), 1),
  (415, 1, '排序稳定性、parallelStream 的顺序保证与 forEachOrdered', '什么是排序的稳定性？`Collections.sort` 稳定吗？`list.parallelStream().forEach` 输出顺序为什么固定不了？`forEachOrdered` 付出了什么代价？并行流里哪些操作会破坏顺序？', '**结论**：稳定性指相等元素在排序后的相对顺序保持不变。`Collections.sort` 与 `List.sort` 使用 TimSort，是**稳定**排序；`Arrays.sort` 对基本类型用双轴快排（稳定与否无意义，因为基本类型无相等语义区分），对对象数组用 TimSort（稳定）。\n\n**并行流的顺序**：`forEach` 明确不保证顺序，各分片完成即输出；`forEachOrdered` 会按源顺序收集再输出，代价是引入同步或额外缓冲，吞吐下降。\n\n**保序的操作**：`collect`、`reduce`、`toArray`、`findFirst` 在有序流上保持顺序；`findAny` 故意不保证，以便提前返回。\n\n**破坏顺序的来源**：\n1. 数据源本身无序，如 `HashSet.stream()`；\n2. 显式调用了 `unordered()`；\n3. 使用 `forEach` 而非 `forEachOrdered`；\n4. 在 `forEach` 里向 `ArrayList` 这类非线程安全集合 add，既乱序又可能丢数据。\n\n**实践**：并行流带副作用时要用线程安全容器或改用 `collect`；数据量小、逻辑简单时直接用串行流，切分与合并开销经常吃掉并行收益。需要稳定排序时也不要忘记比较器本身必须满足契约。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 15 MINUTE), 1),
  (416, 1, 'synchronized 的锁升级过程与偏向锁的废弃', '`synchronized` 在 HotSpot 中经历哪些锁状态？偏向锁、轻量级锁、重量级锁分别针对什么竞争场景？JDK 15 为什么默认废弃偏向锁？请说明 Mark Word 在升级过程中的变化。', '**结论**：锁状态依次为**无锁、偏向锁、轻量级锁、重量级锁**，正常情况下只能升级不能降级。设计目标是为不同竞争强度选择最小开销的实现。\n\n| 状态 | 适用场景 | 实现 |\n|---|---|---|\n| 偏向锁 | 只有一个线程反复进入 | Mark Word 记录线程 ID，后续进入无需 CAS |\n| 轻量级锁 | 多线程交替执行、无真正并发 | 栈上 Lock Record 加 CAS 让 Mark Word 指向它 |\n| 重量级锁 | 存在真实竞争 | 指向 ObjectMonitor，未抢到者 park 阻塞 |\n\n**Mark Word 变化**：无锁时存 hashCode 与分代年龄；偏向时存线程 ID 与 epoch；轻量级时存指向栈帧 Lock Record 的指针；膨胀后存指向 Monitor 的指针。最后两位锁标志位区分状态。\n\n**为什么废弃偏向锁**：撤销偏向需要 STW 并在 safepoint 遍历，维护成本高；现代应用大量使用线程池与并发容器，偏向命中率低；JEP 374 从 JDK 15 起默认关闭，最终移除，以降低 JVM 复杂度。\n\n**实践**：锁粒度要小，锁定对象用 `private final` 避免被外部复用；不要锁 String 常量或包装类缓存对象，它们可能被全局共享。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 16 MINUTE), 1),
  (417, 1, '对象头 Mark Word 的位布局与锁记录', '一个 Java 对象在内存里由哪几部分组成？64 位 JVM 下 `Mark Word` 的位布局如何随锁状态变化？为什么开启指针压缩后普通对象头仍是 12 字节？`identityHashCode` 与偏向锁为何互斥？', '**结论**：对象内存布局为**对象头、实例数据、对齐填充**。对象头包含 `Mark Word`（8 字节）与 `Klass Pointer`（开启 `-XX:+UseCompressedOops` 后 4 字节），数组对象再加 4 字节长度；因此普通对象头 12 字节，整体按 8 字节对齐补齐。\n\n**Mark Word 的 64 位布局（同一段空间按状态复用）**：\n\n| 状态 | 内容 |\n|---|---|\n| 无锁 | 25 位未用、31 位 hashCode、4 位分代年龄、锁标志 01 |\n| 偏向 | 54 位线程指针、2 位 epoch、分代年龄、偏向标志 101 |\n| 轻量级 | 62 位指向栈上 Lock Record 的指针、标志 00 |\n| 重量级 | 62 位指向 ObjectMonitor 的指针、标志 10 |\n| GC 标记 | 转发指针，标志 11 |\n\n**为什么互斥**：位宽只有 64 位，hashCode 与偏向线程 ID 共用同一段空间。一旦调用 `Object.hashCode()` 生成标识哈希并写入 Mark Word，就无法再存偏向线程 ID，只能撤销偏向，因此二者互斥，这也是偏向锁维护成本高的原因之一。\n\n**应用**：用 JOL 工具可打印真实布局；理解字段重排（long 与 double 优先、引用按 4 或 8 字节）有助于估算内存占用，也是分析伪共享与缓存行的基础。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 17 MINUTE), 1),
  (418, 1, '死锁的四个必要条件、jstack 定位与工程预防', '死锁产生的四个必要条件是什么？如何用 `jstack` 从线上 dump 中确认死锁？除了「按固定顺序加锁」，还有哪些工程化预防手段？`tryLock` 超时方案有什么风险？', '**结论**：死锁需同时满足**互斥、占有且等待、不可剥夺、循环等待**四个条件，破坏任意一个即可避免。\n\n**定位**：执行 `jstack <pid>` 把输出重定向到文件，末尾会打印 `Found one Java-level deadlock` 段落，列出互相等待的线程、各自持有的锁与等待的锁，以及对应代码行。也可用 `jcmd <pid> Thread.print`。死锁线程多为 BLOCKED 或 WAITING，CPU 通常不高，所以先看线程栈而不是先看 CPU。\n\n**预防手段**：\n1. **统一加锁顺序**：按主键排序后批量加锁，最有效；\n2. **减小锁范围**：事务内不做 RPC、不嵌套多层锁；\n3. **带超时的锁**：`ReentrantLock.tryLock(timeout)` 失败即回滚重试，把死锁转成可观测的失败；\n4. **单线程化**：热点资源用队列串行处理，从根上消除并发；\n5. 用 `ConcurrentHashMap` 的原子方法或无锁结构替代多把锁。\n\n**tryLock 的风险**：超时后业务处于中间状态，必须保证可回滚且幂等；没有退避的重试会形成活锁。\n\n**注意**：数据库死锁与 Java 层锁是两回事，前者由 InnoDB 检测并回滚，排查要看 `SHOW ENGINE INNODB STATUS`。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 18 MINUTE), 1),
  (419, 1, 'Java 线程六种状态与常见转换路径', '`Thread.State` 有哪六种状态？`BLOCKED` 与 `WAITING` 的区别是什么？调用 `sleep`、`wait`、`park`、`join` 分别进入哪种状态？为什么 `RUNNABLE` 里可能包含操作系统的阻塞？', '**结论**：六种状态为 `NEW`、`RUNNABLE`、`BLOCKED`、`WAITING`、`TIMED_WAITING`、`TERMINATED`。\n\n| 状态 | 触发 | 说明 |\n|---|---|---|\n| NEW | 创建未 start | 尚未分配系统线程 |\n| RUNNABLE | start 之后 | 就绪或运行中，含 IO 等待 |\n| BLOCKED | 等待进入 synchronized | 等的是监视器锁 |\n| WAITING | `wait()`、`join()`、`park()` | 无超时，必须被唤醒 |\n| TIMED_WAITING | `sleep(n)`、`wait(n)`、`join(n)`、`parkNanos` | 有超时，到时自动返回 |\n| TERMINATED | run 结束 | 不可再回到其他状态 |\n\n**BLOCKED 与 WAITING 的本质区别**：BLOCKED 是竞争 monitor 失败，锁释放后由 JVM 自动唤醒；WAITING 是主动让出并等待 notify、notifyAll 或 unpark，必须有人显式唤醒，否则可能永久挂起。\n\n**RUNNABLE 包含 IO 阻塞**：JVM 不区分就绪与运行，socket read 在操作系统层面阻塞时 Java 状态仍是 RUNNABLE，所以「RUNNABLE 很多」不能直接判定 CPU 打满，要结合 `top -Hp` 的实际占用。\n\n**实践**：`jstack` 的状态必须与堆栈一起看；`Thread.getState()` 只是瞬时快照，不能用于同步控制。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 19 MINUTE), 1),
  (420, 1, 'Object.wait/notify 与 Condition 的关系，以及虚假唤醒', '`wait` 为什么必须在 `synchronized` 块中调用？`wait` 与 `sleep` 的区别是什么？什么是虚假唤醒，为什么等待条件必须写在 `while` 循环里？`Condition.await` 相比 `wait` 有什么优势？', '**结论**：`wait` 会释放持有的 monitor 并进入该对象的等待集合，若不先持有锁就调用会抛 `IllegalMonitorStateException`；`sleep` 只让出 CPU，**不释放锁**，且是 `Thread` 的静态方法。\n\n**执行流程**：`wait` 释放锁，线程进入 WAITING，被 `notify` 或 `notifyAll` 唤醒后仍要**重新竞争锁**才能从 `wait` 返回，所以唤醒不等于立即执行。\n\n**虚假唤醒**：操作系统允许线程在没有 notify 的情况下被唤醒。若写成 `if (条件) wait();`，就会在条件仍不满足时继续执行，产生错误。正确写法：\n```java\nsynchronized (lock) {\n    while (!condition) lock.wait();\n    doWork();\n}\n```\n`notify` 只唤醒一个线程且唤醒哪个不确定，多条件场景应优先 `notifyAll`，否则可能唤醒错对象导致死等。\n\n**Condition 的优势**：一把 `ReentrantLock` 可以创建多个 `Condition`，把「队列非空」与「队列未满」分成两个等待队列，`signal` 时只唤醒相关线程，避免 `notifyAll` 的惊群；还支持 `awaitNanos`、`awaitUninterruptibly` 等精细控制。\n\n**注意**：`await` 同样要用 while 包裹，且必须在 `lock()` 与 `unlock()` 之间调用，解锁放在 finally。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 20 MINUTE), 1),
  (421, 1, '线程中断机制与 InterruptedException 的正确处理', '`interrupt()` 到底做了什么？为什么它不强制停止线程？捕获 `InterruptedException` 后为什么不应该吞掉？`isInterrupted` 与 `Thread.interrupted()` 有什么区别？如何在循环任务中正确响应中断？', '**结论**：`interrupt()` 只是给目标线程打一个**中断标志位**；若该线程正阻塞在 `sleep`、`wait`、`join`、`LockSupport.park` 或可中断 IO 上，JVM 会清除标志并抛 `InterruptedException`。它是**协作式**取消，不是强制终止，`Thread.stop` 早已废弃。\n\n**两个 API 的区别**：`isInterrupted()` 只读标志、不清除；`Thread.interrupted()` 是静态方法，读取并**清除**当前线程的标志，误用会让后续检测失效。\n\n**为什么不能吞异常**：catch 后只打日志而不恢复标志，上层再也无法感知取消信号，任务会继续跑到结束，线程池 `shutdownNow` 也会卡住。标准写法：\n```java\ncatch (InterruptedException e) {\n    Thread.currentThread().interrupt();\n    return;\n}\n```\n\n**循环任务**：每轮检查 `Thread.currentThread().isInterrupted()`；使用阻塞队列时 `take()` 本身可中断，无需轮询。\n\n**不可中断的阻塞**：`synchronized` 等锁、部分 `InputStream.read` 不响应中断，需要关闭底层资源，或改用 `Lock.lockInterruptibly()`、`InterruptibleChannel`。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 21 MINUTE), 1),
  (422, 1, 'CountDownLatch、CyclicBarrier 与 Phaser 的适用边界', '`CountDownLatch`、`CyclicBarrier`、`Semaphore`、`Phaser` 各自解决什么问题？`CountDownLatch` 为什么不能重置？`CyclicBarrier` 中一个线程 `await` 抛异常后其他线程会怎样？请给出选型依据。', '**结论**：\n\n| 工具 | 语义 | 可重用 | 底层 |\n|---|---|---|---|\n| CountDownLatch | 一个或多个线程等 N 个事件完成 | 否 | AQS 共享模式 |\n| CyclicBarrier | N 个线程互相等待到齐后一起继续 | 是，自动重置 | ReentrantLock 加 Condition |\n| Semaphore | 控制同时访问的许可数，可用于限流 | 是 | AQS 共享模式 |\n| Phaser | 多阶段、可动态注册注销的屏障 | 是 | 自定义计数 |\n\n**CountDownLatch 不可重置**：`state` 减到 0 后所有等待线程被唤醒，无法回到初始计数，需要复用就新建实例或改用 `CyclicBarrier`。典型用法是主线程等待初始化完成，或压测时同时发起。\n\n**CyclicBarrier 的异常语义**：某个线程在 `await` 时超时、被中断，或 barrierAction 抛异常，屏障会被标记为 broken，其余线程收到 `BrokenBarrierException`，必须 `reset()` 才能继续，这点最常被忽略。\n\n**Phaser 的适用**：分阶段任务且参与者数量会变化，用 `register` 与 `arriveAndDeregister` 动态调整。\n\n**选型**：一次性等待用 CountDownLatch，线程间互相等齐用 CyclicBarrier，限流用 Semaphore，阶段化用 Phaser。这些工具都不负责数据传递，结果共享要另配线程安全容器。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 22 MINUTE), 1),
  (423, 1, 'StampedLock 的乐观读与锁降级', '`StampedLock` 相比 `ReentrantReadWriteLock` 有什么优势？乐观读 `tryOptimisticRead` 的使用范式是什么？为什么它没有实现 `Lock` 接口、也不可重入？使用它最容易踩的坑有哪些？', '**结论**：`StampedLock` 提供**乐观读**：读之前取一个 stamp，读完后用 `validate(stamp)` 校验期间是否有写发生；若没有，说明读到的数据一致，全程不加锁、不写共享状态，读吞吐远高于读写锁。\n\n**标准范式**：\n```java\nlong stamp = lock.tryOptimisticRead();\nint x = fieldX; int y = fieldY;\nif (!lock.validate(stamp)) {\n    stamp = lock.readLock();\n    try { x = fieldX; y = fieldY; }\n    finally { lock.unlockRead(stamp); }\n}\n```\n关键点是**先读数据再 validate**，且读到的值赋给局部变量，避免校验后重读又变了。\n\n**与读写锁对比**：读写锁的读锁仍要 CAS 修改 state，高并发读存在竞争；乐观读完全不写。`StampedLock` 还支持持写锁时 `tryConvertToReadLock` 做锁降级。\n\n**三大坑**：不可重入，同一线程重复加锁会死锁；不支持 `Condition`，也不实现 `Lock` 接口；乐观读不响应中断，校验失败逻辑必须能安全回退重读。\n\n**适用**：读极多写极少且读操作短的场景，如坐标点、配置快照。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 23 MINUTE), 1),
  (424, 1, 'LongAdder 的分段累加与 AtomicLong 的适用边界', '`LongAdder` 为什么在高并发下比 `AtomicLong` 快？`Cell` 数组与 `base` 如何协作？`sum()` 为什么只是一个近似值？什么场景下应该坚持用 `AtomicLong`？', '**结论**：`AtomicLong` 所有线程 CAS 同一个 `value`，高并发下大量自旋失败；`LongAdder` 把计数分散到 `base` 与 `Cell[]` 数组，线程用 `Thread` 内的 probe 值哈希到不同 Cell 累加，竞争被摊薄，吞吐显著提升。\n\n**协作机制**：无竞争时直接 CAS `base`；一旦 CAS 失败就初始化 `Cell[]`（长度按 CPU 数扩容到 2 的幂），此后各线程更新各自的 Cell；`sum()` 把 `base` 与所有 Cell 求和。Cell 用 `@Contended` 填充，避免伪共享。\n\n**sum 为何近似**：求和过程中其他线程仍在更新 Cell，`sum()` 不是原子快照，只是瞬时近似值，并发更新时不能依赖它做精确判断。\n\n**何时用 AtomicLong**：需要 `compareAndSet` 这类读改写语义，如序列号、状态机；需要强一致的即时值；并发不高，`LongAdder` 的多 Cell 反而更占内存。\n\n**选型口诀**：只做累加统计（计数、耗时求和）用 `LongAdder`；需要原子读改写用 `AtomicLong`；复合操作二者都不够，仍要加锁或用 `ConcurrentHashMap` 的原子方法。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 24 MINUTE), 1),
  (425, 1, 'ReentrantReadWriteLock 的读写互斥规则与锁降级', '读写锁的四种获取组合中哪些能成功？为什么支持锁降级却不支持锁升级？`ReentrantReadWriteLock` 如何用一个 `state` 同时表示读锁与写锁？非公平模式下为什么可能出现写线程饥饿？', '**结论**：\n\n| 已持有 | 再申请 | 结果 |\n|---|---|---|\n| 读 | 读 | 允许 |\n| 读 | 写 | **不允许**，升级会死锁 |\n| 写 | 读 | 允许，即**锁降级** |\n| 写 | 写 | 允许，可重入 |\n\n**为什么不能升级**：读锁是共享的，多个线程同时持读锁时若都去申请写锁，会互相等待对方释放读锁，形成死锁；而降级由写锁持有者独占发起，先拿读锁再放写锁，安全且能保证释放写锁后数据不被别人改动。\n\n**state 拆分**：AQS 的 `int state` 高 16 位记录读锁持有总数，低 16 位记录写锁重入次数；另用 `ThreadLocalHoldCounter` 记录每个线程的读重入数，`getReadHoldCount` 靠它判断。\n\n**写线程饥饿**：非公平模式下读线程可以持续抢锁，写线程一直排队。`ReentrantReadWriteLock` 用「有写线程排队时阻塞新读锁」的启发式策略缓解，但仍不保证公平；高写比例场景应改用 `StampedLock` 或降低锁粒度。\n\n**常见误用**：在读锁里修改共享数据、锁对象非 final、忘记在 finally 解锁。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 25 MINUTE), 1),
  (426, 1, 'ThreadLocalRandom 为何比 Random 快，以及种子竞争的来源', '`Random` 在多线程下为什么性能差？`ThreadLocalRandom` 如何消除竞争？为什么它必须通过 `current()` 获取而不能自己 new？`nextInt(bound)` 有哪些边界坑？', '**结论**：`Random` 内部用**单个 AtomicLong 种子**，每次 `nextInt` 都要 CAS 更新种子；线程多时 CAS 大量失败并自旋，吞吐骤降。`ThreadLocalRandom` 把种子放进 `Thread` 的 `threadLocalRandomSeed` 字段，每个线程操作自己的种子，**完全无竞争**，也不需要 ThreadLocalMap 查找。\n\n**实现要点**：`current()` 返回每个线程复用的单例（该实例本身无状态），种子与 probe 存在 `Thread` 字段中，由 `VarHandle` 直接读写，避免对象分配。\n\n**为什么不能 new**：构造器私有，`new` 会抛 `UnsupportedOperationException`；即便能建，也拿不到线程私有的种子。\n\n**边界问题**：\n1. `nextInt(bound)` 要求 bound 为正，否则抛 `IllegalArgumentException`；\n2. `nextInt(origin, bound)` 左闭右开，取不到上界；\n3. 它**不是密码学安全**的随机源，生成 token、验证码要用 `SecureRandom`；\n4. 不要跨线程共享实例，虽然不会出错，但失去了线程私有种子的意义。\n\n**补充**：JDK 17 起 `RandomGenerator` 接口统一了算法族，`RandomGeneratorFactory` 可按名选择 LXM 等新算法。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 26 MINUTE), 1),
  (427, 1, 'ForkJoinPool 的工作窃取与 parallelStream 的共用池风险', '`ForkJoinPool` 的工作窃取是如何实现的？`ForkJoinTask` 的 `fork`、`join` 与普通线程池提交有何不同？为什么在 `parallelStream` 里做阻塞 IO 很危险？如何为并行流指定自定义池？', '**结论**：`ForkJoinPool` 每个工作线程维护一个**双端队列**，任务 `fork` 后压入自己队列头部，自己从头部取（LIFO，利于局部性）；空闲线程从**其他队列尾部**窃取任务（FIFO，减少冲突）。窃取让负载自动均衡，适合可递归分治的计算任务。\n\n**fork 与 join 语义**：`fork` 异步提交子任务，`join` 阻塞等待结果；`join` 在等待时会帮助执行其他任务，这是 work-stealing 的关键，而普通线程池的 `Future.get` 只是干等。\n\n**parallelStream 的风险**：它默认使用 `ForkJoinPool.commonPool()`，并行度约为 CPU 核数减一，且全 JVM 共享。若在流里做阻塞 IO（数据库、HTTP），公共池线程被占满，会拖垮所有使用公共池的功能，包括其他并行流。\n\n**正确做法**：为 IO 型并行任务显式建池，把任务提交进去再在内部用并行流，或改用 `CompletableFuture` 配独立线程池。\n\n**其他坑**：递归拆分阈值太小会因任务管理开销变慢；`ForkJoinTask` 里的异常被包装，需要 `getException` 或妥善捕获。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 27 MINUTE), 1),
  (428, 1, '虚拟线程的调度模型、pin 场景与迁移注意事项', 'JDK 21 的虚拟线程与平台线程有什么本质区别？它由谁调度、栈存在哪里？什么情况下会发生 pinning 导致载体线程被阻塞？把老代码迁移到虚拟线程需要注意什么？', '**结论**：平台线程一一对应操作系统线程，创建成本高、数量受内核限制；虚拟线程是 JVM 管理的**用户态线程**，由 `ForkJoinPool` 作为载体调度，栈以栈片段对象存在堆上，可随挂起恢复搬迁，因此能创建百万级。阻塞时（`sleep`、`BlockingQueue.take`、socket IO）会自动 unmount，释放载体线程。\n\n**pinning 场景**：在 `synchronized` 块内阻塞，JDK 21 会把载体线程一起钉住（JDK 24 起已大幅改善）；调用 native 方法或 `Object.wait`；类初始化过程中的阻塞。载体线程被钉住就退化成平台线程模型，数量一多照样耗尽。诊断加 `-Djdk.tracePinnedThreads=full`。\n\n**迁移注意**：\n1. 不要池化虚拟线程，它本就轻量，用完即弃；\n2. 避免用 `ThreadLocal` 缓存大对象，数量爆炸会放大内存；\n3. 限流靠 `Semaphore` 而不是线程池大小；\n4. CPU 密集型任务用虚拟线程无收益，反而增加调度开销。\n\n**判断标准**：IO 密集、高并发、每请求一线程的模型收益最大。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 28 MINUTE), 1),
  (429, 1, '线程池核心线程数如何估算，以及预热与回收的取舍', 'CPU 密集与 IO 密集任务的线程数该如何估算？`prestartAllCoreThreads` 解决什么问题？「核心线程默认不回收」会带来什么浪费？`allowCoreThreadTimeOut(true)` 又有什么副作用？', '**结论**：\n- **CPU 密集**：线程数约为核数加一，多出的一个用于在偶发缺页时顶替；\n- **IO 密集**：`核数 × (1 + 平均等待时间 / 平均计算时间)`，等待占九成时可取十倍核数，但必须配合有界队列与限流，否则只是把压力转给下游。\n\n以上只是起点，最终要靠压测找吞吐拐点：线程数增加后 QPS 不再上升、P99 开始变差，就是上限。\n\n**预热**：默认核心线程在任务到来时才逐个创建，流量突增时首批请求要承担线程创建开销。启动阶段调用 `prestartAllCoreThreads()` 一次建好，或用 `prestartCoreThread()` 逐个预热，可避免冷启动抖动。\n\n**核心线程不回收**：在 `allowCoreThreadTimeOut(true)` 之前，空闲核心线程常驻，池多时浪费内存与线程栈（每线程约 1MB）。开启后核心线程也按 `keepAliveTime` 回收，但流量波动时会反复创建销毁，需要权衡。\n\n**工程建议**：按业务隔离多个池、给线程起有意义的名字、监控活跃线程数与队列长度与完成任务数，并保留 `setCorePoolSize` 的动态调整能力。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 29 MINUTE), 1),
  (430, 1, 'ScheduledThreadPoolExecutor 的延时队列与任务异常吞掉问题', '`ScheduledThreadPoolExecutor` 内部用什么队列？`scheduleAtFixedRate` 与 `scheduleWithFixedDelay` 的差别是什么？为什么周期任务抛异常后会静默停止？如何避免？', '**结论**：它用 `DelayedWorkQueue`（基于二叉堆的延时队列），任务按触发时间排序，到点才被取出；核心线程数固定，`maximumPoolSize` 无意义，队列无界。\n\n**两种周期语义**：\n\n| 方法 | 下一次执行时间 |\n|---|---|\n| scheduleAtFixedRate | 上次开始时间加 period，任务超时会堆积并追赶 |\n| scheduleWithFixedDelay | 上次结束时间加 delay，不会追赶 |\n\n**异常被吞掉**：`ScheduledFutureTask.run` 里若任务抛异常，异常被存入 Future 而不会打印，且该周期任务**不再被重新调度**，表现为「跑几次就再也不跑了」，这是生产事故的常见来源。\n\n**规避手段**：\n1. 任务体内部 `try-catch Throwable` 兜底，绝不让异常逃逸；\n2. 用 `scheduleWithFixedDelay` 包一层自调度循环，失败后按退避重排；\n3. 保存返回的 `ScheduledFuture` 并检查 `isCancelled`，或统一用 `get()` 捕获 `ExecutionException` 感知失败；\n4. 更重的调度需求用 Quartz、XXL-JOB 等带失败重试与告警的方案。\n\n**注意**：`remove` 只对尚未执行的任务有效，`purge` 可清理已取消任务；关闭时同样要 `shutdown` 加 `awaitTermination`。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 30 MINUTE), 1),
  (431, 1, '线程池 shutdown 与 shutdownNow 的差异及优雅停机', '`shutdown`、`shutdownNow`、`awaitTermination` 各自的行为是什么？为什么 `shutdownNow` 返回的任务列表可能不完整？Spring 应用如何做到优雅停机不丢任务？', '**结论**：\n\n| 方法 | 是否接新任务 | 队列中任务 | 运行中任务 |\n|---|---|---|---|\n| shutdown | 否 | 继续执行完 | 不中断 |\n| shutdownNow | 否 | 取出并返回 | 尝试 interrupt |\n\n`shutdown()` 只是把状态置为 SHUTDOWN 并唤醒空闲线程；`shutdownNow()` 置为 STOP，`drainQueue` 把队列里的任务搬到返回值中，再逐个 `interrupt` 工作线程。被中断的任务是否真的停止取决于它是否响应中断，所以「立即停止」只是尽力而为。\n\n**列表可能不完整**：`drainQueue` 与并发提交存在竞态，已开始执行的任务不在返回列表里，`shutdownNow` 之后到达的任务直接被拒绝。\n\n**优雅停机范式**：\n```java\nexecutor.shutdown();\nif (!executor.awaitTermination(30, TimeUnit.SECONDS)) {\n    executor.shutdownNow();\n}\n```\n先拒绝新任务，给足时间跑完，超时再强制中断，并记录未完成任务用于补偿。\n\n**Spring Boot**：配置 `server.shutdown=graceful` 与 `spring.lifecycle.timeout-per-shutdown-phase`；自定义线程池在 `@PreDestroy` 里执行上述流程，避免容器关闭时任务被硬杀。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 31 MINUTE), 1),
  (432, 1, 'FutureTask 的状态机与 get 的阻塞原理', '`FutureTask` 内部有哪些状态、如何流转？`get()` 阻塞时线程在哪里等待、`cancel(true)` 又是如何生效的？为什么任务只执行一次？`Callable` 与 `Runnable` 在 `ThreadPoolExecutor` 中如何被统一处理？', '**结论**：`FutureTask` 同时实现 `Runnable` 与 `Future`，状态为 `NEW` 到 `COMPLETING` 到 `NORMAL`，或到 `EXCEPTIONAL`，另有 `CANCELLED`、`INTERRUPTED`、`INTERRUPTING`。状态存在 volatile int 字段中，`run()` 用 CAS 把 runner 从 null 置为当前线程，保证**任务体只执行一次**。\n\n**get 的阻塞**：`get()` 先查状态，未完成则把当前线程包装成 `WaitNode` 压入 `waiters` 栈，然后 `LockSupport.park`；任务结束时 `finishCompletion` 依次 unpark 所有等待者。带超时的 `get(timeout)` 用 `parkNanos`，超时抛 `TimeoutException`。\n\n**cancel(true)**：CAS 状态到 INTERRUPTING，调用 `runner.interrupt()`，再置为 INTERRUPTED；若任务已开始且不响应中断，任务仍会跑完，只是结果被丢弃。`cancel(false)` 不中断。\n\n**异常处理**：`run` 捕获 `Throwable` 存进 `outcome`，`get` 时以 `ExecutionException` 抛出，原始异常在 `getCause()` 里，这是最容易踩的坑。\n\n**统一处理**：`AbstractExecutorService.submit` 用 `RunnableAdapter` 把 `Runnable` 包装成 `Callable`，再交给 `newTaskFor` 生成 `FutureTask`。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 32 MINUTE), 1),
  (433, 1, '伪共享的成因、检测与 @Contended 填充', '什么是伪共享？为什么两个互不相关的 volatile 变量放在同一个对象里会互相拖慢？`@Contended` 注解如何解决？为什么它默认受限、需要额外启动参数才生效？', '**结论**：CPU 以**缓存行**（通常 64 字节）为单位在 L1、L2 间搬运数据。若两个线程分别写同一缓存行内的不同变量，缓存一致性协议（MESI）会让该行在核心间反复失效，造成实质串行化，这就是伪共享。\n\n**典型场景**：`LongAdder` 的 `Cell`、`Thread` 里的 `threadLocalRandomSeed` 与 `probe`、队列的 `head` 与 `tail` 相邻存放。\n\n**检测**：单看代码难判断，可对比加填充前后的压测吞吐；Linux 上用 `perf c2c` 直接找跨核争用的缓存行，是最直接的手段。\n\n**解决**：\n1. 手工填充：在变量前后各补 7 个 long 凑满一行；\n2. `@sun.misc.Contended`（JDK 8 起）：由 JVM 在字段前后自动插入 padding，但默认只对 JDK 内部类生效，用户类使用需加 `-XX:-RestrictContended`；\n3. 结构上把高频写的字段拆到独立对象，或直接用 `LongAdder` 这类已优化的结构。\n\n**代价**：填充显著增加内存占用，只在确认是热点的计数器上使用，不要全局滥用。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 33 MINUTE), 1),
  (434, 1, 'VarHandle 的访问模式与 Unsafe 的替代关系', 'JDK 9 引入的 `VarHandle` 解决了什么问题？它支持哪些内存语义的访问模式？与 `Unsafe` 相比有什么优势？请说明 `compareAndSet` 与 `getAndAdd` 的语义差异。', '**结论**：`VarHandle` 是对变量（实例字段、静态字段、数组元素）的**类型安全**动态引用，提供细粒度的内存序控制，是 `Unsafe` 中 CAS 与有序写方法的官方替代。JDK 9 起 `Unsafe` 的内存操作逐步被 `VarHandle` 与 `MethodHandles` 取代。\n\n**访问模式**（按内存语义由弱到强）：\n\n| 模式 | 语义 |\n|---|---|\n| plain（get/set） | 普通读写，可被重排 |\n| opaque | 保证原子性，不保证可见性顺序 |\n| acquire/release | 单向屏障，配对实现发布订阅 |\n| volatile | 全屏障，等价 volatile 读写 |\n\n**与 Unsafe 的差异**：`VarHandle` 有类型检查（签名多态，`invokeExact` 保证不装箱），可被 JIT 内联成普通指令，并且不受 JDK 17 起强封装的影响，而 `Unsafe` 的部分方法已废弃或受限。\n\n**CAS 与 getAndAdd**：`compareAndSet(expect, update)` 仅在当前值等于 expect 时写入并返回是否成功；`getAndAdd(delta)` 原子返回旧值并加上 delta，内部同样是 CAS 循环，但语义是无条件累加，不需要判断失败原因。\n\n**典型用途**：AQS、`ConcurrentHashMap`、`AtomicInteger` 的底层实现；自研无锁队列时用它保证字段可见性与原子性。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 34 MINUTE), 1),
  (435, 1, '生产者消费者模型的三种实现与队列选择', '请分别用 `wait/notify`、`BlockingQueue`、`Semaphore` 实现生产者消费者，说明三者的取舍。为什么 `wait` 必须配合 `while` 而不是 `if`？无界队列会带来什么问题？', '**结论**：三种实现的差别在于**由谁管理等待队列**：自己用 monitor 管、交给 `BlockingQueue` 管、或用信号量管。\n\n**一、wait/notify**：用同一个锁对象，生产者 `while (队列满) lock.wait();`，入队后 `notifyAll()`；消费者对称处理。必须用 while 防虚假唤醒，必须 notifyAll 防止唤醒错对象导致死等。代码最啰嗦，只适合教学。\n\n**二、BlockingQueue**（推荐）：`put` 满时阻塞、`take` 空时阻塞，内部用 `ReentrantLock` 加两个 Condition，语义清晰。`ArrayBlockingQueue` 一把锁两个条件；`LinkedBlockingQueue` 读写两把锁，吞吐更高。配合线程池就是标准做法。\n\n**三、Semaphore**：用 `notEmpty` 与 `notFull` 两个信号量，`acquire` 与 `release` 控制许可，适合需要自定义缓冲结构的场景，但入队本身仍需额外的锁或并发容器保证原子性。\n\n**无界队列的问题**：生产快于消费时内存无限增长直到 OOM，延迟不可控。必须用有界队列，容量按「峰值速率 × 可容忍延迟」估算，满时用拒绝策略或让生产者阻塞形成反压，而不是静默丢弃。\n\n**补充**：多生产者多消费者还要考虑公平性与批量消费 `drainTo` 以降低锁竞争。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 35 MINUTE), 1),
  (436, 1, 'AtomicReferenceFieldUpdater 与字段原子更新的适用场景', '`AtomicIntegerFieldUpdater`、`AtomicReferenceFieldUpdater` 相比 `AtomicInteger` 有什么优势？使用时对字段有哪些硬性要求？为什么 AQS、Netty 这类框架偏爱它？', '**结论**：字段更新器用反射加 `VarHandle` 直接对目标对象的 volatile 字段做 CAS，不额外持有原子对象，因此**省内存、省一层间接访问**。适合「大量对象、每个对象只偶尔原子更新某个字段」的场景。\n\n**硬性要求**（任一不满足都会在 `newUpdater` 时抛异常）：\n1. 字段必须是 `volatile`；\n2. 不能是 `private`，调用方需要能访问，通常用 `protected` 或包级可见；\n3. 只能是实例字段，不能是 static，也不能是 final；\n4. 类型必须精确匹配，`AtomicIntegerFieldUpdater` 只支持 int。\n\n**典型用法**：\n```java\nprivate static final AtomicIntegerFieldUpdater<Node> BUSY =\n    AtomicIntegerFieldUpdater.newUpdater(Node.class, "state");\nBUSY.compareAndSet(node, 0, 1);\n```\n\n**为什么框架偏爱**：AQS 的 `Node.waitStatus`、Netty 的引用计数都是海量小对象上的单字段，若每个对象配一个 `AtomicInteger`，对象头与指针开销会成倍增加；更新器把成本摊到类级别的静态字段上。\n\n**注意**：更新器必须缓存为 `static final`，否则每次反射查找反而更慢；它不提供复合操作语义，复杂逻辑仍需锁。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 36 MINUTE), 1),
  (437, 1, 'G1 与 ZGC 的设计取舍及选型依据', 'G1 的分区（Region）与回收流程是怎样的？ZGC 如何做到毫秒级以内的停顿？两者在堆大小、吞吐、停顿上的取舍是什么？生产环境应如何根据场景选择收集器？', '**结论**：G1 是**分代加 Region** 的收集器，目标是可预测的停顿（默认 200ms）；ZGC 是**以并发为主**的收集器，目标是把停顿压到毫秒以内，代价是更多 CPU 与内存开销。\n\n**G1 流程**：堆划分为大小相等的 Region（1 到 32MB），逻辑上仍有 Eden、Survivor、Old、Humongous。Young GC 是 STW 的复制回收；并发标记周期分为初始标记（STW，借用年轻代 GC 完成）、并发标记、最终标记（STW）、筛选回收。它维护每个 Region 的回收价值，按 `MaxGCPauseMillis` 优先回收收益高的 Region，因此叫 Garbage First。\n\n**ZGC 关键技术**：**染色指针**把标记信息存在 64 位指针的高位，配合**读屏障**在访问对象时修正引用，使标记、转移、重定位都能与用户线程并发；JDK 16 起支持 TB 级堆，停顿与堆大小基本无关。\n\n**选型**：\n\n| 场景 | 建议 |\n|---|---|\n| 堆 4 到 32G，追求吞吐与停顿平衡 | G1 |\n| 超大堆、停顿极敏感（交易、风控） | ZGC 或 Shenandoah |\n| 小堆、离线批处理 | Parallel GC，吞吐最高 |\n\n**注意**：ZGC 需要更多 CPU 做并发标记，容器里 CPU 受限时收益下降，升级前务必用真实流量压测。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 37 MINUTE), 1),
  (438, 1, '对象晋升老年代的判定与动态年龄策略', '对象在什么条件下进入老年代？`MaxTenuringThreshold` 与动态年龄判定分别如何生效？Survivor 空间不足时会发生什么？为什么大对象有时会直接分配到老年代？', '**结论**：对象晋升有四个触发点：\n1. **年龄达标**：每熬过一次 Minor GC 年龄加一，达到 `-XX:MaxTenuringThreshold`（默认 15，对象头只有 4 位存年龄，上限即 15）就晋升；\n2. **动态年龄判定**：Survivor 中某年龄及更小年龄对象总和超过 Survivor 的一半，则把该年龄及以上的对象直接晋升，不必等阈值；\n3. **大对象**：超过 `-XX:PretenureSizeThreshold`（仅对 Serial、ParNew 有效）直接进老年代，避免在 Eden 与 Survivor 间反复复制；\n4. **Survivor 放不下**：晋升时目标空间不足，通过**空间分配担保**直接进老年代，若老年代也放不下就触发 Full GC。\n\n**动态年龄的意义**：避免 Survivor 被大量同龄对象挤爆，减少复制次数，但也会让本该早夭的对象提前进老年代，抬高 Full GC 频率。\n\n**调优要点**：`SurvivorRatio` 决定 Eden 与单个 Survivor 的比例；监控晋升速率比死调阈值更有用。若每次 Minor GC 后老年代都明显上涨，说明有大量中期存活对象，应排查缓存或大对象分配。\n\n**注意**：G1 中年龄语义保留，但晋升以 Region 复制实现，观察需看 GC 日志的 age 相关输出。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 38 MINUTE), 1),
  (439, 1, '三色标记法与并发标记的漏标处理（增量更新 vs SATB）', '三色标记法中黑、灰、白分别代表什么？并发标记期间为什么会漏标？CMS 的增量更新与 G1 的 SATB 分别如何解决？为什么 G1 还需要 TAMS 指针？', '**结论**：白色是未访问对象（可能被回收），灰色是自身已访问但字段未扫描完，黑色是自身与所有引用都已扫描完。标记结束时仍为白色的对象即不可达。\n\n**漏标的两个必要条件**（同时发生才漏）：\n1. 黑色对象新增了指向白色对象的引用（插入）；\n2. 灰色对象到该白色对象的引用被删除（删除），使白色对象不再被任何灰或黑对象可达，却被错误回收。\n\n**增量更新（CMS）**：破坏条件一。黑对象新增指向白对象的引用时，把该黑对象重新标记为灰色，下一轮重新扫描它的字段，通过写屏障记录、事后处理。\n\n**SATB（G1、Shenandoah）**：破坏条件二。删除引用时通过写前屏障记录**旧值**，按「标记开始时存活的对象都视为存活」的快照语义处理，新分配对象一律隐含存活。\n\n**TAMS 指针**：SATB 需要知道哪些对象是标记开始后新分配的。G1 在每个 Region 记录 top-at-mark-start，指针高于 TAMS 的对象默认存活，避免误回收，也让并发标记无需重新扫描新增区域。\n\n**代价**：SATB 会产生浮动垃圾，靠下一次并发周期回收，但重标记阶段停顿更短，更适合大堆。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 39 MINUTE), 1),
  (440, 1, 'Java 内存泄漏的排查路径与 MAT 分析要点', 'Java 有 GC 为什么还会内存泄漏？线上堆持续上涨、Full GC 后也不下降，你的排查步骤是什么？`jmap`、`jcmd`、MAT 各自怎么用？支配树能看出什么？', '**结论**：内存泄漏指对象**仍被 GC Root 强引用**却不再使用，GC 无法回收。常见来源：静态集合只增不减、`ThreadLocal` 未 remove、监听器未注销、线程池队列积压、缓存无淘汰策略、类加载器泄漏、连接或流未关闭。\n\n**排查步骤**：\n1. 确认现象：`jstat -gcutil <pid> 1000` 看老年代占用在 Full GC 后是否仍上涨；\n2. 判断是否真泄漏：对比多次 Full GC 后的老年代基线，持续抬高才是泄漏；\n3. 抓堆：`jmap -dump:live,format=b,file=heap.hprof <pid>` 或 `jcmd <pid> GC.heap_dump`，线上先用 `-XX:+HeapDumpOnOutOfMemoryError` 兜底；\n4. 分析：用 MAT 或 JProfiler 打开，看 Leak Suspects 与 Histogram，按类统计实例数与浅堆深堆；\n5. 定位引用链：对可疑对象看 Path to GC Roots，排除弱引用软引用，找到谁在强引用它；\n6. 支配树：按**保留大小**排序，快速找出真正占内存的对象图根，比 Histogram 更能反映实际影响。\n\n**注意**：dump 会 STW 数秒，大堆要评估影响；容器内存受限时注意堆外内存与 `MaxRAMPercentage` 配置，别把容器打爆。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 40 MINUTE), 1),
  (441, 1, '自定义 ClassLoader 与热部署的实现要点', '如何实现一个自定义类加载器？`loadClass` 与 `findClass` 的重写边界在哪？为什么热部署要丢弃整个 ClassLoader 而不是重新 load 同一个类？双亲委派在什么情况下会被打破？', '**结论**：自定义加载器通常继承 `ClassLoader` 并重写 `findClass(String)`，在其中把全限定名转成路径读取字节流，再调用 `defineClass(name, bytes, 0, len)`。不要轻易重写 `loadClass`，那会绕过双亲委派、破坏核心类的保护。\n\n**loadClass 的模板流程**：先查已加载缓存，再委派父加载器，父加载不到才调 `findClass`。想要「子优先」必须重写 `loadClass`，这正是 Tomcat 对 Web 应用类、SPI 对实现类的做法。\n\n**为什么丢弃 ClassLoader**：JVM 中类的唯一标识是「类加载器加全限定名」。同一加载器对同一个名字只能定义一次，重复定义会抛 `LinkageError`。热部署要新建一个加载器实例加载新版本类，再让旧加载器整体不可达，它的所有类与静态变量随之卸载。\n\n**热部署的坑**：旧加载器若被线程、`ThreadLocal`、JDBC 驱动、定时器、缓存静态字段引用，就无法卸载，导致元空间泄漏，这是 Tomcat 反复重部署后 OOM 的经典原因。\n\n**打破双亲委派的场景**：SPI（父加载器用线程上下文类加载器加载子实现）、Tomcat 的 WebApp 隔离、OSGi 的模块化、JDK 自身的 `java.sql` 与驱动实现。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 41 MINUTE), 1),
  (442, 1, 'JIT 分层编译、逃逸分析与标量替换', '解释器与 JIT 如何协作？C1、C2 与分层编译是什么关系？什么是逃逸分析，它能带来哪些优化？为什么「栈上分配」在生产版 JVM 里几乎观测不到？', '**结论**：JVM 启动时用**解释器**快速执行，同时用方法调用计数器与回边计数器统计热点，热点方法或循环被 JIT 编译为本地代码。分层编译（JDK 8 起默认开启）分五级：0 解释执行，1 到 3 用 C1 编译（profiling 深度不同），4 用 C2 编译。C1 编译快优化浅，C2 编译慢优化深，先 C1 保启动性能，profile 足够后再升级到 C2。\n\n**逃逸分析**：分析对象作用域是否逃出方法（被返回、赋给字段、传入未知方法）。未逃逸时可以做三种优化：\n1. **标量替换**：把对象拆成若干局部变量，直接在栈或寄存器上操作；\n2. **锁消除**：对象只被单线程访问时去掉 `synchronized`；\n3. **栈上分配**：严格说是标量替换的结果，HotSpot 并未实现真正意义上的栈上分配。\n\n**为什么难观测**：优化发生在 C2 编译之后，需要 `-XX:+DoEscapeAnalysis`（默认开启）；生产版只能通过分配速率与 GC 频率间接验证，详细日志要用 fastdebug 版本。\n\n**实践**：小对象短生命周期本就是 TLAB 分配的强项，不必为栈上分配特意改代码；真正要关注的是大对象、长寿对象，以及过大方法体导致内联失效。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 42 MINUTE), 1),
  (443, 1, '常见 OOM 类型与各自的定位线索', '`OutOfMemoryError` 有哪几种常见形态？`Java heap space`、`Metaspace`、`Direct buffer memory`、`unable to create new native thread`、`GC overhead limit exceeded` 分别指向什么问题？', '**结论**：OOM 只是表象，message 才是线索。\n\n| 类型 | 成因 | 定位手段 |\n|---|---|---|\n| Java heap space | 堆不足或内存泄漏 | 堆 dump 加 MAT 看支配树 |\n| GC overhead limit exceeded | GC 耗时超 98% 却只回收不到 2% | 同样抓堆 dump，多半是泄漏或堆过小 |\n| Metaspace | 动态生成类过多（CGLIB、反射、热部署） | `-XX:MaxMetaspaceSize`，`jcmd` 的 VM.metaspace |\n| Direct buffer memory | NIO 直接内存超 `-XX:MaxDirectMemorySize` | 查 Netty 的 ByteBuf 释放与 BufferPoolMXBean |\n| unable to create new native thread | 线程数超过系统限制 | `ulimit -u`、线程数上限文件、线程泄漏 |\n| Requested array size exceeds VM limit | 申请超大数组 | 检查分页或批量大小的计算 |\n\n**关键动作**：启动加 `-XX:+HeapDumpOnOutOfMemoryError` 与 `-XX:HeapDumpPath`，事后才有材料；容器环境确认 `-Xmx` 与 limit 匹配，别让堆外内存把容器打爆；线程类问题先 `jstack` 看线程数分布与阻塞点。\n\n**提醒**：`OutOfMemoryError` 是 `Error`，不应被业务 `catch (Exception)` 捕获；捕获后进程状态可能已不可信，正确做法是快速失败并保留现场。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 43 MINUTE), 1),
  (444, 1, '对象创建流程与 TLAB 的分配机制', '`new` 一个对象在 JVM 里经历哪些步骤？TLAB 是什么、解决什么问题？为什么大对象不走 TLAB？「指针碰撞」与「空闲列表」分别在什么条件下使用？', '**结论**：`new` 的流程为：类加载检查（常量池解析类符号引用，未加载则先加载）、分配内存、内存置零、设置对象头（Mark Word 与 Klass Pointer）、执行构造方法。\n\n**两种分配方式**取决于堆是否规整：Serial、ParNew 等带压缩的收集器用**指针碰撞**，一个指针往后挪即可；CMS 这类不压缩的用**空闲列表**，维护可用块链表。\n\n**TLAB**（Thread Local Allocation Buffer）：Eden 中为每个线程预留的小块私有缓冲区，默认约占 Eden 的 1%，可用 `-XX:TLABSize` 与 `-XX:TLABWasteTargetPercent` 调整。线程在 TLAB 内分配无需 CAS，只有 TLAB 用完才申请新的，极大降低多线程分配的竞争。\n\n**大对象不走 TLAB**：超过 TLAB 剩余空间可容忍浪费比例的对象直接在 Eden 共享区分配，否则会浪费 TLAB 尾部空间；更大的对象还可能直接进老年代（`PretenureSizeThreshold`）。\n\n**实践**：高频分配小对象本就是快路径，无需优化；真正要关注的是分配速率与晋升速率，可用 JFR 的对象分配事件或 GC 日志中的分配统计定位热点。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 44 MINUTE), 1),
  (445, 1, '类初始化的触发时机与 <clinit> 的线程安全', '类在什么时候才会被初始化？「主动引用」与「被动引用」如何区分？`<clinit>` 是线程安全的吗？为什么静态字段的初始化顺序会导致前向引用拿到默认值？', '**结论**：类加载分加载、验证、准备、解析、初始化五步，初始化即执行 `<clinit>`。触发条件（主动引用）有六种：`new` 实例、读写静态字段（非 final 常量）、调用静态方法、反射 `Class.forName`（默认 initialize 为 true）、初始化子类时先初始化父类、作为启动类被虚拟机初始化。\n\n**被动引用不触发初始化**：通过子类访问父类的静态字段、`new A[10]` 创建数组、访问 `static final` 编译期常量（已内联进调用方常量池）。\n\n**<clinit> 线程安全**：JVM 保证类初始化是**加锁**的，多线程同时触发只有一个线程执行，其余阻塞等待；若 `<clinit>` 中发生死锁或耗时过长，其他线程会一直卡在类初始化上，这是「类加载死锁」的来源。\n\n**顺序问题**：`<clinit>` 按源码顺序执行静态赋值与静态块，因此先写 `static int a = b + 1;` 再写 `static int b = 2;` 时 a 得到 1，因为此时 b 还是默认值 0；反过来的前向引用会直接编译报错。`static final` 的编译期常量在准备阶段就赋好值，不走此规则。\n\n**实践**：静态块里不要做远程调用或复杂依赖，避免拖慢首次访问。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 45 MINUTE), 1),
  (446, 1, '定位 CPU 100% 的完整步骤：从 top 到线程栈', '线上 CPU 打满，请给出从操作系统到 Java 线程栈的完整定位链路。`top -Hp` 得到的线程 ID 如何与 `jstack` 对应？为什么 RUNNABLE 的线程不一定是问题线程？还有哪些更现代的工具？', '**结论**：定位链路是「机器、进程、线程、栈帧、代码」。\n\n**步骤**：先用 `top` 找到高 CPU 的 Java 进程 PID；用 `top -Hp <pid>` 找到高 CPU 的线程 TID；把十进制 TID 转成十六进制（`printf %x <tid>`）；用 `jstack <pid>` 输出后按十六进制 nid 检索该线程栈；间隔几秒重复采样三到五次，若同一栈顶反复出现，即为热点。\n\n**为什么 RUNNABLE 不等于问题**：JVM 不区分就绪与运行，socket read 等 IO 阻塞也显示 RUNNABLE，必须结合 `top -Hp` 的实际 CPU 占用判断。反之 BLOCKED 线程不耗 CPU，是锁竞争的表现。\n\n**常见根因**：死循环、正则回溯爆炸、序列化超大对象、频繁 Full GC（此时是 GC 线程在跑，要看 GC 日志与 `jstat`）、日志同步刷盘、循环里的字符串拼接。\n\n**更现代的工具**：`jcmd <pid> Thread.print`、JFR（`jcmd <pid> JFR.start`，几乎无侵入，可在生产常开）、Arthas 的 `thread -n 3` 直接列出最忙线程栈、async-profiler 生成火焰图定位到方法甚至行号。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 46 MINUTE), 1),
  (447, 1, 'JVM 运行时数据区与直接内存', 'JVM 运行时数据区如何划分？哪些线程私有、哪些共享？为什么 JDK 8 用元空间取代永久代？直接内存受不受 `-Xmx` 限制？', '**结论**：\n\n| 区域 | 共享性 | 存放内容 | 异常 |\n|---|---|---|---|\n| 程序计数器 | 私有 | 字节码行号 | 无 |\n| 虚拟机栈 | 私有 | 栈帧、局部变量表、操作数栈 | StackOverflowError 或 OOM |\n| 本地方法栈 | 私有 | native 方法调用 | 同上 |\n| 堆 | 共享 | 对象实例、数组 | OOM: heap space |\n| 方法区（元空间） | 共享 | 类元信息、运行时常量池、静态变量 | OOM: Metaspace |\n\n**元空间替换永久代**（JDK 8，JEP 122）：永久代大小固定且难以调优，容易 OOM；元空间使用**本地内存**，默认不设上限，只受 `-XX:MaxMetaspaceSize` 与机器内存约束。字符串常量池与静态变量在 JDK 7 就已移到堆中。\n\n**直接内存**：通过 `ByteBuffer.allocateDirect` 或 `Unsafe.allocateMemory` 分配，位于本地内存，**不受 -Xmx 限制**，只受 `-XX:MaxDirectMemorySize`（默认约等于最大堆）与物理内存约束。它是零拷贝与高性能 IO 的基础，但分配与回收成本高，靠 Cleaner 在 ByteBuffer 被回收时释放。\n\n**容器注意**：除堆外还有元空间、线程栈、直接内存、CodeCache，容器 limit 要留余量，否则进程会被 OOMKilled 而不是抛 Java OOM。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 47 MINUTE), 1),
  (448, 1, '静态分派与动态分派：重载与重写的方法选择', 'Java 的方法调用如何确定目标方法？重载与重写分别在编译期还是运行期解析？为什么 null 作为实参时重载会「选最具体的」？`invokevirtual` 与 `invokedynamic` 有何不同？', '**结论**：重载是**静态分派**，编译期依据**变量的静态类型**与参数个数、类型确定方法签名，写入常量池的符号引用；重写是**动态分派**，运行期依据**接收者的实际类型**在虚方法表中查找。\n\n**重载选择的三阶段**：先按不装箱、不变长参数的精确匹配；再允许自动装箱与变长参数；最后才考虑父类与接口的兼容类型。`null` 实参时选「最具体」的重载，如 `f(String)` 与 `f(Object)` 之间选 `f(String)`；若两个重载处于无关分支，则编译报错 ambiguous。\n\n**字节码指令**：`invokestatic` 与 `invokespecial`（构造器、私有方法、super 调用）是静态解析；`invokevirtual`、`invokeinterface` 走动态分派；`invokedynamic` 由引导方法在首次调用时链接出 CallSite，之后可替换为目标方法句柄，lambda、JDK 9 起的字符串拼接、Kotlin 与 Groovy 的动态特性都基于它。\n\n**实践含义**：不要在子类实例上用父类引用调重载方法，静态类型决定结果，极易误判；`private`、`static`、`final` 方法不参与动态分派。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 48 MINUTE), 1),
  (449, 1, 'final 关键字的三层语义与安全发布', '`final` 修饰类、方法、字段分别意味着什么？为什么说 `final` 字段具有「初始化安全」的内存语义？`final` 与 `static final` 在编译期常量内联上有何区别？', '**结论**：`final` 类不可被继承；`final` 方法不可被重写（也便于 JIT 内联）；`final` 字段只能赋值一次。三者共同点是不可变约束，但只有字段带有内存语义。\n\n**final 字段的内存语义**：JMM 规定，构造方法中对 final 字段的写入，与随后把对象引用赋给其他线程的读之间，存在 happens-before 保证：**只要对象没有在构造过程中逸出**，其他线程看到的 final 字段一定是构造完成后的正确值，不需要额外同步。这是不可变对象（`String`、`Integer`）可以安全发布的理论基础。\n\n**前提条件**：若构造器把 `this` 泄漏出去（注册监听器、启动线程、放入静态集合），该保证失效，其他线程可能看到默认值。\n\n**编译期常量**：`static final` 修饰的**基本类型或 String 字面量**在编译期就确定值，会被内联进调用方的常量池，因此修改常量值后必须**重新编译依赖方**，否则仍是旧值；而 `static final` 修饰对象引用（如 `new Object()`）不会被内联。\n\n**实践**：不可变类要用 `final` 修饰类本身，并让所有字段 final、构造时完成全部初始化；单例的 `static final` 实例天然线程安全。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 49 MINUTE), 1),
  (450, 1, 'serialVersionUID、transient 与反序列化的安全风险', '`serialVersionUID` 不一致会发生什么？`transient` 字段能被序列化吗？`readObject` 为什么是反序列化漏洞的入口？`Externalizable` 与 `Serializable` 有何区别？', '**结论**：`serialVersionUID` 是序列化的版本号，未显式声明时由编译器按类结构计算，字段或方法一变就变。反序列化时若流中的 UID 与本地类不一致，抛 `InvalidClassException`。显式声明可保持跨版本兼容。\n\n**transient**：被标记的字段不参与默认序列化，反序列化后为默认值；若类自定义了 `writeObject` 与 `readObject`，可以在其中手工读写它。`static` 字段本就不序列化。\n\n**readObject 的危险**：反序列化会直接构造对象并执行 `readObject`，绕过构造器校验，攻击者可构造恶意字节流触发任意代码，这是 Fastjson、Shiro 等反序列化漏洞的根源。防御手段：用 `ObjectInputFilter`（JDK 9 起）配置类白名单、绝不反序列化不可信数据、优先用 JSON 这类数据结构化格式。\n\n**Externalizable**：继承 `Serializable`，但完全由 `writeExternal` 与 `readExternal` 控制，且必须提供 **public 无参构造器**（反序列化时先调用它再填充），控制力更强、体积更小，代价是要手写全部字段逻辑。\n\n**其他注意**：序列化不走构造器，单例若实现 `Serializable` 需加 `readResolve` 返回单例，否则反序列化会得到新实例。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 50 MINUTE), 1),
  (451, 1, 'record 的语义、限制与适用边界', '`record` 与普通类有什么本质区别？它自动生成了哪些成员？为什么 `record` 只是浅不可变？它能否继承、能否声明额外实例字段？与 Lombok 的 `@Value` 相比如何取舍？', '**结论**：`record` 是 JDK 16 正式的语言级**不可变数据载体**，编译器自动生成全参构造器、每个组件的访问器（写作 `x()` 而不是 `getX()`）、`equals`、`hashCode`、`toString`，并隐式继承 `java.lang.Record`。\n\n**本质区别**：组件字段隐式为 `private final`，类隐式为 `final`，不能被继承；不能声明额外的实例字段（只能有 static 字段）；不能继承其他类，但可以实现接口；可定义**紧凑构造器**做校验与防御性拷贝。\n\n**浅不可变**：组件是 final 引用，但若指向数组或 `List`，内容仍可被修改。需要深不可变就在紧凑构造器里 `List.copyOf`、`Arrays.copyOf` 做拷贝。\n\n**与 Lombok 对比**：Lombok 是编译期代码生成，需要插件与 IDE 支持，灵活度更高（可指定 setter、builder）；`record` 是语言特性，零依赖、语义清晰、对模式匹配友好，且能配合 `sealed` 做穷尽分支。\n\n**适用**：DTO、领域事件、多返回值、Map 的复合 key；不适合需要可变状态、需要继承体系或需要 JPA 无参构造器的实体。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 51 MINUTE), 1),
  (452, 1, 'sealed 类型与 switch 模式匹配的穷尽性检查', '`sealed` 接口解决了什么问题？`permits` 子句与 `final`、`sealed`、`non-sealed` 三种修饰有何约束？为什么 `sealed` 能让 `switch` 做穷尽性检查而无需 default？', '**结论**：`sealed`（JDK 17 正式）限定一个类型**只允许指定的子类型**继承或实现它，在「完全开放」与「完全 final」之间提供受控的封闭层次，是代数数据类型在 Java 中的落地方式。\n\n**约束**：子类必须在同一模块（未命名模块时同一包）内，且必须显式声明为 `final`（不再有子类）、`sealed`（继续受限）或 `non-sealed`（重新开放）；`permits` 可省略，此时由同文件内的子类自动推断；子类不能是匿名类或局部类。\n\n**穷尽性检查**：编译器知道全部允许的子类型，因此对 `sealed` 层次做 `switch` 模式匹配时，只要覆盖所有分支就**不需要 default**，漏掉一个会编译报错：\n```java\nint area = switch (shape) {\n    case Circle c -> (int) (3.14 * c.r() * c.r());\n    case Square s -> s.side() * s.side();\n};\n```\n新增子类型时所有 switch 立刻编译失败，强迫调用方处理，这是它相对普通接口最大的工程价值。\n\n**注意**：`case null` 需显式处理；穷尽性要求只对 `sealed` 层次生效，普通接口仍需 default。\n\n**典型用途**：状态机、AST 节点、支付方式、领域事件。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 52 MINUTE), 1),
  (453, 1, '接口默认方法的冲突解决规则与静态方法', '接口的 `default` 方法解决了什么问题？一个类同时实现两个含同名默认方法的接口时编译器如何裁决？为什么接口可以有 static 方法与 private 方法，却不能有实例字段？', '**结论**：`default` 方法（JDK 8）让接口在不破坏已有实现的前提下演进，典型例子是 `Collection.stream()` 与 `Iterable.forEach()`。\n\n**冲突解决三条规则**（按优先级）：\n1. **类优先**：父类中的具体方法胜过接口默认方法；\n2. **子接口优先**：若接口 B 继承 A 并重写了默认方法，实现类用 B 的版本；\n3. **必须显式覆盖**：两个**无关**接口提供同名同参默认方法时，实现类必须重写，否则编译报错；重写时可用 `A.super.hello()` 指定调用哪个。\n\n**static 与 private**：接口的 static 方法属于接口本身，只能通过 `InterfaceName.method()` 调用，不被继承；JDK 9 起允许 private 方法，供多个 default 方法复用代码而不暴露 API。\n\n**不能有实例字段**：接口描述行为契约，不承载状态；字段隐式为 `public static final` 常量。默认方法也无法访问实现类的状态，只能调用其他接口方法。\n\n**设计提醒**：默认方法适合「可选能力」或「基于其他抽象方法组合出的行为」，不要用它塞业务实现，否则接口退化为抽象类，多实现时冲突频发。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 53 MINUTE), 1),
  (454, 1, 'switch 表达式的箭头语法、yield 与穷尽性', 'JDK 14 的 `switch` 表达式与经典 `switch` 语句有何不同？箭头形式为什么不会贯穿（fall-through）？`yield` 与 `return` 有什么区别？什么情况下编译器要求 `switch` 必须穷尽所有分支？', '**结论**：`switch` 表达式有值，可直接赋给变量或作为参数；经典 `switch` 是语句，只能靠副作用。箭头形式天然**不贯穿**，每个分支独立，不再需要 break，消除了忘写 break 导致的经典 bug。\n\n**yield**：只在块形式的分支里使用，用于从 `switch` 表达式返回该分支的值：\n```java\nint num = switch (day) {\n    case MON, TUE -> 1;\n    case WED -> { int x = compute(); yield x; }\n    default -> 0;\n};\n```\n它与 `return` 的区别是作用域：`yield` 只跳出 `switch` 表达式并交出值，`return` 会直接结束整个方法。\n\n**穷尽性要求**：当 `switch` 用作**表达式**（有值）时必须穷尽：枚举要覆盖全部常量或写 default；`sealed` 类型要覆盖全部允许子类型；`int`、`String` 等开放类型必须有 default，否则编译报错。用作语句时不强制，但为可读性建议覆盖。\n\n**其他增强**：多个常量用逗号合并、`case null` 显式处理空值（JDK 21）、结合 when 守卫条件与模式匹配使用。\n\n**注意**：箭头形式下 case 的常量仍要求编译期常量；分支里抛受检异常要自行处理。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 54 MINUTE), 1),
  (455, 1, '自动装箱、IntegerCache 与 == 比较陷阱', '`Integer a = 127; Integer b = 127; a == b` 的结果是什么？换成 128 呢？为什么？`Long`、`Character`、`Boolean` 的缓存范围各是多少？自动装箱在循环里有什么性能问题？', '**结论**：127 时 `a == b` 为 **true**，128 时为 **false**。原因是 `Integer.valueOf(int)` 对 -128 到 127 使用 `IntegerCache` 中预建的实例，范围内返回同一对象；超出范围则新建对象，引用自然不等。\n\n**各包装类缓存范围**：\n\n| 类型 | 缓存范围 |\n|---|---|\n| Byte、Short、Integer、Long | -128 到 127，Integer 上限可用 `-XX:AutoBoxCacheMax` 调大 |\n| Character | 0 到 127 |\n| Boolean | TRUE 与 FALSE 两个常量 |\n| Float、Double | 无缓存 |\n\n**正确比较**：包装类一律用 `equals`，或先比较 `intValue()`；`==` 在包装类与基本类型混用时会自动拆箱比较数值，两个包装类之间则比较引用，极易出错。\n\n**性能问题**：循环里 `sum += i` 若 sum 是 `Long`，每轮都创建对象；`List<Integer>` 存百万级数据的内存开销是 `int[]` 的数倍；三元表达式两分支类型不同时（`int` 与 `Integer`）会触发拆箱，`flag ? 1 : null` 直接抛 NPE。\n\n**实践**：实体字段与返回类型用包装类表达可空，计算密集路径用基本类型；永远不要用包装类做 `==` 判断。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 55 MINUTE), 1),
  (456, 1, 'Optional 的正确用法与常见反模式', '`Optional` 的设计初衷是什么？`orElse` 与 `orElseGet` 的关键区别？为什么说不要用 Optional 做字段类型或方法参数？请列出至少四种应当避免的 Optional 反模式。', '**结论**：`Optional` 的本意是**在返回类型上显式表达「可能没有值」**，强迫调用方处理缺失，减少 NPE 与无意义的 null 约定。它不是 null 的通用替代品。\n\n**orElse 与 orElseGet**：`orElse(defaultValue)` 的实参**总会求值**，即使 Optional 有值也先构造默认值；`orElseGet(supplier)` 只在为空时才调用。默认值是对象创建或远程调用时，必须用 `orElseGet`，否则白白付出代价。\n\n**反模式清单**：\n1. **做字段类型**：`Optional` 不可序列化，字段用它会破坏实体与 DTO；\n2. **做方法参数**：参数可空应重载方法或显式校验，传 Optional 只是把判空负担转移；\n3. **get 前不检查**：直接 get 等于换了种写法的 NPE，应用 `orElseThrow`；\n4. **isPresent 加 get**：等价于 null 判断，失去函数式优势，应用 `map`、`ifPresent`、`orElseThrow`；\n5. **集合里装 Optional**：用空集合表达「没有」更自然；\n6. **Optional.of(null)**：直接 NPE，可空值要用 `ofNullable`。\n\n**推荐写法**：链式 `map` 取值、`filter` 过滤、`orElseThrow(() -> new BizException(...))` 兜底，`ifPresentOrElse`（JDK 9）处理两种情况。\n\n**性能**：`Optional` 是小对象，热点路径上大量创建会增加分配压力，此时直接返回 null 并配套 `@Nullable` 注解也可以接受。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 56 MINUTE), 1);

   `view_count`, `practice_count`, `published_at`, `created_by`)
VALUES
  (457, 2, '唯一索引与普通索引的写性能差异：change buffer 到底省了什么', 'InnoDB 更新二级索引时，如果目标页不在 Buffer Pool，普通索引可以走 change buffer 延迟合并，唯一索引却不行。请回答：\n\n1. change buffer 记录的是什么粒度的操作，什么时候触发 merge；\n2. 唯一索引为什么必须同步读页；\n3. 写多读少的表应如何据此做索引选型。\n\n```sql\nCREATE TABLE t_user (\n  id BIGINT PRIMARY KEY,\n  mobile VARCHAR(20),\n  city VARCHAR(20),\n  UNIQUE KEY uk_mobile (mobile),\n  KEY idx_city (city)\n) ENGINE=InnoDB;\n```', '**结论**：非唯一二级索引的写可以「先记账、后合并」，唯一索引的写必须「先读页、再落盘」。目标页不在内存时，普通索引把随机写转成内存中的顺序追加，唯一索引要多一次随机读，写吞吐差距可达数倍。\n\n**change buffer 是什么**：Buffer Pool 里的一块区域，缓存对**非唯一二级索引页**的 INSERT / UPDATE / mark delete 操作。页不在内存时只写 change buffer 并记 redo，等该页因查询被载入、后台线程调度、正常关机或 redo 空间紧张时再 merge 回索引页。\n\n**唯一索引为什么不行**：插入或更新前必须确认新值在索引中不重复，这个判断只能通过读取索引页完成。若允许延迟，两个并发事务可能各自「记账成功」，唯一性就被破坏。所以唯一索引只要目标页不在内存，就要立刻发起一次随机 IO。\n\n**选型建议**：\n- 业务约束该建唯一索引就建，别为了性能降级成普通索引加应用层查重，那只是把风险搬到线上；\n- 纯检索用的辅助索引保持非唯一，写多读少的表收益最明显；\n- `innodb_change_buffer_max_size` 默认 25（最大 50），写极重的库可适度调大，但会挤压数据页缓存。\n\n**注意**：change buffer 只对二级索引有效，聚簇索引的写永远是「读页-修改」；主键最好自增，让写入集中在少数页上，从源头减少随机 IO。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 57 MINUTE), 1),
  (458, 2, 'redo log 组提交（group commit）三阶段如何摊薄 fsync 成本', '双 1 配置下每次提交都要 fsync redo 与 binlog，但高并发下写入 QPS 依然很高，靠的就是组提交。请说明 flush / sync / commit 三阶段各自的动作与谁在做，以及 `binlog_group_commit_sync_delay` 的作用与风险。\n\n```sql\nSET GLOBAL innodb_flush_log_at_trx_commit = 1;\nSET GLOBAL sync_binlog = 1;\n```', '**结论**：组提交把多个并发事务的刷盘动作合并成一次 fsync，用「排队等一小会儿」换「一次刷多个」，把每次提交的固定 IO 成本摊到 N 个事务上。并发越高，摊得越薄。\n\n**三阶段**（由 binlog 的 flush 队列、sync 队列与 InnoDB 的 prepare 队列配合，队列里的第一个事务当选 leader）：\n1. **flush**：leader 把队列中所有事务的 binlog 从 cache 写入文件（write，尚未落盘）；\n2. **sync**：leader 对 binlog 做一次 fsync，队列中所有事务的 binlog 一起持久化；\n3. **commit**：leader 按顺序调用引擎层 commit，把这些事务的 redo 合并刷盘。\n\n队列中的 follower 只等待，于是 N 个事务共享一到两次 fsync。\n\n**为什么仍然安全**：内部两阶段提交要求 redo prepare 与 binlog 同时成功。若崩溃在 binlog 已 fsync 之后，恢复时能按 XID 找到 prepared 事务并提交；若 binlog 未 fsync，则回滚。刷盘顺序由 LOCK_redo / LOCK_binlog 保护，与 leader 的提交顺序一致。\n\n**可调项**：`binlog_group_commit_sync_delay`（微秒，最多等这么久以凑批）与 `binlog_group_commit_sync_no_delay_count`（攒够多少个立即刷）。延迟越大吞吐越高、单事务响应时间越差。\n\n**风险**：调大 delay 会拉高尾延迟，对在线交易不友好；`sync_binlog=0` 或 `innodb_flush_log_at_trx_commit=2` 更快但崩溃会丢最近的提交。牺牲持久性换吞吐前，先确认业务能接受丢数据。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 58 MINUTE), 1),
  (459, 2, '内部两阶段提交崩溃在三个不同时点，恢复结果分别是什么', 'redo prepare、写 binlog、引擎 commit 三步之间掉电，恢复结果完全不同。请分别说明三个崩溃点对应的恢复动作，并解释为什么不会出现「主库有、从库没有」的半条事务。\n\n```sql\nSTART TRANSACTION;\nUPDATE t SET c = c + 1 WHERE id = 1;\nCOMMIT;\n```', '**结论**：InnoDB 内部 2PC 让 redo 与 binlog 达成「要么都算提交、要么都不算」。崩溃点不同、恢复动作不同，但两份日志的结论始终一致。\n\n**三个崩溃点**：\n1. **redo prepare 之前**：redo 中没有该事务的 prepare 记录，binlog 也未写。恢复时无事可做，事务丢失——但它本来就没成功，一致性无损。\n2. **prepare 之后、binlog 未写完或未 fsync**：恢复扫描 redo 时看到 prepared 事务，再按 XID 去 binlog 中查找；找不到或尾部不完整，就**回滚**该事务。\n3. **binlog 已 fsync、引擎尚未 commit**：同样扫到 prepared 事务，binlog 中能按 XID 找到完整事务，于是**提交**它。这条数据从库也会通过复制收到。\n\n**判定关键**：binlog 中每个事务结尾有 XID 事件，与 InnoDB 的 trx_id 对应。恢复逻辑先由 binlog 的完整性确定「这个事务到底有没有进 binlog」，再决定回滚还是提交。所以主库与从库不会出现半条事务。\n\n**两个延伸结论**：\n- 这就是 `sync_binlog=1` 与 `innodb_flush_log_at_trx_commit=1` 必须同时开启的原因：只保 redo 落盘而 binlog 丢失，等于主库有数据、从库没有，复制直接断裂。\n- 基于位点的一致性备份（XtraBackup 记录 binlog position）也依赖这套机制，才能做到「备份 + binlog」回放到任意时间点。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 59 MINUTE), 1),
  (460, 2, '半同步复制的 after_sync 与 after_commit，哪个才是无损复制', 'MySQL 半同步复制有 AFTER_COMMIT 与 AFTER_SYNC 两种等待点。请说明两者在主库提交时序上的差别、为什么只有 after_sync 被称为无损复制，以及 `rpl_semi_sync_master_timeout` 超时退化带来的隐患。', '**结论**：`AFTER_COMMIT` 是「先提交、后等从库 ACK」，主库可能在等待期间已经对外返回成功，此时崩溃切换会丢数据；`AFTER_SYNC` 把等待点提前到 binlog 已 fsync、引擎尚未 commit 之间，收到 ACK 才真正提交。因此只有 `AFTER_SYNC` 是无损复制。\n\n**时序差异**：\n- AFTER_COMMIT：引擎 commit → 发 binlog 给从库 → 等 ACK。若主库在等待中宕机且 binlog 未落到从库，客户端已收到成功，数据却没了。\n- AFTER_SYNC（5.7 起默认）：写 binlog 并 fsync → 等从库 ACK → 才做引擎层 commit。等待中的事务对其他会话不可见，失败可直接回滚。\n\n**ACK 的真实语义**：从库收到 binlog 并写入 relay log 即回 ACK，**默认不保证已 apply**。要更稳需配合 relay log 刷盘策略。所以「无损」指的是不丢日志、切换后新主包含已确认事务，而不是从库已执行完。\n\n**超时退化是最大的坑**：`rpl_semi_sync_master_timeout`（默认 10s）到期仍无 ACK，主库会自动降级为异步复制，语义悄悄从「无损」变回「可能丢」，且不会自动恢复，要等 ACK 重新出现。必须监控 `Rpl_semi_sync_master_status` 并对退化事件告警。\n\n**代价与取舍**：每次提交多一个网络 RTT，同城双机房通常 1~2ms 可接受；跨地域会显著拉高写延迟，此时应改用组复制，或接受异步并用业务对账兜底。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 60 MINUTE), 1),
  (461, 2, '主从延迟的四个真实来源与并行复制（MTS / WRITESET）调优', '从库 `Seconds_Behind_Master` 持续上涨，除了「从库配置差」还有哪些原因？请说明单线程回放的瓶颈、MTS 并行度的来源（按库 / LOGICAL_CLOCK / WRITESET），以及如何判断瓶颈在 IO 线程还是 SQL 线程。', '**结论**：延迟分两类——网络/IO 拉取跟不上，与 SQL 线程回放跟不上。绝大多数线上延迟是后者：主库写入是并发的，而从库早期只能单线程串行回放。\n\n**四个真实来源**：\n1. **大事务与大 DDL**：主库跑 60s，从库必须完整重放 60s，延迟线性上涨；\n2. **从库硬件或参数更弱**：`innodb_buffer_pool_size` 比主库小、磁盘更差，重放同样 binlog 要更久；\n3. **无主键表**：ROW 格式下定位行要全表扫描，一条 update 放大成 O(n)；\n4. **回放并行度不足**：MTS 只有 1 个 worker，或并行度上不去。\n\n**怎么判断瓶颈**：`SHOW REPLICA STATUS` 看 `Seconds_Behind_Master` 与两个线程状态；再查 `performance_schema.replication_applier_status_by_worker` 各 worker 的忙碌情况。relay log 堆积但 worker 空闲等待 → 回放/锁等待瓶颈；IO 线程位点落后 → 网络或拉取问题。\n\n**并行复制演进**：\n- 5.6 `DATABASE`：按库并行，单库多表完全无效；\n- 5.7 `LOGICAL_CLOCK`：按组提交并行，同一组内事务可并发回放，配合 `replica_parallel_workers`（建议 8~16）与 `replica_preserve_commit_order=1` 保证提交顺序；\n- 8.0 `WRITESET`：按行级冲突检测打标记，无冲突事务可更大并行。\n\n**工程手段**：拆大事务、所有表加主键、DDL 走 gh-ost、热点表串行写入；延迟无法消除时，按业务分级让关键读走主库或缓存兜底，而不是让所有读都等复制。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 61 MINUTE), 1),
  (462, 2, 'GTID 的生成规则与基于 GTID 的主从切换、跳事务处理', 'GTID 由 server_uuid 与事务序号组成。请说明它的生成与持久化方式、如何用 GTID 自动定位复制位点，以及误操作后为什么不能简单「跳过一个 GTID 事务」，正确做法是什么。\n\n```sql\nCHANGE REPLICATION SOURCE TO SOURCE_AUTO_POSITION = 1;\nSELECT @@gtid_executed, @@gtid_purged;\n```', '**结论**：GTID 是全局唯一的事务标识 `uuid:事务号`，把「复制到哪了」从字节偏移变成集合运算，从而支持自动定位、自动切换与幂等重放。\n\n**生成与持久化**：每个事务提交时由 MySQL 分配 `server_uuid:sequence`，写入 `mysql.gtid_executed` 表；`@@gtid_executed` 是已执行集合。`gtid_purged` 表示已被 binlog 清理、无法再补发的集合——从库的 executed 必须是主库的子集，否则报 1236。\n\n**自动定位**：`SOURCE_AUTO_POSITION=1` 时，从库把自己的 `gtid_executed` 发给主库，主库从第一个缺失事务开始发。切换主库不需要再算 binlog 文件名与 position，大幅降低人工出错概率，这是 MHA / Orchestrator 等工具的基础。\n\n**误删数据后的误区**：GTID 模式禁用 `sql_slave_skip_counter`，只能用 `SET GTID_NEXT = ''uuid:n''` 注入空事务来「假装已执行」。但要注意：\n- 跳过只是掩盖症状，那条 SQL 在从库没执行，数据已经不一致；\n- 跳过的若是 DDL 或唯一键冲突，后续事务会连环报错；\n- 正确做法是先在从库执行同样的误操作以保持同步，再从备份 + binlog 定点恢复；或直接用备份重建从库。\n\n**运维要点**：`gtid_mode=ON` 配 `enforce_gtid_consistency=ON`，避免 `CREATE TABLE ... SELECT` 这类非事务语句；切换前确认旧主 `super_read_only=ON`，否则双写会让 GTID 集合分叉，再也无法合并。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 62 MINUTE), 1),
  (463, 2, 'MySQL 分区表的适用场景、裁剪失效与唯一索引硬限制', '分区表看起来能「把大表变小」，但很多团队上线后发现收益为零。请说明分区裁剪（partition pruning）生效的条件、主键与唯一索引必须包含分区键的原因，以及分区表在 OLTP 中的真实定位。\n\n```sql\nCREATE TABLE t_log (\n  id BIGINT NOT NULL,\n  created_at DATE NOT NULL,\n  PRIMARY KEY (id, created_at)\n) PARTITION BY RANGE (TO_DAYS(created_at)) (\n  PARTITION p202401 VALUES LESS THAN (TO_DAYS(''2024-02-01'')),\n  PARTITION p202402 VALUES LESS THAN (TO_DAYS(''2024-03-01''))\n);\n```', '**结论**：分区表的价值主要在**管理维度**（秒级删历史分区、按分区维护），而不是查询加速。只有查询条件能命中分区键时才产生裁剪收益，否则就是「一张表 + 一堆额外开销」。\n\n**裁剪生效条件**：WHERE 中必须是分区表达式可静态求值的形式。`created_at >= ''2024-01-01''` 能推出涉及哪些分区；写成 `YEAR(created_at)=2024`、`DATE_FORMAT(...)`、或用 `OR` 混入非分区列，就会退化成扫描全部分区。用 `EXPLAIN` 的 `partitions` 列验证到底裁到哪几个分区。\n\n**硬限制**：\n- 主键与每个唯一索引**必须包含分区键**，因为唯一性只能在一个分区内保证。所以常见写法是 `PRIMARY KEY (id, created_at)`，代价是 id 单独不再唯一，全局唯一要另做保证；\n- 不支持外键；分区数有上限（8192）；改分区策略基本要重建数据。\n\n**OLTP 中的真实定位**：单表几千万行、且访问几乎都带时间条件（日志、流水、消息表）适合；若查询条件与分区键无关（如按 user_id 查），分区只会增加优化器判断成本，还可能因每个分区独立索引而降低 Buffer Pool 命中率。\n\n**更好替代**：按时间拆物理表（`t_log_202401`）由应用或中间件路由，`DROP TABLE` 即可清理，比分区更可控；跨维度查询需求多时，应上分库分表或把分析流量引到数仓，而不是指望分区解决。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 63 MINUTE), 1),
  (464, 2, '分库分表下的全局唯一 ID：雪花、号段与 Leaf-segment 的取舍', '分表后自增主键不再全局唯一。请对比 UUID、雪花算法、数据库号段（segment）与 Redis 发号四种方案，并说明时钟回拨、号段双 buffer 预加载、以及「ID 是否暴露业务量」该如何权衡。\n\n```sql\nCREATE TABLE t_order_0 (id BIGINT NOT NULL PRIMARY KEY, user_id BIGINT) ENGINE=InnoDB;\nCREATE TABLE t_order_1 (id BIGINT NOT NULL PRIMARY KEY, user_id BIGINT) ENGINE=InnoDB;\n```', '**结论**：优先选**趋势递增的 64 位整型**，既保证全局唯一，又让 InnoDB 插入集中在索引尾部，兼顾写性能与可读性。雪花与号段是两条主流路线，适用面不同。\n\n| 方案 | 优点 | 缺点 |\n|---|---|---|\n| UUID | 本地生成、零依赖 | 36 字符过长，随机分布导致页分裂与二级索引膨胀，不可读 |\n| 雪花 | 本地生成、趋势递增、含时间信息 | 强依赖时钟，回拨会发重复 ID；workerId 要治理 |\n| 数据库号段 | 数值连续、一次取 1000 个、性能好 | 强依赖 DB，取号段瞬间抖动会阻塞发号，需双 buffer |\n| Redis INCR | 简单、性能尚可 | 依赖高可用，持久化丢失会回退重号 |\n\n**雪花要点**：41 位时间戳 + 10 位机器 + 12 位序列，单机每毫秒 4096 个。时钟回拨处理要分档：小幅回拨（<5ms）自旋等追平，大幅回拨直接拒绝发号并告警，绝不能拿旧时间戳继续发。workerId 用配置中心或 Zookeeper 分配，容器化环境尤其要防止重复。\n\n**号段双 buffer**：当前段消耗到 10% 时异步加载下一段，正常情况下无阻塞；DB 抖动时靠剩余号段撑住，这是它比「每次查库取 ID」强的地方。Leaf-segment 还支持按 biz_tag 隔离，不同业务互不影响。\n\n**权衡**：连续 ID 会暴露业务量（竞对能从订单号推算日单量），敏感业务用带随机序列的方案或做号段加密映射；要求严格递增的对账流水号，用号段更合适。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 64 MINUTE), 1),
  (465, 2, '跨分片 JOIN 与聚合：为什么要在设计阶段就禁止，路由层怎么补', '订单按 user_id 分片后，运营要「按商品维度统计销量」，SQL 无法在单个分片完成。请说明跨分片 JOIN、ORDER BY、COUNT(DISTINCT) 的执行代价，中间件（如 ShardingSphere）的处理方式，以及架构上的解法。', '**结论**：跨分片 JOIN 的本质是把「数据库内的归并」降级成「内存或网络的归并」，代价随分片数线性放大。必须在设计阶段通过分片键选择或冗余表规避，而不是靠中间件硬扛。\n\n**代价分析**：\n- **JOIN**：中间件要么把驱动表结果拆成 N 份下发（N 次网络往返），要么做内存归并/Hash Join，结果集可能放大到 OOM；\n- **ORDER BY + LIMIT**：每个分片都要返回 offset+limit 行，中间件再归并排序，深分页时开销是 N 倍；\n- **COUNT(DISTINCT)**：无法简单相加，必须把去重列全部拉回内存去重；\n- **AVG**：不能对各分片的 AVG 再求平均，要拆成 SUM 与 COUNT 分别归并再相除。\n\n**中间件的做法**：ShardingSphere 提供归并引擎（内存归并、流式归并、装饰归并），并通过配置降低跨片代价：**绑定表**让同分片键的表 JOIN 下推为单分片操作（订单与订单明细都按 user_id 分片）；**广播表**让小字典表在每个分片各存一份，JOIN 本地完成。绑定表是性价比最高的一招。\n\n**架构解法**：\n1. 选高基数、覆盖绝大多数查询的分片键（user_id / tenant_id），把跨片查询收敛成少数场景；\n2. 冗余与反范式：把商品名、店铺名冗余进订单，从源头消除 JOIN；\n3. 异构索引表：另建一份按 sku_id 分片的统计宽表，由 binlog + Canal/Flink 同步；\n4. 报表类需求走数仓、ES 或 ClickHouse，别让 OLTP 分片库承担分析查询。\n\n**底线**：分片键定错后改造成本极高，设计时把 Top 10 查询逐条列出核对路由结果，比事后优化便宜得多。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 65 MINUTE), 1),
  (466, 2, 'MySQL XA、Seata AT 与本地消息表：三种分布式事务的落地边界', '跨库转账要保证两个库的扣减与入账同时成功。请对比 MySQL XA（两阶段提交）、Seata AT（自动补偿）与本地消息表 + 最终一致三种方案的一致性强度、性能与运维成本，并说明各自不适合的场景。', '**结论**：强一致（XA、Seata AT）换来的是更长的事务持有时间与更低吞吐；最终一致（本地消息表、事务消息）换来可用性与性能，但要求业务能接受短暂不一致，并具备幂等与重试能力。\n\n**MySQL XA**：`XA START / XA END / XA PREPARE / XA COMMIT`，数据库层真正实现 2PC，一致性最强。代价是：\n- 从 prepare 到 commit 期间一直持有行锁与连接，跨服务调用把持锁时间拉到毫秒级以上；\n- 协调者宕机会留下 in-doubt 事务，需要人工或守护程序处理悬挂与空回滚；\n- 实测吞吐常比单库下降一个数量级。\n适合内部两三个库、低并发但要求强一致的场景（资金冻结、券核销）。\n\n**Seata AT**：一阶段直接提交本地事务并把前后镜像写进 `undo_log`，二阶段异步删除或反向补偿，靠全局锁保证写隔离。优点是对业务几乎无侵入，缺点是全局锁增加冲突、`undo_log` 膨胀，热点行更新不适合。\n\n**本地消息表 / 事务消息**：业务写与「消息记录」在同一本地事务里提交，再由投递器（或 RocketMQ 事务消息）异步投递，下游幂等消费 + 重试 + 对账兜底。性能最好、可用性最高，缺点是只保证最终一致，必须实现幂等键与定时对账。\n\n**选型建议**：能不用分布式事务就不用——通过「同库同事务」或把相关数据收敛到一个聚合根来消除跨库需求；必须跨库时优先本地消息表 + 对账，只有强一致硬要求才上 XA/Seata，并严格限制事务时长与并发量。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 66 MINUTE), 1),
  (467, 2, '分片扩容与数据迁移：双写、影子表与一致性校验怎么做', '分片从 4 个扩到 8 个，要求不停机迁移。请说明「双写 + 存量搬迁 + 增量追平 + 校验切换」的完整流程，以及迁移窗口内读到旧分片、双写失败、校验误报这三类问题如何规避。', '**结论**：扩容的核心是「新旧路由并存 → 双写与回补 → 追平校验 → 灰度切读 → 禁用旧写」。顺序上必须**先切读、再停旧写**，否则会丢写入；任何一步跳过校验，都会留下长期不一致。\n\n**四阶段**：\n1. **准备**：新分片建表，按旧分片键范围做存量搬迁（分批、按主键游标、小事务提交，避免长事务与锁等待）。\n2. **双写**：新写入同时落旧位置与新位置。跨库无法放进同一事务，实践上以**旧库为准**，新库失败只记录并进入补偿队列重试，保证「至少一次」而不是「可能丢失」。\n3. **追平与校验**：订阅 binlog（Canal/Flink）持续补增量，直到延迟接近 0；再按分片键分组、按主键分页做全量 diff——比行数、比关键列校验和，差异行单独修复。校验必须基于同一快照位点，否则主从延迟会造成大量误报。\n4. **切换**：灰度把读流量按 1%→10%→100% 切到新分片，观察错误率与延迟；全量切读后把旧库设为 `super_read_only`，再跑一轮校验确认无新差异，最后下线旧表并清理双写代码。\n\n**三类坑**：\n- 双写期间混读会导致「刚写的数据读不到」，因此双写阶段固定读旧库，不要提前放开新库读；\n- 迁移工具重启后必须能断点续跑，游标与补偿队列都要持久化；\n- 校验要忽略时间戳、自增列等天然差异列，否则 diff 永远是噪音。\n\n**更省事的替代**：一致性哈希能让扩容只搬迁 1/N 的数据；分片数一次规划够（如直接留 1024 个逻辑分片映射到少量物理库），避免反复迁移。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 67 MINUTE), 1),
  (468, 2, 'InnoDB 表空间的段、区、页三级结构，以及为什么按区分配', 'InnoDB 以页为最小 IO 单位。请说明页、区（extent）、段、表空间的层级关系，为什么分配要以区为单位而不是按页，以及一个区默认包含多少页。', '**结论**：InnoDB 的存储层级是「表空间 → 段 → 区 → 页」。**分配按区、IO 按页**，目的是让逻辑上连续的页在物理上也连续，把顺序访问真正变成顺序 IO。\n\n**各层含义**：\n- **页（16KB）**：最小 IO 单位，也是 Buffer Pool 的缓存单位。数据页内部依次是 File Header、Page Header、Infimum/Supremum、User Records、Free Space、Page Directory、File Trailer。\n- **区（1MB）**：`innodb_page_size=16K` 时是 64 个连续页。若每次只分配单页，B+ 树叶子顺序扫描时页的物理位置随机，顺序扫描会退化成随机 IO；按 64 页连续分配后，一次预读就能命中一整片，范围扫描效率大幅提升。\n- **段**：一组区的集合。每个索引有两个段（叶子节点段、非叶子节点段），此外还有回滚段、undo 段。段让「大树」按需增长而不必预留连续空间。\n- **表空间**：`ibdata1` 系统表空间、`*.ibd` 独立表空间（`innodb_file_per_table=ON` 为默认）、undo 表空间与临时表空间。\n\n**由此可以解释的现象**：\n- 按主键顺序插入快，因为顺序填充区、几乎不页分裂；随机主键会频繁分裂并产生碎片；\n- 表空间文件只涨不缩，因为区被释放后仍留在表空间内复用；\n- 大字段会 off-page 存放，行内只留 20 字节指针；\n- 页内空闲低于 `MERGE_THRESHOLD`（默认 50%）时，相邻页可能合并。\n\n**可观察点**：`INFORMATION_SCHEMA.INNODB_TABLESPACES` 与 `INNODB_TABLESTATS` 能看到页数、区数与碎片情况，是评估表膨胀的第一手数据。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 68 MINUTE), 1),
  (469, 2, '为什么互联网团队普遍禁用外键：级联锁、DDL 限制与分库分表冲突', '外键能保证引用完整性，但多数互联网业务明确禁用。请说明外键在并发写入时带来的锁行为、对 DDL 与在线变更的影响、与分库分表的根本冲突，以及不用外键时如何保证一致性。\n\n```sql\nALTER TABLE t_order ADD CONSTRAINT fk_user\n  FOREIGN KEY (user_id) REFERENCES t_user(id) ON DELETE CASCADE;\n```', '**结论**：外键把「跨表一致性」的代价转移到数据库内核的锁与检查路径上。在高并发写入、频繁变更结构、需要分库分表的互联网场景里，它的收益远小于成本。\n\n**四个具体问题**：\n1. **额外的锁与校验**：向子表插入时，InnoDB 要对父表对应行加 S 锁做存在性检查。并发写同一父行时形成热点，甚至与业务锁交叉导致死锁；`ON DELETE CASCADE` 把锁扩散到多张表，事务持锁时间不可控。\n2. **DDL 与在线变更受限**：父表被引用后，改字段类型、改字符集、甚至部分在线工具都受牵连；`foreign_key_checks=0` 只能临时绕过检查，无法解除元数据依赖。\n3. **分库分表下直接失效**：外键只在同一实例内成立，跨库、跨分片无法建立约束，一旦分片就必须全部拆掉，属于架构上的死路。\n4. **导入与归档麻烦**：批量导入、逻辑删除、数据归档都要按依赖顺序处理，gh-ost/pt-osc 重建表时外键处理尤其琐碎。\n\n**不用外键如何保证一致性**：\n- 应用层在同一本地事务内「先校验再写入」，或用 `INSERT ... SELECT` 带条件写入；\n- 删除走逻辑删除 + 状态机，避免产生悬垂引用；\n- 定时对账任务扫描孤儿行（子表 user_id 在父表不存在）；\n- 真正的跨库引用交给业务编排（Saga、消息 + 补偿）保证最终一致。\n\n**例外**：内部管理系统、数据量小、变更少的库，外键依然划算，能省掉大量防御代码。是否禁用取决于团队运维能力与业务规模，不该教条化。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 69 MINUTE), 1),
  (470, 2, '索引基数 cardinality 怎么算，统计信息为什么会误导优化器', '`SHOW INDEX` 里的 `Cardinality` 代表什么，是精确值吗？请说明 InnoDB 采样计算基数的方式、`innodb_stats_persistent` 的影响，以及统计信息失真时有哪些干预手段。\n\n```sql\nSHOW INDEX FROM t_order;\nANALYZE TABLE t_order;\nSELECT * FROM mysql.innodb_index_stats WHERE table_name = ''t_order'';\n```', '**结论**：`Cardinality` 是索引列**去重值个数**的估计值，不是精确值。优化器用它估算「一个等值条件平均命中多少行」，再在多个访问路径间比较成本；它一失真，执行计划就可能选错。\n\n**怎么算**：InnoDB 随机采样 `innodb_stats_persistent_sample_pages`（8.0 默认 20）个叶子页，统计页内不同值个数后按比例外推整表。采样页越少，估算波动越大；大表加数据倾斜时，误差可能达数倍。`innodb_stats_persistent=ON` 时统计信息落盘到 `mysql.innodb_index_stats`，重启不丢；OFF 时打开表就可能重新采样，计划更不稳定。\n\n**失真的典型后果**：\n- 基数被低估 → 以为等值条件命中很多行，放弃索引走全表扫；\n- 基数被高估 → 误判回表成本，选错驱动表或连接顺序；\n- 联合索引的基数是按前缀累计算的，只看某一列容易误判可用性。\n\n**干预手段**：\n1. `ANALYZE TABLE t` 立即重算（会短暂持有 MDL 读锁，大表选低峰）；\n2. 调大 `innodb_stats_persistent_sample_pages` 提升精度；\n3. 8.0 直方图：`ANALYZE TABLE t UPDATE HISTOGRAM ON col WITH 100 BUCKETS`，专门对付倾斜；\n4. 用 `optimizer_trace` 看优化器实际估算的行数，别靠猜；\n5. 极端场景才 `FORCE INDEX`，并在 SQL 注释里写清原因，防止后人误删。\n\n**经验**：基数接近行数说明选择性好（唯一键）；基数远小于行数（性别、状态位）不适合单独建索引；联合索引把高基数列放前面，让前缀就能过滤掉大部分行。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 70 MINUTE), 1),
  (471, 2, '优化器成本模型与 optimizer_trace：一条 SQL 为什么选了错的索引', '两条都能用的索引，优化器为什么选了扫描行数更多的那条？请说明基于成本的优化如何计算 IO 与 CPU 成本、`index dive` 与统计信息外推两种行数估算方式的差异，以及如何用 `optimizer_trace` 定位选择过程。\n\n```sql\nSET optimizer_trace = ''enabled=on'';\nSELECT * FROM t_order WHERE a = 1 AND b = 2;\nSELECT * FROM information_schema.OPTIMIZER_TRACE;\n```', '**结论**：MySQL 用基于成本的优化器，给每个候选方案算一个成本分，选最低的。成本由 IO（读页）与 CPU（比较、过滤）加权得到，而输入是**统计信息估算的行数**——所以「选错索引」绝大多数是行数估错了，不是优化器有 bug。\n\n**成本模型要点**：\n- `mysql.server_cost` 与 `mysql.engine_cost` 定义了 `row_evaluate_cost`、`io_block_read_cost`、`memory_block_read_cost` 等常数，可调但要慎重；\n- 全表扫描成本 ≈ 聚簇索引页数 × IO 成本 + 行数 × CPU 成本；\n- 二级索引等值成本 ≈ 索引扫描行数 × (索引 IO + 回表 IO) + 过滤 CPU；\n- 当预估回表行数占比过高（经验上超过两三成），优化器会认为顺序扫全表更便宜，于是放弃索引——这正是「有索引却全表扫」最常见的原因。\n\n**两种行数估算**：\n- **index dive**：对等值/范围条件直接深入 B+ 树统计，准确但有代价；当 `IN` 列表长度超过 `eq_range_index_dive_limit`（默认 200）时退化为统计外推，误差变大；\n- **index statistics**：用基数与页数外推，便宜但粗糙，倾斜数据上偏差很大。\n\n**用 optimizer_trace 定位**：开启后执行 SQL，从 `information_schema.OPTIMIZER_TRACE` 的 JSON 里看 `rows_estimation`、`considered_executions` 与各方案的 `cost_info`，能直接读出「优化器以为扫多少行、算了多少成本」，从而判断是统计信息问题还是成本常数问题。\n\n**处理顺序**：`ANALYZE TABLE` 刷新统计 → 建更贴合的联合索引或覆盖索引降低回表成本 → 调整 `eq_range_index_dive_limit` 或直方图 → 最后才是 `FORCE INDEX` 并记录原因。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 71 MINUTE), 1),
  (472, 2, 'index merge 的三种形态与「用了索引反而更慢」的陷阱', '`EXPLAIN` 里出现 `type=index_merge` 意味着什么？请说明 intersect、union、sort_union 三种形态的适用条件，以及为什么它常常比单索引甚至全表扫描更慢。\n\n```sql\nEXPLAIN SELECT * FROM t WHERE a = 1 OR b = 2;\nSET optimizer_switch = ''index_merge=off'';\n```', '**结论**：index merge 是「一次查询用多个索引，再对各索引结果做主键的集合运算」。它在两侧都强过滤的 `OR` 场景下有效，但需要额外的排序去重，回表又是随机 IO，稍不注意就比全表扫描还慢。\n\n**三种形态**：\n- **intersect**：`WHERE a=1 AND b=2`，两个索引各取一批主键做交集，只适合两侧单独都很 selective 的情况；\n- **union**：`WHERE a=1 OR b=2`，两个索引各取一批主键做并集；\n- **sort_union**：用于范围条件（`a>1 OR b<2`），先按主键排序去重再合并，代价高于 union。\n\n**为什么常常更慢**：\n1. 每个索引都要完整扫一遍并取出主键集合，若某侧选择性差，扫描量已经很可观；\n2. 交集/并集需要额外排序与去重，数据量大时会落临时表甚至磁盘；\n3. 合并后的主键集合回表是**随机 IO**，命中行多时远不如全表顺序扫描；\n4. 优化器对它也是按成本估算的，统计不准时容易被误选。\n\n**判断与干预**：\n- `EXPLAIN` 的 `Extra` 会出现 `Using intersect(...)` / `Using union(...)`，`key` 列列出多个索引；\n- `SET optimizer_switch=''index_merge=off''` 可会话级关闭做对比验证，全局修改要评估其他 SQL；\n- 改写：把 `OR` 拆成 `UNION ALL` 再外层去重，或直接建联合索引 `(a, b)` 让一次索引扫描解决。\n\n**经验**：联合索引几乎总比 index merge 稳。只有当两个维度都必须独立索引、且查询写法无法合并时，才容忍它出现，并监控其耗时。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 72 MINUTE), 1),
  (473, 2, '前缀索引的选择性估算与索引长度上限 3072 字节的来历', '给 `VARCHAR(255)` 的 url 列建索引时，为什么要用前缀索引？请说明如何计算前缀的选择性、前缀索引的三大局限，以及 InnoDB 单列索引 3072 字节上限是怎么来的。\n\n```sql\nSELECT COUNT(DISTINCT LEFT(url, 20)) / COUNT(*) AS sel20 FROM t_link;\nALTER TABLE t_link ADD KEY idx_url (url(20));\n```', '**结论**：前缀索引用「列的前 N 个字符」建索引，用可控的精度损失换取索引体积与内存占用的大幅下降。适合长字符串列，代价是它既不能做覆盖索引，也不能支撑排序与唯一性。\n\n**怎么选 N**：算选择性——`COUNT(DISTINCT LEFT(col, N)) / COUNT(*)`，逐步增大 N，直到该比值接近整列的去重比（如 0.95 以上）且增长趋缓。经验上 10~20 个字符通常够用。注意 `utf8mb4` 下前缀长度按**字符**计，索引字节数是 N × 4，`url(20)` 最多占 80 字节。\n\n**三大局限**：\n- **无法覆盖查询**：前缀可能碰撞，`WHERE url = ''...''` 必须回表取完整值再比较，所以 `SELECT url` 仍要回表；\n- **不能避免排序**：`ORDER BY url` 依然 filesort，因为索引里存的是截断值；\n- **不能保证唯一**：`UNIQUE KEY (url(20))` 会把两个不同长 URL 判为重复，业务上不可接受；\n- 另外 `LIKE ''%xxx''` 仍然失效。\n\n**3072 字节上限的来历**：InnoDB 页 16KB，B+ 树一个索引页至少要能容纳两条索引记录，否则无法分裂。`DYNAMIC`/`COMPRESSED` 行格式配合 16KB 页时，单列索引长度上限为 3072 字节；早期 `COMPACT` + `innodb_large_prefix=OFF` 时代只有 767 字节。这正是「utf8mb4 下 `VARCHAR(768)` 建索引报 1071 错误」的原因——`768 × 4 = 3072`，再长就必须用前缀索引或把列改短。\n\n**替代方案**：对 URL、邮箱这类长串，额外存一列 `url_crc`（或 MD5 前 8 字节）建普通/唯一索引，用哈希做等值查找，碰撞由应用层二次校验兜底，效果往往优于短前缀。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 73 MINUTE), 1),
  (474, 2, '函数索引与生成列：把 WHERE 里的函数搬到索引上', '`WHERE DATE(create_time) = ''2024-01-01''` 会让索引失效。除了改写成范围查询，8.0.13 起还能用函数索引。请说明函数索引的实现机制（隐藏生成列）、使用限制，以及它与显式生成列索引的取舍。\n\n```sql\nALTER TABLE t ADD KEY idx_d ( (DATE(create_time)) );\nALTER TABLE t ADD COLUMN d DATE GENERATED ALWAYS AS (DATE(create_time)) VIRTUAL,\n  ADD KEY idx_d2 (d);\n```', '**结论**：函数索引的本质是「建一个隐藏的虚拟生成列，再在它上面建普通索引」，把表达式结果物化进索引。它把函数从**查询时**搬到**写入时**，从而让带函数的条件重新走索引。\n\n**实现机制**：`ADD KEY idx ((expr))` 会在数据字典里创建一个不可见的虚拟生成列，索引建在该列上。写入或更新行时计算表达式并维护索引；查询时若 `WHERE` 中的表达式与索引表达式完全一致，优化器就直接用索引定位，`EXPLAIN` 的 `key` 显示函数索引，`Extra` 里也不再因该表达式而多一层过滤。\n\n**限制**：\n- 表达式必须**确定性**：不能含 `NOW()`、`RAND()`、子查询或非确定 UDF；\n- 必须写法完全匹配，`DATE(t)` 与 `DATE(t + INTERVAL 0 DAY)` 不被视为同一表达式；\n- 索引体积与写入成本增加，表达式复杂、选择性差时得不偿失；\n- 8.0.13 之前不支持，只能用显式生成列绕过。\n\n**与生成列对比**：显式 `GENERATED ALWAYS AS (...) VIRTUAL` + 普通索引效果等价，但生成列可见、可被 `SELECT` 引用、可被多个索引复用，语义更清晰；函数索引更简洁，适合临时或单点优化。JSON 字段抽取、加密列哈希这类场景更常用显式生成列。\n\n**实践建议**：首选改写 SQL 为范围条件（`create_time >= ''2024-01-01'' AND create_time < ''2024-01-02''`），零额外存储、零写入放大；只有当 SQL 无法修改（ORM 固定条件、第三方报表、审计查询）时才上函数索引，并实测写入性能影响。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 74 MINUTE), 1),
  (475, 2, '索引跳跃扫描 skip scan：缺最左列还能用上 (a,b) 索引吗', '联合索引 `(a, b)`，查询 `WHERE b = 2` 缺少最左列。请说明 8.0.13 引入的 Skip Scan 在什么条件下能利用该索引、优化器为什么常常不选它，以及在 EXPLAIN 上如何确认。\n\n```sql\nEXPLAIN SELECT * FROM t WHERE b = 2;\nSET optimizer_switch = ''skip_scan=on'';\n```', '**结论**：Skip Scan 让缺少最左列的查询也能用上联合索引，但前提是**最左列基数足够低**。做法是枚举 a 的每个不同值，对每个值执行一次 `a = 常数 AND b = 2` 的索引定位——用多几次 B+ 树下降，换掉一次全表扫描。\n\n**生效条件**（缺一不可）：\n1. 缺失的最左列基数低（status、type 这类只有几个值），否则枚举成本爆炸；\n2. 后续列选择性较好，值得为它做多次定位；\n3. 索引中没有 `a` 的条件——若带了 `a`，就退化为普通最左前缀，不需要 skip scan；\n4. 优化器估算总成本低于全表扫描。这一条最要命，实践中经常不满足。\n\n**为什么常不选**：优化器要估「a 的去重值个数 × 每次定位成本」。若统计显示 a 有上千个不同值，直接放弃；`SELECT *` 还要回表，回表成本会把总成本进一步推高。所以它只能算兜底能力，不能当作可依赖的优化手段。\n\n**如何确认**：`EXPLAIN` 的 `key` 显示该联合索引，`Extra` 可能出现 `Using index for skip scan`；`EXPLAIN FORMAT=JSON` 里能看到 skip scan 相关标记。也可用 `optimizer_switch=''skip_scan=off''` 对比计划与耗时，验证是否真有收益。\n\n**正确做法**：不要指望 skip scan。要么建以 b 为最左的索引 `(b)` 或 `(b, a)`，要么在业务上补一个前置条件（缩小时间范围或类型），要么用覆盖索引减少回表。skip scan 的意义是「少建一个索引也能跑」，不是「索引设计可以不讲最左前缀」。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 75 MINUTE), 1),
  (476, 2, '直方图 histogram 解决的是哪一类数据倾斜导致的估算失真', '某列严重倾斜（95% 的行 status=0），优化器却按平均值估算命中行数，导致选错计划。请说明 MySQL 8.0 直方图的原理、两种 bucket 类型，以及它与索引统计信息的区别与维护方式。\n\n```sql\nANALYZE TABLE t_order UPDATE HISTOGRAM ON status WITH 32 BUCKETS;\nSHOW INDEX FROM t_order;\n```', '**结论**：直方图解决「值分布极不均匀」时的行数估算问题。它把列的取值分布切成若干桶存入数据字典，让优化器知道「这个具体值占多少行」，而不是用 `总行数 / 基数` 的平均值去猜。\n\n**为什么需要**：`Cardinality` 只说「有多少个不同值」，不说每个值各占多少。数据倾斜时（status 95% 为 0、5% 为 1），平均值估算会把 `status=1` 估成约一半行数，于是优化器可能放弃索引、或选错连接顺序。\n\n**两种 bucket 类型**：\n- **singleton（等高）**：每桶存一个具体值及其频率，桶数等于不同值个数（不超过指定上限），最精确，适合不同值较少的列；\n- **equi-height（等频）**：把数据按频率切成 N 段，每段行数大致相同，桶内存区间上下界与累计频率，适合不同值很多的列。\n\n**使用与维护**：`ANALYZE TABLE ... UPDATE HISTOGRAM ON col WITH N BUCKETS`，N 最大 1000、默认 100；关键在于**直方图不会自动更新**，数据分布变化后要手动或定时重建；`DROP HISTOGRAM ON col` 删除。它只影响过滤行数的估算，不能替代索引本身。\n\n**与索引统计的区别**：索引统计由 InnoDB 采样维护，只覆盖索引列，用于估算索引范围扫描行数；直方图由 server 层维护，可作用于**任意列**（包括没建索引的列），主要影响「用不用索引、按什么顺序连接」。两者互补，不冲突。\n\n**实践**：倾斜列 + 多条件查询 + 执行计划飘忽，是直方图的典型适用场景。建完后用 `EXPLAIN` 对比 `rows` 是否更贴近真实值、耗时是否改善，再决定保留；对结果稳定的列没必要长期维护直方图。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 76 MINUTE), 1),
  (477, 2, '派生表是合并还是物化：8.0 的 derived condition pushdown 带来了什么', '`SELECT * FROM (SELECT ...) d WHERE d.x = 1` 这样的派生表，优化器有时合并（merge）、有时物化（materialize）。请说明两者的判定条件、物化的代价，以及 8.0.22 的 derived condition pushdown 解决了什么问题。\n\n```sql\nSELECT * FROM (\n  SELECT user_id, SUM(amount) AS amt FROM t_order GROUP BY user_id\n) d WHERE d.user_id = 100;\n```', '**结论**：派生表能被**合并**时，外层条件会与子查询合成一条查询，索引照常生效；不能合并时必须**物化**成内部临时表再查，外层条件往往无法下推，于是先全量物化再过滤。\n\n**合并的判定**：`derived_merge` 优化（5.7 起默认开启）要求派生表不含 `GROUP BY`、`DISTINCT`、`LIMIT`、聚合函数、窗口函数、`UNION` 等。示例里有 `GROUP BY`，因此走物化。\n\n**物化的代价**：子查询结果写进内部临时表（8.0 用 TempTable 引擎，超限落盘），外层再扫这张没有索引的临时表。行数大时，`d.user_id = 100` 只能在临时表上顺序过滤，前一步的全量聚合完全白算。\n\n**8.0.22 的 derived condition pushdown**：允许把外层的条件下推到派生表内部，在物化之前就参与过滤，从而减少物化行数。对含 `GROUP BY` 的派生表，只有能安全下推的条件（如分组列上的等值条件）才生效，聚合结果列上的条件仍需在外层判断。该优化可用 `optimizer_switch=''derived_condition_pushdown=off''` 关闭做对比。\n\n**优化方向**：\n- 尽量让派生表可合并：去掉不必要的 `GROUP BY`、`DISTINCT`；\n- 必须聚合时把条件写进子查询内部（`WHERE user_id IN (...)`、`HAVING`），而不是留给外层；\n- `EXPLAIN` 看 `select_type=DERIVED` 与 `Extra` 中的 `Using temporary`，`EXPLAIN FORMAT=JSON` 能看到是否发生物化与下推；\n- 复杂报表直接改写为 JOIN 或临时表分步计算，比让优化器猜更可控。\n\n**经验**：派生表物化是「隐形的性能杀手」，它不报错、不告警，只在慢查询日志里表现为耗时数秒。看到 `DERIVED` + 大表聚合，优先怀疑它。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 77 MINUTE), 1),
  (478, 2, '子查询优化：semi-join 的五种执行策略与 exists 改写', '`WHERE id IN (SELECT ...)` 与 `WHERE EXISTS (...)` 在 MySQL 里到底怎么执行？请说明 semi-join 的五种策略（table pullout、firstmatch、loosescan、materialization、duplicate weedout），以及什么情况下会退化成逐行执行的相关子查询。\n\n```sql\nSELECT * FROM t_user u\nWHERE u.id IN (SELECT o.user_id FROM t_order o WHERE o.amount > 100);\n```', '**结论**：`IN` / `EXISTS` 子查询在 5.6+ 通常被改写成 semi-join（半连接，只判断「存在」不产生重复行），优化器在五种策略里挑成本最低的一种；只有无法半连接化时才退化成逐行执行的相关子查询。\n\n**五种策略**：\n1. **Table pullout**：子查询只涉及同一张表的等值条件时，把表直接提到外层 JOIN，最优；\n2. **FirstMatch**：对每个外层行，在子查询表里找到第一条匹配即停，依赖子查询表上的索引（`ref` 访问），避免重复扫描；\n3. **LooseScan**：匹配列位于索引前缀时跳跃扫描去重，适合「子查询表大但去重值少」；\n4. **Materialization**：把子查询结果物化成带唯一索引的临时表再 JOIN，适合子查询大、外层小，代价是写临时表；\n5. **DuplicateWeedout**：先普通 JOIN 再用临时表按主键去重，代价是临时表 + 去重开销。\n\n**退化为 DEPENDENT SUBQUERY**：子查询含 `LIMIT`、无法改写的 `UNION`、聚合函数，或 `NOT IN` 遇到可空列（无法安全半连接）时，`EXPLAIN` 的 `select_type` 会显示 `DEPENDENT SUBQUERY`——外层每行执行一次子查询，是典型的最坏情况。\n\n**改写建议**：\n- 先确认 `select_type`，出现 `DEPENDENT SUBQUERY` 必须处理；\n- `IN` 子查询的连接列上必须有索引，否则 materialization 可能比原来的写法更慢；\n- `NOT IN` 在子查询返回 NULL 时整体结果为空（三值逻辑陷阱），改 `NOT EXISTS` 或 `LEFT JOIN ... IS NULL`；\n- 子查询返回百万行时物化临时表会吃内存与磁盘，应改为分批或 JOIN。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 78 MINUTE), 1),
  (479, 2, 'MySQL 8.0 的 Hash Join 与 BNL、BKA 的关系与触发条件', '8.0.18 引入 Hash Join 后，很多执行计划里的 `Block Nested Loop` 消失了。请说明 Hash Join 的构建/探测两阶段、它与 BNL、BKA 的关系，以及为什么非等值 JOIN 仍然要用块嵌套循环。\n\n```sql\nEXPLAIN FORMAT=TREE\nSELECT * FROM t_order o JOIN t_user u ON o.user_id = u.id;\n```', '**结论**：Hash Join 用「把小表建成哈希表、再扫大表逐行探测」，把 JOIN 的比较复杂度从 O(n×m) 降到 O(n+m)，而且不要求被驱动表上有索引。它是 BNL 在等值连接场景下的现代替代品。\n\n**两阶段**：构建阶段读入较小的一侧（优化器按行数与过滤后大小选构建侧），在内存里建哈希表；探测阶段扫另一侧，用连接键查表。内存不足时（受 `join_buffer_size` 限制）会分区落盘做 grace hash join，性能下降但通常仍优于 BNL。\n\n**与 BNL、BKA 的关系**：\n- **BNL**：把驱动表一批行读进 join buffer，再扫被驱动表逐行比较，比较次数是乘积，纯 CPU 消耗；被驱动表无索引时的老方案。\n- **BKA**：被驱动表**有索引**时的优化，把驱动表的主键批量排序后回表，把随机 IO 变成近似顺序 IO，需开启 `batched_key_access`。\n- **Hash Join**：8.0.18 起用于等值 JOIN 替代 BNL，`EXPLAIN` 显示 `Using join buffer (hash join)`；BKA 在索引场景下依然独立存在。\n\n**触发条件**：连接条件为**等值**且被驱动表没有可用索引时才优先走 Hash Join；有合适索引时优化器通常仍选 NLJ + ref，因为索引定位成本更低。\n\n**为什么 BNL 没消失**：非等值连接（`<`、`>`、`BETWEEN`、`LIKE`）无法建哈希表，只能用块嵌套；部分外连接与半连接场景也仍会使用。所以看到 `Block Nested Loop` 的第一反应应是：能否加索引，或能否把条件改成等值。\n\n**实践**：Hash Join 不是免优化金牌——构建侧选错会把大表塞进内存导致落盘；`join_buffer_size` 要匹配实际数据量，并关注慢查询里 `hash join` 的落盘迹象。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 79 MINUTE), 1),
  (480, 2, '内部临时表与 TempTable 引擎：哪些写法会落盘，怎么避免', '哪些 SQL 会用到内部临时表？8.0 的 TempTable 引擎相比 MEMORY 引擎改进了什么？请说明 `internal_tmp_mem_storage_engine`、`temptable_max_ram` 与落盘条件，以及如何发现临时表已经落盘。\n\n```sql\nSHOW STATUS LIKE ''Created_tmp%'';\nEXPLAIN SELECT DISTINCT city FROM t_user ORDER BY city;\n```', '**结论**：内部临时表是 SQL 执行过程中自己创建的表，用于 `GROUP BY`、`DISTINCT`、`UNION`、派生表物化、无法用索引的 `ORDER BY` 等。它在内存起步，超阈值就落盘，落盘后性能往往下降一个数量级。\n\n**8.0 的 TempTable 引擎**：替代旧的 MEMORY 引擎处理内部临时表，改进点包括：\n- 变长存储，不像 MEMORY 按最大长度定长分配，`VARCHAR` 不再浪费内存；\n- 支持 BLOB/TEXT 类型（MEMORY 不支持，以前只能直接落盘）；\n- 内存中的临时表可建 hash 索引，`GROUP BY` 显著更快；\n- 由 `temptable_max_ram`（默认 1GB）控制内存上限，超过后先尝试 mmap 临时文件，再落 InnoDB 临时表空间。\n\n**落盘条件**：超过 `temptable_max_ram` → 使用 `temptable_use_mmap`（8.0.16+，默认 ON）映射文件 → 再超 `temptable_max_mmap` 则写入 `ibtmp1`，而 `ibtmp1` 只增不减。\n\n**如何发现**：`Created_tmp_tables`（创建总数）、`Created_tmp_disk_tables`（落盘数）、`Created_tmp_files`；`EXPLAIN` 的 `Extra` 出现 `Using temporary`。`Created_tmp_disk_tables / Created_tmp_tables` 比例偏高就必须治理。\n\n**常见诱因与改写**：\n- `GROUP BY` 列无索引 → 建索引让分组有序扫描；\n- 多列 `DISTINCT` 且无索引 → 先确认业务是否真的需要；\n- `UNION` 去重 → 业务允许时改 `UNION ALL`；\n- `ORDER BY` 与 `WHERE` 用的索引不一致 → 建联合索引同时兼顾过滤与排序；\n- 派生表被物化 → 尽量让 `derived_merge` 生效。\n\n**注意**：临时表按连接私有，长事务 + 大临时表会长期占用空间；`ibtmp1` 暴涨通常意味着某条 SQL 在疯狂落盘。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 80 MINUTE), 1),
  (481, 2, 'SELECT ... FOR UPDATE SKIP LOCKED：用数据库做任务队列的正确姿势', '多实例消费同一张任务表时如何避免抢到同一行？请说明 `FOR UPDATE SKIP LOCKED` 的语义、它与 `NOWAIT` 的区别，以及这一模式在长事务、崩溃恢复与主从延迟上的坑。\n\n```sql\nSTART TRANSACTION;\nSELECT id FROM t_job WHERE status = 0 ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;\nUPDATE t_job SET status = 1, worker = ''w1'' WHERE id = 1001;\nCOMMIT;\n```', '**结论**：`SKIP LOCKED` 让「已被其他事务锁住的行」直接从结果集里跳过，而不是排队等待。多个消费者因此各自拿到不同的行，天然实现并行分片消费，不需要额外的分布式锁。\n\n**与 NOWAIT 的区别**：`NOWAIT` 是「撞到锁立刻报错」，适合「抢不到就算了」的交互式场景；`SKIP LOCKED` 是「跳过这批、继续找下一批」，适合队列式消费。两者都避免长时间锁等待。\n\n**语义要点**：只对**当前读**（`FOR UPDATE` / `FOR SHARE` 所在语句）生效，普通快照读不受影响；被跳过的行不出现在结果里，也不保证公平顺序（按索引扫描顺序取第一条未被锁的行）。\n\n**为什么高效**：传统 `SELECT ... FOR UPDATE` 在同一行上串行排队，消费吞吐被单行锁限制；`SKIP LOCKED` 把等待变成跳过，消费者并行度随实例数线性提升。配合 `status` 索引与 `ORDER BY id LIMIT 1` 效果最好。\n\n**四个必须注意的坑**：\n1. **事务要短**：锁在提交前一直持有。正确姿势是「取任务 → 立即提交 → 事务外处理 → 再更新状态」，不要把业务处理放在事务里；\n2. **崩溃恢复**：进程挂掉会让行卡在「处理中」，需要 `processing_at` 字段 + 超时回收；\n3. **主从延迟**：只能在主库用，从库上读不到最新状态；\n4. **索引必须命中**：没走索引时会扫大量行，甚至退化成锁住大范围记录。\n\n**适用边界**：中小规模可靠队列完全够用，省一个中间件；万级 QPS 以上应改用 Kafka/RocketMQ，数据库只做兜底与对账。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 81 MINUTE), 1),
  (482, 2, '插入意向锁：唯一键冲突为什么会引发死锁', '两个事务并发 `INSERT` 相同的唯一键，可能一个成功、一个报 1213 死锁。请说明插入意向锁（insert intention lock）的语义、唯一键冲突时的加锁过程，以及并发写入同一批键值时的规避方案。\n\n```sql\nINSERT INTO t_user (mobile, name) VALUES (''13800138000'', ''a'');\n-- 另一会话同时执行同样的 INSERT，可能返回 Deadlock found\n```', '**结论**：插入意向锁是「我要在这个间隙里插一条」的表态，多个插入意向锁彼此兼容；但一旦发生唯一键冲突，后到的事务必须加 **S 锁**读取已存在的那条记录以确认冲突，若前一个事务已持有该记录的 X 锁，就形成等待环。\n\n**加锁过程**：\n1. `INSERT` 在插入位置加插入意向锁（gap 锁的特例，仅在插入瞬间持有）；\n2. 唯一性检查发现已存在相同值，InnoDB 对该记录加 S 锁（当前读校验，RC 与 RR 下都会加）；\n3. 这个 S 锁会一直持有到事务结束——**即使 INSERT 最终以 1062 失败**；\n4. 两个事务交叉持有 X 与 S、或都在等对方释放，就构成死锁。\n\n**典型触发场景**：并发插入相同唯一键；并发 `INSERT ... ON DUPLICATE KEY UPDATE`；批量 `INSERT IGNORE`；甚至 RC 下没有间隙锁也照样发生。\n\n**规避方案**：\n- 用 `INSERT IGNORE` / `ON DUPLICATE KEY UPDATE` 并不能免疫死锁，**必须捕获 1213 并重试**；\n- 把并发插入串行化：按唯一键哈希分桶做应用层锁，或投递到单队列写入；\n- 批量导入前先 `SELECT` 过滤已存在的键，降低冲突概率（无法根除）；\n- 事务保持极短，冲突后立刻结束事务，不要继续做其他写入；\n- 必要时降隔离级别到 RC，减少间隙锁带来的额外冲突面。\n\n**排查**：`SHOW ENGINE INNODB STATUS` 的 `LATEST DETECTED DEADLOCK` 会明确写出 `insert intention waiting` 与持有 S 锁的事务，这是最直接的证据；8.0 也可查 `performance_schema.data_lock_waits`。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 82 MINUTE), 1),
  (483, 2, '自增主键为什么不连续：批量预分配、回滚与 autoinc lock mode', '自增主键出现跳号（1、2、5、6、100…）是 bug 吗？请说明批量插入时的预分配机制、回滚与唯一键冲突造成的空洞、`innodb_autoinc_lock_mode` 三种模式的影响，以及为什么业务不能依赖自增 id 连续。\n\n```sql\nINSERT INTO t (a) VALUES (1), (2), (3);\nSHOW VARIABLES LIKE ''innodb_autoinc_lock_mode'';\n```', '**结论**：自增主键**只保证唯一与递增，不保证连续**。跳号是 InnoDB 为并发性能主动做的「预分配」，属于设计如此，不是缺陷。\n\n**空洞的三个来源**：\n1. **批量预分配**：`INSERT ... VALUES (...),(...),(...)` 时一次性申请 N 个值，若语句中途失败（如唯一键冲突）只用掉一部分，剩余号作废；8.0 默认的交错模式下，同一语句拿到的值也可能不连续。\n2. **回滚**：自增值一旦分配就**不回退**，`ROLLBACK` 之后这些号成为永久空洞。\n3. **REPLACE INTO / INSERT IGNORE / 唯一键冲突**：删除重建类语句与失败写入同样消耗自增值。\n\n**三种 lock mode**：\n| 模式 | 行为 | 连续性 |\n|---|---|---|\n| 0 传统 | 语句级 AUTO-INC 表锁，持有到语句结束 | 连续，但并发插入差 |\n| 1 连续（5.7 默认） | 简单插入可预知数量，语句结束即释放 | 批量插入仍连续 |\n| 2 交错（8.0 默认） | 多语句并行分配，性能最好 | 不保证连续，且需 ROW 格式 binlog |\n\n**工程含义**：\n- 不要用「max(id) + 1」生成业务编号，也不要靠 id 连续判断有无丢数据；\n- 订单号、流水号不要直接用自增 id，既暴露业务量，也无法支撑分库分表；\n- 统计条数用 `COUNT(*)`，别用 `MAX(id) - MIN(id)`；\n- 主从切换、重启后自增起点可能跳跃，属于正常现象。\n\n**确实需要连续号时**：用独立的号段表在事务内 `UPDATE ... SET next = next + 1` 再读取，代价是串行化，只建议用在发票号、凭证号这类强需求场景。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 83 MINUTE), 1),
  (484, 2, '大量 DELETE 之后磁盘不降：表碎片、页填充率与 OPTIMIZE 的代价', '删除 60% 数据后，`data_free` 很大但表文件几乎不变。请说明 InnoDB「删除只标记不回收」的机制、页填充率与碎片如何形成、`OPTIMIZE TABLE` 的真实代价，以及线上大表的替代方案。\n\n```sql\nSELECT table_name, data_length, data_free FROM information_schema.TABLES\nWHERE table_schema = ''db1'';\nOPTIMIZE TABLE t_order;\n```', '**结论**：InnoDB 的 `DELETE` 只是把行标记删除、把空间还给页内的 Free Space，**不归还给操作系统**。页内空洞只能被后续插入同页的数据复用；整页空了才回到本表的空闲页链表，文件依然不缩小。\n\n**碎片怎么形成**：随机主键或频繁删除会让页填充率下降、页的物理顺序与逻辑顺序不一致，范围扫描要读更多页，即更多 IO。`data_free` 表示「已分配但未使用的字节数」，可粗略反映碎片程度，但受区（1MB）粒度影响，小表上看不出来。\n\n**重建的代价**：\n- `OPTIMIZE TABLE t` 等价于 `ALTER TABLE t ENGINE=InnoDB`：重建表 + 重建全部索引 + 更新统计信息。8.0 支持 `ALGORITHM=INPLACE` 但仍需约等于表大小的额外磁盘空间，产生大量 IO 与 binlog，结束时还要短暂获取排他 MDL，**大表上可能阻塞写入数十秒**；\n- `ALTER TABLE t FORCE` 效果类似，同样重建。\n\n**线上替代方案**：\n1. **gh-ost / pt-osc**：影子表 + 增量同步 + 原子 rename，可限速可暂停，是大表标准做法；\n2. 按主键分批把数据迁到新表，再 `RENAME TABLE` 原子切换；\n3. 若根因是「历史数据太多」，用**分区表按时间 `DROP PARTITION`** 或定期归档到冷库，比事后重建更治本。\n\n**是否值得做**：几 GB 且查询都走索引的表收益有限；上百 GB 且 `data_free` 占比超过 30% 时收益明显。动手前必须评估磁盘余量、主从延迟与 MDL 阻塞窗口，并优选低峰执行。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 84 MINUTE), 1),
  (485, 2, '大表 ONLINE DDL 与 gh-ost、pt-osc 的取舍与切换风险', '给 2 亿行的表加索引或改字段，直接 `ALTER TABLE` 与用 gh-ost、pt-osc 有什么本质差别？请说明三种 DDL 算法（COPY / INPLACE / INSTANT）、gh-ost 无触发器的原理，以及切换瞬间的风险点。\n\n```sql\nALTER TABLE t_order ADD INDEX idx_ct (create_time), ALGORITHM=INPLACE, LOCK=NONE;\n```', '**结论**：原生 Online DDL 在服务端用「临时日志 + 增量应用」完成，多数加索引场景能做到 `LOCK=NONE`，但仍受 MDL 等待与 row_log 膨胀影响；第三方工具把风险外置到可控的拷贝过程，用影子表 + 增量同步 + 原子改名完成切换。\n\n**三种算法**：\n- **INSTANT**：只改数据字典（8.0 末尾加列、改默认值），秒级完成，不碰数据页；\n- **INPLACE**：不整体拷贝，但可能重建索引或数据，期间允许并发 DML（`LOCK=NONE`）或仅允许读；加二级索引、中间位置加列常见；\n- **COPY**：建新表逐行拷贝，全程阻塞写，大表基本不可用。\n\n**为什么要用 gh-ost/pt-osc**：\n- 原生 INPLACE 在大表上仍可能因 row_log 撑爆、磁盘不足、长事务占着 MDL 而卡死；`ALTER` 开始要拿排他 MDL，一旦排队，后续所有查询都会被一起阻塞，这就是经典的「DDL 雪崩」；\n- pt-osc 用触发器同步增量，有额外开销且部分场景不支持；\n- gh-ost 伪装成从库**读取 binlog** 同步增量（无触发器），支持限流、暂停、干跑演练，切换时 `RENAME TABLE` 原子替换。代价是要求 ROW 格式 binlog、额外磁盘与网络流量。\n\n**切换瞬间的四个风险**：\n1. rename 前必须确认增量已追平（lag 趋近 0），否则会丢最后一批变更；\n2. rename 需要短暂锁表，务必在低峰执行，并提前 `information_schema.innodb_trx` 确认没有长事务；\n3. rename 会写 binlog，从库执行期间可能出现秒级延迟；\n4. 旧表不要立刻删，保留一段时间以便回滚与比对。\n\n**实践**：小表直接 DDL；大表走 gh-ost 并固化流程（MDL 预检 → 限速拷贝 → 观察延迟 → 低峰切换 → 灰度验证 → 保留旧表）。\n', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 85 MINUTE), 1),
  (486, 2, 'INSTANT ADD COLUMN 的原理，以及哪些 DDL 仍然必须重建表', '8.0 的 `ALTER TABLE ... ADD COLUMN` 为什么有时秒级完成、有时要跑几小时？请说明 INSTANT 算法的实现（数据字典记录默认值）、支持与不支持的操作，以及 8.0.29 前后「列位置」的变化与降级风险。\n\n```sql\nALTER TABLE t_order ADD COLUMN remark VARCHAR(100) DEFAULT '''', ALGORITHM=INSTANT;\n```', '**结论**：INSTANT 只改数据字典、不碰任何数据页，所以是常数时间；一旦操作需要改变行的物理布局或索引结构，就只能退化为 INPLACE（重建索引）或 COPY（重建表）。\n\n**原理**：8.0 在数据字典里记录「这一列是在哪个行版本加入的」以及默认值。读取旧行时，若该行版本早于加列版本，就用字典里的默认值补齐，无需回填数据，因此没有 IO 放大。\n\n**支持 INSTANT 的常见操作**：在表**末尾**加列（8.0.12+）、8.0.29 起任意位置加列与删列、修改列默认值、重命名列（8.0）、设置/删除 `AUTO_INCREMENT`、加/删虚拟生成列。\n\n**不支持 INSTANT 的操作**：修改列类型或字符集、修改 `ROW_FORMAT`、加主键、改变可空性、加全文/空间索引——这些通常走 INPLACE 重建，个别只能 COPY。\n\n**8.0.29 的改进**：支持任意位置 `ADD COLUMN` 与 `DROP COLUMN` 走 INSTANT，通过「行版本 + 列顺序映射」实现，代价是读路径多一层判断。\n\n**三个必须知道的坑**：\n1. INSTANT 加列后表的行记录格式与旧版本不兼容，**降级到低版本会打不开表**，回滚前要先 `ALTER TABLE ... FORCE` 重建；\n2. 每次 INSTANT 操作都会增加一个行版本，行版本上限为 64，超过后下一次必须重建表（`FORCE` 可重置计数）；\n3. 显式写 `ALGORITHM=INSTANT`，让不支持的场景直接报错，避免优化器悄悄选了耗时算法导致长时间锁表。\n\n**判断方法**：执行前查 `INFORMATION_SCHEMA.INNODB_TABLES` 看行格式，或用 `ALGORITHM=INSTANT` 试探；生产上仍建议先在同规格的影子实例上试跑并计时。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 86 MINUTE), 1),
  (487, 2, 'MySQL 8.0 数据字典与 information_schema 的性能坑', '8.0 用事务型数据字典替代了 `.frm` 文件。请说明这一变化带来的好处、`information_schema` 查询在大实例上变慢的原因，以及 8.0 为缓解它做的优化（视图、`information_schema_stats_expiry`）。', '**结论**：8.0 把表、列、索引、字符集等元数据从 `.frm`/`.opt` 文件搬进 InnoDB 系统表（`mysql` 库下的数据字典表），带来原子 DDL 与崩溃安全，但也让 `information_schema` 变成「多表 JOIN + 权限过滤」的查询，在几万张表的实例上很容易变慢。\n\n**好处**：\n- **原子 DDL**：元数据变更与存储引擎操作在同一事务内提交，崩溃后不会出现「表结构改了但数据没改」的中间态；\n- 元数据统一存 InnoDB，可参与崩溃恢复、复制与备份，不再依赖文件系统；\n- 消除了 `.frm` 与 InnoDB 数据字典两份真相不同步的老问题。\n\n**为什么 I_S 变慢**：8.0 的 `INFORMATION_SCHEMA` 大多是系统表的**视图**，查询时要把 `mysql.tables`、`mysql.columns`、`mysql.indexes` 等 JOIN 起来，再按当前用户权限逐表过滤。几十万张表时，一次 `SELECT * FROM information_schema.tables` 可能要几秒到几十秒，还会占用 MDL 与 Buffer Pool，影响正常业务。\n\n**8.0 的缓解手段**：\n- `information_schema_stats_expiry`（默认 86400 秒）控制动态统计信息（`TABLES.UPDATE_TIME`、`AUTO_INCREMENT` 等）的缓存时长，未过期直接用缓存，避免每次都打开表取实时值；\n- 部分视图有缓存与优化路径，`SHOW` 语句走更短的代码路径；\n- `performance_schema` 提供了更轻量的元数据与等待视图。\n\n**实践建议**：巡检优先用 `SHOW TABLE STATUS`、`SHOW INDEX`、`performance_schema`，少查全量 `information_schema`；必须查时限定 `TABLE_SCHEMA` 并加 `LIMIT`；长事务持 MDL 会同时阻塞 DDL 与元数据查询，治理长事务一并受益。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 87 MINUTE), 1),
  (488, 2, 'mysqldump 与 XtraBackup：一致性备份的原理与恢复演练', '逻辑备份与物理备份分别适合什么场景？请说明 `mysqldump --single-transaction` 如何保证一致性快照、XtraBackup 的 redo 追平原理，以及「备份成功但恢复失败」的常见原因与演练要点。', '**结论**：逻辑备份（mysqldump）导出 SQL 文本，跨版本、可读、可裁剪，但导出与恢复都慢；物理备份（XtraBackup）直接拷贝数据文件并持续追 redo，速度快、适合大库，但强依赖版本、页大小与配置一致。两者都必须验证「能恢复」，否则等于没有备份。\n\n**mysqldump 的一致性**：`--single-transaction` 在 RR 隔离级别下开启事务并建立一致性快照，之后所有表都在同一快照点导出，不会因并发写入而错位。但它**只对 InnoDB 有效**，MyISAM 表仍可能不一致。配套参数：`--master-data=2`（把 binlog 位点写进注释，用于搭从库与 PITR）、`--set-gtid-purged`、`--routines --triggers --events`、`--default-character-set=utf8mb4`。大库要按表或按 `--where` 分批导出，避免生成单个巨型 SQL 文件导致恢复时事务过大。\n\n**XtraBackup 的原理**：以不阻塞 DML 的方式拷贝 `ibd` 文件，同时**持续拷贝 redo log** 并记录 LSN；备份结束后在 `--prepare` 阶段重放 redo，把数据文件推进到一致状态（相当于做一次崩溃恢复）。因此备份期间必须保证 redo 不被覆盖——`innodb_log_file_size` 太小会让备份直接失败。\n\n**「备份成功但恢复失败」的常见原因**：\n- 备份集与目标实例的版本、`innodb_page_size`、字符集、collation 不一致；\n- 只备份数据没备份 binlog，无法做到 PITR；\n- 恢复时未关闭 `sql_log_bin`，把恢复数据又写进了从库；\n- 独立表空间文件路径/权限不匹配，或未执行 `import tablespace`；\n- 备份文件早已损坏，却从未做过恢复校验。\n\n**演练要点**：定期在隔离实例上完整恢复，校验行数与关键表校验和，记录实测 RTO/RPO；对备份任务本身监控成功率、耗时与备份集体积变化（体积骤降往往意味着备份不完整）。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 88 MINUTE), 1),
  (489, 2, '崩溃恢复的完整流程：redo 前滚、undo 回滚与 binlog 对账', 'MySQL 异常重启后究竟做了哪些事才重新对外服务？请按顺序说明 redo 重放（前滚）、未提交事务回滚（undo）、prepared 事务与 binlog 的对账，以及 doublewrite 在其中的角色。', '**结论**：崩溃恢复分三段——**前滚**重放 redo 补齐已落盘日志对应的页修改、**回滚**用 undo 撤销未提交事务、**对账**用 binlog 判定 prepared 事务该提交还是回滚。三步都完成，数据才重新一致。\n\n**1. 前滚（redo apply）**：从最近一次 checkpoint 的 LSN 开始顺序重放到日志末尾。WAL 保证「日志先于数据页落盘」，凡是提交过的事务，其修改一定能从 redo 恢复。重放是**幂等**的（记录页内物理位置与修改内容，重复应用结果相同），所以可以反复崩溃、反复重放。\n\n**2. 回滚（undo rollback）**：重放结束后扫描事务表，找到状态为 ACTIVE 的未提交事务，按 undo log 反向撤销其修改并释放锁。这一步可能非常久——大事务崩溃后恢复慢，主要慢在这里。因此生产要拆大事务，并关注 `innodb_undo_log_truncate` 与回滚段的健康状况。\n\n**3. 与 binlog 对账**：对状态为 PREPARED 的事务（内部 2PC 的中间态），按 XID 到 binlog 中查找：找到完整事务就提交，找不到就回滚。这一步保证主库数据与 binlog 一致，从库不会拿到主库并不存在的数据。\n\n**doublewrite 的角色**：前滚只能修复「日志已落盘、数据页尚未写」的情况。若崩溃发生在写 16KB 页的中途（页断裂），页本身已损坏，redo 无法在其上重放。doublewrite 先把页顺序写到连续区域并 fsync，再写实际位置；恢复时用完好副本覆盖损坏页，之后 redo 才有意义。\n\n**恢复时长的影响因素**：checkpoint 间隔（脏页多少）、redo 容量、未提交事务的 undo 量、doublewrite 需修复的页数，以及 `innodb_fast_shutdown` 的设置。想让重启更快，就要控制脏页比例与事务大小，而不是简单调小 redo。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 89 MINUTE), 1),
  (490, 2, 'redo log 容量、checkpoint 与刷脏抖动的关系', '把 `innodb_log_file_size` 调大通常能提升写入性能，但也会带来代价。请说明 redo 循环写与 checkpoint 的关系、什么情况下会出现「刷脏跟不上导致写入卡顿」，以及 redo 容量与 `innodb_io_capacity` 该如何配。', '**结论**：redo log 是**循环复用**的固定大小文件组，写满必须推进 checkpoint（把对应脏页刷盘）才能继续写。redo 太小 → checkpoint 频繁、刷脏追不上，写入周期性卡顿；redo 太大 → 崩溃恢复要重放的日志更多。两者需要平衡。\n\n**机制**：\n- redo 以 LSN 递增写入，写到文件末尾回绕到头部；\n- 回绕前必须保证「最早可复用位置」之前的脏页都已落盘，这个位置就是 checkpoint LSN；\n- 当脏页比例逼近 `innodb_max_dirty_pages_pct`（默认 90）或 redo 空间将耗尽时，InnoDB 会触发**强制刷脏**，用户线程被同步占用，表现为写入延迟尖刺。\n\n**典型症状**：`Innodb_log_waits` 持续增长；LOG 段出现 `log waits`；TPS 周期性抖动；写入高峰时主从延迟上升。\n\n**容量与刷脏配比**：\n- `innodb_log_file_size`：建议能容纳 1~2 小时的写入量（经验 1~4GB）；8.0.30 起统一由 `innodb_redo_log_capacity` 管理，支持在线调整；\n- `innodb_io_capacity` / `innodb_io_capacity_max`：告诉 InnoDB 磁盘的 IOPS 能力（SSD 常见 2000/4000 起），设太小会限制刷脏速度，反而制造卡顿；\n- `innodb_max_dirty_pages_pct` 与 `innodb_max_dirty_pages_pct_lwm`：控制脏页上限与提前刷脏水位；\n- `innodb_flush_neighbors`：SSD 上应设为 0，避免刷一页连带刷相邻页，放大写放大。\n\n**权衡**：加大 redo 能显著减少 checkpoint 频率与写放大，但恢复时间变长，且 `容量 × 实例数` 占用磁盘。建议先测量 LSN 增长速率（`Log sequence number` 每秒增量）再定容量。\n\n**验证**：压测时看脏页比例与 `Innodb_log_waits` 增量即可判断。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 90 MINUTE), 1),
  (491, 2, 'doublewrite buffer 为什么必须存在：页断裂与部分写失效', '断电时 16KB 的数据页可能只写了一半，这种「页断裂」为什么 redo 也救不回来？请说明 doublewrite 的写入顺序、恢复时的作用，以及关闭 `innodb_doublewrite` 的收益与风险。', '**结论**：redo 是**物理逻辑日志**——它记录「在某个页的某个偏移处改了什么」，重放的前提是页本身结构完好。若页只写了一半（前 8KB 是新内容、后 8KB 是旧内容），校验和不通过、结构也不成立，redo 无法在其上重放。doublewrite 的存在就是为了消灭这种「部分写」。\n\n**为什么会有部分写**：文件系统与磁盘的最小写入单位（常见 4KB 甚至 512B）小于 InnoDB 的 16KB 页，一次页写入被拆成多次物理写，掉电正好打断就产生半新半旧的页。SSD 的原子写能力也无法跨 16KB 页保证。\n\n**写入顺序**：\n1. 脏页先**顺序**写入 doublewrite 区域（共享表空间中连续的若干页，8.0.20 起为独立 `.dblwr` 文件）；\n2. fsync 之后，再写到数据文件的实际位置；\n3. 因此任何时刻，实际数据页损坏都能从 doublewrite 里找到完好的完整副本。\n\n**恢复时**：启动时检查数据页校验和，发现损坏就从 doublewrite 拷回完整副本，再重放 redo 前滚。这样「页断裂」被降级为「页内容完整但偏旧」，redo 才能正常应用。\n\n**开销与取舍**：每次刷脏多一次顺序写（约 2 倍写放大，但顺序写很便宜），并占用少量空间。`innodb_doublewrite=OFF` 能提升写入性能约 5%~20%，但在掉电、内核崩溃、文件系统故障时可能产生无法修复的页损坏，生产环境不应关闭。\n\n**相关细节**：`innodb_doublewrite_dir` 可把 dblwr 文件放到更快的盘；`innodb_doublewrite_pages` 控制每次批量写的页数；doublewrite 只保护数据页，不保护 redo 自身——redo 靠日志块校验和与两阶段写保证完整。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 91 MINUTE), 1),
  (492, 2, 'Buffer Pool 预热、dump/load 与命中率的正确算法', '实例重启后为什么一段时间内性能很差？请说明 Buffer Pool 预热（dump / load）的原理、缓冲池命中率的正确计算方式，以及为什么「命中率 99.9% 也可能很慢」。', '**结论**：重启后 Buffer Pool 是空的，所有查询都要从磁盘读页，性能明显下降，直到热数据被重新加载。预热就是把这个过程从「被动等访问慢慢填满」变成「启动时批量加载」。\n\n**预热机制**：正常关闭时，InnoDB 把每个 Buffer Pool 实例中缓存页对应的**表空间 id 与页号**（不是页内容）dump 到 `ib_buffer_pool` 文件，dump 比例由 `innodb_buffer_pool_dump_pct`（默认 25）控制；启动时按该文件异步预读这些页（`innodb_buffer_pool_load_at_startup=ON`）。也可在线执行 `SET GLOBAL innodb_buffer_pool_dump_now=ON` 与 `innodb_buffer_pool_load_now=ON` 手动触发，用 `Innodb_buffer_pool_load_status` 查看进度。\n\n**为什么加载不到 100%**：dump 的只是页地址，加载仍要真实 IO；若期间表结构变化或页已被淘汰，部分地址会失效。\n\n**命中率的正确算法**：`1 - Innodb_buffer_pool_reads / Innodb_buffer_pool_read_requests`。前者是不得不从磁盘物理读的页数，后者是逻辑读请求数。不要用其他相似指标替代；`SHOW ENGINE INNODB STATUS` 里的 `Buffer pool hit rate` 是短窗口采样值，波动大，只能参考。\n\n**为什么 99.9% 也可能慢**：\n- 命中率是全局平均值，会掩盖「某几条 SQL 在做全表扫」；\n- 大表全表扫描会把热数据挤出 LRU（缓冲池污染），命中率随后下滑；\n- 命中率高但脏页刷不动时，写延迟照样抖动；\n- `Innodb_buffer_pool_wait_free` 增长说明空闲页不足，已经是容量问题。\n\n**容量规划**：`innodb_buffer_pool_size` 取物理内存的 50%~75%（专用实例），并按每实例 ≥1GB 拆分实例以减少锁竞争。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 92 MINUTE), 1),
  (493, 2, 'Buffer Pool 实例数、chunk 与 NUMA 亲和性的参数调优', '`innodb_buffer_pool_instances` 与 `innodb_buffer_pool_chunk_size` 该怎么设？请说明多实例如何减少锁竞争、size 与 chunk 的取整规则（为什么配 10G 实际会变成 10.5G），以及 NUMA 架构下的常见问题。', '**结论**：Buffer Pool 拆成多个实例，是为了用**多把独立的锁**管理不同区域，减少高并发下的互斥等待。实例数不是越多越好——每个实例至少 1GB 才有意义，否则管理开销与内存碎片会吃掉收益。\n\n**实例数与 chunk**：\n- `innodb_buffer_pool_instances`：默认 8；当 `innodb_buffer_pool_size` 小于 1GB 时强制为 1。总容量被平均分到各实例，每个实例独立维护 free list、LRU、flush list 与 mutex；\n- `innodb_buffer_pool_chunk_size`：默认 128MB，是**扩容的最小粒度**；\n- **取整规则**：总大小必须是 `instances × chunk_size` 的整数倍。若 `chunk=128M`、`instances=7`，则每轮步进 896M，配 10G 不是其整数倍，InnoDB 会向上取整到 **10.5G** 并打印告警——这就是「配了 10G 实际用了 10.5G」的原因。修改时应同时调整 chunk 与 size，避免非预期取整。\n\n**NUMA 问题**：多路 CPU 的机器上，内存分配默认倾向本地 node，InnoDB 的大块内存可能集中在某个 node，另一 node 的线程访问要走跨片总线，出现「内存够但性能上不去」。解决方式：启动参数 `innodb_numa_interleave=ON` 让内存交错分配，或在 OS 层用 `numactl --interleave=all` 启动 mysqld，并关闭 `zone_reclaim_mode`。\n\n**相关参数**：`innodb_buffer_pool_dump_pct` 控制预热比例；`innodb_lru_scan_depth` 控制每次刷脏扫描深度；`innodb_flush_method=O_DIRECT` 可避免文件系统 page cache 与 Buffer Pool 双重缓存。\n\n**验证**：`SHOW ENGINE INNODB STATUS` 的 BUFFER POOL AND MEMORY 段能看到各实例的 free buffers 与等待情况。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 93 MINUTE), 1),
  (494, 2, 'max_connections 与线程模型：连接数打满时到底发生了什么', '应用报 `Too many connections`，但数据库 CPU 并不高。请说明 MySQL 的连接线程模型（one-thread-per-connection 与 thread pool）、`max_connections` 与 `thread_cache_size` 的关系，以及为什么「加连接数」常常让问题更糟。', '**结论**：MySQL 默认「一连接一线程」，每个连接都占内存（线程栈、会话缓冲、排序/连接缓冲），并且在等锁、等 IO 时也占着线程。连接数打满往往不是并发能力不足，而是连接池配置过大或慢 SQL 占着连接不放。\n\n**线程模型**：\n- **one-thread-per-connection**（社区版默认）：每个连接一个 OS 线程，调度交给内核。连接数一多，上下文切换与内存开销陡增，出现「线程风暴」；\n- **thread pool**（Percona/MariaDB/企业版）：固定 worker 线程 + 任务队列，把「连接数」与「活跃线程数」解耦，避免上千连接的调度开销。社区版没有官方线程池，只能靠限制连接数与优化 SQL。\n\n**关键参数**：\n- `max_connections`：最大连接数，达到上限后新连接报 1040；root 通常还保留一个额外名额；\n- `thread_cache_size`：缓存空闲线程，减少频繁建连/断连的创建开销；\n- `wait_timeout` / `interactive_timeout`：空闲连接超时（默认 28800s），过长会让闲置连接长期堆积；\n- `back_log`：TCP 连接队列长度，瞬时建连风暴时容易丢连接。\n\n**为什么「加连接数」更糟**：每个活跃连接都在争 CPU、Buffer Pool 的 mutex 与行锁。连接越多，锁等待与上下文切换越严重，吞吐反而下降。正确方向是缩短事务、优化慢 SQL、把连接池调小（经验值 `CPU核数 × 2 + 磁盘数` 量级），并配置获取连接超时与熔断降级。\n\n**排查手段**：`SHOW PROCESSLIST` 看多少连接处于 `Sleep`、多少在 `Sending data`/`Waiting for lock`；`performance_schema.threads` 与 `events_waits_summary_by_thread_by_event_name` 定位等待类型；`Threads_connected / Threads_running` 的比值能直观反映连接是否被浪费。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 94 MINUTE), 1),
  (495, 2, 'utf8mb4 与 collation 不一致，为什么会让 JOIN 索引失效', '两张表关联列的字符集或 collation 不同（如 utf8mb4_general_ci 对 utf8mb4_0900_ai_ci），JOIN 变慢甚至报 1267。请说明原因、隐式转换的代价与方向，以及字符集与排序规则的统一规范。', '**结论**：JOIN 两侧字符集或 collation 不一致时，MySQL 必须先做**隐式转换**才能比较。转换发生在**列**上，等价于给列套了函数，于是被驱动表无法用索引定位，退化为全表扫描。\n\n**为什么**：索引按列的原始 collation 排序存储。两侧 collation 不同时，优化器无法直接按索引顺序判断相等，只能在执行期逐行转换后比较。`EXPLAIN` 表现为被驱动表 `type=ALL`、`key=NULL`，而单查该表时明明走索引。\n\n**1267 错误**：当差异大到无法隐式转换（`Illegal mix of collations`）时直接报错，常见于 `latin1` 与 `utf8mb4`、或不同版本默认 collation 混用的表之间。\n\n**转换方向**：字符集不同时，MySQL 会把「可表示范围更小」的一侧转成更大的一侧（latin1 → utf8mb4）；collation 不同但字符集相同时，按强弱与补位规则选择。关键在于判断**哪一侧的索引会失效**，通常是被转换的一侧。\n\n**统一规范**：\n1. 建库建表统一 `CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci`（8.0 默认），并在 `my.cnf` 固定 `character_set_server` 与 `collation_server`；\n2. 关联列必须**类型、字符集、collation 完全一致**，长度也建议一致；\n3. 存量修复用 `ALTER TABLE ... CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci`，大表走 gh-ost；\n4. JDBC 连接串显式声明编码，避免驱动层再做一次转换；\n5. 应急可在 SQL 中对较小的一侧 `CONVERT(col USING utf8mb4)`，但那只是治标，索引仍然用不上。\n\n**验证**：`SHOW FULL COLUMNS FROM t` 看 `Collation` 列，`EXPLAIN` 对比 JOIN 前后 `key` 是否变化。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 95 MINUTE), 1),
  (496, 2, 'JSON 字段的查询代价与多值索引的用法与限制', '把标签存进 JSON 数组后，`JSON_CONTAINS` 查询越来越慢。请说明 JSON 的存储方式与为何无法直接走普通索引、8.0.17 多值索引的建法与使用条件，以及 JSON 与关系表的选型边界。', '**结论**：JSON 列在 InnoDB 中以二进制格式（JSON Binary）整体存储，普通索引只能索引整列，无法索引数组中的元素。所以 `JSON_CONTAINS(tags, ...)` 只能全表扫描；8.0.17 的多值索引（multi-valued index）正是为此设计。\n\n**存储与代价**：`JSON` 列不存原始文本，而是解析后的二进制结构，读取时要反序列化；每次查询都要按路径遍历文档，CPU 开销远高于普通列。它也不能有默认值（8.0.13 起可以）、不能直接建普通索引，统计信息也差。\n\n**多值索引**：\n```sql\nALTER TABLE t_article\n  ADD INDEX idx_tags ( (CAST(tags->''$[*]'' AS CHAR(32) ARRAY)) );\nSELECT id FROM t_article WHERE ''mysql'' MEMBER OF (tags->''$[*]'');\n```\n要求：表达式必须形如 `CAST(json_col->''$[*]'' AS type ARRAY)`，type 只能是 CHAR / DATE / DATETIME / TIME / 整数 / DECIMAL（不能是 JSON 或浮点）；查询必须使用 `MEMBER OF`、`JSON_CONTAINS`、`JSON_OVERLAPS` 等能被优化器改写的谓词，否则不走索引。\n\n**限制**：一个多值索引只对应一个数组路径；数组元素多会让索引迅速膨胀；不能用于 `ORDER BY`；复杂分析要用 `JSON_TABLE` 展开成关系表再查。\n\n**选型边界**：\n- 需要按字段过滤、排序、统计、约束的数据，用关系表 + 关联表（标签表 + 中间表），索引与唯一约束都自然成立；\n- 真正稀疏、schema 频繁变化的扩展属性（用户偏好、埋点参数）才用 JSON，并仅为高频过滤路径建多值索引或生成列索引；\n- 别把 JSON 当成「不用设计表结构」的借口，后期查询与迁移成本会反噬。\n\n**实践**：先用 `EXPLAIN` 确认多值索引生效，再评估写入放大；高频标签检索场景，倒排索引（ES）通常比 JSON 多值索引更合适。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 96 MINUTE), 1),
  (497, 2, '全文索引与 ngram：中文 LIKE ''%关键词%'' 的替代方案', '商品表按标题模糊搜索，`LIKE ''%手机%''` 走不了索引。请说明 InnoDB 全文索引的倒排结构、`ngram` 解析器对中文的切分方式、`MATCH ... AGAINST` 的三种模式，以及全文索引的适用边界。\n\n```sql\nALTER TABLE t_product ADD FULLTEXT INDEX ft_title (title) WITH PARSER ngram;\nSELECT id FROM t_product WHERE MATCH(title) AGAINST (''手机'' IN BOOLEAN MODE);\n```', '**结论**：全文索引是**倒排索引**——把文本切成词（token），记录「词 → 文档 id 列表」，查询时先用词定位候选文档再回表。因此它能支持「包含某个词」的检索，而 `LIKE ''%词%''` 只能逐行扫描。\n\n**中英文差异**：英文按空格与标点切词，默认解析器够用；中文没有空格，必须用 `ngram` 解析器，`ngram_token_size`（默认 2）表示按 2 个字符切分。「MySQL 数据库」会被切成 `My`、`yS`、`SQ`、`QL`、`L `、`数`、`数据`、`据库` 等二元组。由此产生两个现象：\n- 查询词短于 token size（只搜一个汉字）时无法命中；\n- 搜「数据库」会拆成「数据」「据库」两个 token，按 AND 语义匹配，可能误召回或漏召回。\n\n**三种模式**：\n- **自然语言模式**（默认）：按词频与逆文档频率计算相关性，可返回 score，但无法表达「必须包含」；\n- **BOOLEAN 模式**：支持 `+词`（必须含）、`-词`（必须不含）、双引号短语、`词*` 前缀，常用于精确过滤；\n- **查询扩展模式**：先搜一轮把相关词补充进来再搜一次，召回更大但噪声也多。\n\n**边界**：全文索引只处理「词/子串」层面的匹配，不做语义、纠错、多字段加权与聚合统计；数据量大、要求实时性与相关性排序时应交给 Elasticsearch/OpenSearch。写入会带来倒排维护开销，`innodb_ft_cache_size`、`innodb_ft_total_cache_size` 影响构建与内存。\n\n**替代方案**：短文本可用「关键词 + 关联表」做精确匹配；只需前缀匹配时用 `LIKE ''手机%''` 仍能走索引；大规模检索上 ES，MySQL 只保留主数据。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 97 MINUTE), 1),
  (498, 2, '空间索引与 R-Tree：地理位置近邻查询怎么建索引', '表里存经纬度，要查「附近 1 公里的门店」。请说明 MySQL 空间类型与 SRID、R-Tree 索引的组织方式、`ST_Distance_Sphere` 与 `MBRContains` 的配合方式，以及为什么只对 lat/lng 建 B-Tree 复合索引效果不好。', '**结论**：二维范围查询应该用空间索引 **R-Tree**，它按最小包围矩形（MBR）组织数据，能同时裁剪「两个维度都不在范围内」的区域；而 `(lat, lng)` 的 B-Tree 只能先按 lat 过滤，lng 维度仍需逐行判断，效率随候选集放大而下降。\n\n**基础要点**：\n- 空间类型有 `POINT`、`LINESTRING`、`POLYGON` 等，列需声明 `SRID 4326`（WGS84 经纬度）才能正确计算球面距离，8.0 对 SRID 是强校验的；\n- 索引写法 `SPATIAL INDEX (location)`，InnoDB 支持，且列必须 `NOT NULL`；\n- `SRID 4326` 下坐标单位是度，`ST_Distance` 得到的是度，求米要用 `ST_Distance_Sphere`。\n\n**标准两步法**：先用 MBR 做粗筛（走空间索引），再用精确距离过滤排序：\n```sql\nSELECT id, ST_Distance_Sphere(location, ST_SRID(POINT(116.40, 39.90), 4326)) AS d\nFROM t_shop\nWHERE MBRContains(ST_GeomFromText(''POLYGON((...))'', 4326), location)\nHAVING d < 1000\nORDER BY d LIMIT 20;\n```\n其中 polygon 由应用按中心点与半径换算出外接矩形。`ST_Distance` 本身无法走索引，所以必须拆成「空间索引粗筛 + 精确计算」两步，否则退化为全表算距离。\n\n**为什么 B-Tree 不够**：`(lat, lng)` 能用 lat 做范围扫描，lng 只能靠过滤；当纬度跨度大、经度分布广时，扫描行数接近全表。换成 `(lng, lat)` 只是换了瓶颈维度。空间索引对两个维度同时裁剪，稳定性更好。\n\n**边界与替代**：千万行以上、QPS 高、还要按距离排序并结合多条件过滤时，Redis GEO、PostGIS 或 ES 的 geo_point 更合适；MySQL 空间索引适合中小规模、需要与业务数据同库事务查询的场景。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 98 MINUTE), 1),
  (499, 2, 'DATETIME 与 TIMESTAMP：时区、精度与 2038 年问题', '订单时间字段该用 DATETIME 还是 TIMESTAMP？请说明两者的存储方式、时区行为、精度写法（DATETIME(3)）、2038 年上限，以及「同一份数据在不同时区看到不同值」这类事故的根因。', '**结论**：`TIMESTAMP` 存的是 UTC 秒数，读写按会话时区转换，范围只到 2038-01-19；`DATETIME` 存「不带时区的字面量」，范围到 9999 年。业务时间通常用 `DATETIME(3)` 存字面量（建议统一存 UTC），跨时区展示交给应用层；只有需要数据库自动做时区换算时才用 `TIMESTAMP`。\n\n| 维度 | DATETIME | TIMESTAMP |\n|---|---|---|\n| 存储 | 存字面值，8.0 前占 5 字节 | 4 字节，存 UTC 秒 |\n| 时区 | 不做转换，存什么读什么 | 写入按 `time_zone` 转 UTC，读出再转回 |\n| 范围 | 1000-01-01 ~ 9999-12-31 | 1970-01-01 ~ 2038-01-19 |\n| 自动更新 | 8.0.13 起支持表达式默认值 | 原生支持 `CURRENT_TIMESTAMP` 与 `ON UPDATE` |\n\n**时区事故的根因**：同一个 `TIMESTAMP` 值，在 `time_zone='' +08:00''` 与 `''+00:00''` 的会话里查出来相差 8 小时。导出、跨机房同步、多语言服务写入时若两侧时区设置不同，数据就会整体偏移。`DATETIME` 不参与转换，因此很多团队统一用 `DATETIME` 存 UTC，展示层再转本地时间，从源头消灭这类问题。\n\n**精度**：两者默认都是秒级；需要毫秒用 `DATETIME(3)` / `TIMESTAMP(3)`（3 位小数占 3 字节）。常见写法 `created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)`。\n\n**2038 问题**：`TIMESTAMP` 用 4 字节有符号整数存 Unix 时间，2038-01-19 之后溢出。过期时间、预约时间这类未来时间字段若用 `TIMESTAMP`，必须提前规划，改用 `DATETIME` 或 `BIGINT` 存毫秒。\n\n**索引与比较**：两者都能正常建索引；查询时避免 `WHERE DATE(create_time) = ...`，改成左闭右开范围；`CONVERT_TZ` 也会破坏索引，应在应用层换算后传参。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 99 MINUTE), 1),
  (500, 2, 'sql_mode 严格模式与隐式默认值导致的线上数据事故', '插入时字段超长被悄悄截断、`NOT NULL` 列写入 NULL 变成 0 或空串——这些「静默改数据」由什么控制？请说明 `STRICT_TRANS_TABLES`、`NO_ZERO_DATE`、`ONLY_FULL_GROUP_BY` 的作用与 8.0 默认值的变化。', '**结论**：这些「静默改数据」的行为由 `sql_mode` 决定。MySQL 5.7/8.0 默认启用严格模式，超长、非法值、缺列都会直接报错而不是猜测；但也并非所有路径都受保护，不能把 `sql_mode` 当作数据质量的唯一防线。\n\n**关键模式项**：\n- **STRICT_TRANS_TABLES / STRICT_ALL_TABLES**：严格模式，非法数据直接报错。区别在于事务表与非事务表的处理：前者对事务表严格、对非事务表可能只给 warning；后者一律报错，但可能留下部分行已写入的中间状态；\n- **NO_ZERO_DATE / NO_ZERO_IN_DATE**：禁止 `0000-00-00` 与零月零日，8.0 默认开启；\n- **ONLY_FULL_GROUP_BY**：`GROUP BY` 的 SELECT 列必须在分组列或聚合函数中，8.0 默认开启。老系统升级到 8.0 的报错大多来自它，正确做法是改写 SQL 或对确定性列用 `ANY_VALUE()`，而不是关掉它；\n- **ERROR_FOR_DIVISION_BY_ZERO**：除零报错而不是返回 NULL；\n- **NO_ENGINE_SUBSTITUTION**：指定引擎不可用时直接报错，避免被悄悄换成 MyISAM。\n\n**8.0 的默认组合**：`ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION`。相比 5.7 去掉了已废弃的 `NO_AUTO_CREATE_USER`。\n\n**仍会静默出问题的地方**：非严格会话下的超长截断只给 warning，应用若忽略 warning 就会写出脏数据。\n\n**实践**：新库沿用 8.0 默认 `sql_mode`；升级前用影子流量对比，把 `ONLY_FULL_GROUP_BY` 报错当代码缺陷修；开发阶段强制检查 `SHOW WARNINGS`，生产禁止随手改全局 `sql_mode` 绕过问题。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 100 MINUTE), 1),
  (501, 2, 'INSERT ... ON DUPLICATE KEY UPDATE 的返回值、加锁与并发坑', '用 `INSERT ... ON DUPLICATE KEY UPDATE` 做 upsert 时，`affected_rows` 为什么有时是 1、有时是 2、有时是 0？并发下它凭什么还会死锁、还会让自增 id 跳号？请说明加锁过程与替代写法。', '**结论**：它是「先尝试插入，冲突则改为更新」的原子语句，但**并非无锁**：冲突时会对记录加 X 锁并持有到事务结束，同时消耗一个自增值。高并发 upsert 同一行会退化为串行，还可能叠加唯一键死锁。\n\n**affected_rows 的三种取值**：\n- 插入成功：**1**；\n- 冲突且新值确实改变了数据：**2**；\n- 冲突但新旧值相同、实际未更新：**0**（客户端开启 `CLIENT_FOUND_ROWS` 时可能返回 1）。\n所以业务判断「是否真的写入」不能只看 `> 0`，要区分 0 与 2。\n\n**加锁过程**：插入时先加插入意向锁；唯一键冲突后对该记录加锁（先 S 校验、再升级为 X 做更新），持有到事务结束。并发 upsert 同一行因此排队；若两个事务的 upsert 顺序不同，或与其他唯一键写入交叉，就构成死锁（返回 1213）。\n\n**自增跳号**：即使最终走 UPDATE 分支，InnoDB 也**已经分配了自增值**，这个号被浪费。高并发 upsert 会让自增 id 出现大量空洞，属于正常现象，不要依赖 id 连续。\n\n**其他坑**：\n- 会触发触发器，插入与更新可能各触发一次；\n- `VALUES(col)` 语法自 8.0.20 起废弃，改用行别名：`INSERT INTO t ... AS new ON DUPLICATE KEY UPDATE c = new.c`；\n- 表上有多个唯一索引时，冲突可能命中不同索引，需要逐一验证行为；\n- 批量 upsert 前按主键/唯一键排序，能显著降低死锁率。\n\n**替代写法**：`INSERT IGNORE`（忽略冲突但不更新，仍消耗自增）、`REPLACE INTO`（删除再插入，副作用更大）、`SELECT ... FOR UPDATE` 后判断再写（显式但更重）、计数场景用 `cnt = cnt + 1` 的原子更新。选择依据是「是否允许丢失更新」与「能否接受串行化」。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 101 MINUTE), 1),
  (502, 2, 'REPLACE INTO 为什么危险：删除语义、自增消耗与主从不一致', '`REPLACE INTO` 看起来是「有则替换、无则插入」，但很多团队明令禁止。请说明它的真实执行语义（DELETE + INSERT）、对自增 id 与二级索引的影响，以及为什么它可能造成主从数据不一致。', '**结论**：`REPLACE INTO` 的真实语义是「冲突则**先删除**旧行，再插入新行」，而不是更新。由此带来三个后果：未提供的列被重置为默认值、自增 id 变化、删除带来的副作用（触发器、级联、binlog 双倍事件）被一并执行。\n\n**执行过程**：\n1. 尝试插入；\n2. 若主键或唯一索引冲突，对冲突行加 X 锁并**删除**；\n3. 再插入新行。\n\n因为经历删除 + 插入，行的物理位置、`DB_TRX_ID`、以及未显式指定时的自增 id 都会变化。\n\n**四个具体问题**：\n1. **数据丢失**：只写了部分列的 `REPLACE` 会把其余列重置为默认值或 NULL，`UPDATE` 不会；\n2. **主键漂移与自增膨胀**：重新插入会分配新自增值，主键变化让引用它的业务关联与缓存全部失效；\n3. **二级索引全量重建**：该行所有索引项都要删掉重建，写放大明显，ROW 格式 binlog 还会记录 DELETE + INSERT 两条，从库开销翻倍；\n4. **触发器与级联**：`AFTER DELETE` 触发器、`ON DELETE CASCADE` 外键都会被触发，可能牵连其他表，这是最容易被忽视的破坏。\n\n**主从一致性风险**：statement 格式下 `REPLACE` 的行为依赖从库当前数据，若主从已有差异，从库可能走不同分支；ROW 格式虽然安全，但变更量翻倍。因此复制环境更推荐 `INSERT ... ON DUPLICATE KEY UPDATE`。\n\n**正确替代**：想更新就用 `UPDATE`；想 upsert 用 `INSERT ... ON DUPLICATE KEY UPDATE` 并显式列出所有要保留的列；只有「整行就是最新快照」的场景（缓存表、字典全量同步、去重后的统计快照）才适合 `REPLACE`，且必须写全所有列并接受自增变化。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 102 MINUTE), 1),
  (503, 2, '批量写入的吞吐优化：多值 INSERT、LOAD DATA 与 max_allowed_packet', '逐条 `INSERT` 导入 100 万行非常慢。请说明多值 `INSERT` 相比单条插入快在哪里、`LOAD DATA` 为什么更快、`max_allowed_packet` 与刷盘参数的影响，以及大批量导入的推荐做法与风险。', '**结论**：慢的根因是「每条语句一个事务、一次网络往返、一次日志刷盘」。批量写入的核心就是把 N 条合并成一次事务、一个网络包、一组日志记录。\n\n**多值 INSERT**：`INSERT INTO t (a,b) VALUES (1,2),(3,4),...` 一次解析、一次提交、一组 redo/binlog，通常比逐条快 5~10 倍。注意：\n- 单条语句大小受 `max_allowed_packet`（默认 64MB）限制，超了直接报错并可能断开连接；\n- 事务过大又会导致 undo 膨胀、锁持有时间长、主从延迟加剧，建议每批 500~5000 行或每批不超过几 MB；\n- 出错时整批回滚，需能定位是哪个值冲突，可退化为「分批 + 单条重试」。\n\n**LOAD DATA INFILE**：绕过 SQL 解析层，按文本/CSV 直接构造记录，是最快的导入方式，通常比多值 `INSERT` 再快数倍。需要 `local_infile` 权限与服务端配置，导入期间仍要维护索引，因此先导入后建索引往往更快（前提是能接受索引构建期的开销）。\n\n**关键参数**：\n- `innodb_flush_log_at_trx_commit=2` 或临时关闭 `sync_binlog` 可大幅提速，代价是崩溃可能丢最近的提交——**只允许在可重建的临时库或明确导入窗口内使用，导完立即改回**；\n- `unique_checks` / `foreign_key_checks` 临时关闭可减少校验开销，但前提是数据源可信；\n- `innodb_autoinc_lock_mode=2` 让批量插入并发分配自增值；\n- 按主键**有序**导入可避免页分裂，比乱序快得多。\n\n**风险与收尾**：大批量导入会撑大 undo、拖慢从库、把热数据挤出 Buffer Pool；导入后应 `ANALYZE TABLE` 更新统计信息并检查复制延迟。生产大导入优先「从库/影子实例导入 → 校验 → 切主」，而不是直接打主库。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 103 MINUTE), 1),
  (504, 2, '大事务与批量删除：为什么必须分片提交，怎么切', '一次性 `DELETE FROM t WHERE created_at < ''2023-01-01''` 删除 1000 万行，导致主从延迟、锁等待与 undo 暴涨。请说明大事务的危害、`LIMIT` 分批删除的正确写法与坑，以及归档场景的更优方案。', '**结论**：大事务的问题不在「执行慢」，而在它**同时持有大量资源**：undo 不能回收、行锁覆盖广、binlog 事件巨大、从库要串行重放整个事务。分批提交就是把这些代价切成可控的小块。\n\n**四个危害**：\n1. **undo 膨胀**：事务未提交前，其 undo 不能 purge，长事务让 undo 表空间暴涨，其他快照读的版本链也随之变长；\n2. **锁与 MDL**：范围删除会锁住大量行（无索引时接近全表），阻塞其他 DML；持有的 MDL 还会卡住 DDL；\n3. **复制延迟**：ROW 格式下整个事务作为一个 GTID 在从库重放，主库跑 10 分钟，从库也要 10 分钟；\n4. **回滚代价**：失败后回滚的耗时与正向执行相当甚至更久。\n\n**分批删除的写法**：\n```sql\nDELETE FROM t WHERE created_at < ''2023-01-01'' ORDER BY id LIMIT 1000;\n```\n每批提交后 sleep 几十毫秒，循环执行。要点：\n- **必须有 `ORDER BY id LIMIT`**，否则每批扫描量不稳定，甚至可能长期删不掉满足条件的行；\n- `WHERE` 条件列要有索引，否则每批都是全表扫描；\n- RC 隔离级别可减少间隙锁；批间 sleep 给从库追赶时间；\n- 循环要有终止条件与监控（删除行数、耗时、从库延迟），避免变成无人看守的脚本。\n\n**归档场景的更优方案**：\n- **分区表 + `DROP PARTITION`**：整段时间的数据删除变成元数据操作，秒级完成，没有 undo 与锁问题（要求分区键包含时间列）；\n- **先导出到冷库/对象存储再删**，保证可回溯；\n- `pt-archiver` 这类工具自带分批、限速与延迟检测，比手写脚本稳。\n\n**注意**：`TRUNCATE TABLE` 虽快，但不可回滚、会重置自增，且是 DDL，只适用于整表清空。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 104 MINUTE), 1),
  (505, 2, '读写分离下的读己之写：延迟窗口内的三种兜底方案', '用户下单后立刻刷新订单列表，却看不到刚下的单——典型的「读己之写」失败。请说明主从延迟窗口的成因，以及强制走主库、会话粘滞、位点/GTID 校验三种兜底方案各自的成本与适用场景。', '**结论**：写主库、读从库时，从库回放存在毫秒到秒级的延迟。用户写后立刻读，若请求落到尚未回放的从库，就会「看不到自己刚写的数据」。这是架构层面的问题，靠调小延迟无法根除。\n\n**延迟窗口为什么存在**：binlog 从主库传到从库（网络）→ 写入 relay log → SQL 线程回放。任何一环抖动都会放大窗口；大事务、DDL、从库负载高时窗口可达数秒甚至更久。\n\n**三种兜底方案**：\n1. **强制走主库**：写操作后的一段时间（如 1~3 秒）内，该用户/会话的读请求都路由到主库。实现简单，常与 ThreadLocal 会话标记结合。成本是主库读压力上升，适合写后读比例不高、对一致性敏感的场景（下单结果页、支付状态）。\n2. **会话粘滞（sticky）**：把同一会话/同一用户的读固定打到同一从库，减少「这次读得到、下次读不到」的抖动。它降低的是**不一致的概率**，并不缩短延迟，适合列表、详情这类弱一致读。\n3. **位点/GTID 校验**：写入后记录当前 binlog 位点或 GTID，读之前检查目标从库的 `Executed_Gtid_Set` 是否已包含该位点，未包含则等待或改走主库。一致性最强、主库压力最小，代价是实现复杂，需要中间件或客户端 SDK 支持，且每次读多一次判断开销。\n\n**工程实践**：\n- 按业务分级：强一致读（订单状态、余额）走主库或方案 3；弱一致读（商品列表、评论）走从库；\n- 异步化：写完直接返回，前端轮询或推送结果，避免同步读；\n- 缓存兜底：写入后把最新值写进 Redis，读路径优先读缓存；\n- 监控 `Seconds_Behind_Master` 并设阈值，超阈值自动把部分流量切回主库（降级开关）。\n\n**常见误区**：只把「写后第一次读」改走主库不够，因为延迟可能持续更久；方案要么覆盖完整窗口，要么用位点校验做精确判断。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 105 MINUTE), 1),
  (506, 2, '连接池与 wait_timeout：MySQL 主动断连引发的报错与配置', '服务低峰期频繁报 `Communications link failure` 或 `Connection reset`。请说明 `wait_timeout` 与连接池 `maxLifetime` / `idleTimeout` 的关系、为什么会出现「连接被服务端单方面关闭」，以及正确的参数配比与保活方式。', '**结论**：MySQL 会在连接空闲超过 `wait_timeout` 后主动关闭它；如果连接池仍把这个连接当作可用连接借给业务，第一次使用就会报连接已断开。这类报错几乎都是「连接池生命周期参数大于服务端超时」造成的。\n\n**两侧参数**：\n- **MySQL 侧**：`wait_timeout`（非交互连接，默认 28800s）、`interactive_timeout`（交互式客户端）。两者应设成一致，否则不同客户端行为不同；云数据库常调到 60~600s，并配合 `tcp_keepalive_time`；\n- **连接池侧**（以 HikariCP 为例）：`maxLifetime`（连接最大存活时间）、`idleTimeout`（空闲回收）、`keepaliveTime`（定期探活）、`validationTimeout`。\n\n**正确配比**：`maxLifetime` 必须**小于**服务端 `wait_timeout`，一般留 30~60 秒余量，让池在自己淘汰并重建连接，而不是等数据库先动手。典型事故是把云数据库的 `wait_timeout=60` 与默认 `maxLifetime=30min` 搭配，低峰期必然集中报错。\n\n**为什么是「单方面关闭」**：服务端发 FIN 后，客户端若没有读事件，socket 仍显示 ESTABLISHED，直到真正写入才收到 RST。连接池若没有有效的探活机制（`connectionTestQuery` 或 JDBC4 的 `isValid`），就无法提前发现死连接——所以「保活」比「重试」更重要。\n\n**容易忽略的中间层**：SLB、NAT、防火墙的空闲超时（常见 300s）也会悄悄断连，同样要纳入 `maxLifetime` 计算，取「所有超时中最小的那个」再减余量。\n\n**排查**：看 `SHOW PROCESSLIST` 的连接数与 `Time` 列、`Aborted_clients` 是否异常增长，并上报连接池的活跃/空闲/等待指标。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 106 MINUTE), 1),
  (507, 2, 'InnoDB 行锁对象与锁等待队列在内存里长什么样', '行锁并不是「锁住一行数据」，而是内存中的锁结构。请说明 `lock_t` 的关键字段、锁哈希表与等待队列的组织方式、位图（bitmap）如何合并同页的锁，以及为什么锁信息本身也会消耗大量内存。', '**结论**：InnoDB 的行锁是**挂在索引记录上的内存对象**（`lock_t`），由锁系统统一管理，与数据页内容无关。锁对象记录「谁持有、锁什么模式、锁住哪个页的哪些记录、谁在等」，并通过锁哈希表按「表空间 + 页号」快速定位。\n\n**结构要点**：\n- `lock_t`：`trx`（持有事务）、`type_mode`（锁类型 + 锁模式 + 是否处于等待态）、`rec_lock`（页号、heap_no 等记录标识）、等待队列指针；\n- **锁类型**：表级（`LOCK_TABLE`）与记录级（`LOCK_REC`）；**锁模式**：`LOCK_S`、`LOCK_X`、`LOCK_IS`、`LOCK_IX`、`LOCK_AUTO_INC`；`LOCK_GAP` 与 `LOCK_INSERT_INTENTION` 是记录锁上的类型位；\n- **位图合并**：同一页上多条记录的相同锁会合并进一个 `lock_t`，用 bitmap 按 heap_no 标记被锁记录，避免「一行一个对象」的内存爆炸；\n- **哈希表**：`lock_sys` 按 `(space_id, page_no)` 分桶，粒度是页而不是行，所以同页上的锁申请也会相互影响。\n\n**等待与唤醒**：申请锁冲突时，在该锁对象的等待队列尾部插入等待锁，并挂起（`os_event_wait`）；释放锁时按队列顺序唤醒，被唤醒者需重新检查兼容性——可能被插队，也可能因模式降级而失败重来。\n\n**内存风险**：一条无索引的 `UPDATE` 可能涉及数十万行，锁对象数量随之暴涨。治理手段：\n- 避免大事务、避免无索引更新（锁范围随扫描行数放大）；\n- `innodb_lock_wait_timeout`（默认 50s）只控制等待时长，不控制锁数量；\n- 用 `performance_schema.data_locks` 与 `data_lock_waits`（8.0）实时观察锁与阻塞关系。\n\n**理解要点**：锁挂在「索引记录」而不是「行」上，主键与二级索引上的锁是两套，这才能解释「改的不是同一行却互相阻塞」。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 107 MINUTE), 1),
  (508, 2, '一条 UPDATE 到底加了哪些锁：唯一索引、普通索引与无索引', '同一条 `UPDATE t SET c = 1 WHERE b = 2`，在 b 是唯一索引、普通索引、完全没有索引三种情况下加锁范围完全不同。请分别说明，并解释 RR 与 RC 下的差异及其对死锁排查的意义。', '**结论**：InnoDB 的锁加在**索引记录**上，加锁范围取决于「命中了多少索引记录、是否需要锁间隙」。同一句 SQL：唯一索引等值命中只锁一行；普通索引要锁命中记录加间隙；无索引则扫描全表并锁住扫过的所有记录，效果接近锁表。\n\n**三种情况**：\n1. **唯一索引等值命中**：定位到唯一记录，只加 **Record Lock（X）**，不需要间隙锁——唯一性保证同值不可能有第二行。\n2. **唯一索引等值未命中**：没有记录可锁，RR 下加一个 **Gap Lock** 锁住该值所在的间隙（防止其他事务插入，导致「不存在」判断失效）；RC 下不加。\n3. **普通索引等值**：同值可能多行，对每条记录加 X 锁并加 **Next-Key Lock**（记录 + 前面的间隙），范围两端还会有间隙锁，防止幻读插入。\n4. **完全无索引**：只能全表扫描聚簇索引，扫过的每一行都加 X 锁（RR 含间隙），实际接近锁全表；RC 下的 semi-consistent read 会提前释放不匹配行的锁，缓解但不解决。\n\n**RR 与 RC 的差异**：\n- **RC** 基本不使用间隙锁（唯一性检查与外键除外），只锁命中记录，插入不会被阻塞，死锁概率更低；\n- **RR** 默认 Next-Key Lock 防幻读，锁范围更大，更容易互相阻塞。\n\n**其他扩大锁范围的因素**：\n- `UPDATE` 修改了索引列：要删旧索引项 + 插新索引项，多棵索引树都要加锁；\n- 条件走了低选择性索引：命中行数多，锁自然多；\n- 未提交事务让锁一直持有，`data_locks` 可验证实际范围。\n\n**优化方向**：让 WHERE 命中**唯一索引或高选择性索引**，把锁范围压到最小；写并发高的表考虑 RC；坚决避免无索引更新——它是线上锁等待与死锁的第一大来源。\n\n**排查**：`SHOW ENGINE INNODB STATUS` 的 `LATEST DETECTED DEADLOCK` 段会打印每条 SQL 持有的锁与等待的锁；8.0 可查 `performance_schema.data_locks` 区分记录锁与间隙锁。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 108 MINUTE), 1),
  (509, 2, '半一致性读（semi-consistent read）在 RC 下如何减少锁冲突', 'RC 隔离级别下，`UPDATE ... WHERE` 扫描到不满足更新条件的行时，InnoDB 会先释放锁再继续。请说明 semi-consistent read 的触发条件、它如何降低锁等待与死锁，以及为什么 RR 下不生效。', '**结论**：semi-consistent read 是 InnoDB 在「读已提交」下的一种优化：`UPDATE`/`DELETE` 扫描到某行但该行不满足 WHERE 条件时，**先释放它持有的锁**，并把最新提交版本交给 server 层判断，从而避免为「根本不会修改的行」长期持锁。\n\n**工作过程**：\n1. 存储引擎按索引扫描，锁住候选行；\n2. server 层用 WHERE 条件判断，不满足则**释放该行的锁**并继续扫描；\n3. 满足则保留锁并执行更新。\n\n**收益**：没有合适索引的更新会扫过大量不匹配的行。普通加锁方式会把这些行全部锁到事务结束，其他事务只能排队甚至形成死锁；semi-consistent read 让不匹配行立即解锁，显著缩小冲突面，尤其缓解「更新范围大、真正命中的少」的场景。\n\n**触发条件**：\n- 隔离级别为 **READ COMMITTED**（或显式设置 `innodb_locks_unsafe_for_binlog=ON`，该变量 8.0 已废弃）；\n- 语句是 `UPDATE` 或 `DELETE`，`SELECT ... FOR UPDATE` 不适用；\n- 被扫描行在加锁后被判定为不匹配。\n\n**为什么 RR 下不生效**：RR 要保持事务内一致视图并用间隙锁防幻读。若允许「读到最新提交版本再判断」，同一事务内两次执行的结果可能不同，破坏可重复读语义，因此 InnoDB 在 RR 下禁用该优化。\n\n**代价与风险**：它让语句看到「最新的已提交数据」，与 RR 的快照语义不同，这也是 RC 下 binlog 必须用 ROW 格式的原因之一。它降低锁冲突，但**不解决根因**：根本办法仍是给 WHERE 建合适的索引，减少扫描行数。\n\n**观察方式**：死锁日志里出现 `semi-consistent read` 字样可直接确认；对比同一 SQL 在 RC 与 RR 下的锁等待时长、`data_locks` 行数，差异非常直观。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 109 MINUTE), 1),
  (510, 2, '唯一索引等值查询为什么只需要 Record Lock，不需要 Gap Lock', '同样是 `WHERE id = 5` 的当前读，唯一索引上加的是 Record Lock，普通索引上却要加 Next-Key Lock。请解释原因、唯一索引在什么情况下仍会加间隙锁，以及这对死锁排查有什么意义。', '**结论**：唯一索引保证「一个键值最多一行」，等值命中后不存在「同值的新行被插入」，所以只需锁住这条记录；普通索引同一个值可能有多行，为防止其他事务插入同值新行（幻读），必须连间隙一起锁。\n\n**四种情形对比**：\n- **唯一索引 + 等值命中**：加 `LOCK_REC_NOT_GAP` 的记录锁，不锁间隙；\n- **唯一索引 + 等值未命中**：没有记录可锁，只能锁住该值所在的间隙（`LOCK_GAP`），否则别的事务可以插入这个值，让「不存在」的判断失效；\n- **唯一索引 + 范围查询**：退化为 Next-Key Lock，因为范围两侧都可能插入新值；\n- **普通索引 + 等值**：加 Next-Key Lock（记录 + 前面的间隙），并锁住到下一个不同值之间的间隙。\n\n**举例**：`UPDATE t SET c = 1 WHERE id = 5`（id 为主键）只锁一条记录；`UPDATE t SET c = 1 WHERE k = 5`（k 为普通索引，存在三行 k=5）要锁三行记录加前后间隙，任何试图插入 k=5 或在间隙内插入新值的事务都会被阻塞。\n\n**对死锁排查的意义**：\n- 唯一索引等值更新几乎不会因间隙锁与插入形成死锁，冲突面小；\n- 普通索引上的范围更新、批量更新容易形成「记录锁 + 间隙锁」交叉，是死锁高发区；\n- 死锁日志里大量出现 `lock_mode X locks gap before rec`，说明语句正在非唯一索引上做范围操作，应考虑改用唯一键精确定位，或把隔离级别降到 RC。\n\n**三个前提会被打破**：WHERE 用了唯一索引但条件是范围、`UPDATE` 修改了索引列（需要插入新索引项）、或查询走了非唯一索引——只要有一个成立，「只锁一行」就不成立。\n\n**实践**：设计上尽量用唯一索引做点查定位；批量操作按主键分片执行，把每个事务的锁范围限定在少量记录内。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 110 MINUTE), 1),
  (511, 2, 'MRR（Multi-Range Read）与磁盘顺序化回表', '范围查询回表时，主键顺序与二级索引顺序不一致会产生大量随机 IO。请说明 MRR 的优化原理、`mrr` 与 `mrr_cost_based` 两个开关的作用，以及为什么 SSD 上 MRR 的收益会变小。', '**结论**：MRR 把「按二级索引顺序逐行回表」改成「先把主键收集起来排序，再按主键顺序批量回表」，把随机 IO 变成近似顺序 IO，同时减少 Buffer Pool 的反复换页。\n\n**问题背景**：`WHERE k BETWEEN 10 AND 20` 走二级索引 k，命中的主键可能是 100、5、300、77……按索引顺序逐行回表，每次都是聚簇索引上的随机定位。命中行一多，随机 IO 成为瓶颈。\n\n**MRR 流程**：\n1. 扫描二级索引，把命中的主键放入 `read_rnd_buffer`（大小由 `read_rnd_buffer_size` 控制）；\n2. 缓冲区满或扫描结束时，对主键排序；\n3. 按主键顺序批量回表，取出整行。\n\n**相关开关**：\n- `optimizer_switch` 中的 `mrr=on`、`mrr_cost_based=on`（默认）；\n- `mrr_cost_based=off` 表示**强制使用** MRR，不按成本判断，适合验证收益；\n- `EXPLAIN` 的 `Extra` 出现 `Using MRR` 表示生效；\n- `read_rnd_buffer_size` 太小时缓冲区频繁填满，排序收益被削弱。\n\n**为什么 SSD 上收益变小**：MRR 的价值来自「随机 IO → 顺序 IO」，而 SSD 随机读延迟已降到几十微秒，排序本身还要占 CPU 与内存。所以 SSD 上收益通常只有几个百分点，`mrr_cost_based` 也常判断不划算而不启用。\n\n**与 ICP 的配合**：`Using index condition`（索引条件下推）在存储引擎层先过滤掉不满足条件的行，减少需要回表的行数；剩下的回表再由 MRR 优化顺序。两者可叠加，但优化器会按成本权衡，未必同时出现。\n\n**实践**：机械盘、网络存储或大结果集范围查询时值得专门验证 MRR；SSD 上优先把精力放在「减少回表行数」（覆盖索引、更精确的联合索引），而不是排序回表这一层。测量方法是对比开关前后的 `Innodb_buffer_pool_reads` 与总耗时。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 111 MINUTE), 1),
  (512, 2, '复合主键与自增主键：聚簇索引设计的两种取舍', '订单详情表用 `(order_id, sku_id)` 做复合主键，还是用自增 id 加唯一索引？请从插入顺序、二级索引体积、页分裂、分库分表四个角度分析两种设计，并给出判断标准与折中方案。', '**结论**：复合主键让「业务唯一组合」直接成为聚簇索引，省掉一次唯一索引查找与回表，但要求插入尽量按主键顺序；自增主键让写入永远顺序追加、二级索引更小，代价是多一个索引与一次回表。选择取决于写入顺序与访问模式。\n\n**复合主键的优势**：\n- 天然表达业务唯一性（`(order_id, sku_id)`），不必再建唯一索引；\n- 按 `order_id` 前缀查询时聚簇索引直接命中，无需回表；\n- 同一订单的明细在聚簇索引上物理相邻，范围查询局部性好。\n\n**复合主键的问题**：\n- **二级索引会带上整个主键**：InnoDB 二级索引叶子存的是主键值，主键越长所有二级索引越大。两个 BIGINT 是 16 字节，而自增 BIGINT 只有 8 字节；\n- **插入顺序**：若明细按 `sku_id` 为主生成、`order_id` 随机，插入会打散到索引各处，造成大量页分裂；\n- **主键变更成本高**：修改主键列等于删行重插；\n- **分库分表不友好**：复合主键无法直接做全局唯一 ID，跨分片路由更复杂。\n\n**自增主键的优势**：单调递增，插入永远追加在 B+ 树末尾，页填充率高、页分裂少；主键短，二级索引小；便于分库分表与全局 ID 体系。代价是业务唯一组合需要额外唯一索引，按业务键查询要走「唯一索引 → 回表」两步。\n\n**判断标准**：\n1. 写入是否严格按主键顺序？是 → 复合主键可行；否 → 自增更稳；\n2. 主键是否偏宽（多列、字符串）？宽 → 选自增；\n3. 是否有大量「按主键前缀范围查」的访问？有 → 复合主键局部性优势明显；\n4. 是否需要分库分表或全局唯一 ID？需要 → 自增或雪花。\n\n**实践折中**：`PRIMARY KEY (id)` 自增 + `UNIQUE KEY uk_order_sku (order_id, sku_id)`，兼顾写入顺序与业务唯一。高频按订单查明细时，`uk_order_sku` 本身已覆盖 `order_id` 前缀，效果接近复合主键，只需为查询列补成覆盖索引即可消除回表。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 112 MINUTE), 1);

;
   `view_count`, `practice_count`, `published_at`, `created_by`)
VALUES
  (513, 3, 'Redis 的 ae 事件循环与 Reactor 模型是怎么运转的', 'Redis 服务端全程单线程，却要同时处理数万连接、定时任务、AOF 刷盘与集群心跳，这依赖一套自研的事件驱动框架。\n\n请说明：\n- ae 事件循环的核心数据结构，文件事件与时间事件的处理顺序；\n- epoll 等多路复用在其中扮演的角色；\n- 哪些操作会阻塞这个循环，Redis 又如何把部分工作移出主线程。\n\n期望能讲到 aeEventLoop、aeApiPoll、beforeSleep 与 serverCron 之间的协作关系。', '**结论**：Redis 用单线程 Reactor 模型，ae 库把 IO 多路复用、时间事件、休眠与唤醒封装成一个循环，所有命令执行都跑在这个循环里，因此天然无锁、单命令原子。\n\n**核心结构**\n- `aeEventLoop`：`events`（注册的 fd 事件）、`fired`（本次就绪事件）、`timeEventHead`（时间事件链表）、`beforesleep`/`aftersleep` 钩子。\n- 文件事件 `aeFileEvent`：`AE_READABLE`/`AE_WRITABLE` 加回调（acceptTcpHandler、readQueryFromClient、sendReplyToClient）。\n- 时间事件：`serverCron` 默认 `hz=10`，负责过期键抽样、增量 rehash、持久化状态检查、集群心跳。\n\n**执行顺序**（`aeMain` 调 `aeProcessEvents`）\n1. 先执行 `beforesleep`：把 AOF 缓冲刷盘、对待回复客户端直接写 socket、向集群总线发消息。\n2. 取最近的时间事件算出 `aeApiPoll` 的 timeout，避免睡过头错过定时任务。\n3. `aeApiPoll` 返回就绪 fd，按 `fired` 顺序执行读/写回调。\n4. 最后执行到期的时间事件。\n\n`aeApiPoll` 底层优先 `epoll`（Linux），另有 kqueue、evport、select 兜底，就绪收集是 O(1)。\n\n**阻塞点与缓解**：复杂命令（`KEYS`、大集合运算）、大 key 同步释放、`fork` 做 RDB、AOF `fsync`、客户端输出缓冲区积压都会卡住循环。Redis 的应对是把 close fd、fsync、lazy free 交给 bio 线程，6.0 再把读写与协议解析拆给 IO 线程，但命令执行仍然串行，这正是原子性的来源。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 113 MINUTE), 1),
  (514, 3, 'intset 的升级机制与不可逆设计', 'intset 是 Redis set 在「全整数且元素不多」时的紧凑编码，它的升级机制是面试常问的底层细节。\n\n请说明：\n- intset 的内存布局与查找复杂度；\n- 升级的触发条件与代价，为什么升级不可逆；\n- 什么条件下 set 会从 intset 转成别的编码。\n\n期望能给出 set-max-intset-entries 的默认值，并列出 set 的编码转换条件。', '**结论**：`intset` 是一块连续内存中存放有序整数数组的结构，查找用二分，插入可能触发整体升级，而升级只升不降。\n\n**布局**\n```bash\nstruct intset {\n  uint32_t encoding;  // INTSET_ENC_INT16/32/64\n  uint32_t length;\n  int8_t contents[];\n}\n```\n元素按值升序连续排列，`contents` 不按声明类型解释，而是由 `encoding` 决定每个元素占 2、4 或 8 字节。内存利用率极高、缓存友好。查找 `O(log n)`，插入与删除 `O(n)`，因为要搬移数组。整个集合用统一宽度，取当前最大元素的所需宽度。\n\n**升级**：插入一个超出当前宽度的整数（例如 16 位集合里插入 40000），Redis 按新宽度重新分配整块内存，从后往前把旧元素逐个搬运并做符号扩展，最后插入新元素。单次复杂度 `O(n)`，但每次升级至少让容量翻倍，均摊仍是 `O(1)`，且元素数受阈值限制，实际开销可控。\n\n**不可逆的原因**：降级需要重新计算并搬移全部元素，收益只是省一点内存，却会带来频繁抖动与实现复杂度，因此 Redis 直接放弃。\n\n**编码转换**\n| 条件 | 编码 |\n| --- | --- |\n| 全整数且元素数不超过 set-max-intset-entries（默认 512） | intset |\n| 加入非整数元素 | hashtable |\n| 元素数超过阈值 | hashtable |\n| 7.2 起的小集合字符串元素 | listpack |\n\n线上用 `OBJECT ENCODING key` 验证。一旦转成 `hashtable` 就不会退回，这也是把小整数集合当 bitset 用时内存反而暴涨的原因。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 114 MINUTE), 1),
  (515, 3, 'dict 的渐进式 rehash 如何避免单线程卡顿', 'dict 支撑着 Redis 的键空间、Hash、Set、ZSet 以及过期字典，它的 rehash 是理解「单线程却不卡顿」的关键。\n\n请说明：\n- dictht 双表结构与 rehashidx 的作用；\n- 触发扩容与缩容的负载因子条件；\n- 渐进式 rehash 期间查找、插入、删除的处理差异；\n- 为什么这期间 SCAN 可能返回重复元素。', '**结论**：Redis 的 dict 用两张哈希表加一个 `rehashidx`，把一次大 rehash 摊到每次增删改查中，避免单线程被长时间阻塞。\n\n**结构**\n```bash\ntypedef struct dict {\n  dictType *type;\n  dictht ht[2];\n  long rehashidx;  // -1 表示未在 rehash\n} dict;\n```\n`ht[0]` 在用，rehash 时 `ht[1]` 按不小于 `used*2` 的 2 的幂分配。\n\n**触发条件**（负载因子为 `used/size`）\n- 扩容：比值大于等于 1，且没有子进程在做 `BGSAVE`/`BGREWRITEAOF`；比值大于 5 时强制扩容，避免哈希冲突爆炸。\n- 缩容：比值小于 0.1，由 `serverCron` 周期性检查触发。\n\n**渐进式流程**\n1. 给 `ht[1]` 分配空间，置 `rehashidx = 0`。\n2. 每次读写命令顺带搬迁 `ht[0]` 的一个桶（`_dictRehashStep`），`serverCron` 每 100ms 再搬 1ms 的量。\n3. 搬完后 `rehashidx = -1`，释放 `ht[0]`，两表互换指针。\n\n**期间的行为差异**\n- 查找与删除：先查 `ht[0]`，没有再查 `ht[1]`。\n- 插入：只写 `ht[1]`，保证 `ht[0]` 只减不增。\n- 遍历：要同时扫两张表，所以 `SCAN` 在 rehash 期间可能重复返回同一个 key，这是设计允许的（保证至少一次，不保证只一次）。\n\n**要点**：`rehashidx` 是桶下标而不是元素下标；rehash 期间不会再触发新的扩容，因为 `ht[1]` 已存在。线上排查内存抖动时，要同时看 `used_memory` 曲线与大 key 的 `HGETALL` 耗时，二者经常是同一个根因。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 115 MINUTE), 1),
  (516, 3, 'redisObject 的字段含义与 type、encoding 组合', '所有 Redis 值都包在一个 16 字节的 redisObject 里，type 与 encoding 的组合决定了真实的底层结构。\n\n请说明：\n- redisObject 各字段的含义与总大小；\n- 常见的 type 与 encoding 组合；\n- refcount 的共享整数机制及其副作用；\n- 为什么这个结构对内存估算特别重要。', '**结论**：`redisObject` 是值对象的统一头部，`type` 决定哪些命令可用，`encoding` 决定底层实现；二者解耦，让同一类型可以在不同规模下切换结构。\n\n**布局（64 位系统 16 字节）**\n```bash\ntypedef struct redisObject {\n  unsigned type:4;\n  unsigned encoding:4;\n  unsigned lru:24;   // LRU 时钟，或 LFU 的 ldt 与 logc\n  int refcount;\n  void *ptr;\n} robj;\n```\n`lru:24` 在 LRU 模式存访问时间，切到 LFU 时拆成 16 位时间加 8 位对数计数器。\n\n**常见组合**\n| type | encoding |\n| --- | --- |\n| string | int / embstr / raw |\n| list | listpack 或 quicklist |\n| hash | listpack / hashtable |\n| set | intset / listpack / hashtable |\n| zset | listpack / skiplist |\n| stream | stream |\n\n小数据走紧凑编码，元素数或单元素长度超过 `*-max-listpack-entries`、`*-max-listpack-value` 就转成指针结构。\n\n**refcount 与共享对象**：启动时预建 0 到 9999 的整数字符串对象供共享，引用计数初始化为极大值，命中时不再分配。副作用是只能共享值对象，无法共享带 TTL 的键结构。\n\n**为什么重要**：估算内存时每个 key 至少有 `dictEntry`（约 24 字节）、key 的 SDS、`redisObject` 与底层结构开销。1 亿个短 key 的纯头部就是数 GB 量级，这是容量规划必须留余量的根本原因。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 116 MINUTE), 1),
  (517, 3, 'embstr 与 raw 的 44 字节边界是怎么来的', '同样是字符串，embstr 与 raw 的差别不只是编码名，而是内存分配次数与缓存局部性。\n\n请说明：\n- 44 字节这个边界如何算出；\n- embstr 与 raw 在分配次数上的差异；\n- 为什么 embstr 是只读的，追加内容会转成 raw。', '**结论**：短字符串用 `embstr`，把 `redisObject` 与 SDS 放在一块连续内存中一次分配；更长的用 `raw`，需要两次分配。分界线是 44 字节。\n\n**44 的来历**：jemalloc 中 64 字节是最常用的 size class，一次分配 64 字节块时，减掉对象头与 SDS 头即可：\n```bash\n64（分配块）- 16（redisObject）- 3（sdshdr8 头）- 1（结尾空字符）= 44\n```\n所以 `SET k <不超过 44 字节的值>` 得到 `embstr`，45 字节起变成 `raw`。\n\n**分配差异**\n- `embstr`：一次 `zmalloc`，对象头与内容相邻，释放也只释放一次，CPU 缓存命中更好。\n- `raw`：`redisObject` 与 `sdshdr` 分两次分配，通过指针关联。\n- 整数且能放进 `long`：直接用 `int` 编码，`ptr` 存数值本身，连 SDS 都省掉。\n\n**为什么只读**：`embstr` 的内存是一整块，`APPEND` 或 `SETRANGE` 需要扩容，无法原地 realloc（会破坏对象头布局），因此 Redis 直接把编码转成 `raw` 再做修改。执行一次 `append` 后用 `OBJECT ENCODING` 就能看到变成 raw，这是个常见追问点。\n\n**实践含义**：把长 value 拆小、避开 45 字节附近的尴尬长度、把热点小对象塞进 hash 的 listpack，都是利用这条边界的优化手段。用 `MEMORY USAGE key` 可以量化优化前后的差值。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 117 MINUTE), 1),
  (518, 3, 'AOF 三种 appendfsync 策略的取舍', 'AOF 的可靠性最终取决于 fsync 策略，这是「性能与丢数据量」之间最直接的旋钮。\n\n请说明：\n- appendfsync 三种取值的写盘与 fsync 时机；\n- 为什么 everysec 最多丢 1 秒，以及 fsync 变慢时对主线程的影响；\n- 生产环境如何选型，相关配置项有哪些。', '**结论**：`always` 每条命令都 fsync，最安全但吞吐骤降；`everysec` 由后台线程每秒 fsync，最多丢 1 秒，是默认与推荐值；`no` 完全交给操作系统，通常丢 30 秒左右。\n\n**机制**：命令执行后把协议文本追加到 `server.aof_buf`，`beforeSleep` 中统一 `write()` 到文件，这一步三种策略都一样，差别只在 fsync 由谁、何时执行。\n\n| 策略 | fsync 时机 | 丢数据窗口 | 性能 |\n| --- | --- | --- | --- |\n| always | 每批写入后主线程同步 fsync | 几乎为 0 | 最差，受磁盘 IOPS 限制 |\n| everysec | bio 线程每秒一次 | 不超过 1 秒 | 好，默认推荐 |\n| no | 内核脏页回写，约 30 秒 | 数十秒 | 最好 |\n\n**everysec 的两个坑**\n1. 上一秒的 fsync 尚未完成时，主线程的 `write()` 可能被阻塞（磁盘打满），表现为周期性延迟毛刺。可用 `no-appendfsync-on-rewrite yes` 在重写期间暂停 fsync 缓解，代价是重写期间丢数据窗口变大。\n2. `aof_last_write_status` 变成 err（如磁盘满）时 Redis 会拒绝写入，必须做监控告警。\n\n**选型建议**：订单与资金类要么 `always`，要么改用带共识的存储；普通业务用 `everysec` 加主从与 `WAIT` 兜底；纯缓存可以关掉 AOF 只留 RDB。相关配置还有 `appendonly`、`aof-use-rdb-preamble`、`auto-aof-rewrite-percentage`、`aof-load-truncated`。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 118 MINUTE), 1),
  (519, 3, 'AOF 重写的流程与 aof_rewrite_buf 的风险', 'AOF 文件会随写入无限增长，重写是把它压缩成最小命令集的过程，也是线上内存与延迟抖动的高发点。\n\n请说明：\n- 重写的触发方式与 fork 子进程的流程；\n- aof_rewrite_buf 的作用与风险；\n- Redis 7.0 的 multi-part AOF 相对 6.x 改进了什么。', '**结论**：重写由 fork 出的子进程基于当前内存快照生成新 AOF，父进程同时把新写入缓存起来，子进程完成后合并替换，全程不阻塞命令执行。\n\n**触发**：`auto-aof-rewrite-percentage 100` 加 `auto-aof-rewrite-min-size 64mb`，即文件相对上次重写增长一倍且超过 64MB 时自动触发；也可手动 `BGREWRITEAOF`。\n\n**流程**\n1. 父进程 `fork`，子进程遍历内存生成新 AOF；`aof-use-rdb-preamble yes` 时先写一段 RDB 二进制。\n2. 父进程把这期间的新写命令同时追加到旧 AOF 和 `aof_rewrite_buf`。\n3. 子进程完成，父进程把 `aof_rewrite_buf` 刷进新文件，最后 `rename` 原子替换旧文件。\n\n**风险**\n- `fork` 的写时复制会让写入多的实例内存接近翻倍，可能触发 maxmemory 淘汰甚至被 OOM Killer 干掉。\n- `aof_rewrite_buf` 在重写期间无上限增长，写入量大时本身就是内存隐患。\n- 子进程写盘与主进程 fsync 争抢磁盘 IO，造成延迟毛刺。\n\n**7.0 的改进**：multi-part AOF 把 AOF 拆成 `base.rdb`、若干 `incr.aof` 与 `manifest` 清单，重写只需生成新 base 并原子切换清单，不再需要把增量缓冲合并进旧文件，从根上消除了 `aof_rewrite_buf` 膨胀与 rename 阻塞。\n\n**运维要点**：监控 `aof_rewrite_in_progress`、`aof_rewrite_scheduled`、`latest_fork_usec`，避开业务高峰做重写，并给磁盘预留足够空间。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 119 MINUTE), 1),
  (520, 3, 'BGSAVE 的 fork 与写时复制对内存和延迟的影响', 'BGSAVE 看起来只是「后台存盘」，但 fork 与写时复制对内存和延迟的影响常被低估。\n\n请说明：\n- fork 之后父子进程如何共享内存；\n- 写时复制在什么时机发生，为什么会导致内存放大；\n- 如何评估与缓解对线上服务的影响。', '**结论**：`BGSAVE` 通过 fork 得到子进程，子进程与父进程共享同一份物理页，只有当某一方写入某页时才复制该页，这就是写时复制 COW。\n\n**过程**\n1. `fork()` 复制父进程页表，不复制数据页，返回值 0 给子进程。\n2. 子进程遍历内存写入临时 RDB 文件，写完 `rename` 成 `dump.rdb`。\n3. 父进程继续处理命令，一旦修改某个共享页，内核触发缺页异常，复制 4KB 到新页并改父进程映射。\n\n**内存放大估算**：最坏情况是 fork 期间父进程把所有页都写了，额外占用接近 `used_memory`。实际取决于写入分布，高峰期常见增长 30% 到 100%。这部分增量不体现在 `used_memory`，却体现在 `used_memory_rss`，因此容易触发系统 OOM Killer 或容器内存超限。\n\n**fork 耗时**：与页表项数量成正比，内存越大越慢。开启透明大页 THP 时页从 4KB 变成 2MB，页表项少了，但写一个字节要复制 2MB，往往让 fork 与内存放大都更糟。官方建议关闭 THP，把 `transparent_hugepage/enabled` 设为 never。\n\n**缓解手段**\n- 单实例内存控制在 10 到 16GB 以内，超了就分片。\n- 用 `repl-diskless-sync` 让从节点承担备份，主节点减少 `BGSAVE`。\n- 放在低峰期执行，监控 `rdb_last_bgsave_status` 与 `latest_fork_usec`。\n- 预留 30% 以上内存余量给 COW 与复制缓冲区。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 120 MINUTE), 1),
  (521, 3, '混合持久化 RDB 加 AOF 的文件结构与取舍', 'Redis 4.0 引入的混合持久化把 RDB 的快与 AOF 的全结合起来，成为多数生产环境的默认形态。\n\n请说明：\n- 混合持久化的文件结构；\n- 相比纯 AOF 在启动速度与数据安全上的取舍；\n- 兼容性与运维上的注意事项。', '**结论**：开启 `aof-use-rdb-preamble yes` 后，重写生成的 AOF 前半段是 RDB 二进制的全量快照，后半段是重写期间的增量命令；加载时先快速载入 RDB，再回放增量，兼顾启动速度与数据完整性。\n\n**结构**\n```bash\n[RDB 二进制全量] + [AOF 增量命令 ...]\n```\n恢复时 Redis 识别文件头部的 REDIS 魔术字，先用 RDB 加载器批量导入，再切换到 AOF 解析器继续回放。\n\n**取舍对比**\n| 维度 | 纯 AOF | 混合持久化 |\n| --- | --- | --- |\n| 启动速度 | 慢，逐条回放 | 快，先批量载入 |\n| 文件体积 | 大 | 小 |\n| 丢数据窗口 | 取决于 appendfsync | 同 appendfsync |\n| 可读性 | 可读、可手工修复 | 前半段不可读 |\n\n**兼容性**：混合格式文件不能被 4.0 以下的 Redis 读取。做版本回滚或迁移前，必须先关闭该配置并触发一次重写，否则回滚后直接启动失败。\n\n**运维要点**\n- 打开后 `redis-check-aof` 无法修复 RDB 段，损坏时通常要靠 RDB 备份兜底。\n- 加载期间主线程阻塞，超大实例可能数十秒不可用，应压低单实例体积。\n- 与 `aof-load-truncated yes` 配合，尾部半条命令可自动截断后启动。\n\n**一句话选型**：既要持久化又要快速重启，混合持久化是默认答案；需要逐条审计写入，才值得上纯 AOF。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 121 MINUTE), 1),
  (522, 3, '透明大页与超大实例下 fork 卡顿的定位与治理', '主从全量同步或定时 RDB 时出现的秒级卡顿，经常既不是慢查询也不是网络，而是 fork 本身。\n\n请说明：\n- fork 的耗时由什么决定；\n- 透明大页 THP 为什么会放大 fork 与 COW 的代价；\n- 线上如何定位并治理这类卡顿。', '**结论**：`fork` 的耗时主要取决于页表规模，而不是数据量本身；THP 把页从 4KB 放大到 2MB，会让页表更小但 COW 单位更大，两端都可能变差，因此 Redis 官方建议关闭 THP。\n\n**耗时来源**\n- 复制页表：`fork` 要为子进程复制父进程的全部页表项，内存 64GB 的实例可能几十万到上百万个页表项，耗时可达数百毫秒。\n- `fork` 期间主线程被挂起，所有客户端命令排队，表现为一次尖峰延迟。\n- 内存越大、碎片越多，耗时越长，且与写入量无关。\n\n**THP 的影响**\n- 开启后匿名页以 2MB 为单位映射，页表项数量降到 1/512，`fork` 复制页表变快。\n- 但 COW 的粒度变成 2MB：父进程改一个字节就要复制整页，内存放大与缺页开销剧增，反而更容易触发内存超限。\n- 实测中 THP 常让 `latest_fork_usec` 抖动更大、COW 内存膨胀更明显，官方配置建议里明确要求关闭。\n\n**定位手段**\n1. `INFO stats` 看 `latest_fork_usec`，与业务延迟毛刺时间点对齐。\n2. `INFO persistence` 看 `rdb_last_bgsave_status` 与耗时。\n3. `LATENCY DOCTOR` 与 `SLOWLOG` 排除慢命令。\n4. 系统层看 `dmesg` 是否有 THP 相关告警，容器内注意 cgroup 内存上限。\n\n**治理**\n- 关闭 THP：`echo never > /sys/kernel/mm/transparent_hugepage/enabled`。\n- 单实例内存控制在 16GB 以内，用 Cluster 分片。\n- 用从节点做持久化与备份，主节点减少 `BGSAVE`。\n- 大实例迁移到 `repl-diskless-sync` 并加 `repl-diskless-sync-delay` 合并多个从节点请求。\n\n结论：把 fork 当成一个需要容量规划的事件，而不是透明无感的操作。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 122 MINUTE), 1),
  (523, 3, 'AOF 文件损坏如何修复，redis-check-aof 做了什么', 'AOF 损坏导致 Redis 起不来是常见线上事故，修复流程与背后的取舍值得掌握。\n\n请说明：\n- AOF 损坏的典型原因；\n- redis-check-aof --fix 做了什么，代价是什么；\n- aof-load-truncated 的作用，以及 7.0 multi-part AOF 下的差异。', '**结论**：AOF 最常见的损坏是文件尾部只有半条命令，`redis-check-aof --fix` 会把文件截断到最后一条完整命令处，代价是丢弃尾部不完整的数据。\n\n**典型原因**\n- 磁盘写满导致 `write` 只写了半条命令。\n- 容器被 SIGKILL，用户态缓冲尚未落盘。\n- 手工编辑 AOF，破坏了 RESP 协议结构。\n- 文件系统或云盘异常、快照不一致。\n\n**修复步骤**\n1. 先备份原文件，切勿直接动手。\n2. 执行 `redis-check-aof --fix appendonly.aof`，工具从头逐条解析 RESP 命令，遇到不完整命令时会提示并截断。\n3. 再用 `redis-check-aof` 校验通过后启动实例。\n4. 启动后比对 `DBSIZE` 与业务预期，确认丢失范围。\n\n**aof-load-truncated**：默认 yes，启动时发现尾部不完整会自动截断并记日志继续启动，适合无人值守；设为 no 则直接拒绝启动，逼人工确认，资金类业务常用这种保守配置。注意它只能处理尾部截断，中间损坏仍然起不来。\n\n**7.0 multi-part AOF**：AOF 变成 `base.rdb` 加多个 `incr.aof` 再加 `manifest` 清单。修复对象变成清单与其引用的文件，损坏的通常是最后一个 incr 文件，删掉它并修正清单即可，影响面比 6.x 的单文件小很多，这也是 multi-part 的额外收益。\n\n**预防**：磁盘容量告警、`aof_last_write_status` 监控、`everysec` 加主从、避免容器无优雅停机。RDB 侧对应工具是 `redis-check-rdb`，但 RDB 损坏通常只能靠备份恢复。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 123 MINUTE), 1),
  (524, 3, 'Redis 的近似 LRU 算法与采样精度', 'Redis 的 LRU 不是教科书里的双向链表，而是采样近似，这个取舍直接决定了淘汰精度与 CPU 开销。\n\n请说明：\n- 为什么不用全局 LRU 链表；\n- 采样淘汰的具体流程，maxmemory-samples 如何影响精度；\n- lru 字段在 LRU 与 LFU 两种模式下如何复用。', '**结论**：维护全局 LRU 链表需要在每次访问时移动节点，每个 key 多两个指针，内存与 CPU 开销都不小；Redis 改为随机采样加候选池的近似 LRU，用 `maxmemory-samples` 调节精度。\n\n**流程**（`performEvictions`）\n1. 在键空间 dict 中随机采样 `maxmemory-samples`（默认 5）个设置了过期时间的 key。\n2. 读取各自 `redisObject.lru` 算出的空闲时间，把最久未使用的放入一个固定大小的候选池（3.0 起引入，默认 16）。\n3. 池满后只有更旧的 key 才能挤进去，最终淘汰池中最旧的一个。\n4. 重复直到内存回落到 `maxmemory` 以下，或达到 `maxmemory-eviction-tenacity` 限制。\n\n**精度**：采样 5 时选中「真正最旧」的概率约九成，采样 10 可达 99% 以上，代价是每次淘汰的 CPU 开销线性上升。官方基准显示 5 已够用；对命中率极敏感、又愿意付 CPU 的场景可调到 10。\n\n**字段复用**：`lru:24` 在 LRU 策略下存最后访问时间（秒级或毫秒级，由 `lru-clock-resolve` 决定）；切到 LFU 策略时被拆成 16 位 `ldt`（分钟级最后衰减时间）加 8 位 `logc`（对数计数器）。同一份结构支撑两种策略，切换后需要一段时间重新收敛。\n\n**实践**：`OBJECT IDLE key` 可查看空闲秒数；纯缓存用 `allkeys-lru`；同时存在持久数据与缓存时用 `volatile-lru`，并确保缓存 key 都设置了 TTL，否则等于没开淘汰。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 124 MINUTE), 1),
  (525, 3, 'LFU 的对数计数器、增长概率与衰减', 'LFU 解决的是 LRU 的一个经典缺陷：偶尔被批量扫一次的冷数据会把真正的热点挤出去。\n\n请说明：\n- LFU 计数器如何存储；\n- lfu-log-factor 与 lfu-decay-time 的作用；\n- LFU 适合什么业务，有哪些坑。', '**结论**：LFU 用 8 位对数计数器记录访问频次，访问越频繁增长越慢，并按时间衰减，从而在极少位数内表达很大的频率范围。\n\n**存储**：`redisObject.lru` 的 24 位被拆成 `ldt`（16 位，分钟级最后衰减时间）与 `logc`（8 位，0 到 255 的对数计数）。两个 key 共用同一字段，所以 LRU 与 LFU 不能同时生效。\n\n**增长概率**：每次访问不是简单地 `logc++`，而是以概率 `p = 1 / (baseval * lfu-log-factor + 1)` 递增，`baseval` 默认 1，`lfu-log-factor` 默认 10。含义是：命中几十次计数到 10 上下，要接近 255 上限需要百万级访问。把 factor 调小增长快但区分度低，调大则更适合超高热点。\n\n**衰减**：`lfu-decay-time`（默认 1 分钟）决定每隔多久 `logc` 减 1，长时间不被访问的 key 会自然回落，避免历史热点永久占坑。衰减只在访问或采样时按时间差补算，不是后台定时改。\n\n**初始化**：新 key 的 `logc` 初始为 5 而不是 0，防止刚写入的缓存立刻被淘汰，这是冷启动保护。\n\n**适用与坑**\n- 适合访问分布稳定、有明显长尾热点的缓存，如商品详情、热点新闻。\n- 不适合突发流量：新晋热点需要时间积累计数，可能先被淘汰。\n- 不适合访问模式快速翻转的业务，衰减参数要按业务周期调。\n- 用 `OBJECT FREQ key` 观察真实计数分布再定参数。\n\n**对比**：LRU 看最近有没有被访问，LFU 看被访问得够不够多；`maxmemory-policy` 只能二选一。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 125 MINUTE), 1),
  (526, 3, '内存已达 maxmemory 却无法淘汰键时怎么排查', 'used_memory 已经贴着 maxmemory，写入仍报 OOM command not allowed，这类问题很能体现对内存模型的理解。\n\n请说明可能的原因，并给出逐层排查的顺序与对应命令。', '**结论**：报错说明驱逐之后仍无法把内存降到 `maxmemory` 以下，或当前策略根本不允许驱逐。要区分「没得淘汰」「淘汰不动」「不是淘汰能解决」三类原因。\n\n**1. 策略不允许**\n`maxmemory-policy noeviction` 时任何写命令直接拒绝。先 `CONFIG GET maxmemory-policy` 确认。\n\n**2. 没有可淘汰的 key**\n`volatile-lru`、`volatile-ttl` 只淘汰设置了 TTL 的 key。如果绝大多数 key 是永久的，就淘汰不动。对比 `INFO keyspace` 里的 keys 与 expires 两个数字；纯缓存场景应改成 `allkeys-lru`。\n\n**3. 单个 key 太大**\n淘汰几个小 key 腾出的空间仍然不够，或某个大 key 本身就超过水位。用 `redis-cli --bigkeys`、`MEMORY USAGE` 定位，然后改造为分片结构。\n\n**4. 内存不归 maxmemory 管**\n以下部分不受驱逐控制，容易把 RSS 顶爆：\n- 主从复制缓冲区 `mem_clients_slaves`\n- 客户端输出缓冲区（`client list` 的 `omem`，大范围查询与 Pub/Sub 积压）\n- 复制 backlog、AOF 缓冲、`aof_rewrite_buf`\n- 内存碎片，`mem_fragmentation_ratio` 大于 1.5 时尤其明显\n用 `INFO memory` 与 `INFO clients` 把 `used_memory_rss` 与 `used_memory` 分段比对。\n\n**处置顺序**：看策略，看有无 TTL，看大 key，看客户端与复制缓冲，看碎片，最后才扩容。同时把 `evicted_keys`、`rejected_connections`、`mem_fragmentation_ratio` 纳入告警，别等业务写失败才发现。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 126 MINUTE), 1),
  (527, 3, '过期键在 RDB 与 AOF 中的处理差异', '同一个过期键，在 RDB 与 AOF 里被保存和被删除的时机并不相同，主从之间还有额外约定。\n\n请说明：\n- RDB 保存与加载时如何处理过期键，主库与从库有何不同；\n- AOF 何时记录过期键的删除，重写时怎么处理；\n- 由此产生的「从库能查到 key 却读不到值」现象如何解释。', '**结论**：过期键的删除不是写入持久化文件的一部分，而是由过期删除策略触发后作为一条 `DEL` 命令传播；主库与从库在加载与读取上的处理不同。\n\n**RDB**\n- 保存：写入键值对时，若 key 已过期且当前是主库，直接跳过不落盘。\n- 加载：主库加载时丢弃已过期键；从库加载时保留，因为从库不主动过期，删除权在主库，需要等主库同步 `DEL` 下来。\n- 因此用 RDB 恢复后基本不会复活过期键（主库视角）。\n\n**AOF**\n- 写入：过期键不会立刻追加 `DEL`，只有惰性删除（访问命中）或定期删除扫描到时，才追加一条 `DEL`。\n- 重写：`BGREWRITEAOF` 遍历内存时会跳过已过期键，所以重写后的文件里不再包含它们。\n- 从库的 AOF：从库不主动删除，其 AOF 中可能存在逻辑上已过期的键，直到主库下发 `DEL`。\n\n**主从读一致性**：从库执行读命令时会检查 key 是否逻辑过期，若已过期则返回 nil，既不返回数据也不删除。所以会出现 `EXISTS` 或 `KEYS` 能看到、`GET` 却拿不到的现象，这是设计行为而不是 bug。`DBSIZE` 在从库上也可能比主库偏大。\n\n**实战结论**\n- 只用 RDB 恢复，过期键基本不会复活。\n- 用纯 AOF 恢复，需要回放到那条 `DEL` 才真正消失，文件更大。\n- 主从架构下不要把从库当作强一致的读源，尤其是刚写过、带 TTL 的 key。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 127 MINUTE), 1),
  (528, 3, 'Redis 过期事件通知为什么不能当可靠消息用', '用 keyspace notification 监听 key 过期来做订单超时关闭，是典型的踩坑现场。\n\n请说明：\n- 过期事件通知的配置与发布机制；\n- 它为什么不可靠，有哪几类丢失或延迟场景；\n- 替代方案如何选。', '**结论**：keyspace notification 基于 Pub/Sub，无持久化、无确认、无重投，且过期事件只有在键被实际删除时才触发，因此只能用于容忍丢失的提示型场景，不能当作可靠定时消息。\n\n**配置与机制**：\n```bash\nCONFIG SET notify-keyspace-events KEA\nPSUBSCRIBE __keyevent@0__:expired\n```\n`K` 表示 keyspace 事件，`E` 表示 keyevent 事件，`A` 表示全部类型（不含 m 与 n 两个特殊类）。事件由 `notifyKeyspaceEvent` 在删除动作发生后发布。\n\n**不可靠的四个原因**\n1. 依赖实际删除：Redis 用惰性删除加定期抽样删除，一个已过期但从未被访问的 key 可能几分钟后才被删，事件时间点远不精确。\n2. 发布即丢弃：Pub/Sub 不落盘，订阅端断连、重连期间的事件直接丢失，没有 ACK 与重投。\n3. 主从与集群：事件只在执行删除的节点发布，主从切换或集群多节点时可能漏掉；客户端需要订阅所有节点的对应事件。\n4. 慢消费者：输出缓冲区超限会被踢下线（`client-output-buffer-limit pubsub`），事件静默丢失。\n\n**替代方案**\n- 可靠延迟：Redis Stream 加消费组，用 `XPENDING` 处理未确认消息；或直接上 RocketMQ 延迟消息、RabbitMQ 死信队列。\n- 定时扫描：业务侧用低精度轮询兜底，容忍分钟级延迟。\n- 状态机补偿：订单表存过期时间，定时任务扫超时未支付记录，这才是资金类业务的正确姿势。\n\n**结论**：过期通知适合缓存失效广播、监控告警这类丢了也能忍的场景。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 128 MINUTE), 1),
  (529, 3, 'SCAN 的游标原理与为什么不会阻塞', '线上禁用 KEYS 后，SCAN 成了遍历键空间的标准手段，但它的语义常被误解。\n\n请说明：\n- SCAN 的游标是如何计算出来的；\n- 它保证了什么、不保证什么；\n- COUNT 参数的真实含义，以及在 rehash 期间的行为。', '**结论**：SCAN 用反向二进制迭代（reverse binary iteration）遍历哈希表的桶下标，每次调用只扫描有限个桶就返回新游标，因此不会长时间阻塞主线程；它保证遍历期间一直在集合里的元素至少返回一次，但可能重复。\n\n**游标原理**：游标不是元素下标，而是桶索引按位反转后的数值。假设表大小 8，遍历顺序是 0、4、2、6、1、5、3、7，这正好是「高位进位」的顺序。这样设计的好处是：当表扩容或缩容（大小变成 2 的幂的另一值）时，已遍历过的桶不会被重复扫描，也不会漏掉新元素，只需按位掩码取模即可映射到新表。\n\n**保证与不保证**\n- 保证：从开始到结束期间一直存在的元素至少返回一次。\n- 不保证：可能重复返回（rehash 期间扫两张表）；遍历开始后才写入的元素可能返回也可能不返回。\n\n**COUNT 的含义**：只是「每次调用建议扫描的桶数」，不是返回条数。实际返回数量可能远小于 COUNT（桶是空的），也可能更多（桶是链表）。调大 COUNT 减少往返次数但单次阻塞更久，默认 10 偏保守，生产常用 100 到 1000。\n\n**rehash 期间**：dict 有两个哈希表时，SCAN 会按 `rehashidx` 交替扫描 `ht[0]` 与 `ht[1]`，这正是可能重复的根源。\n\n**实践**：用 `SCAN 0 MATCH user:* COUNT 500` 循环直到游标回到 0；大 key 上慎用 `HSCAN`（仍会遍历整桶）；把遍历类任务放到从库执行。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 129 MINUTE), 1),
  (530, 3, '线上为什么禁止使用 KEYS 命令', 'KEYS pattern 是新手最爱的调试命令，也是线上最危险的命令之一。\n\n请说明：\n- KEYS 的时间复杂度与阻塞机理；\n- 百万级 key 的实例执行一次大概会怎样；\n- 生产环境有哪些替代手段。', '**结论**：`KEYS` 会遍历整个键空间并对每个 key 做模式匹配，复杂度 O(N)，且在主线程同步执行，在百万级 key 的实例上可能阻塞数百毫秒甚至数秒，期间所有请求排队。\n\n**阻塞机理**：Redis 命令串行执行，`KEYS` 不释放主线程，遍历期间事件循环停转，客户端连接上的其他命令、过期键清理、心跳全部延后。key 越多、pattern 越复杂、网络带宽越紧张（返回结果还要写 socket），阻塞越久。极端情况下客户端输出缓冲区被打满，触发 `client-output-buffer-limit` 被强制断开。\n\n**实测感受**：100 万 key 单次 `KEYS *` 大约几十到几百毫秒，若结果有几十万条，序列化与网络发送会让总耗时到秒级，监控上表现为一个明显的延迟尖刺与 QPS 掉零。\n\n**替代手段**\n- `SCAN` 游标遍历，分批处理，不阻塞。\n- 维护索引：写入时同步把 id 放进一个 Set 或 ZSet，查询时直接取索引，这是最优解。\n- 按业务前缀拆 key 空间，或直接用 `RedisSearch` 建立二级索引。\n- 离线分析走 RDB 备份到独立实例，不碰线上主库。\n\n**工程兜底**：在 `redis.conf` 里用 `rename-command KEYS ""` 直接禁用（7.0 起推荐用 ACL 限制），同时禁用 `FLUSHALL`、`FLUSHDB`、`CONFIG`；把 `SLOWLOG` 阈值设成 10ms，出现即告警。团队规范里明确：遍历类操作用 SCAN，禁止 KEYS。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 130 MINUTE), 1),
  (531, 3, '用 Redis 实现延迟队列的三种方案与各自缺陷', '订单 30 分钟未支付自动关闭、预约任务到期触发，这类需求经常被要求「用 Redis 实现」。\n\n请说明：\n- 基于 zset 轮询的实现与原子性问题；\n- 基于 Stream 消费组的实现；\n- 两种方案的缺陷，什么场景该换专业消息队列。', '**结论**：zset 加轮询适合小规模、可容忍秒级误差的延迟任务；要可靠投递与重试，应使用 Redis 5.0 之后的 Stream 消费组；对顺序、堆积、事务要求高的场景应直接用 RocketMQ 延迟消息或 RabbitMQ 死信队列。\n\n**方案一：zset 轮询**\n```bash\nZADD delay_queue <执行时间戳> <task_id>\n```\n消费者循环 `ZRANGEBYSCORE delay_queue 0 <now> LIMIT 0 10`，取到后用 Lua 脚本完成 `ZREM` 加投递，保证「只有一个消费者拿到」。缺陷：\n- 空轮询浪费 CPU 与连接，需要自适应休眠。\n- `ZREM` 成功但投递失败会丢任务，需要额外补偿表。\n- 时间精度取决于轮询间隔，通常 1 秒。\n- 多消费者并发时靠 Lua 去重，仍需处理重复消费的幂等。\n\n**方案二：Stream 消费组**\n`XADD` 写入，消费者 `XREADGROUP ... BLOCK 2000 STREAMS s >` 读取，处理成功 `XACK`，失败或宕机遗留的消息用 `XPENDING` 与 `XAUTOCLAIM` 转移重投。天然支持阻塞等待（无空轮询）、ACK、重投与消费进度监控（`XINFO GROUPS` 看 lag）。\n\n**方案三：时间轮加本地调度**\n把任务按到期时间分桶放在本地内存，Redis 只存持久化副本，重启时重建。延迟最低，但需要处理节点故障转移。\n\n**选型建议**：延迟精度秒级、任务量百万以内、能接受至少一次投递，Stream 是 Redis 内最优解；秒杀、订单关闭这类对可靠性要求高的场景，Redis 只做前置缓冲，真正的定时与重试交给专业 MQ 加数据库状态机兜底。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 131 MINUTE), 1),
  (532, 3, '用 zset 实现排行榜时的同分排序与精度问题', '排行榜是 zset 最经典的业务场景，但同分排序、分数精度、超大榜单三个坑几乎必踩。\n\n请说明：\n- zset 的 score 精度限制在哪里；\n- 如何用复合分数解决同分按时间排序；\n- 榜单规模很大时如何设计。', '**结论**：zset 的 score 是 IEEE754 double，整数有效位只有 53 位，超过 2 的 53 次方会丢精度；同分时按 member 字典序排列，因此需要用复合分数把时间维度编码进去。\n\n**精度限制**：score 用 double 存储，整数部分超过 9007199254740992 后相邻整数无法区分。把毫秒时间戳（约 1.7 乘以 10 的 12 次方）直接当 score 没问题，但若再乘上 10 的 6 次方就会溢出精度，导致排序错乱。\n\n**复合分数设计**：\n```bash\nscore = 业务分数 * 10^10 + (基准时间 - 达成时间)\n```\n业务分数占高位，时间差占低位，先比分数、同分比谁更早达成。低位部分必须预留足够位宽并确认总和不超过 2 的 53 次方。若分数本身带小数，改用「分数取整乘系数」或把时间放到 member 里用 `ZREVRANGE` 后二次排序。\n\n**常用命令**\n- `ZINCRBY rank 1 user:1` 更新分数\n- `ZREVRANGE rank 0 9 WITHSCORES` 取前 10\n- `ZREVRANK rank user:1` 查排名（O(log N)）\n- `ZREVRANGEBYSCORE` 按分数区间取\n\n**超大榜单**：千万级成员时单 key 太大，`ZREVRANGE` 与 `ZREVRANK` 都会变慢且迁移困难。方案：按分数段或用户 ID 哈希分片成多个 zset，查询时先查各分片 Top N 再归并；或只维护 Top N 榜单，全量排名交给离线计算。\n\n**注意点**：`ZADD` 更新不会重置 TTL（key 级），榜单要有明确的生命周期与归档策略；并发更新用 `ZINCRBY` 而不是读改写。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 132 MINUTE), 1),
  (533, 3, 'Stream 消费组的 PEL、ACK 与消息转移', 'Stream 是 Redis 官方给出的消息队列方案，理解消费组与 PEL 才算真正会用。\n\n请说明：\n- XADD 的消息 ID 结构与 XGROUP 的创建；\n- XREADGROUP 中 > 与具体 ID 的区别；\n- PEL 的作用，XPENDING 与 XAUTOCLAIM 如何做故障转移。', '**结论**：Stream 用消费组把消息分发给多个消费者，未被 ACK 的消息留在 PEL（Pending Entries List）里，可以用 XPENDING 查看、用 XAUTOCLAIM 把它们转给其他消费者重投，这是 Redis 内唯一支持「至少一次」投递的结构。\n\n**消息 ID**：`<毫秒时间戳>-<序号>`，例如 `1699999999999-0`。`XADD s * field v` 让服务端生成，`XADD s 1699999999999-0` 指定（必须大于现有最大 ID）。`XADD s MAXLEN ~ 100000 *` 近似裁剪控制内存。\n\n**消费组**：\n```bash\nXGROUP CREATE s g1 0 MKSTREAM\nXREADGROUP GROUP g1 c1 COUNT 10 BLOCK 2000 STREAMS s >\n```\n`>` 表示「从未投递给任何消费者的新消息」，会同时写入 `c1` 的 PEL；若传具体 ID（如 `0`），则读取该消费者自己 PEL 里的历史消息，用于重处理。\n\n**PEL 与故障转移**\n- 处理成功后必须 `XACK s g1 <id>`，否则消息永远留在 PEL。\n- `XPENDING s g1` 看整体滞留数量、最小最大 ID、各消费者持有数；`XPENDING s g1 - + 10` 看明细与空闲时长。\n- `XAUTOCLAIM s g1 c2 60000 0-0 COUNT 10` 把空闲超过 60 秒的消息转给 `c2`，Redis 6.2 起替代手写的 `XPENDING` 加 `XCLAIM`。\n- `XINFO GROUPS s` 的 `lag` 反映积压量。\n\n**与 Kafka 的差异**：无分区、无再均衡、无副本（依赖主从），单 key 吞吐有限；消费组内消费者数量与并行度受单线程限制，超大吞吐场景仍应上专业 MQ。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 133 MINUTE), 1),
  (534, 3, 'LPUSH 加 BRPOP 做队列为什么会丢消息', 'List 做队列是最简单的用法，也是最容易丢消息的用法。\n\n请说明：\n- BRPOP 的语义与消息丢失的时机；\n- 如何用 LMOVE 改造成可靠队列；\n- 与 Stream 消费组相比差在哪里。', '**结论**：`BRPOP` 是「弹出即删除」，消息一旦从 Redis 移除就只存在于消费者内存中，消费者崩溃或处理失败就永久丢失；要做到至少一次投递，必须把消息先搬到 processing 列表并配合超时补偿。\n\n**丢失场景**\n1. 弹出后进程被 kill，消息既不在队列也不在处理结果里。\n2. 处理逻辑抛异常，没有重试机制。\n3. 多消费者并发弹出后，其中一个长时间阻塞，消息被它「占着」。\n4. 客户端超时重连，服务端已弹出但响应丢失。\n\n**可靠队列改造**：\n```bash\nLMOVE queue processing RIGHT LEFT\n```\n消费者从 `queue` 取出并原子写入 `processing`（相当于 PEL），处理成功后 `LREM processing 1 <msg>` 确认；另起巡检任务把 `processing` 中超过阈值时长的消息搬回 `queue` 重投。这是在 Stream 出现前的标准做法。\n\n**其他注意点**\n- `BRPOP` 超时设为 0 会永久阻塞，客户端连接不能复用给其他命令，需独立连接。\n- 空的 `BRPOP` 轮询在连接数多时消耗明显，`BLPOP` 有超时上限时要合理设置。\n- List 不支持消费组，无法多播，多个业务方只能各自复制一份。\n\n**Stream 的优势**：PEL 天然记录未确认消息，`XPENDING` 与 `XAUTOCLAIM` 提供标准化的重投，`XACK` 显式确认，还支持按 ID 回溯与消费组 lag 监控。因此新项目应直接选 Stream，List 只适合日志投递、异步通知这类可丢场景。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 134 MINUTE), 1),
  (535, 3, '基于 Redis 的四种限流方案与边界突刺问题', '限流是网关与开放接口的必备能力，用 Redis 做分布式限流又是最常见的选择。\n\n请说明：\n- 固定窗口、滑动窗口、令牌桶、漏桶各自的实现与缺陷；\n- 固定窗口的边界突刺如何产生；\n- 分布式限流在集群下的注意点。', '**结论**：固定窗口用 `INCR` 加 `EXPIRE` 最简单但有边界突刺；滑动窗口用 zset 精确但内存随请求量增长；令牌桶允许一定突发、最贴近真实业务；漏桶输出恒定、适合保护下游。\n\n**固定窗口**\n```bash\nINCR rate:api:1699999999\nEXPIRE rate:api:1699999999 60\n```\n计数超阈值即拒绝。缺陷是边界突刺：第 59 秒打满 100 次，第 61 秒又打满 100 次，两个窗口交界处 2 秒内实际放过 200 次。\n\n**滑动窗口**：用 zset 存每次请求的时间戳，`ZREMRANGEBYSCORE` 清理过期、`ZCARD` 计数、`ZADD` 记录，三段用 Lua 保证原子。精确但每个请求一条记录，QPS 高时内存与 CPU 都吃紧。可用「滑动窗口计数」折中：把大窗口切成若干小格，按格累加。\n\n**令牌桶**：Redis 里用 hash 存 `tokens` 与 `last_ts`，每次请求按 `(now - last_ts) * rate` 补充令牌，取走一个。允许突发到桶容量，长期速率受 rate 约束，是最常用的方案，用 Lua 保证读改写原子。\n\n**漏桶**：以固定速率放行，超出排队或丢弃，输出绝对平滑，适合保护脆弱的下游。\n\n**分布式注意点**\n- 每个限流维度一个 key，注意 key 数量膨胀与 TTL 清理。\n- Cluster 下限流 key 是单点热 key，可用本地令牌桶加中心配额预取（每节点一次取 100 个令牌）降低压力。\n- Redis 不可用时的兜底策略必须提前定：放行、拒绝还是退化到本地限流。\n- 时间必须取服务端时间，避免多机时钟漂移导致配额错乱。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 135 MINUTE), 1),
  (536, 3, '写出一个正确的令牌桶限流 Lua 脚本并说明坑', '用 Lua 实现令牌桶是高频手写题，能写出边界正确的版本才算过关。\n\n请说明：\n- 脚本的入参与核心逻辑；\n- 为什么时间必须取 Redis 服务端时间；\n- 脚本超时、key 过期、集群下的注意点。', '**结论**：令牌桶的核心是「按时间差补令牌、上限截断、够则扣减并写回」，必须整段放在 Lua 里原子执行，读写分离的实现一定超发。\n\n**脚本**\n```lua\nlocal k = KEYS[1]\nlocal rate = tonumber(ARGV[1])\nlocal cap = tonumber(ARGV[2])\nlocal t = redis.call("TIME")\nlocal now = t[1] + t[2] / 1e6\nlocal d = redis.call("HMGET", k, "tokens", "ts")\nlocal tk = tonumber(d[1]) or cap\nlocal ts = tonumber(d[2]) or now\ntk = math.min(cap, tk + math.max(0, now - ts) * rate)\nlocal ok = 0\nif tk >= 1 then tk = tk - 1; ok = 1 end\nredis.call("HMSET", k, "tokens", tk, "ts", now)\nredis.call("PEXPIRE", k, math.ceil(cap / rate * 1000) + 1000)\nreturn ok\n```\n\n**关键坑**\n1. 时间必须取服务端 `TIME`，客户端传时间会因时钟漂移让配额错乱；用了 TIME 就依赖 effects replication，老版本需显式 `redis.replicate_commands()`。\n2. `tokens` 初始化为容量、`ts` 初始化为当前时间，避免冷启动误限流或一次性补满。\n3. 必须设 PEXPIRE，否则每个维度一个永久 hash 会把内存吃光。\n4. 集群下用 `{rate}:user:1` 这类 hash tag 保证 KEYS 同槽；脚本要短，超时后只能 `SCRIPT KILL`。\n\n返回剩余令牌数比返回 0/1 更有用，便于响应头回填。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 136 MINUTE), 1),
  (537, 3, 'Redlock 算法的争议与它到底解决了什么问题', 'Redlock 是分布式锁领域最著名的辩论题，面试官想听的是边界而不是站队。\n\n请说明：\n- Redlock 的加锁与解锁流程；\n- Kleppmann 的质疑核心是什么；\n- 什么场景能用、什么场景不该用。', '**结论**：Redlock 试图用多个独立 Redis 主节点把「单点故障导致锁失效」的概率降下来，流程是向多数节点加锁并在总耗时小于锁有效期时才算成功；但它无法解决时钟漂移与进程停顿，因此不能提供严格的互斥保证。\n\n**流程**\n1. 客户端记录开始时间，依次向 N 个（通常 5 个）互相独立的 Redis 实例执行 `SET key val NX PX 30000`。\n2. 若在超过半数节点上加锁成功，且总耗时小于锁有效期（还要减去时钟漂移余量），则认为加锁成功。\n3. 失败则向所有节点发送解锁（用 Lua 比对 value 再删）。\n4. 解锁同样向所有节点发起。\n\n**Kleppmann 的质疑**\n- 锁的有效性依赖各节点本地时钟，一旦某节点时钟跳变，锁可能提前失效。\n- 客户端发生长时间 GC 或虚拟机暂停，醒来时锁已过期却浑然不知，仍会执行临界区代码，此时另一个客户端已持锁，互斥被破坏。\n- 解决办法是 fencing token：每次加锁返回单调递增的令牌，下游存储校验令牌，拒绝旧令牌的写。而这恰恰说明锁本身不足以保证安全。\n\n**antirez 的回应**：Redlock 面向的是「效率型」场景（避免重复劳动），不是「正确性型」场景（资金扣减），在合理假设下足够用。\n\n**结论**：需要严格互斥时，选带 fencing 的方案或 etcd、ZooKeeper 这类基于共识的实现；只是防止重复执行、降低资源竞争的效率场景，单实例加过期时间加唯一 value 校验就够，Redlock 的复杂度往往不值得。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 137 MINUTE), 1),
  (538, 3, '分布式锁的看门狗续期机制与它的风险', '锁的过期时间设短了业务没执行完就失效，设长了节点宕机后要等很久，看门狗就是为这个矛盾而生。\n\n请说明：\n- 看门狗的工作机制；\n- 什么条件下才会启用续期；\n- 续期机制本身有哪些风险。', '**结论**：看门狗是一个后台任务，在持锁期间周期性把锁的过期时间重置为设定值（如每 10 秒把 30 秒的锁续回 30 秒），从而让业务执行时间不再被写死的 leaseTime 限制。\n\n**机制（以 Redisson 为例）**\n- 加锁时不指定 `leaseTime`，默认 30 秒过期，同时注册一个定时任务。\n- 定时任务每 `leaseTime/3`（10 秒）检查一次，锁仍被当前线程持有则执行 `PEXPIRE` 续期。\n- 显式指定了 `leaseTime` 则**不启用**看门狗，到点必释放，这是最容易踩的坑。\n- 解锁时取消定时任务，并用 Lua 比对 value 再删除，避免误删别人的锁。\n\n**风险**\n1. 网络分区：客户端与 Redis 断连，续期失败，锁过期后别的客户端拿到锁，出现双持有。\n2. 长时间 STW：Full GC 或容器被冻结期间续期线程不跑，锁过期，与 Redlock 的质疑同源。\n3. 业务死循环：续期会一直成功，锁永不释放，把并发彻底堵死，比锁提前失效更糟。\n4. 续期本身增加 QPS：大量锁时后台任务与 Redis 交互频繁，需评估容量。\n\n**工程建议**：\n- 明确业务最大执行时间，优先用固定 `leaseTime` 加超时控制，而不是无限续期。\n- 配合 fencing token 或数据库乐观锁做最终防线。\n- 监控锁等待时间与续期失败次数。\n- 临界区尽量短，把长耗时操作挪到锁外。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 138 MINUTE), 1),
  (539, 3, 'Lua 脚本的原子性边界与超时处理', '很多人把 Lua 当成「Redis 事务的完美替代」，但它的原子性有明确边界。\n\n请说明：\n- Lua 在 Redis 中的原子性到底指什么；\n- 脚本执行超时会怎样，能否被中断；\n- 写脚本时有哪些必须遵守的纪律。', '**结论**：Lua 的原子性是「执行期间不插入其他客户端的命令」，而不是「要么全成功要么全失败」；脚本中途报错，前面已执行的写命令不会回滚。\n\n**原子性的真实含义**：Redis 单线程执行脚本，脚本运行期间事件循环不处理其他命令，因此脚本内的多个操作对外表现为一个整体。但脚本没有事务的回滚能力，`redis.call` 抛错后脚本终止，已完成的写入保留。要保证一致性，必须把校验放在所有写操作之前，让脚本要么全做要么在第一个写之前退出。\n\n**超时处理**\n- `lua-time-limit` 默认 5 秒（`busy-reply-threshold`）。超过后 Redis 不会强行杀死脚本，而是开始对其他客户端返回 BUSY 错误。\n- 此时只允许两类命令：`SCRIPT KILL`（仅当脚本尚未执行过写命令）和 `SHUTDOWN NOSAVE`。\n- 一旦脚本已经写过数据，就只能等它跑完或重启，这是「原子性」的另一面代价。\n\n**必须遵守的纪律**\n1. 脚本要短：禁止 `KEYS`、全量 `SMEMBERS`、大 `ZRANGE`，单次操作控制在毫秒级。\n2. 所有 key 显式放进 `KEYS` 数组，便于集群校验同 slot 与代理层路由。\n3. 集群下用 hash tag 保证多 key 同 slot。\n4. 不要依赖客户端时间，用 `redis.call("TIME")`；5.0 前还要求脚本确定性（不能有随机、时间），之后 effects replication 放宽了限制。\n5. 优先 `EVALSHA` 减少传输，但要处理 `NOSCRIPT` 回退。\n\n**替代方案**：Redis 7.0 的 Functions 把脚本作为库持久化，随 AOF 与 RDB 一起复制，解决了脚本缓存丢失问题，新项目可以优先考虑。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 139 MINUTE), 1),
  (540, 3, 'Lua 脚本的复制方式与 EVALSHA 缓存失效问题', '脚本在主从与集群环境下的复制行为，是理解「为什么脚本要可重入」的关键。\n\n请说明：\n- 脚本复制从「复制脚本本身」到「复制效果」的演进；\n- EVALSHA 的脚本缓存机制与 NOSCRIPT 的成因；\n- Redis 7.0 Functions 如何解决这个问题。', '**结论**：Redis 5.0 起默认使用效果复制（effects replication），即把脚本执行产生的写命令复制给从库，而不是复制脚本本身；这让脚本可以使用随机命令与时间，但要求脚本在执行前把所有写操作确定下来。\n\n**演进**\n- 早期（2.6 到 4.x）：主库把整个脚本发给从库重放，因此要求脚本必须确定性——不能用 `TIME`、`RANDOMKEY`、`SPOP` 这类结果依赖环境的命令，否则主从数据会分叉。\n- 5.0 起：默认 `effects replication`，脚本执行时把产生的写命令包在 `MULTI`/`EXEC` 里传播。需要时可用 `redis.replicate_commands()`（5.0 前必须显式调用）开启，7.0 起为默认且不可关闭。\n\n**EVALSHA 与缓存**\n`EVAL` 每次发送脚本体，浪费带宽。`SCRIPT LOAD` 或首次 `EVAL` 后，Redis 用脚本的 SHA1 作为 key 缓存在 `server.lua_scripts` 字典里，客户端后续用 `EVALSHA <sha>` 只发 40 字符。问题在于：\n- 从库提升为主库、实例重启、`SCRIPT FLUSH` 之后，缓存为空，`EVALSHA` 返回 `NOSCRIPT No matching script`。\n- 客户端必须捕获 `NOSCRIPT` 并回退到 `EVAL` 重新加载，成熟的客户端库（如 Redisson、Lettuce）已内置这个逻辑。\n\n**集群下的额外问题**：脚本缓存不跨节点，客户端连到不同节点时要各自加载；代理型方案要注意 `EVALSHA` 的路由与缓存一致性。\n\n**7.0 Functions**：`FUNCTION LOAD` 注册的脚本库会随 AOF 与 RDB 一起持久化和复制，从库天然拥有相同函数，`FCALL` 不再有缓存失效问题，同时支持库级管理与 ACL 授权，是脚本方案的发展方向。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 140 MINUTE), 1),
  (541, 3, '用 WATCH 实现 CAS 乐观锁的正确姿势', 'WATCH 是 Redis 里最像「乐观锁」的机制，但它与事务的绑定方式常被写错。\n\n请说明：\n- WATCH 加 MULTI/EXEC 的执行语义；\n- 用 WATCH 实现库存 CAS 的完整流程与重试；\n- 它有哪些限制，何时该改用 Lua。', '**结论**：`WATCH` 监视若干 key，若在 `EXEC` 之前这些 key 被任何客户端修改，`EXEC` 返回 nil 表示事务未执行，客户端需要读取最新值重试；这就是乐观锁的 CAS 语义。\n\n**语义细节**\n- `WATCH` 必须在 `MULTI` 之前调用，且与事务在**同一个连接**上。`MULTI` 之后的 `WATCH` 会报错。\n- `EXEC` 返回 nil 表示被监视的 key 至少有一个被改动（包括过期删除、被其他客户端写、甚至被自己 WATCH 后修改）。\n- `EXEC` 或 `DISCARD` 后所有监视自动清除，需要重新 `WATCH`。\n- `UNWATCH` 可主动放弃监视，用于提前退出。\n\n**库存 CAS 流程**\n```bash\nWATCH stock:1001\nGET stock:1001          -- 判断是否充足\nMULTI\nDECRBY stock:1001 1\nEXEC                    -- 返回 nil 则重试整个流程\n```\n注意 `GET` 与判断在 `WATCH` 之后、`MULTI` 之前完成，判断逻辑在客户端，因此存在「判断与执行之间值被改动」的窗口，靠 `EXEC` 的失败来发现，而不是靠锁。\n\n**限制**\n1. 冲突高时重试次数暴涨，CPU 与连接被浪费，高并发扣减不适合。\n2. 集群模式下所有被 WATCH 的 key 必须在同一 slot。\n3. `EXEC` 返回 nil 只能说明失败，不告诉你哪个 key 变了，重试逻辑必须幂等。\n\n**何时改用 Lua**：需要「判断加修改」原子完成、冲突频繁、逻辑超过两三个 key 时，用 Lua 脚本一次搞定，无需重试，也不会因并发失败而空转。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 141 MINUTE), 1),
  (542, 3, 'Pipeline 的批量大小该如何控制', 'Pipeline 显著降低 RTT，但无节制地攒一千条命令又会引入新的问题。\n\n请说明：\n- Pipeline 减少开销的原理；\n- 批量过大时会带来哪些服务端与客户端风险；\n- 生产上如何选择批量大小，以及和事务的区别。', '**结论**：Pipeline 把 N 条命令一次性发出、一次性读取响应，节省 N 次网络往返与系统调用；但批量大小要按「条数加字节数」双重限制，通常每次 100 到 1000 条或 1MB 以内。\n\n**原理**：普通调用每条命令都要经历发送、等待、读取三次开销，RTT 是主要成本。Pipeline 在客户端把命令攒在发送缓冲区，服务端逐条执行并把响应堆在输出缓冲区，最后一次性读回。吞吐提升在网络 RTT 较大时最明显，同机通信提升有限。\n\n**批量过大的风险**\n1. 客户端内存：N 条命令加 N 条响应同时在内存里，十万条大 value 能直接把客户端撑爆。\n2. 服务端内存：输出缓冲区 `omem` 超限会触发 `client-output-buffer-limit` 被强制断开，客户端只看到连接重置。\n3. 主线程阻塞：服务端虽然逐条执行，但连续处理大批命令会让其他客户端排队，表现为别人的延迟毛刺。\n4. 超时放大：整批读写在一个超时窗口内，失败后无法知道哪些命令已执行，重试有风险。\n\n**实践建议**\n- 分批发送，每批 100 到 1000 条，或按累计字节数达到 1MB 即发送。\n- 命令尽量不带大 value，避免 `LRANGE 0 -1` 这类会放大响应的命令。\n- 批量操作放在低峰或独立连接池，别和在线请求共享。\n- 记录每批耗时，超时阈值按 P99 设，不要用默认的 2 秒。\n\n**与事务的区别**：Pipeline 只是网络层打包，服务端仍可能插入其他客户端的命令，不保证原子性；`MULTI/EXEC` 才保证这批命令连续执行不被插入，两者可以组合但要注意语义与集群限制。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 142 MINUTE), 1),
  (543, 3, 'MGET、Pipeline 与 Lua 批量操作的选型', '同样是一次处理多个 key，三种手段的语义、性能与限制完全不同。\n\n请说明：\n- 三者的执行模型与原子性差异；\n- 各自在集群下的限制；\n- 给出选型判断标准。', '**结论**：单纯批量读同类型 key 用 `MGET`；命令种类不同或需要批量写用 Pipeline；需要「读判断写」原子完成用 Lua。三者不能互相替代。\n\n**执行模型对比**\n| 手段 | 网络往返 | 原子性 | 服务端开销 |\n| --- | --- | --- | --- |\n| MGET/MSET | 1 次 | 单命令原子 | 低，一次查找 |\n| Pipeline | 1 次 | 不保证 | 逐条执行 |\n| Lua | 1 次 | 脚本内原子 | 阻塞主线程 |\n\n**MGET 的特点**：服务端一条命令完成多次查找，返回顺序与 key 顺序一致，缺失返回 nil。只能用于 string，且 key 数量过大时单次响应也会很大（官方建议控制在一千以内）。集群下所有 key 必须在同一 slot，否则直接报 `CROSSSLOT`。\n\n**Pipeline 的特点**：可以混合 `GET`、`HGETALL`、`INCR` 等任意命令，灵活度最高。但服务端可能在两条命令之间插入其他客户端的请求，所以不能用来实现「先读后写」的并发安全逻辑。响应要逐条读取，客户端代码要处理部分失败。\n\n**Lua 的特点**：把读、判断、写封在一次原子执行里，适合库存扣减、令牌桶、分布式锁释放。代价是阻塞主线程，脚本必须短小；集群下要保证所有 key 同 slot。\n\n**选型标准**\n1. 只是把 N 个 `GET` 合并：MGET，最简单也最快。\n2. 命令异构、量大、不与并发逻辑耦合：Pipeline 分批。\n3. 有并发正确性要求（判断依赖读到的值）：只能 Lua 或 WATCH 事务。\n4. 集群下多 key 场景先设计 hash tag，再考虑用哪种手段。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 143 MINUTE), 1),
  (544, 3, 'Cluster 下 MGET 与 Pipeline 的跨槽问题怎么解决', '单机跑得好好的批量代码，上了 Cluster 就开始报 CROSSSLOT。\n\n请说明：\n- 报错的根本原因；\n- hash tag 的使用方式与代价；\n- 客户端路由拆分的实现思路。', '**结论**：Cluster 按 `CRC16(key) mod 16384` 把 key 映射到槽，`MGET`、`MSET`、`SUNION`、事务与 Pipeline 中涉及多个 key 时必须全部落在同一槽，否则报 `CROSSSLOT Keys in request do not hash to the same slot`。\n\n**根本原因**：跨槽命令无法在单个节点上完成，Redis 选择直接拒绝而不是在服务端做分布式聚合，把复杂度交给客户端。\n\n**方案一：hash tag**\n把需要一起操作的 key 用 `{}` 包住相同片段：\n```bash\n{user:1001}:profile\n{user:1001}:cart\n{user:1001}:orders\n```\n只有 `{}` 内的内容参与哈希，因此三者同槽、可以 `MGET` 或放一个事务。代价是**数据倾斜**：如果 `{user:1001}` 是超热用户，它的所有数据都压在同一个节点上，热 key 问题被放大。设计时要评估 tag 的分布是否均匀。\n\n**方案二：客户端拆分**\n按槽分组，把一次 `MGET k1 k2 k3` 拆成「同槽的几组子请求」，并行发到对应节点后在客户端聚合结果。主流客户端（Jedis、Lettuce、Redisson）的集群模式默认就是这么做的，只是 Pipeline 需要显式按节点分批。\n\n**方案三：结构聚合**\n把同一实体的字段放进一个 hash，用 `HMGET` 一次取多个字段，天然单 key 单槽，比多个 string key 更省内存也更快。\n\n**实践建议**\n- 优先在 key 设计阶段就规划好 hash tag，而不是事后救火。\n- 不要用 `{type}` 这种粗粒度 tag，会造成严重倾斜。\n- 跨槽的强一致操作（如转账）应该改用业务补偿或分布式事务，而不是硬凑同槽。\n- 用 `CLUSTER KEYSLOT <key>` 验证设计。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 144 MINUTE), 1),
  (545, 3, 'Cluster 脑裂导致的数据丢失与 min-replicas 配置', '网络分区时旧主仍在接受写入，分区恢复后这部分写凭空消失，这是异步复制的固有问题。\n\n请说明：\n- 脑裂产生的完整过程；\n- min-replicas-to-write 与 min-replicas-max-lag 如何降低损失；\n- 为什么它只能缓解不能根除。', '**结论**：主节点与集群多数派失联但仍能接受客户端写入时，这些写只存在于旧主内存中；分区恢复后旧主被降级并从新主全量同步，未复制的写就永久丢失。`min-replicas-to-write` 让主节点在健康从节点不足时拒绝写，从而缩小可丢失窗口。\n\n**过程还原**\n1. 主 A 与从 B、C 之间网络中断，但 A 与部分客户端仍通。\n2. 集群多数派认为 A 失联，把 B 提升为新主，客户端开始写 B。\n3. A 仍然接受写（它不知道已被替换），产生分叉数据。\n4. 网络恢复，A 收到更高配置纪元（configEpoch）的消息，降级为从并清空数据做全量同步，A 上的写全部丢失。\n\n**缓解配置**\n```bash\nmin-replicas-to-write 1\nmin-replicas-max-lag 10\n```\n含义：至少要有 1 个从节点的复制延迟不超过 10 秒，主节点才允许写；否则直接返回错误。这样在分区瞬间 A 就会拒写，把「静默丢数据」变成「明确报错」，业务可以做降级或重试。\n\n**配套手段**\n- `cluster-node-timeout` 不宜过大，否则故障发现慢；也不宜过小，避免误判。\n- 关键写操作用 `WAIT 1 100` 等待至少一个从节点确认，代价是延迟上升且仍非强一致。\n- 应用层幂等与对账，发现丢失能补偿。\n\n**为什么不能根除**：Redis 复制是异步的，主节点在回复客户端时无法保证数据已到从节点。要做到零丢失必须引入共识协议（如 Raft），那已经不是 Redis 主从模型的性能特征了。所以正确的心态是：接受毫秒级窗口，用配置把窗口压到最小，用业务兜底。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 145 MINUTE), 1),
  (546, 3, 'Cluster 扩容缩容时的槽迁移流程与线上影响', '给 Cluster 加节点看起来只是执行一条 reshard 命令，但迁移期间的客户端行为必须搞清楚。\n\n请说明：\n- 槽迁移的完整步骤与涉及的命令；\n- 迁移过程中客户端访问被迁 key 会发生什么；\n- 如何降低迁移对线上的影响。', '**结论**：槽迁移是「标记状态、逐 key 搬迁、广播归属」三步，迁移期间源节点对已迁走的 key 返回 ASK 重定向，客户端需要先发 ASKING 再访问目标节点，因此要求客户端支持 ASK 语义。\n\n**完整步骤**\n1. 目标节点执行 `CLUSTER SETSLOT <slot> IMPORTING <source-id>`，源节点执行 `CLUSTER SETSLOT <slot> MIGRATING <target-id>`。\n2. 源节点用 `CLUSTER GETKEYSINSLOT <slot> <count>` 取一批 key，逐个 `MIGRATE host port key 0 5000` 搬到目标节点。\n3. 搬完后向所有节点广播 `CLUSTER SETSLOT <slot> NODE <target-id>`，完成归属变更。\n4. 用 `redis-cli --cluster reshard` 或 `--cluster rebalance` 可自动完成上述流程。\n\n**迁移期间的访问语义**\n- key 还在源节点：正常返回。\n- key 已迁走：源节点返回 `ASK <slot> <target>`，客户端需先向目标发 `ASKING`，再发原命令，目标才会处理（否则返回 MOVED）。\n- 槽整体归属变更后：返回 `MOVED`，客户端应刷新槽位缓存并长期改道。\n\n**降低影响的实践**\n- 每次迁移的 key 数量设小（如 100），避免单次 `MIGRATE` 阻塞；大 key 会阻塞更久，先拆分。\n- 在低峰期执行，迁移会占用带宽与 CPU。\n- 保证集群所有节点 `cluster-enabled` 且 `cluster-node-timeout` 一致。\n- 迁移前确认没有客户端只支持 MOVED 不支持 ASK，否则会出现短暂报错。\n- 监控 `cluster_state`、`migrating_slots`、`importing_slots`。\n\n', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 146 MINUTE), 1),
  (547, 3, 'Cluster 的 gossip 通信、故障检测与从节点选举', '为什么集群节点能自己发现彼此、判活并选主，这套机制决定了故障恢复的速度与稳定性。\n\n请说明：\n- 集群总线与 gossip 协议交换了什么；\n- PFAIL 到 FAIL 的判定过程；\n- 从节点发起选举并接管槽位的条件。', '**结论**：Cluster 通过独立的集群总线（客户端端口加 10000）用 gossip 协议交换节点表与槽位图，故障判定分主观下线与客观下线两级，从节点需获得多数持有槽的主节点投票且数据足够新才能当选。\n\n**通信机制**\n- 每个节点维护一份 `clusterState`，包含节点表、槽位分配、配置纪元 `currentEpoch` 与主节点纪元 `configEpoch`。\n- 每秒随机挑选 5 个节点发 `PING`（`cluster-node-timeout` 的一半时间内没收到回复则重试），收到 `PONG` 后顺带带上自己已知的部分节点信息，实现最终一致的拓扑传播。\n- 消息里包含发送者的槽位图，接收方按配置纪元新旧决定是否更新，避免网络抖动导致脑裂式误判。\n\n**故障检测**\n1. 节点 A 在 `cluster-node-timeout` 内没收到 B 的 `PONG`，把 B 标记为 `PFAIL`（主观下线）。\n2. A 在 gossip 中传播 B 的 `PFAIL`，其他节点也标记后，当持有槽的主节点中超过半数认为 B 下线，B 升级为 `FAIL`（客观下线），并广播全网。\n3. 若 B 是主节点，其从节点开始竞选。\n\n**选举**\n- 从节点等待一个随机延迟（按数据新鲜度排名靠前则延迟更短）后广播 `FAILOVER_AUTH_REQUEST`。\n- 只有持有槽的主节点有投票权，且每个纪元只投一票；从节点获得超过半数票即当选。\n- 当选后提升 `configEpoch`，接管原主的所有槽，广播 `PONG` 让全网更新路由。\n- 若集群中可用主节点不足半数，从节点不会当选，集群进入 `fail` 状态拒绝写入，这就是 Cluster 没有「少数派可用」的原因。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 147 MINUTE), 1),
  (548, 3, '主从复制风暴的成因与级联复制方案', '主节点重启后所有从节点同时来要 RDB，一瞬间把带宽和 CPU 打满，这就是复制风暴。\n\n请说明：\n- 复制风暴的典型触发场景；\n- 级联复制与无盘复制的缓解作用；\n- 相关配置项与容量规划建议。', '**结论**：复制风暴指多个从节点在同一时刻向主节点发起全量同步，主节点需要 fork 生成 RDB、占用大量带宽发送，导致主节点延迟飙升甚至雪崩；缓解手段是无盘复制加延迟合并、级联复制、以及增大复制积压缓冲区减少全量同步。\n\n**触发场景**\n- 主节点重启或故障转移后，所有从节点同时重连。\n- 批量扩容时一次性拉起多个从节点。\n- 网络抖动导致复制中断，`repl-backlog` 不够大，只能走全量。\n- 从节点执行了 `DEBUG RELOAD` 或配置重启。\n\n**缓解手段**\n1. 无盘复制加等待窗口：\n```bash\nrepl-diskless-sync yes\nrepl-diskless-sync-delay 5\n```\n主节点 fork 后等 5 秒，把这期间到达的从节点合并到同一次 RDB 传输，避免 N 次 fork 与 N 份文件。\n2. 级联复制：让部分从节点挂到其他从节点下（`replicaof` 指向从节点），把扇出压力分散。代价是链路变长、延迟叠加，故障排查更复杂，一般两层足够。\n3. 增大 `repl-backlog-size`（如 256MB），让短暂断连走增量同步 `PSYNC` 而不是全量。\n4. 控制单主从节点数量，建议不超过 3 到 5 个。\n5. 从节点分批重启，错开时间窗口。\n\n**容量规划**：全量同步期间主节点内存因 COW 上涨、带宽被占满。按单次 RDB 大小乘以并发数预留带宽，网络至少留 30% 余量；跨机房复制要评估专线带宽与 RTT。\n\n**监控**：`master_link_status`、`master_sync_in_progress`、`rdb_bgsave_in_progress`、`sync_full` 与 `sync_partial_ok` 的比例，后者持续偏低说明 backlog 太小。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 148 MINUTE), 1),
  (549, 3, '主从切换为什么会丢数据，WAIT 命令能做什么', '故障转移后业务发现少了几条写入，这不是 bug，而是异步复制的固有代价。\n\n请说明：\n- 数据丢失的时间窗口在哪里；\n- WAIT 命令的语义与它的边界；\n- 有哪些手段可以把窗口压到最小。', '**结论**：主节点执行完命令就回复客户端，数据此刻只在主节点内存中；若在传播到从节点之前主节点宕机，这部分写就丢了。`WAIT` 可以让客户端等待指定数量的从节点确认，但它是同步等待而非强一致，仍不能保证不丢。\n\n**丢失窗口**：命令执行完成到从节点应用之间的这段时间，取决于网络 RTT、从节点负载与 `repl-ping-replica-period`。正常情况下是毫秒级，从节点繁忙时可能到秒级，故障转移恰好落在这个窗口就会丢。\n\n**WAIT 语义**\n```bash\nSET k v\nWAIT 1 100     -- 等待至少 1 个从节点确认，最多等 100 毫秒\n```\n返回实际确认的从节点数量。注意三点：\n1. 它只是阻塞当前连接等待 ACK，不改变主节点「先回复再复制」的本质。\n2. 超时返回小于期望的数量并不代表失败，也不回滚已执行的命令。\n3. 集群下 `WAIT` 只统计当前分片的从节点。\n\n**配套手段**\n- `min-replicas-to-write` 加 `min-replicas-max-lag`：从节点不足或延迟过大时主节点直接拒写。\n- 关键操作用 `WAIT 1` 提升持久性，接受延迟代价。\n- 应用层对账与补偿：把关键写入同时落库，事后比对修正。\n- 用 `INFO replication` 的 `master_repl_offset` 与从节点 offset 差值监控延迟。\n\n**结论**：Redis 主从是性能优先的设计，任何宣称「配置一下就零丢失」的说法都不成立。要零丢失只能用支持共识的存储，或者把 Redis 当缓存、真实数据落库。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 149 MINUTE), 1),
  (550, 3, '复制延迟的监控与读写分离的一致性处理', '读写分离能扛住读流量，但「刚写完就读不到」的投诉也随之而来。\n\n请说明：\n- 复制延迟的主要来源；\n- 如何量化延迟并设置告警；\n- 业务层如何规避读到旧数据。', '**结论**：复制延迟来自网络、从节点单线程处理能力与从节点的阻塞操作；用主从 offset 差值量化，业务上通过「写后读走主库」「延迟敏感读加版本校验」来规避。\n\n**延迟来源**\n1. 网络带宽与 RTT，跨机房尤其明显。\n2. 从节点执行大命令阻塞：`KEYS`、大 key 的 `DEL`、`FLUSHDB` 会同步卡住复制流。\n3. 从节点开启 AOF 且 `appendfsync always`，fsync 慢会拖慢应用命令的速度。\n4. 从节点 CPU 被其他进程抢占、内存 swap。\n5. 主节点写入突增，复制缓冲区积压。\n\n**量化方式**\n- `INFO replication` 中 `master_repl_offset` 与每个 `slaveN:offset` 的差值即字节延迟。\n- `master_last_io_seconds_ago` 反映上次交互时间。\n- 从节点侧 `slave_repl_offset` 与 `master_repl_offset` 对比。\n- 结合 `INFO commandstats` 看从节点是否有慢命令。\n- 告警阈值一般按业务容忍度设，超过 5 秒或 10MB 就该介入。\n\n**业务规避**\n- 写后立即读的场景强制走主库，最简单的做法是在会话或请求上下文里打标记。\n- 关键数据带版本号或时间戳，读到旧版本时回源主库并回填缓存。\n- 对延迟极度敏感的业务干脆不做读写分离，改用加内存或分片提升主库能力。\n- 从节点只承担报表、离线导出、`SCAN` 类重活，别把在线读全压上去。\n\n**根因治理**：减少大 key 与慢命令、从节点关闭不必要的持久化、保证从节点规格不低于主节点、跨机房复制评估专线带宽。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 150 MINUTE), 1),
  (551, 3, '无盘复制 repl-diskless-sync 的适用场景', '磁盘慢、容器没有持久盘时，无盘复制是救命配置，但它也有自己的代价。\n\n请说明：\n- 无盘复制的工作原理；\n- repl-diskless-sync-delay 的作用；\n- 它适合与不适合哪些环境。', '**结论**：无盘复制让主节点 fork 出的子进程直接把 RDB 序列化到从节点的 socket，不在本地落盘，省掉一次磁盘写与一次磁盘读，适合磁盘 IO 是瓶颈或没有持久盘的云环境。\n\n**原理**\n```bash\nrepl-diskless-sync yes\nrepl-diskless-sync-delay 5\n```\n- 子进程边遍历内存边把 RDB 数据写入复制 socket，从节点边接收边加载。\n- 主节点仍然要 fork，因此 COW 内存开销照旧。\n- 从节点侧用 `repl-diskless-load disabled/on-empty-db/swapdb` 控制接收时是否清库、是否用 swapdb 减少不可用时间。\n\n**delay 的作用**：主节点收到第一个全量同步请求后不立即开始，而是等 `repl-diskless-sync-delay` 秒（默认 5），把这期间到达的从节点合并到同一次传输。这能显著缓解复制风暴，代价是新从节点要多等几秒。\n\n**适合的场景**\n- 云主机或容器，本地盘性能差、容量小。\n- 磁盘 IOPS 成为复制瓶颈，`rdb_last_bgsave_time_sec` 明显偏大。\n- 单次全量传输体积不大且网络带宽充足。\n\n**不适合的场景**\n- 网络带宽紧张或 RTT 高，传输中断后必须从头再来，而磁盘方案可以复用已生成的文件重传。\n- 从节点数量多且到达时间分散，delay 合并效果差，主节点会多次 fork。\n- 需要留存 RDB 备份的环境仍要单独配置备份任务。\n\n**实践**：先用默认的磁盘复制，观察 `rdb_last_bgsave_time_sec` 与磁盘 util，确认瓶颈在磁盘后再切无盘，并配合 delay 与从节点分批上线。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 151 MINUTE), 1),
  (552, 3, '延迟双删与 binlog 订阅，哪种缓存一致性方案更可靠', '「先删缓存还是先更新数据库」的讨论之后，真正落地时面对的是失败重试与并发回填。\n\n请说明：\n- 延迟双删的原理与它的固有缺陷；\n- 基于 binlog 订阅的异步失效如何做到最终一致；\n- 两种方案的适用边界。', '**结论**：延迟双删通过「更新库、删缓存、延迟再删一次」降低并发读回填旧值的概率，但延迟时长无法精确设定、删除失败也无补偿；订阅 binlog 异步失效把「何时删」交给数据库的提交事件，可靠性更高，是主流电商的落地方式。\n\n**延迟双删**\n```bash\n更新数据库 -> DEL cache -> sleep(N) -> DEL cache\n```\n第二次删除是为了清掉「在更新期间读请求回填的旧值」。缺陷：\n1. 延迟时间只能靠经验估（常见 500ms 到 1 秒），读请求链路越长越不准。\n2. 第二次删除失败没有重试，缓存脏数据一直存在。\n3. sleep 占用线程，高并发下浪费资源，通常要丢到延迟队列执行。\n4. 仍存在理论上的并发窗口，只是概率变小。\n\n**binlog 订阅**\n用 Canal、Debezium 或云厂商的 DTS 订阅 MySQL binlog，解析出变更行后投递到 MQ，由消费者删除或更新对应缓存。优点：\n- 以数据库提交为准，天然覆盖所有写入路径（包括其他服务、手工改库）。\n- 失败可重试、可堆积、可监控，能保证最终一致。\n- 与业务代码解耦，不用在每个写方法里加删除逻辑。\n代价是引入中间件、增加链路延迟（通常百毫秒级），以及要处理消息顺序（同一 key 的变更要串行）。\n\n**选型边界**\n- 读多写少、能接受短暂不一致、团队不想引组件：Cache Aside 加删除重试（失败进 MQ 重试）足够。\n- 写路径多、数据敏感、要求最终一致：binlog 订阅。\n- 强一致：不要靠缓存，读写都走数据库或加分布式锁串行化。\n\n**通用兜底**：给缓存设 TTL、写入时用版本号、定期对账，任何方案都该有这三道保险。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 152 MINUTE), 1),
  (553, 3, 'Cache Aside、Read Through 与 Write Behind 的对比', '缓存模式不只是「先读缓存再读库」这么一句，不同模式决定了谁来承担一致性责任。\n\n请说明：\n- 三种模式的读写流程；\n- 各自的一致性、性能与实现复杂度；\n- 典型适用场景。', '**结论**：Cache Aside 由应用同时管缓存与数据库，最灵活也最常见；Read/Write Through 由缓存层代理数据库访问，应用只面对缓存；Write Behind 先写缓存再异步批量落库，写性能最高但有丢数据风险。\n\n**Cache Aside（旁路）**\n- 读：先读缓存，未命中读库并回填，同时设 TTL。\n- 写：先更新库，再删缓存（而不是更新缓存）。\n- 优点：实现简单、缓存不可用时业务可降级直连库、只缓存热点。\n- 缺点：并发下可能短暂不一致；删除失败需要重试机制。\n\n**Read/Write Through**\n应用只与缓存交互，缓存组件内部完成对数据库的读写与回填：\n- 读穿透：缓存未命中时由缓存层加载并写入。\n- 写穿透：写缓存时同步写库，二者在同一调用链里。\n- 优点：业务代码干净，一致性由缓存层统一保证。\n- 缺点：需要成熟的缓存框架支持（如 Spring Cache 的部分抽象、Guava 的 CacheLoader），缓存层成为关键路径，容量规划更难。\n\n**Write Behind（Write Back）**\n- 写只落缓存，异步批量刷库。\n- 优点：写延迟极低、可合并同 key 的多次写，适合计数、点赞、播放量。\n- 缺点：缓存宕机会丢数据，需要 WAL 或定期快照兜底；实现复杂度最高。\n\n**对比表**\n| 模式 | 一致性 | 写性能 | 复杂度 | 场景 |\n| --- | --- | --- | --- | --- |\n| Cache Aside | 最终一致 | 中 | 低 | 大多数业务 |\n| Read/Write Through | 较强 | 中 | 中 | 有缓存框架支撑 |\n| Write Behind | 弱，可能丢 | 高 | 高 | 计数、日志、非关键指标 |\n\n**结论**：默认选 Cache Aside，并在删除失败、并发回填上做加固；只有明确追求写吞吐且能接受丢数据时，才考虑 Write Behind。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 153 MINUTE), 1),
  (554, 3, '缓存预热、降级与熔断的完整设计', '大促开始时 Redis 冷启动、或者 Redis 整体挂掉，系统会瞬间被压垮，这三件事必须提前设计。\n\n请说明：\n- 缓存预热怎么做，为什么必须做；\n- 缓存降级的层次与实现方式；\n- 熔断与超时配置的要点。', '**结论**：预热解决冷启动穿透，降级解决依赖失效时的可用性，熔断防止故障扩散；三者共同构成缓存高可用体系，缺一环都会在流量高峰暴露。\n\n**预热**\n- 时机：服务发布后、大促前、Redis 扩容或主从切换后。\n- 方式：启动时按热点清单（运营配置、历史访问 Top N）批量写入，或从离线数仓导出；用 Pipeline 分批灌入，避免瞬时打满。\n- 注意：预热要带随机化的 TTL，避免同一时刻集体过期造成雪崩；预热期间对数据库做限流，防止把库压垮。\n- 必须预热的原因：冷缓存下所有请求直达数据库，QPS 放大数十倍，数据库先扛不住。\n\n**降级**\n分层设计：\n1. 客户端本地缓存（Caffeine）作为第一层，Redis 不可用时仍能应答热点请求。\n2. 静态兜底值：商品价格、库存等返回上一版本或默认值，页面标注「稍后重试」。\n3. 非核心功能直接关闭（推荐位、评论数、排行榜），保核心链路。\n4. 开关化：用配置中心控制降级开关，能在秒级生效，不要依赖发版。\n\n**熔断与超时**\n- 客户端设置连接超时与读超时（如 50ms、200ms），禁止无限等待。\n- 熔断器统计失败率，超过阈值（如 50%）后进入打开状态，直接快速失败，半开状态试探恢复。\n- 线程池隔离：缓存调用用独立线程池，避免拖死业务线程。\n- 注意 Redis 客户端重试策略，重试会放大故障期间的流量，通常只允许 1 次。\n\n**兜底监控**：命中率、错误率、P99 延迟、降级开关状态都要有看板与告警，否则降级了也没人知道。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 154 MINUTE), 1),
  (555, 3, 'Redis 的 key 命名规范与设计约束', 'key 设计看着是小问题，但它决定了内存占用、集群路由、排查效率与过期策略。\n\n请说明：\n- 命名规范应该包含哪些要素；\n- key 长度与内存的关系；\n- 集群与过期策略对 key 设计的约束。', '**结论**：key 应当「见名知意、层级清晰、长度可控、生命周期明确」，并预留集群路由（hash tag）与批量检索（前缀）的设计空间。\n\n**命名规范**\n- 统一格式：`业务:实体:id:字段`，例如 `order:1001:detail`、`user:42:follows`。冒号分隔便于人工阅读与 `SCAN MATCH`。\n- 禁止空格、换行、控制字符；不要用二进制内容直接当 key。\n- 统一小写与单复数约定，避免 `User:1` 与 `user:1` 并存导致重复缓存。\n- 版本化：`v2:user:1` 便于灰度与全量刷新时的双写迁移。\n\n**长度与内存**：key 本身也是 SDS，长 key 会显著增加内存。经验上控制在 32 到 64 字节内；百万级 key 时，每多 10 字节就是十几 MB 的纯开销。但也不要为省内存把 key 缩成不可读的编码，排查成本更高，通常用「短前缀加数字 id」的折中。\n\n**过期策略**：几乎所有缓存 key 都要设 TTL，并加随机抖动（如 `base + random(0, 300)` 秒），防止批量同时过期引发雪崩。永久 key 只留给配置、计数这类确实需要长期存在的结构，并单独监控其数量增长。\n\n**集群约束**\n- 需要一起操作的 key 用 hash tag 固定到同槽：`{user:42}:profile`、`{user:42}:cart`。\n- tag 粒度不能太粗，否则数据倾斜成热点。\n- 避免用时间戳或随机数作为 tag 内容。\n\n**其他**：大 value 要拆分（单 key 不超过 10KB 为宜）；同一实体的多个字段优先放一个 hash 而不是多个 string，既省内存也便于批量读。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 155 MINUTE), 1),
  (556, 3, '如何估算 Redis 的内存占用并做容量规划', '面试官问「一亿个 key 要多少内存」，考的是你是否知道每一项开销的来源。\n\n请说明：\n- 单个 key 的内存由哪些部分组成；\n- 有哪些经验估算方式与验证命令；\n- 容量规划要预留哪些余量。', '**结论**：一个 key 的内存大致由 dictEntry、key 的 SDS、redisObject、value 的底层结构、过期字典条目以及哈希表负载因子共同决定；实际规划时按「数据量乘单 key 均值」估算后再留 30% 到 50% 余量，并用 `MEMORY USAGE` 抽样校准。\n\n**组成部分**\n| 部分 | 典型开销 |\n| --- | --- |\n| dictEntry | 约 24 字节，加指针与桶空间 |\n| key 的 SDS | 长度加头加 1 字节结尾 |\n| redisObject | 16 字节 |\n| value 结构 | 视编码而定，listpack 极省，skiplist 较贵 |\n| 过期字典 | 每个带 TTL 的 key 多一个 dictEntry |\n\n**经验值**：短 key 短 value 的 string，单条约 60 到 100 字节；同样数据放进 hash 的 listpack 可以降到一半。1 亿个这样的 key，纯数据就要 6 到 10GB，加上碎片与复制缓冲，实际需要 12GB 以上。\n\n**验证方式**\n```bash\nMEMORY USAGE key SAMPLES 5\nredis-cli --bigkeys\nINFO memory  # used_memory 与 used_memory_rss\n```\n抽样若干代表性 key，乘数量级即可校准估算。\n\n**规划余量**\n- fork 做 RDB 或 AOF 重写时的 COW 增量，高峰期可达 50%。\n- 主从复制缓冲区与 backlog。\n- 客户端输出缓冲区（大范围查询、Pub/Sub）。\n- 内存碎片，`mem_fragmentation_ratio` 建议维持在 1.5 以下。\n- `maxmemory` 设置为物理内存的 60% 到 70%，把余量留给上述开销。\n\n**结论**：别按「value 大小乘数量」拍脑袋，那条线往往只占真实占用的一半。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 156 MINUTE), 1),
  (557, 3, 'Redis 7.0 的 multi-part AOF 与 Function 带来了什么', '7.0 是 Redis 近几年改动最大的版本，AOF 结构与脚本能力都有实质变化。\n\n请说明：\n- multi-part AOF 的文件组织与重写流程；\n- 它解决了 6.x 的哪些痛点；\n- Function 相对 EVAL 的优势。', '**结论**：7.0 把 AOF 从单文件改成「base 快照加多个增量文件加 manifest 清单」的多部分结构，重写不再需要合并缓冲，从根本上解决了 6.x 中 `aof_rewrite_buf` 膨胀与 rename 阻塞的问题；同时引入 Function，把脚本变成可持久化、可管理的库。\n\n**multi-part AOF**\n```bash\nappendonlydir/\n  appendonly.aof.1.base.rdb\n  appendonly.aof.1.incr.aof\n  appendonly.aof.manifest\n```\n- 重写时生成新的 base 文件，写完后只在 manifest 里切换引用，旧文件随后删除。\n- 不再需要把重写期间的写命令缓存在 `aof_rewrite_buf` 里再合并，内存不会因重写而暴涨。\n- 清理过期 base 文件是异步的，主线程几乎不参与。\n- 打开 AOF 时可以指定 `aof-use-rdb-preamble yes`，base 就是 RDB 格式，加载更快。\n\n**Function**\n```bash\nFUNCTION LOAD "#!lua name=mylib ..."\nFCALL myfunc 1 key1 arg1\n```\n- 脚本以库为单位注册并随 RDB/AOF 持久化，从库天然拥有相同函数，不再有 `EVALSHA` 的 `NOSCRIPT` 问题。\n\n**同版本其他变化**：Sharded Pub/Sub 让集群下的频道按槽分布，避免全节点广播；listpack 全面替代 ziplist；ACL 支持更细的 key 与命令模式；`CLIENT NO-EVICT` 等新选项。\n\n**升级注意**：multi-part AOF 的目录结构与 6.x 不兼容，降级前必须关闭 AOF 或转换格式；`appendfilename` 改为 `appenddirname`，运维脚本要同步调整。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 157 MINUTE), 1),
  (558, 3, 'Redis 6 的 ACL 如何做多租户与最小权限', '共享一套 Redis 的多个业务方，靠一个 requirepass 显然不够，ACL 就是为此设计的。\n\n请说明：\n- ACL 用户的定义语法与各部分的含义；\n- 如何做到 key 前缀级别的隔离；\n- 生产上如何持久化与审计。', '**结论**：ACL 用一条 `ACL SETUSER` 定义用户名、密码、可操作的 key 模式与命令权限，可以让每个业务方只访问自己的 key 前缀与命令集合，实现最小权限与故障隔离。\n\n**语法拆解**\n```bash\nACL SETUSER app_a on >StrongPwd ~cache:a:* +@read +@write -@dangerous +select\n```\n- `on`/`off`：是否启用该用户。\n- `>pwd`：设置明文密码，`#hash` 设置 SHA256。\n- `~pattern`：允许访问的 key 模式，`allkeys` 表示全部，`resetkeys` 清空。\n- `+@read`、`+@write`、`+@admin`、`+@dangerous`：按命令类别授权；也可写成 `+get`、`-del`。\n\n**客户端使用**\n```bash\nAUTH app_a StrongPwd\nACL WHOAMI\n```\n或连接串里带用户名密码，主流客户端均支持。\n\n**默认用户**：`default` 用户默认拥有全部权限且无密码，生产必须 `ACL SETUSER default on >pwd ~* +@all` 收敛，或直接 `ACL SETUSER default off` 并创建业务账号。\n\n**持久化与审计**\n- `aclfile /etc/redis/users.acl` 加 `ACL SAVE`，重启后权限不丢；`CONFIG REWRITE` 只能保存到配置文件。\n- `ACL LOG` 查看被拒绝的认证与命令，用于排查与安全审计。\n- `ACL LIST`、`ACL GETUSER` 定期导出核对。\n\n**实践要点**：给只读业务只授 `+@read`；禁止业务账号使用 `FLUSHALL`、`CONFIG`、`KEYS`；运维账号与业务账号分离；密码轮换用双密码过渡（`>new` 加 `<old`），避免批量重启。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 158 MINUTE), 1),
  (559, 3, 'Redis 未授权访问的风险与安全加固清单', '默认配置的 Redis 监听所有网卡且无密码，直接暴露公网等于把服务器交出去。\n\n请说明：\n- 未授权访问能被利用来做什么；\n- 网络层与配置层的加固手段；\n- 还有哪些容易被忽略的风险点。', '**结论**：Redis 未授权访问不只是「数据被读」，攻击者可通过 `CONFIG SET dir` 加 `SAVE` 写 SSH 公钥或定时任务实现远程命令执行，因此必须从网络、认证、命令、运行账户四个层面加固。\n\n**典型攻击链**：连接无密码实例，`CONFIG SET dir /root/.ssh` 加 `CONFIG SET dbfilename authorized_keys`，写入构造的 value 后 `SAVE`，得到免密登录；或写 `/var/spool/cron/root` 反弹 shell。主从复制还可以用 `SLAVEOF` 让受害实例同步恶意 RDB 加载模块。\n\n**网络层**\n- `bind 127.0.0.1 或内网 IP`，绝不监听 0.0.0.0。\n- 安全组与防火墙只放行应用服务器网段。\n- Cluster 总线端口（客户端端口加 10000）同样要隔离。\n\n**认证与命令**\n- `requirepass` 或 ACL 强密码，禁止空密码。\n- `protected-mode yes`，未设密码且非本机访问时直接拒绝。\n- `rename-command` 禁用 `FLUSHALL`、`FLUSHDB`、`CONFIG`、`KEYS`、`MODULE`；7.0 起用 ACL 更规范。\n- 关闭或限制 `DEBUG`、`SHUTDOWN`。\n\n**运行环境**\n- 使用独立低权限账号运行，不要用 root。\n- 开启 TLS（`tls-port`、证书配置），跨机房链路尤其必要。\n- 关闭危险模块，`enable-protected-configs`、`enable-debug-command` 保持关闭。\n- 数据目录权限收敛，避免被其他进程篡改 RDB。\n\n**运维**：定期升级修复已知漏洞；用配置扫描工具校验线上配置与基线一致；对 `CONFIG GET`、`ACL LOG` 做审计告警；不要把 Redis 直接暴露在公网或只做端口映射。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 159 MINUTE), 1),
  (560, 3, 'Redis 生产监控该盯哪些 INFO 指标', 'Redis 出问题时最常见的反应是「先看一眼监控」，但看哪些字段决定了排查效率。\n\n请说明：\n- 内存、连接、命中率、持久化、复制五类关键指标；\n- 各项的健康阈值与告警建议；\n- 如何把这些指标串成一次完整的故障定位。', '**结论**：核心盯五组指标——内存与淘汰、连接与缓冲、命中率、持久化状态、复制延迟；任何一项异常都能顺藤摸瓜定位到根因。\n\n**内存**\n- `used_memory` 对比 `maxmemory`：超过 80% 预警。\n- `used_memory_rss` 与 `used_memory` 比值即 `mem_fragmentation_ratio`，大于 1.5 说明碎片严重，小于 1 说明发生 swap，都要处理。\n- `evicted_keys` 持续增长：容量不足或淘汰策略不对。\n\n**连接与缓冲**\n- `connected_clients`、`blocked_clients`：突增可能是连接泄漏或阻塞命令。\n- `rejected_connections`：超过 `maxclients` 被拒，需扩容或排查泄漏。\n- `client list` 的 `omem` 与 `qbuf`：大值或慢消费者。\n\n**命中率**\n- `keyspace_hits` 与 `keyspace_misses` 计算命中率，长期低于 90% 说明缓存设计或容量有问题。注意 `EXISTS` 之类的探测也会计入 miss，要结合业务看。\n\n**持久化**\n- `rdb_last_bgsave_status`、`aof_last_write_status` 必须为 ok。\n- `rdb_changes_since_last_save`、`aof_rewrite_in_progress`、`latest_fork_usec`。\n- `rdb_last_bgsave_time_sec` 突然变长说明磁盘或内存有问题。\n\n**复制**\n- `master_link_status` 为 down 立即告警。\n- `master_repl_offset` 与从节点 offset 差值判断延迟。\n\n**定位路径**：P99 升高时依次看 `slowlog`、`latest_fork_usec`、`evicted_keys` 与连接数。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 160 MINUTE), 1),
  (561, 3, '慢查询日志 slowlog 的配置与正确用法', 'slowlog 是排查 Redis 延迟最直接的工具，但默认值几乎抓不到东西。\n\n请说明：\n- 两个核心配置项的含义；\n- SLOWLOG GET 返回字段如何解读；\n- 它记录不到哪些耗时，排查时还要配合什么。', '**结论**：`slowlog-log-slower-than` 以微秒为单位设定阈值（0 记录全部命令，负数关闭），`slowlog-max-len` 限制保留条数（默认 128，超出后丢弃最旧的）；生产建议阈值设 10000 微秒即 10 毫秒，长度调到 512 到 1024。\n\n**命令**\n```bash\nCONFIG SET slowlog-log-slower-than 10000\nCONFIG SET slowlog-max-len 1024\nSLOWLOG GET 10\nSLOWLOG LEN\nSLOWLOG RESET\n```\n\n**字段含义**\n1. 日志 id，递增。\n2. 发生时的 Unix 时间戳。\n3. 执行耗时（微秒）。\n4. 命令与参数数组（参数过多会被截断，避免日志本身占内存）。\n5. 客户端地址与端口。\n6. 客户端名称（`CLIENT SETNAME` 设置后便于定位业务方）。\n\n**局限性（重要）**\n- 只统计命令**执行**时间，不含网络传输、排队等待、客户端处理时间。所以客户端看到 200ms、slowlog 里却只有 1ms 的情况很常见。\n- 不记录 `EXEC` 内部单条命令的耗时，事务里只能看到整体。\n- 阻塞命令如 `BLPOP` 只统计实际执行时间，不统计等待时间。\n- slowlog 本身占内存，长度别设过大。\n\n**配合手段**\n- `LATENCY DOCTOR` 与 `LATENCY HISTORY` 看 fork、AOF fsync、过期删除等非命令类事件。\n- `INFO commandstats` 看各类命令的平均耗时与调用次数，定位高频慢命令。\n- `redis-cli --latency` 与 `--intrinsic-latency` 区分是 Redis 慢还是机器慢。\n\n**实践**：把 slowlog 采集进监控系统并聚合成 P99，比人工 `SLOWLOG GET` 有效得多。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 161 MINUTE), 1),
  (562, 3, 'bio 后台线程承担了哪些工作，为什么要拆出去', 'Redis 号称单线程，但进程里其实还有几个后台线程，它们负责的都是「不能让主线程等」的事。\n\n请说明：\n- bio 线程的类型与触发场景；\n- 为什么要用队列加条件变量的模型；\n- 这对主线程延迟有什么实际意义。', '**结论**：Redis 用 bio（background I/O）线程处理三类可能阻塞主线程的操作：关闭文件描述符、AOF 的 fsync、以及大对象的异步释放；主线程只投递任务，不做等待。\n\n**三类任务**\n| 类型 | 触发场景 | 不拆出去的后果 |\n| --- | --- | --- |\n| BIO_CLOSE_FILE | 关闭 AOF、RDB 临时文件 | 慢磁盘上 close 可能耗时数十毫秒 |\n| BIO_AOF_FSYNC | `appendfsync everysec` 每秒刷盘 | fsync 抖动直接变成命令延迟毛刺 |\n| BIO_LAZY_FREE | `UNLINK`、异步淘汰、异步过期 | 释放百万元素结构可能阻塞数百毫秒 |\n\n**实现模型**：每种类型一个线程（`bio_threads`），共享一个 `bio_jobs` 队列加互斥锁与条件变量。主线程 `bioCreateBackgroundJob` 入队后立即返回；后台线程在循环里取任务执行，空闲时等待条件变量，避免忙轮询。`bioWaitStepOfType` 只在关停等少数场景同步等待。\n\n**为什么不是多线程执行命令**：命令执行若是并发的，就需要给 dict、过期、复制状态加锁，复杂度与延迟都会上升。Redis 的策略是「命令串行，把确定性阻塞的 IO 与内存释放挪走」，这是单线程模型能成立的关键补丁。\n\n**与 IO 线程的区别**：6.0 的 IO 线程处理的是 socket 读写与协议解析（多线程 IO），命令执行仍在主线程；bio 处理的是文件与内存操作。两者解决不同问题，常被混淆。\n\n**实际意义**：`INFO stats` 中 `lazyfree_pending_objects` 能看出异步释放是否积压；若持续增长，说明释放速度跟不上，需要关注内存曲线与淘汰压力。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 162 MINUTE), 1),
  (563, 3, 'lazyfree 与 UNLINK 如何避免删除大 key 卡住主线程', '删除一个百万元素的集合，DEL 可能在主线程里卡上几百毫秒。\n\n请说明：\n- DEL 为什么会阻塞；\n- UNLINK 与 lazyfree 配置项的作用；\n- 异步删除带来的新问题。', '**结论**：`DEL` 在释放 value 时是同步递归释放每个元素，元素越多越慢，全部发生在主线程；`UNLINK` 先把 key 从键空间摘除（O(1)），再把内存释放交给 bio 线程异步完成，主线程不再被大对象拖住。\n\n**阻塞原理**：删一个 string 只是释放一块内存，很快；删一个百万元素的 hash，需要遍历并逐个释放 dictEntry 与 SDS，耗时与元素数成正比，期间事件循环停转。百万元素的 set 实测可达数百毫秒，直接表现为接口超时。\n\n**UNLINK 语义**\n```bash\nUNLINK big:set\n```\n- 键立刻从 keyspace 消失，后续读不到。\n- 内存由后台线程逐步回收，`used_memory` 下降有延迟。\n- 语义上与 `DEL` 等价，只是释放异步。\n\n**lazyfree 相关配置**\n```bash\nlazyfree-lazy-eviction yes\nlazyfree-lazy-expire yes\nlazyfree-lazy-server-del yes\nlazyfree-lazy-user-del yes\nlazyfree-lazy-user-flush yes\n```\n- `eviction`：淘汰时异步释放，避免淘汰大 key 卡顿。\n- `expire`：过期删除异步化。\n- `server-del`：内部删除（如 `RENAME` 覆盖、`SET` 覆盖旧值）异步化。\n- `user-del`：把 `DEL` 直接当作 `UNLINK` 处理。\n- `user-flush`：`FLUSHDB`、`FLUSHALL` 异步清空。\n\n**新问题**\n1. 内存释放滞后，可能在这期间触发额外淘汰或 OOM，需要预留余量。\n2. `lazyfree_pending_objects` 持续增大说明释放跟不上，要查是否在短时间内删除大量大 key。\n3. 异步释放与 fork 的 COW 叠加时，内存峰值更难预测。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 163 MINUTE), 1),
  (564, 3, 'Redis 与 Memcached 的差异与选型', '两者常被当成同类缓存，但在数据结构、线程模型与能力边界上差别很大。\n\n请说明：\n- 数据结构、线程模型、持久化与集群能力的差异；\n- 各自的性能特征；\n- 什么场景该选哪个。', '**结论**：Redis 是带丰富数据结构、持久化与高可用能力的内存数据库，命令执行单线程；Memcached 是纯 KV 的多线程缓存，内存利用率高但无持久化、无原生集群。多数业务应选 Redis，只有在「纯 KV、超高并发、可接受丢数据」时才考虑 Memcached。\n\n**对比表**\n| 维度 | Redis | Memcached |\n| --- | --- | --- |\n| 数据结构 | string、list、hash、set、zset、bitmap、HLL、geo、stream | 仅 string（value 为字节串） |\n| 线程模型 | 命令单线程，6.0 起 IO 多线程 | 多线程，可吃满多核 |\n| 持久化 | RDB、AOF、混合 | 无 |\n| 高可用 | 主从、哨兵、Cluster | 无，靠客户端分片 |\n| 事务与脚本 | MULTI、Lua、Function | 无 |\n| 单 value 上限 | 512MB | 1MB（默认） |\n| 内存管理 | jemalloc 加碎片整理 | slab allocator，预分配分片 |\n| 过期与淘汰 | 惰性加定期、八种策略 | 惰性过期加 LRU |\n\n**性能特征**：Memcached 多线程在纯 KV 大 value 场景吞吐上限更高，slab 分配避免了碎片；Redis 单线程在 value 较小时靠减少上下文切换与系统调用也能跑到十万级 QPS，且单次操作的数据结构能力强得多。\n\n**选型建议**\n- 需要 list、zset、hash、bitmap、Stream，或需要持久化与自动故障转移：Redis。\n- 已有 Memcached 做页面级大对象缓存、且无持久化需求：可以保留，但要自己实现一致性哈希与故障摘除。\n- 缓存计数、排行榜、分布式锁、限流：只有 Redis 能做。\n\n**结论**：新项目默认 Redis；Memcached 的优势主要在极简 KV 的内存效率与多核扩展性，不值得为这点收益引入第二套中间件。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 164 MINUTE), 1),
  (565, 3, '单机、主从、哨兵与 Cluster 的架构选型', '同样是 Redis，「怎么部署」直接决定了可用性等级与运维成本。\n\n请说明：\n- 四种架构的能力与短板；\n- 数据量与 QPS 如何影响选型；\n- 迁移路径与注意事项。', '**结论**：单机用于开发与不重要的场景；主从提供读扩展与备份但故障需人工切换；哨兵在主从之上实现自动故障转移，适合单机内存装得下的数据；Cluster 用 16384 个槽做水平分片，适合数据量大或写 QPS 高的场景。\n\n**能力对比**\n| 架构 | 自动故障转移 | 水平扩展 | 多 key 操作 | 运维复杂度 |\n| --- | --- | --- | --- | --- |\n| 单机 | 无 | 无 | 无限制 | 低 |\n| 主从 | 无，需人工 | 读扩展 | 无限制 | 低 |\n| 哨兵 | 有 | 读扩展 | 无限制 | 中 |\n| Cluster | 有 | 读写都扩展 | 需同槽 | 高 |\n\n**选型判断**\n- 数据量小于单机内存（经验值 16GB 以内）且写 QPS 不高：哨兵最省心，客户端兼容性好，Lua 与事务不受槽限制。\n- 数据量超过单机内存，或单实例 QPS 打满：Cluster，按业务拆分多个集群比一个大集群更好运维。\n- 只需要读写分离与备份、能接受分钟级人工切换：主从加监控。\n- 云上优先用托管版，把故障转移与扩容交给云厂商。\n\n**关键约束**\n- Cluster 需要客户端支持 MOVED/ASK 重定向，且多 key 操作必须同槽，业务改造往往比部署更花时间。\n- 哨兵至少 3 个（奇数），且要独立部署，不能与 Redis 同机。\n- 主从与哨兵都无法水平扩展写，写瓶颈只能靠分片解决。\n\n**迁移路径**：单机到主从加哨兵最平滑；到 Cluster 需要评估多 key 命令、事务、Lua 与 hash tag，通常先在预发环境全量回归，再用双写或代理层灰度切流。\n\n**容量提醒**：Cluster 每个分片仍要遵守单实例内存上限，否则 fork 卡顿与迁移慢的问题会原样复现。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 165 MINUTE), 1),
  (566, 3, 'Lettuce 与 Jedis 的差异及连接池配置', '客户端选型与连接池参数配错，会把 Redis 的性能优势全部抵消。\n\n请说明：\n- Lettuce 与 Jedis 在模型上的核心差异；\n- 连接池关键参数该怎么设；\n- 阻塞命令与集群模式下要注意什么。', '**结论**：Jedis 是同步阻塞、以连接池为核心的轻量客户端，一个线程一条连接；Lettuce 基于 Netty，连接线程安全可共享，支持异步、响应式与自动重连，Spring Boot 2 起为默认。\n\n**核心差异**\n| 维度 | Jedis | Lettuce |\n| --- | --- | --- |\n| IO 模型 | 阻塞 BIO | Netty NIO |\n| 线程安全 | 否，需连接池 | 是，单连接可共享 |\n| 异步与响应式 | 不支持 | 支持 |\n| 集群拓扑刷新 | 需手动 | 自动 |\n| 断线重连 | 需池化重建 | 内建 |\n高并发下 Jedis 靠连接池扩连接，连接数约等于并发线程数；Lettuce 可以几条连接扛住全部请求，但要注意单连接上的命令是排队执行的。\n\n**连接池关键参数**\n- `maxTotal`：按并发线程数设置，通常为线程数的 1.2 倍，不要盲目设大，服务端 `maxclients` 会被打满。\n- `maxIdle` 与 `minIdle`：保持一定空闲连接，减少建连开销；`minIdle` 太小会导致流量突增时集中建连。\n- `maxWaitMillis`：获取连接的最长等待，必须设置，否则线程会无限阻塞。\n- `testOnBorrow` 与 `testWhileIdle`：配合 `timeBetweenEvictionRunsMillis` 做健康检查，避免拿到已被服务端断开的连接。\n- 超时：连接超时与命令超时分开设，命令超时建议 200ms 到 1s，视业务而定。\n\n**注意事项**\n- 阻塞命令（`BLPOP`、`BRPOP`、`SUBSCRIBE`）在 Lettuce 共享连接上会阻塞其他命令，必须使用独立连接（`Redis命令的 dedicated connection`）。\n- 集群模式下 Pipeline 需要按节点分批；Lettuce 会自动处理 MOVED/ASK，但跨槽命令仍会失败。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 166 MINUTE), 1),
  (567, 3, '秒杀场景下用 Redis 预扣库存的完整设计', '秒杀是 Redis 的高频面试场景题，考的是超卖、幂等、削峰与最终一致的组合设计。\n\n请说明：\n- 为什么不能直接让请求打到数据库；\n- 用 Lua 预扣库存的脚本要点；\n- 异步下单链路如何保证不丢单、不超卖。', '**结论**：秒杀的核心是「前端限流、Redis 原子预扣、消息异步下单、数据库最终扣减」四层配合；Redis 只做流量闸门与快速失败，真实库存以数据库为准并由消息驱动，靠幂等与对账保证一致。\n\n**为什么不让请求直达数据库**：瞬时 QPS 可能是平时的百倍，数据库连接池与行锁会瞬间打满，且大量无效请求白白消耗资源。Redis 单机十万级 QPS 可以快速把 99% 的请求挡在门外。\n\n**库存预热**：活动前把 `seckill:stock:{id}` 写入 Redis，同时把已购用户写入 set 用于去重，两者用同一 hash tag 保证同槽。\n\n**Lua 预扣要点**\n```lua\nlocal stock = tonumber(redis.call("GET", KEYS[1]))\nif stock == nil or stock <= 0 then return 0 end\nif redis.call("SISMEMBER", KEYS[2], ARGV[1]) == 1 then return -1 end\nredis.call("DECR", KEYS[1])\nredis.call("SADD", KEYS[2], ARGV[1])\nreturn 1\n```\n- 判断、扣减、去重必须在同一脚本内完成，任何拆分都会超卖。\n- 返回三种状态：成功、售罄、重复购买，前端据此给不同提示。\n\n**异步下单**：预扣成功后 `XADD` 到 Stream（或发 MQ），下游消费创建订单并扣数据库库存。要点：\n- 消息要可靠：用 Stream 消费组的 ACK 与 `XAUTOCLAIM` 重投，或本地消息表加定时补偿。\n- 消费必须幂等：订单表对 `(user_id, 活动id)` 建唯一索引。\n- 下单失败要回滚 Redis 库存（`INCR` 并 `SREM`），并记录失败原因。\n\n**兜底**：活动结束后用数据库真实库存校准 Redis；对账任务发现差异要能告警与人工修复。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 167 MINUTE), 1),
  (568, 3, '用 Redis 实现接口幂等的几种方式', '重复提交、网关重试、消息重投都会造成重复执行，幂等设计是接口的必备能力。\n\n请说明：\n- 基于 token 的一次性凭证方案；\n- 基于业务唯一键的去重方案；\n- 各自的失败边界与注意事项。', '**结论**：常用两种做法——客户端先申请一次性 token，提交时用 Lua 校验并删除；或用业务唯一键（订单号、请求 ID）做 `SET NX` 去重并记录处理结果，两种都要注意失败补偿与并发原子性。\n\n**方案一：token 机制**\n1. 进入页面时调用 `GET /token`，服务端生成 UUID 并 `SET token:xxx 1 EX 300 NX`，返回给前端。\n2. 提交时带上 token，服务端用 Lua 执行「存在则删除并返回 1，否则返回 0」。\n3. 返回 0 说明是重复提交，直接拒绝。\n要点：token 必须一次性且删除与校验原子；要设 TTL 防止堆积；删除后业务失败重试需要重新申请 token，因此更适合「提交即终结」的场景。\n\n**方案二：唯一键去重**\n```bash\nSET order:req:1001 1 NX EX 3600\n```\n- 返回 OK 表示首次请求，可以继续执行；返回 nil 表示重复，需要查询上次结果。\n- 仅做「是否在处理「判断时，要额外存处理状态（处理中、成功、失败）与结果，否则重复请求拿不到响应。\n- 更适合幂等查询、支付回调这类带业务键的场景。\n\n**方案三：数据库唯一索引兜底**\n无论 Redis 怎么做，最终表上要有唯一约束。Redis 只是性能前置，进程崩溃、缓存失效后数据库仍要拦住重复写入，这一层不能省。\n\n**常见坑**\n- 先删 token 再执行业务，业务失败后无法重试，应改为「先置处理中，成功后置完成」。\n- 用 `GET` 加 `DEL` 两步判断，并发下两个请求都能通过，必须用 Lua 或 `SET NX`。\n- key 没设 TTL，长期运行后内存被撑爆。\n- 集群下多个 key 操作需要 hash tag 同槽。\n\n**组合建议**：前端防重复点击、Redis 做快速去重、数据库唯一索引做最终保证，三层叠加才稳。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 168 MINUTE), 1);

;
   `view_count`, `practice_count`, `published_at`, `created_by`)
VALUES
  (569, 4, 'var、let、const 的提升差异与暂时性死区', '下面代码的输出是什么？请结合执行上下文的创建阶段，说明 var 与 let/const 在提升上的本质差异，并解释暂时性死区（TDZ）的起止边界。\n\n```js\nconsole.log(a);\nvar a = 1;\nfunction f() {\n  console.log(b);\n  let b = 2;\n}\nf();\n```\n\n请进一步说明：为什么 typeof 对完全未声明的变量返回 undefined 字符串，而对 TDZ 中的变量会直接抛错；以及 for 循环里 let 为什么能记住每一轮的值。', '**输出与结论**：`console.log(a)` 打印 `undefined`，随后 `f()` 内 `console.log(b)` 抛出 `ReferenceError: Cannot access b before initialization`。原因是 var 在执行上下文创建阶段就被绑定并初始化为 undefined，而 let/const 只完成了创建绑定，初始化要等声明语句真正执行。\n\n**1. 提升的本质**：进入函数或全局代码时，引擎先扫描声明，在词法环境（Lexical Environment）中预置绑定。var 走 CreateMutableBinding 并立即 InitializeBinding(undefined)；let/const 只创建未初始化绑定，读取未初始化绑定即触发 TDZ 报错。所以提升提升的是绑定，而不是赋值。\n\n**2. TDZ 的边界**：从块（或函数）开始执行，到声明语句执行完毕为止。函数参数默认值、class 声明、switch 的 case 块内部都存在 TDZ。\n\n**3. typeof 的反常**：对完全未声明的标识符，typeof 按规范返回字符串 undefined 而不报错；对处于 TDZ 的绑定，typeof 也要先取值，因此同样抛 ReferenceError。这是两者最容易被问倒的差别。\n\n**4. for 循环的每轮绑定**：`for (let i = 0; ...)` 每次迭代都会复制一份新的绑定，并把上一轮的值作为初值，所以闭包里捕获到的是各自那一轮的 i；换成 var 则共享同一个函数级绑定，回调执行时全部读到终值。\n\n**实践**：默认用 const，需要重新赋值才用 let，避免 var；并把声明写在作用域顶部附近，缩短 TDZ 窗口，减少看似可用实则报错的隐性 bug。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 169 MINUTE), 1),
  (570, 4, 'new 运算符做了哪四件事，手写 new 与继承实现', '请说明 `new Foo()` 在执行时依次发生了什么，并手写一个 `myNew`。\n\n```js\nfunction Foo(name) { this.name = name; }\nFoo.prototype.say = function () { return this.name; };\n```\n\n在此基础上回答三个追问：如果构造函数内显式 return 一个对象会怎样？return 一个原始值呢？箭头函数为什么不能被 new 调用？请给出 `Object.create` 与寄生组合继承的完整写法。', '**结论**：new 依次做了四件事——创建新对象、把新对象的原型指向 `Constructor.prototype`、以新对象为 this 执行构造函数、根据返回值决定最终结果（返回对象则用它，否则用新对象）。\n\n**手写实现**：\n\n```js\nfunction myNew(Ctor, ...args) {\n  const obj = Object.create(Ctor.prototype);\n  const ret = Ctor.apply(obj, args);\n  return ret !== null && typeof ret === "object" ? ret : obj;\n}\n```\n\n**1. 为什么原型要提前挂**：`Object.create(Ctor.prototype)` 一步完成创建与设原型，避免了早期写法里先 new 一个临时对象再改原型的浪费。要注意 `prototype` 为原始值时被忽略，实例原型退化为 `Object.prototype`。\n\n**2. 返回值的规则**：只有返回对象（含数组、函数、null 以外的 object）才覆盖实例；返回原始值、undefined、null 都会被忽略。这也是工厂函数能替换构造函数的原因。\n\n**3. 箭头函数不可 new**：箭头函数没有 `[[Construct]]` 内部方法，也没有自己的 prototype 与 this，`new (() => {})` 直接 TypeError。\n\n**4. 继承的推荐写法**：\n\n```js\nfunction Child(name, age) {\n  Parent.call(this, name);\n  this.age = age;\n}\nChild.prototype = Object.create(Parent.prototype, {\n  constructor: { value: Child, writable: true, configurable: true }\n});\n```\n\n寄生组合继承只调用一次父构造函数，既不重复执行父类逻辑，也不会让子类原型被污染，是 ES5 时代最标准的方案；ES6 的 class extends 在语义上等价，但多了 [[HomeObject]] 与 super 的静态绑定。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 170 MINUTE), 1),
  (571, 4, '手写 call/apply/bind 与 this 绑定丢失', '请手写 `Function.prototype.call`、`apply`、`bind` 的 polyfill，并说明 bind 返回的函数被 new 调用时 this 为什么会被忽略。\n\n```js\nconst obj = { name: "a", say() { return this.name; } };\nconst fn = obj.say;\nsetTimeout(obj.say, 0);\n```\n\n请解释上面两处调用为什么拿不到 name，并给出至少三种修复方式，说明各自的取舍。', '**结论**：call/apply 的本质是临时把函数挂到目标对象上调用，用完删除；bind 返回一个永久绑定的新函数，且该函数被 new 调用时绑定失效。\n\n**手写实现**：\n\n```js\nFunction.prototype.myCall = function (ctx, ...args) {\n  ctx = ctx ?? globalThis;\n  const key = Symbol("fn");\n  ctx[key] = this;\n  const ret = ctx[key](...args);\n  delete ctx[key];\n  return ret;\n};\n\nFunction.prototype.myBind = function (ctx, ...preset) {\n  const fn = this;\n  function bound(...rest) {\n    const isNew = this instanceof bound;\n    return fn.apply(isNew ? this : ctx, [...preset, ...rest]);\n  }\n  bound.prototype = Object.create(fn.prototype);\n  return bound;\n};\n```\n\n**1. 为什么用 Symbol 做键**：避免与对象已有属性重名导致覆盖，也避免 enumerable 属性污染。\n\n**2. 绑定丢失的根因**：this 在运行时由调用位置决定。`const fn = obj.say` 之后调用变成了普通函数调用（this 为 undefined，非严格模式下为 globalThis）；`setTimeout(obj.say)` 是把函数引用交给宿主环境，调用点已经不在 obj 上，所以同样丢失。\n\n**3. 三种修复**：一是 `fn.call(obj)` 显式绑定；二是 `fn = obj.say.bind(obj)` 固化 this；三是箭头函数包裹 `() => obj.say()`，最直观，但需保留函数引用才能移除监听。\n\n**4. 追问点**：bind 的 this 一旦绑定不可再用 call 覆盖；bind 支持偏应用参数（preset）；bind 返回的函数如果被 new，则 this 指向新实例，绑定的 ctx 被忽略。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 171 MINUTE), 1),
  (572, 4, 'class 继承中 super 的语义与私有字段 #', '请说明 class 的 `extends` 相比 ES5 原型继承在语义上多了什么，重点解释 `super` 在构造器、方法与静态方法中的三种行为差异。\n\n```js\nclass A { constructor() { this.x = 1; } static s() { return "A"; } }\nclass B extends A {\n  #v = 2;\n  constructor() { super(); this.y = 3; }\n  static s() { return super.s() + "B"; }\n}\n```\n\n请回答：为什么子类构造器里 `this` 必须在 super 之后才能访问？私有字段 `#v` 在实例上能否被枚举到？`class` 是否会被提升到可用？', '**结论**：ES6 class 不只是语法糖，它引入了 [[HomeObject]] 静态绑定、不可调用的构造器、块级作用域内不提升（存在 TDZ）以及私有字段等真正的新语义。\n\n**1. super 的三种形态**：在构造器中 `super(...)` 等价于 `Reflect.construct(Parent, args, new.target)`，作用是初始化父类部分并返回 this；在实例方法中 `super.m()` 是沿 HomeObject 的原型链取方法，且调用时 this 仍是当前实例；在静态方法中 super 指向父类的构造函数本身，所以 `super.s()` 实际是 `A.s.call(B)`。注意 super 不是变量，不能脱离方法单独使用，也不能被解构赋值。\n\n**2. this 必须在 super 之后**：派生类构造器执行时 this 尚未被绑定（处于 [[thisBindingStatus]] = uninitialized 状态），父类构造器返回的对象才是 this 的来源。因此 `this.y = 3` 写在 super 之前会抛 ReferenceError；如果要返回自定义对象，必须显式 `return obj`。\n\n**3. 私有字段不可枚举**：`#v` 由私名字（Private Name）实现，不在原型上、不出现在 `Object.keys`、`JSON.stringify`、`for...in` 的结果里，也无法被 `Reflect.ownKeys` 看到。访问必须通过 `#v in obj` 或类内部的 `this.#v`，这正是它比下划线约定更强的封装保证。\n\n**4. 提升问题**：class 声明存在 TDZ，在声明前访问会抛错；它也不会像函数声明那样被整体提升，因为它同时创建了绑定与值。另外 class 内部默认是严格模式，方法不可枚举，直接调用未用 new 的 class 构造器会报错。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 172 MINUTE), 1),
  (573, 4, 'Proxy 与 Reflect 的陷阱机制和实际用途', '请说明 ES6 Proxy 的 get/set/has/ownKeys 等陷阱（trap）分别在什么时机被触发，并解释为什么几乎每个 trap 内部都要配合 Reflect 使用。\n\n```js\nconst p = new Proxy({ a: 1 }, {\n  get(t, k, r) { return Reflect.get(t, k, r); }\n});\n```\n\n请结合 Vue 3 响应式、不可变数据、参数校验三个场景，说明 Proxy 相比 Object.defineProperty 的优势与代价。', '**结论**：Proxy 在对象外层包了一层可编程的拦截层，trap 在对应的内部方法（如 [[Get]]、[[Set]]、[[HasProperty]]、[[OwnPropertyKeys]]）被调用时触发；Reflect 提供与内部方法一一对应的默认行为，配合使用能保证 receiver 正确、返回值符合规范约束。\n\n**1. 常见 trap 与时机**：get 在读取属性、方法调用取函数时触发；set 在赋值时触发，返回 false 会在严格模式下抛 TypeError；has 对应 `in`；ownKeys 对应 `Object.keys`、`for...in`、展开运算；deleteProperty 对应 delete；getPrototypeOf / setPrototypeOf 影响原型操作。每个 trap 都有不变量（invariant），比如 ownKeys 不能返回被设为不可配置的属性之外的东西，否则直接 TypeError。\n\n**2. 为什么要用 Reflect**：`Reflect.get(t, k, r)` 把 receiver 一起传下去，只有当 this 指向 receiver 时，getter 与继承链上的访问才会走回代理，避免无限递归和 this 错位；同时 Reflect 方法与 trap 的返回值类型一一对应，set/delete 返回布尔，get 返回任意值，写起来更严谨。\n\n**3. 优势**：Vue 3 用 get/set 做依赖收集与派发，用 ownKeys/deleteProperty 覆盖新增与删除属性，天生支持 Map/Set 与数组索引，不像 defineProperty 需要递归遍历已有属性。\n\n**4. 代价**：一是性能开销，代理后的对象读写都变慢，需要 shallowRef / markRaw 兜底；二是兼容性，无法 polyfill；三是代理不是原对象，`===` 比较、`instanceof`、值传递到第三方库时都可能出问题；四是内部槽（如 Date 的方法）直接代理会报错，需要绑定 this 或改用 get 返回包装。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 173 MINUTE), 1),
  (574, 4, '属性描述符与 Object.defineProperty 的边界', '请说明数据描述符与访问器描述符的区别，以及 writable/configurable/enumerable 三个标志在什么操作上生效。\n\n```js\nconst o = {};\nObject.defineProperty(o, "x", { value: 1, writable: false, enumerable: false });\no.x = 2;\n```\n\n请回答上面赋值的结果、`Object.keys(o)` 的返回，以及为什么 Vue 2 用 defineProperty 实现响应式时无法监听新增属性与数组下标。', '**结论**：属性描述符分两类——数据描述符（value/writable）与访问器描述符（get/set），二者互斥；configurable 决定能否重定义或删除，writable 决定能否改值，enumerable 决定能否出现在枚举中。\n\n**1. 三个标志的作用域**：\n\n| 标志 | 为 false 时的后果 |\n| --- | --- |\n| writable | 普通赋值静默失败（严格模式抛 TypeError），但可通过 defineProperty 重定义 |\n| enumerable | 不出现在 for...in、Object.keys、JSON.stringify、展开中 |\n| configurable | 不能 delete，不能改 enumerable/writable，不能把数据描述符改成访问器描述符 |\n\n注意对不可配置属性只有一种放宽：可以把 writable 从 true 改为 false，也可以把 value 改为相同值。\n\n**2. 上面代码的结果**：`o.x = 2` 在非严格模式下静默失败，x 仍为 1；严格模式抛 TypeError。`Object.keys(o)` 返回空数组，因为 enumerable 默认为 false。这也是 defineProperty 定义属性时必须显式写 enumerable: true 的原因，Vue 2 就踩过这个坑。\n\n**3. 与响应式的关系**：defineProperty 只能在定义属性的那一刻劫持已有的 get/set，所以 `vm.obj.newKey = 1` 这种新增属性、`arr[0] = x` 这种索引赋值、`arr.length = 0` 都无法被感知，需要 `Vue.set` / `Vue.delete` 或重写数组七个方法。Proxy 作用在对象整体上，没有这个问题。\n\n**4. 实践**：需要不可变常量用 writable: false；需要隐藏内部状态用 enumerable: false；`Object.freeze` 是把所有属性设为不可写且不可配置，但仍是浅冻结，嵌套对象要递归处理。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 174 MINUTE), 1),
  (575, 4, 'Symbol、迭代器协议与 for...of 的执行过程', '请说明可迭代协议（Iterable）与迭代器协议（Iterator）的区别，并解释 `for...of` 在遇到 break、异常时如何清理资源。\n\n```js\nconst obj = {\n  data: [1, 2, 3],\n  [Symbol.iterator]() { return this.data[Symbol.iterator](); }\n};\n```\n\n请回答：普通对象为什么不能直接 for...of？如何让类数组对象同时支持 for...of 与展开？迭代器为什么被称为惰性求值？', '**结论**：可迭代协议要求对象上有 `Symbol.iterator` 方法并返回迭代器；迭代器协议要求对象有 `next()` 且返回 `{ value, done }`。`for...of` 就是不断调用 next 直到 done 为 true。\n\n**1. 普通对象不能 for...of 的原因**：对象没有 `Symbol.iterator`，而 for...of 只认这个符号。数组、字符串、Map、Set、arguments、NodeList、生成器对象默认实现了它；普通对象只实现了 for...in 用的枚举协议。上面例子通过手动实现 `[Symbol.iterator]` 委托给数组迭代器，就变成可迭代对象，同时支持 `[...obj]`、解构与 for...of。\n\n**2. 清理资源**：for...of 在异常、break、return 时都会调用迭代器的 `return()` 方法。所以需要释放资源（关闭文件、断开连接）的自定义迭代器应实现 return，生成器则依赖 finally 块完成清理。这一点在题库里经常被追问。\n\n**3. 惰性求值**：迭代器每次 next 才计算下一个值，因此可以表达无限序列，也能与早退结合只取前 N 个。生成器把这一特性做到了语法级别，`yield` 暂停后保留完整执行上下文。\n\n**4. 常见陷阱**：一是迭代器是一次性的，`[...it]` 之后再用就空了；二是 `Symbol.iterator` 返回的对象如果 itself 不是迭代器会抛 TypeError；三是 Map 迭代产出的是 `[key, value]` 数组，配合解构很方便；四是 for...in 会遍历原型链上的可枚举属性且顺序按规范对整数键优先，与 for...of 语义完全不同。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 175 MINUTE), 1),
  (576, 4, 'Generator 的暂停恢复机制与协程调度', '请描述调用生成器函数后，代码分别在什么时刻执行；`yield` 表达式的返回值来自哪里；`next/throw/return` 三个方法各有什么效果。\n\n```js\nfunction* g() {\n  const x = yield 1;\n  try { yield x + 1; } catch (e) { yield "caught:" + e.message; }\n}\n```\n\n请结合这段代码说明为什么生成器可以充当 async/await 的底层实现（co 库的自驱动原理），以及 `return()` 触发 finally 的时机。', '**结论**：调用生成器函数不会执行函数体，只返回一个迭代器对象；只有调用 next 才推进到第一个 yield 并暂停，暂停时保留完整的执行上下文（局部变量、调用栈位置）。\n\n**1. 执行流程**：`next(v)` 从上次暂停处恢复，把 v 作为上一个 yield 表达式的值，然后执行到下一个 yield 并把其后表达式作为 value 返回。第一次 next 传参会被丢弃，因为没有等待中的 yield。`throw(e)` 在上次暂停处注入异常，相当于把 yield 语句替换成 throw；`return(v)` 直接结束并触发 finally 块，之后迭代器 done 为 true。\n\n**2. 上面代码的轨迹**：第一次 next 返回 { value: 1, done: false }，x 尚未赋值；第二次 next(10) 让 x = 10，返回 11；如果改成 throw(new Error("x"))，则进入 catch，返回 caught:x。\n\n**3. 与 async/await 的关系**：async 函数本质是生成器加自动执行器。co 库的思路是：把 Promise 交给 yield，执行器在 then 回调里调用 next，在 catch 里调用 throw，如此往复直到 done，最终 resolve 整个链。这解释了为什么 await 后面的代码相当于 then 回调、为什么 try/catch 能捕获 await 的 reject，也解释了 await 会保留调用栈上下文。\n\n**4. finally 与清理**：`return()` 会当作在暂停处执行 return 语句，先跑 finally 再结束；如果 finally 里又 yield，则 return 会被挂起，直到生成器真正结束。因此在用生成器做资源管理时必须把释放逻辑写进 finally，for...of 的 break 也会走这条路径。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 176 MINUTE), 1),
  (577, 4, '垃圾回收机制、分代回收与 WeakMap 弱引用', '请说明 V8 的可达性（reachability）判定与常见 GC 算法，并结合分代假说解释新生代与老生代为什么采用不同策略。\n\n```js\nlet k = { id: 1 };\nconst m = new WeakMap();\nm.set(k, "big");\nk = null;\n```\n\n请回答：WeakMap 的键为什么必须是对象？它的值会被回收吗？如何用 WeakMap 实现不泄漏的私有数据与对象缓存？', '**结论**：现代 GC 以可达性分析为核心——从根（全局对象、当前调用栈、闭包环境等）出发能遍历到的对象才存活，其余可回收。V8 把堆分成新生代与老生代，用不同算法平衡吞吐与停顿。\n\n**1. 算法分层**：新生代用 Scavenge（Cheney 复制算法），把空间分成 from/to 两块，存活对象复制到 to 后整体翻转，代价与存活对象数量成正比，适合朝生夕死的小对象；对象经过两次回收仍存活就晋升到老生代。老生代用标记-清除加标记-压缩，清除产生碎片，压缩整理内存；为避免长时间停顿又引入增量标记、并发标记与惰性清理，把标记工作切片到多个任务里。\n\n**2. 分代假说**：绝大多数对象很快死亡，少数长期存活（如全局缓存、DOM 引用）。分区处理让高频的短命对象回收很便宜，长命对象很少被扫描。\n\n**3. WeakMap 的语义**：键必须是对象（只有对象有身份可被弱引用），键是弱引用——当 k 被置 null 且没有其他强引用时，整个条目会被回收，值也随之释放。不能遍历、没有 size，正是弱引用语义的必然结果：遍历会暴露回收的不确定性。\n\n**4. 实际用途**：一是给对象挂私有数据（`const priv = new WeakMap()`，实例作键），外部拿不到也无法枚举；二是做对象缓存与记忆化，键被销毁时缓存自动失效，比 Map 更安全；三是 DOM 节点关联元数据，节点移除后不会因缓存而泄漏。注意 WeakRef 与 FinalizationRegistry 能做更细的控制，但规范明确不保证回调时机，不适合承载业务逻辑。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 177 MINUTE), 1),
  (578, 4, '前端内存泄漏的常见场景与排查方法', '请列举前端内存泄漏的典型成因，并说明如何用 Chrome DevTools 的 Memory 面板定位泄漏源。\n\n场景：一个 SPA 页面反复进入、离开详情页，数小时后标签页内存涨到 1.5G 后崩溃。\n\n请给出你的排查步骤：用哪几个工具、看哪些指标、如何确认是泄漏而不是缓存、修复后如何验证。', '**结论**：前端泄漏的本质是"已不再需要的对象仍被根可达"。常见成因集中在全局引用、闭包、定时器、事件监听、DOM 游离节点、缓存无上限六类。\n\n**1. 典型场景**：\n\n| 场景 | 典型写法 |\n| --- | --- |\n| 全局缓存 | 把组件实例或大对象挂到 window / 全局 Map，从不删除 |\n| 未清理的监听 | window.addEventListener、IntersectionObserver、WebSocket 未在 unmount 时移除 |\n| 定时器 | setInterval 内部引用组件 this，组件销毁后仍运行 |\n| 游离 DOM | JS 变量持有已从文档移除的节点，其子树都无法回收 |\n| 闭包 | 大对象被长生命周期回调捕获（如缓存了 event 对象） |\n| 绑定到 DOM 的引用 | 在 DOM 上挂 expando 属性指向大对象 |\n\n**2. 排查步骤**：先用 Performance 面板录制一段操作，看 JS Heap 与 DOM Nodes 曲线是否在每次进出后阶梯上升且不回落；再用 Memory 面板的 Heap Snapshot 做三次快照（进入前、进入后、离开并 GC 后），用 Comparison 视图对比 delta，重点看 Detached HTMLElement、闭包作用域里的变量名；对可疑对象用 Allocation instrumentation on timeline 抓分配栈，直接定位到源码行。\n\n**3. 区分缓存与泄漏**：执行一次强制 GC（垃圾桶按钮）后内存回落说明只是未被及时回收；反复进出 N 次内存线性增长才是泄漏。还要注意 console 里保留的对象引用会阻止回收，排查时先清空控制台。\n\n**4. 修复与验证**：统一在组件卸载钩子里清理（用 AbortController 一次性移除所有监听、clearInterval、observer.disconnect）；缓存改用 WeakMap 或加 LRU 上限；修复后跑同样的进出脚本 20 次，确认堆快照的对象数稳定在常数级别，再在 CI 中用 Playwright 采集 CDP 的 heap 指标做长期监控。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 178 MINUTE), 1),
  (579, 4, '事件流、事件委托与 passive 监听', '请描述 DOM 事件流的三个阶段，并解释事件委托依赖的是哪个阶段。\n\n```html\n<ul id="list">\n  <li data-id="1">a</li>\n  <li data-id="2">b</li>\n</ul>\n```\n\n请回答：为什么把 click 监听挂在 ul 上能拿到具体 li？`e.target` 与 `e.currentTarget` 有何区别？什么场景下事件委托会失效？移动端滚动为什么要给监听加 passive: true？', '**结论**：DOM 事件流分捕获、目标、冒泡三个阶段，事件委托利用冒泡阶段在祖先节点统一处理，从而减少监听数量、天然支持动态节点。\n\n**1. 三个阶段的取值**：在祖先上监听时，`e.currentTarget` 是绑定监听的那个元素（如 ul），`e.target` 是实际触发事件的最内层元素（如 li）。委托的典型写法是根据 target 向上 closest 找到目标项：\n\n```js\nlist.addEventListener("click", (e) => {\n  const li = e.target.closest("li[data-id]");\n  if (li) console.log(li.dataset.id);\n});\n```\n\n**2. 失效场景**：一是不冒泡的事件，如 focus、blur、mouseenter、load，需改用 focusin/focusout 或 capture 阶段；二是 `e.stopPropagation()` 会中断委托链；三是被 Shadow DOM 或 iframe 隔断，事件不会穿透边界；四是 target 被 replace 后已脱离文档，需包装判断。\n\n**3. 捕获与阻止**：第三个参数传 true 即捕获阶段监听；`stopPropagation` 只阻止继续传播，`stopImmediatePropagation` 还会阻止同元素上的其他监听；`preventDefault` 与传播无关。\n\n**4. passive 的意义**：浏览器无法预知监听里是否调用 preventDefault，必须等监听执行完才能滚动，导致滚动被 JS 阻塞。`passive: true` 承诺不会 preventDefault，浏览器可以立即在合成器线程滚动。Chrome 现已把 window/document 上的 touchstart、wheel 默认设为 passive，自定义监听应显式声明；若确实需要 preventDefault（如自定义缩放），才设 passive: false。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 179 MINUTE), 1),
  (580, 4, 'setTimeout 最小延迟、setInterval 漂移与 rAF 的差异', '请解释为什么 `setTimeout(fn, 0)` 并不是立即执行，嵌套调用为什么会被限制到 4ms 以上。\n\n```js\nlet n = 0;\nconst t = setInterval(() => { heavySync(50); if (++n > 3) clearInterval(t); }, 100);\n```\n\n请回答：setInterval 在回调耗时超过间隔时会发生什么？为什么说它不适合做动画？requestAnimationFrame 相比它有什么优势？后台标签页里两者分别怎样被节流？', '**结论**：定时器回调只是把任务放进宏任务队列，实际执行时间取决于主线程何时空闲，因此 0ms 只代表尽快排队；嵌套超过 5 层的定时器会被强制最少 4ms 延迟，这是 HTML 规范为了抑制 CPU 空转的钳制。\n\n**1. setInterval 的核心问题**：定时器只保证"不早于"间隔触发，回调耗时超过间隔时任务会连续堆积或直接丢帧；且每次回调都在上一次执行完之后才重新排队，导致实际周期 = 间隔 + 执行耗时，长期运行必然漂移。用递归 setTimeout 在回调末尾重新计时，可以避免堆积，也能根据耗时做补偿。\n\n**2. 为什么不适合动画**：它按固定时间触发，与屏幕刷新不同步，容易丢帧或同一帧内多次执行，视觉上抖动。\n\n**3. requestAnimationFrame 的优势**：由浏览器统一在下一帧渲染前批量调用回调，回调参数是帧时间戳；页面不可见时自动暂停，省电；天然与刷新率对齐（120Hz 屏也能自适应）。用它做逐帧动画时，位移要基于时间差计算而不是固定步长，否则在高刷屏上会加速。\n\n**4. 节流策略**：后台标签页里 rAF 完全停止，setTimeout/setInterval 被限制到最低 1s 一次（Chrome 对隐藏超过 5 分钟的页面进一步降到 1 分钟）。因此倒计时、轮询这类逻辑不能依赖定时器精度，应在恢复可见时用 Date.now 差值校正。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 180 MINUTE), 1),
  (581, 4, 'JSON.stringify 的边界行为与自定义序列化', '请列出 JSON.stringify 在遇到 undefined、函数、Symbol、Date、NaN、循环引用、BigInt 时的行为，并说明如何实现自定义序列化。\n\n```js\nconst o = { a: undefined, b: () => 1, c: NaN, d: new Date(0) };\nJSON.stringify(o);\n```\n\n请给出上面结果，并实现一个安全的 stringify：能处理循环引用、支持 BigInt、且不丢 undefined 语义（或明确说明为何要丢）。', '**结论**：JSON.stringify 只输出 JSON 支持的类型，其余按规则丢弃或转换；遇到循环引用直接抛 TypeError。\n\n**1. 各类型的处理**：\n\n| 输入 | 输出 |\n| --- | --- |\n| undefined / 函数 / Symbol（对象属性） | 该键被省略 |\n| undefined（数组元素） | 变成 null |\n| NaN / Infinity | 变成 null |\n| Date | 调用 toJSON，输出 ISO 字符串 |\n| BigInt | 抛 TypeError |\n| 循环引用 | 抛 TypeError |\n\n所以上面代码的输出是 `{"c":null,"d":"1970-01-01T00:00:00.000Z"}`，a 与 b 被省略。\n\n**2. 三个可定制钩子**：`toJSON` 方法优先于 replacer；replacer 数组用于白名单字段；replacer 函数可以改写每个值，注意它拿到的 this 是被序列化对象本身；space 参数控制缩进。对 Map/Set 需要先转数组，否则得到空对象。\n\n**3. 安全实现循环引用**：用 WeakSet 记录当前路径上的对象，重复出现时替换为 `"[Circular]"`；BigInt 转字符串；Date 保留 toJSON。也可用 structuredClone 做深拷贝，但它不支持函数与 DOM 节点。\n\n```js\nfunction safeStringify(v) {\n  const seen = new WeakSet();\n  return JSON.stringify(v, (k, val) => {\n    if (typeof val === "bigint") return val.toString();\n    if (val && typeof val === "object") {\n      if (seen.has(val)) return "[Circular]";\n      seen.add(val);\n    }\n    return val;\n  });\n}\n```\n\n**4. undefined 的取舍**：JSON 没有 undefined，传输层只能丢弃或转 null。前后端要约定用 null 表示空值；若必须保留 undefined 语义，需自定义协议（如标记字段）或改用支持的类型序列化方案。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 181 MINUTE), 1),
  (582, 4, '0.1 + 0.2 精度问题与 BigInt 的适用边界', '请解释为什么 `0.1 + 0.2 !== 0.3`，IEEE 754 双精度浮点数是如何表示 0.1 的。\n\n```js\n0.1 + 0.2;            // 0.30000000000000004\n(0.1 + 0.2).toFixed(2); // "0.30"\n```\n\n请回答：为什么 toFixed(2) 能得到看起来正确的结果？如何正确比较两个浮点数？金额计算应该用什么方案？BigInt 能解决这个问题吗？', '**结论**：IEEE 754 双精度用 1 位符号、11 位指数、52 位尾数表示一个二进制分数，0.1 在二进制下是无限循环小数，只能被截断存储，因此加法结果带有极小误差，这是表示法的固有局限而非引擎 bug。\n\n**1. 误差从哪来**：0.1 存成最接近的二进制值，约为 0.1000000000000000055511151231257827；0.2 同理；两者相加后再舍入到 53 位有效数字，得到 0.30000000000000004。误差量级约 1e-17，随运算次数累积。\n\n**2. 正确比较**：不要用 `===`，用差值绝对值小于容差：`Math.abs(a - b) < Number.EPSILON`（单次运算）或按业务精度取 `1e-9`。也不要依赖 toFixed 做四舍五入，它按二进制值取整且存在 1.005 这类经典反例。\n\n**3. 金额方案**：换算成整数分（以最小货币单位存储与运算），展示时再除 100；复杂场景用 decimal.js 这类十进制库；后端统一用 DECIMAL 类型，前端不要做二次浮点累加。\n\n**4. BigInt 的边界**：BigInt 只解决大整数精度问题（超过 2^53-1 的整数、雪花 ID、大额分单位），不支持小数，不能与 Number 混用（会抛 TypeError），也不支持 Math 方法。所以金额可以转成 BigInt 的分单位来算，但涉及利率、汇率等小数运算仍需十进制库。另外 JSON 不支持 BigInt，接口传输大整数 ID 时要转字符串，否则精度会在解析时丢失。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 182 MINUTE), 1),
  (583, 4, '隐式类型转换规则与 == 的判定流程', '请说明 JavaScript 中 ToPrimitive、ToNumber、ToString 三条抽象操作的优先级，并解释下面结果。\n\n```js\n[] == false;      // true\n[] == ![];        // true\nnull == 0;        // false\nnull == undefined; // true\n```\n\n请给出 `{} + []`、`[] + {}` 的结果与原因，并说明为什么工程规范普遍禁用 ==。', '**结论**：松散相等在类型不同时会走一套固定流程：null/undefined 互等且只与彼此相等；数字与字符串比较先转数字；对象与原始值比较先 ToPrimitive 再转；布尔值永远先转数字。\n\n**1. 关键规则**：\n\n| 表达式 | 过程 | 结果 |\n| --- | --- | --- |\n| [] == false | false 转 0，[] 经 ToPrimitive 得空串再转 0 | true |\n| [] == ![] | ![] 为 false，退化为上一条 | true |\n| null == 0 | 规范特例：null 只与 undefined 相等 | false |\n| null == undefined | 特例直接返回 true | true |\n\n**2. ToPrimitive 的细节**：默认 hint 为 default，对象先尝试 valueOf 再 toString（Date 例外，优先 toString）。数组的 valueOf 返回自身，于是走 toString 得到逗号拼接的字符串，这才是 `[] == false` 成立的根源。重写 valueOf/toString 可以操纵比较结果，也是面试常见的考点。\n\n**3. 加法与一元加**：`+` 只要有一侧是字符串就做拼接，否则做数字加法；`{} + []` 在语句位置被解析为块语句加空数组，实际是 `+[]` 得 0；`[] + {}` 是表达式，得字符串 `[object Object]`。这类结果依赖上下文解析，本身就不该出现在业务代码里。\n\n**4. 工程结论**：一律用 ===，需要判空时显式写 `x === null || x === undefined` 或 `x == null`（这是唯一被广泛接受的例外，因为它精确等于判 null 与 undefined 两者）；配套用 Object.is 处理 NaN 与 -0 的边界。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 183 MINUTE), 1),
  (584, 4, 'Array 排序稳定性、稀疏数组与 reduce 的空位陷阱', '请说明 `Array.prototype.sort` 的稳定性在 ES2019 前后有何变化，默认比较规则是什么。\n\n```js\n[{ k: 1 }, { k: 1 }, { k: 0 }].sort((a, b) => a.k - b.k);\n[10, 9, 1, 100].sort();\nnew Array(3).map(() => 1);\n```\n\n请给出三处结果并解释：为什么数字默认排序会出错？稀疏数组的 map/forEach 会不会执行回调？reduce 不传初始值在空数组上会怎样？', '**结论**：ES2019 起 sort 被规范要求稳定（相同键保持原相对顺序）；默认比较是把元素转成字符串后按 UTF-16 码元比较，因此数字排序必须传比较函数。\n\n**1. 三处结果**：第一行按 k 升序且两个 k 为 1 的元素保持原序（稳定性）；第二行得到 `[1, 10, 100, 9]`，因为字符串比较逐位进行，"10" 小于 "9"；第三行返回三个空位（sparse），因为 map 跳过不存在的索引，不会产生 1。\n\n**2. 稀疏数组规则**：forEach、map、filter、some、every、reduce 都会跳过空位（hole），但 length 保留；`[,,].length` 为 2；`Object.keys` 看不到空位索引。要真正遍历请先 `Array.from(arr)` 或 `[...arr]`，它们会把空位变成 undefined。\n\n**3. reduce 的边界**：不传初始值时用第一个元素当累加器，因此空数组会抛 TypeError（Reduce of empty array with no initial value），单元素数组则直接返回该元素、不执行回调。传初始值后空数组返回初始值。类型也会漂移：`[].reduce((a, b) => a + b, 0)` 安全，而对象累加时一定要给初始值，否则第一个元素会被当成累加器导致字段丢失。\n\n**4. 其他要点**：sort 会原地修改并返回同一数组，不要假设它返回新数组；比较函数必须返回值而非布尔；大数组排序要意识到 V8 在元素少时用插入排序、多时用 TimSort，稳定性由算法保证；排序前做一次拷贝可避免污染共享数据。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 184 MINUTE), 1),
  (585, 4, 'Unicode、代理对与 emoji 字符串长度计算', '请解释为什么 `"😀".length === 2`，以及 `[...str]` 与 `Array.from(str)` 为什么能得到 1 个字符。\n\n```js\nconst s = "a😀b";\ns.length;          // 4\n[...s].length;     // 3\n```\n\n请回答：码点（code point）与码元（code unit）的区别？如何正确处理用户输入的字符数上限？为什么有些 emoji 组合（如家庭 emoji、带肤色的手势）用扩展运算符仍然会拆开？', '**结论**：JS 字符串是 UTF-16 码元序列，length 返回的是码元个数；BMP 之外的字符（码点大于 0xFFFF）需要两个码元组成代理对，因此 length 为 2，而展开运算符按码点迭代，得到 1 个。\n\n**1. 码点与码元**：码点是 Unicode 给字符的编号（最大 0x10FFFF），码元是 UTF-16 的 16 位存储单元。`charCodeAt` 取码元，`codePointAt` 取码点；反查用 `String.fromCodePoint`。高代理区 0xD800 到 0xDBFF 与低代理区 0xDC00 到 0xDFFF 成对出现，单独出现是非法序列。\n\n**2. 用户可感知字符（字素簇）**：`[...s]` 按码点拆分，但一个用户感知的字符可能由多个码点组合而成——带肤色的手势是基础 emoji 加修饰符，家庭 emoji 是多个 emoji 加零宽连接符 U+200D 拼接，旗帜是两个区域指示符。这类字符必须用 `Intl.Segmenter` 按 grapheme 切分。\n\n```js\nconst seg = new Intl.Segmenter("zh", { granularity: "grapheme" });\nconst count = [...seg.segment(s)].length;\n```\n\n**3. 实践：输入长度限制**：不要用 `input.value.length` 直接截断，否则会把代理对劈成两个非法码元，产生乱码方块。正确做法是按 grapheme 计数并截断；在后端也要用同一套规则校验，避免前后端计数不一致。\n\n**4. 其他易错点**：`JSON.stringify` 输出 emoji 时是现代浏览器直接给字符，某些旧环境会转成代理对转义；正则的 u 标志让 `.` 与字符类按码点匹配，不再匹配半个代理对；排序中文应使用 `Intl.Collator` 而非默认码元顺序。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 185 MINUTE), 1),
  (586, 4, '柯里化与函数组合 compose 的实现', '请实现一个通用 curry 函数，支持 `curry(fn)(1)(2)(3)` 与 `curry(fn)(1, 2)(3)` 两种调用方式，并实现 compose 与 pipe。\n\n```js\nfunction add(a, b, c) { return a + b + c; }\nconst curried = curry(add);\ncurried(1)(2)(3); // 6\ncurried(1, 2)(3); // 6\n```\n\n请说明柯里化的实际价值（不要只答"函数式"），以及 compose 中 reduce 的方向为什么容易写错、如何兼顾 this 与占位符参数。', '**结论**：柯里化把接受多个参数的函数变成一系列单参数（或部分参数）的函数，只有当累计参数达到原函数 arity 时才真正执行。\n\n**1. 实现要点**：用 `fn.length` 判断所需参数个数，闭包累积已传参数，凑够就 apply，不够就返回新函数。注意 length 不计入有默认值的参数与剩余参数，所以更稳妥的方式是允许显式传入 arity。\n\n```js\nfunction curry(fn, arity = fn.length, ...preset) {\n  return function (...args) {\n    const all = [...preset, ...args];\n    return all.length >= arity ? fn.apply(this, all) : curry(fn, arity, ...all);\n  };\n}\n```\n\n**2. 实际价值**：一是参数预置，把通用函数特化成场景函数（`const isAdmin = hasRole("admin")`），减少重复传参；二是提升可组合性，配合 map/filter 直接得到一元函数，避免写箭头包装；三是延迟执行与部分应用，便于构造配置化管道。它不是性能优化手段，反而多一层闭包开销。\n\n**3. compose 方向**：`compose(f, g)(x)` 约定为 `f(g(x))`，即从右往左，用 `reduce((acc, fn) => fn(acc), x)` 时若函数数组是 [f, g]，需要先反转或改用 reduceRight；pipe 则是从左往右，更符合阅读习惯，工程里更常用。\n\n```js\nconst compose = (...fns) => (x) => fns.reduceRight((acc, fn) => fn(acc), x);\nconst pipe = (...fns) => (x) => fns.reduce((acc, fn) => fn(acc), x);\n```\n\n**4. 边界**：用 apply 传递 this 以免丢失上下文；中间件的第一个函数若是多参数（如 (req, res)），compose 只适合单入单出，多参数场景应改用 reduce 手动展开；空数组时 compose 应返回恒等函数而不是抛错。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 186 MINUTE), 1),
  (587, 4, 'ESM 与 CommonJS 的差异、循环依赖与动态 import', '请从加载时机、导出值的绑定方式、this 指向、作用域四个维度对比 ESM 与 CommonJS，并解释下面代码为什么在两种模块系统下表现不同。\n\n```js\n// a.js\nimport { b } from "./b.js";\nexport const a = "a";\nconsole.log(b);\n\n// b.js\nimport { a } from "./a.js";\nexport const b = "b";\nconsole.log(a);\n```\n\n请说明循环依赖时哪个值可能是 undefined，ESM 的 live binding 如何缓解这个问题，以及 import() 动态导入的典型用途。', '**结论**：ESM 是静态的、编译期确定依赖图、导出的是活绑定（live binding）、默认严格模式且顶层 this 为 undefined；CommonJS 是运行时同步加载、导出的是值的拷贝、this 指向 module.exports。\n\n**1. 四维对比**：\n\n| 维度 | ESM | CommonJS |\n| --- | --- | --- |\n| 加载 | 预解析依赖，静态提升 | 运行时 require，同步阻塞 |\n| 导出 | 活绑定，读取时取值 | module.exports 对象快照 |\n| 顶层 this | undefined | module.exports |\n| 条件加载 | 只能 import() 动态 | 可任意 if 内 require |\n\n**2. 循环依赖的差异**：CommonJS 在模块首次 require 时就执行并缓存未完成的 exports，a 拿到的 b 可能是空对象或 undefined；ESM 则是先建立模块记录与绑定，再执行求值，只要不在初始化阶段读取（TDZ 内），后续拿到的是最新值。所以上面例子在 ESM 中可能因为 TDZ 抛 ReferenceError，而不是静默 undefined，这正是活绑定带来的"更早暴露问题"。\n\n**3. 活绑定的含义**：`import { count }` 拿到的是绑定而非拷贝，模块内部执行 `count++` 后使用方看到新值；这也意味着不能给导入的绑定重新赋值（常量语义）。`export default` 导出的是值，不是活绑定，容易被误解。\n\n**4. 动态 import**：返回 Promise，用于路由级代码分割、条件加载 polyfill、按需加载重型库；打包器会把目标拆成独立 chunk，但要注意它会破坏静态分析，滥用会让首屏请求数暴增，应配合 prefetch 与体积预算使用。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 187 MINUTE), 1),
  (588, 4, '用 AbortController 取消请求与统一清理副作用', '请说明 AbortController 的工作原理，以及如何用同一个 signal 同时取消 fetch、移除事件监听、断开 observer。\n\n```js\nconst ctrl = new AbortController();\nfetch(url, { signal: ctrl.signal }).catch(err => {\n  if (err.name === "AbortError") return;\n  throw err;\n});\nctrl.abort();\n```\n\n请回答：abort 之后 Promise 是 reject 还是 resolve？如何给请求加超时？为什么说 signal 也是组件卸载时清理副作用的好工具？', '**结论**：AbortController 通过一个 signal 对象广播取消信号，任何接受 signal 的 API（fetch、addEventListener、ReadableStream、AbortSignal.timeout 等）都会响应；abort 后 fetch 的 Promise 以 name 为 AbortError 的 DOMException reject。\n\n**1. 基本用法**：`ctrl.abort(reason)` 会触发 signal 的 abort 事件，且已 abort 的 signal 不能再复用，需要新建控制器。监听侧统一判断 `err.name === "AbortError"` 并静默返回。\n\n**2. 超时控制**：现代写法 `AbortSignal.timeout(5000)` 直接生成超时信号；需要同时支持手动取消与超时时用 `AbortSignal.any([ctrl.signal, AbortSignal.timeout(5000)])`。没有这些 API 时用 setTimeout 调 ctrl.abort() 并在 finally 里 clearTimeout。\n\n**3. 组件卸载的统一清理**：把 signal 传给所有副作用，卸载时一次 abort 全部解绑：\n\n```js\nonUnmounted(() => ctrl.abort());\nwindow.addEventListener("resize", onResize, { signal: ctrl.signal });\nconst io = new IntersectionObserver(cb);\nio.observe(el); // 卸载时需 io.disconnect()\n```\n\naddEventListener 支持 signal 后不需要再手动 removeEventListener。\n\n**4. 常见坑**：一是 abort 后 catch 里必须区分取消与真实错误；二是并发请求共享一个控制器时，取消一个会连带取消全部，应按请求维度建控制器或用 AbortSignal.any 组合；三是旧的 XHR 需要用 xhr.abort()，不支持 signal；四是 abort 不会终止已到达的服务端处理，只影响客户端。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 188 MINUTE), 1),
  (589, 4, 'fetch 与 XHR 的差异及流式响应处理', '请从能力、错误处理、进度、取消、流式处理五个方面对比 fetch 与 XMLHttpRequest。\n\n```js\nconst res = await fetch("/api", { method: "POST", body: fd });\nif (!res.ok) throw new Error(res.status);\nconst reader = res.body.getReader();\n```\n\n请回答：为什么 fetch 在 4xx/5xx 时不 reject？上传进度怎么监控？如何用 ReadableStream 实现打字机效果的流式渲染？为什么说 fetch 默认不携带 Cookie？', '**结论**：fetch 是基于 Promise 的新一代 API，语义更清晰、原生支持流与 Service Worker，但缺少上传进度、需要手动判断状态码、默认不改凭证策略；XHR 老但保留了 progress 事件与可中断的同步能力。\n\n**1. 错误语义**：fetch 只在网络层失败（DNS、断连、CORS 被拦）时 reject，HTTP 状态码 4xx/5xx 仍算成功响应，必须自己判 `res.ok`。这是线上事故的高发点，封装时应在拦截器里统一抛错。\n\n**2. 进度监控**：fetch 目前没有上传进度事件，需要读 `res.body.getReader()` 只能拿到下载进度；上传进度要用 XHR 的 `upload.onprogress`、axios 的 onUploadProgress，或改用 `ReadableStream` 分片上传自行累计已发送字节。\n\n**3. 流式响应**：`res.body` 是 ReadableStream，配合 TextDecoder 增量解码，遇到换行或 SSE 的 `data:` 分隔符就解析一帧并渲染，可实现大模型对话的打字机效果。要点是处理跨 chunk 截断的半个 UTF-8 字符与半个 JSON，必须用 `{ stream: true }` 解码并维护缓冲区。\n\n**4. 凭证与兼容**：fetch 默认 credentials 为 same-origin，跨域时不会带 Cookie，需显式 `credentials: "include"`，同时服务端要返回具体的 Access-Control-Allow-Origin 而不能是通配符。XHR 的 `withCredentials` 是同样的开关。另外 fetch 不支持超时参数（用 AbortSignal.timeout），不支持同步请求，也不遵循 XSRF 自动防护。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 189 MINUTE), 1),
  (590, 4, '浏览器多进程架构与各进程职责', '请说明现代浏览器（以 Chrome 为例）的主要进程类型及各自职责，并解释为什么渲染进程要单独隔离。\n\n场景：你在页面里打开 10 个标签页，其中一个页面的死循环导致整个浏览器卡死（早期版本）。\n\n请回答：多进程架构如何缓解这个问题？站点隔离（Site Isolation）解决了什么安全威胁？浏览器主进程、GPU 进程、网络进程、渲染进程各自负责什么？', '**结论**：Chrome 采用多进程架构，浏览器主进程管界面与协调，渲染进程负责每个标签页的解析与执行，GPU 进程负责合成与光栅化，网络进程统一处理请求，插件与工具进程各自独立。\n\n**1. 各进程职责**：\n\n| 进程 | 职责 |\n| --- | --- |\n| 浏览器主进程 | 地址栏、书签、标签管理、进程调度、文件访问 |\n| 渲染进程 | HTML/CSS 解析、JS 执行、布局绘制，每个标签页一个（或按站点拆分） |\n| GPU 进程 | 图层合成、光栅化、WebGL，供所有标签页共享 |\n| 网络进程 | DNS、连接、缓存、Cookie 管理 |\n| 工具进程 | 扩展、Utility、音频等 |\n\n**2. 隔离的价值**：单个渲染进程崩溃只影响对应标签页，不会拖垮浏览器；死循环只卡住该页面的主线程，其他标签页仍可交互。同时内存可通过进程回收彻底释放。\n\n**3. 站点隔离**：早期同一进程可能承载多个不同源的页面，Spectre 类侧信道攻击可跨站读取内存。Site Isolation 按站点（scheme + eTLD+1）划分进程，配合 CORB/ORB 与跨源隔离（COOP/COEP），让跨站数据无法进入同一地址空间。代价是进程数增多、内存占用上升。\n\n**4. 与前端的关系**：跨进程通信要走 IPC，因此 postMessage、跨标签页共享的 BroadcastChannel 都不是零成本；渲染进程内的主线程与合成器线程、光栅线程并行，滚动与 CSS 动画能脱离主线程运行正是这个架构的结果。理解这一点才能解释为什么长任务会阻塞交互而纯 transform 动画不会。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 190 MINUTE), 1),
  (591, 4, '关键渲染路径与渲染流水线的各阶段', '请完整描述从 HTML 字节流到屏幕像素的渲染流水线，并说明每个阶段前端可以干预的手段。\n\n```html\n<link rel="stylesheet" href="a.css">\n<script src="b.js"></script>\n```\n\n请回答：CSS 会阻塞什么？同步 script 会阻塞什么？为什么把 script 放在 body 末尾或加 defer/async？图层（layer）在哪个阶段产生？哪些属性只会触发合成而不会重排重绘？', '**结论**：流水线为 解析 HTML 构建 DOM → 解析 CSS 构建 CSSOM → 合并为渲染树 → 布局（Layout/Reflow）计算几何 → 绘制（Paint）生成绘制指令 → 分层与光栅化 → 合成（Composite）上屏。\n\n**1. 阻塞关系**：CSS 阻塞渲染树的构建，也阻塞其后同步脚本的执行（因为脚本可能读取样式）；同步 script 阻塞 HTML 解析，因为它可能 document.write 或改 DOM。defer 让脚本在解析完成后按顺序执行（DOMContentLoaded 前），async 下载完就执行、顺序不定，适合统计脚本。\n\n**2. 分层与合成**：浏览器把页面拆成多个合成层（compositing layer），常见触发条件有 3D transform、will-change、video/canvas、position: fixed、filter 等。光栅化把图层内容转成位图，合成线程按变换与透明度把图层拼成最终画面。\n\n**3. 属性代价分级**：\n\n| 改动 | 触发的阶段 |\n| --- | --- |\n| width/height/top/margin | Layout + Paint + Composite |\n| color/background/box-shadow | Paint + Composite |\n| transform/opacity | 仅 Composite |\n\n这就是用 transform 做动画更流畅的原因：它能在合成线程完成，不占用主线程。\n\n**4. 优化手段**：内联关键 CSS、给非关键 CSS 加 media 或 preload、script 加 defer、避免在首屏渲染前插入同步样式表、用 content-visibility 跳过视口外渲染、用 will-change 提前提升但不要滥用（会造成层爆炸与显存压力）。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 191 MINUTE), 1),
  (592, 4, '强制同步布局（布局抖动）的成因与规避', '请解释什么是强制同步布局（forced synchronous layout），并分析下面代码的性能问题。\n\n```js\nfor (let i = 0; i < items.length; i++) {\n  items[i].style.width = box.offsetWidth + 10 + "px";\n}\n```\n\n请说明读写交替为什么会触发多次布局，浏览器在什么时机自动刷新布局，并给出两种优化方案及其原理。', '**结论**：当 JS 在修改样式之后立刻读取会依赖布局的几何属性（offsetWidth、clientHeight、getBoundingClientRect、getComputedStyle 的部分属性、scrollTop）时，浏览器为了返回正确值必须立即同步执行一次布局，这就是强制同步布局；在循环里读写交替会导致布局次数与元素数量成正比，即布局抖动。\n\n**1. 问题代码**：每轮先写 style.width，再读 offsetWidth，而上一轮的写入已经使布局失效（layout dirty），于是每轮都触发一次完整重排，N 个元素就是 N 次重排。若把读取提前，只需一次。\n\n**2. 浏览器的刷新时机**：正常情况下样式与布局的失效被标记为 dirty，浏览器在下一帧渲染前（一次 rAF 回调之后、绘制之前）批量重算，这叫 layout flush；一旦脚本同步读取几何值，就会提前 flush，打破批量化。\n\n**3. 两种优化**：\n\n```js\n// 方案一：先读后写，分离读写阶段\nconst w = box.offsetWidth;\nfor (const el of items) el.style.width = w + 10 + "px";\n\n// 方案二：批量写，下一帧统一测量\nconst w2 = box.offsetWidth;\nrequestAnimationFrame(() => {\n  items.forEach(el => { el.style.width = w2 + 10 + "px"; });\n});\n```\n\n**4. 延伸**：同样的坑还有读写混用的列表动画、滚动监听里读 scrollTop 后再改样式、频繁 getComputedStyle。工具上可用 Performance 面板看 Layout 是否被标为 Forced reflow，或看经验法则：单帧内 Layout 次数大于 1 且紧跟脚本调用栈就要怀疑。正确的思路是"读一批、写一批"，必要时用 FastDOM 这类调度库。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 192 MINUTE), 1),
  (593, 4, 'Core Web Vitals 的度量与优化策略', '请说明 LCP、INP、CLS 三个核心指标的判定标准与采集方式，并针对一个首屏是巨幅 banner 加长文列表的营销页给出优化方案。\n\n```js\nnew PerformanceObserver(list => {\n  for (const e of list.getEntries()) report(e);\n}).observe({ type: "largest-contentful-paint", buffered: true });\n```\n\n请回答：LCP 的元素候选如何变化？INP 与 FID 的本质区别？哪些操作会导致 CLS？实验室数据与真实用户数据（RUM）应如何配合？', '**结论**：LCP 衡量最大内容元素完成渲染的时间，良好阈值为 2.5s 内；INP 衡量从交互到下一帧绘制的整体延迟，良好为 200ms 内；CLS 衡量意外布局偏移，良好为 0.1 内。三者都按第 75 百分位评估。\n\n**1. LCP 的候选与阶段**：候选元素包括 img、image 内的 svg、video 封面、带背景图的块、文本块，随渲染推进可能被更大的元素替换。可拆成四段：TTFB、资源加载延迟、资源加载时长、元素渲染延迟。优化对应为：CDN 与缓存降低 TTFB、`fetchpriority="high"` 提前拉取主图、图片压缩与 AVIF、避免首屏图片懒加载、减少阻塞渲染的 CSS 与字体。\n\n**2. INP 与 FID**：FID 只测第一次输入到事件回调开始执行的延迟，INP 则取整页所有交互的延迟分布并看高分段，覆盖输入延迟、处理耗时、下一帧呈现三段，因此更能反映页面是否"卡"。优化核心是拆分长任务（scheduler.yield / isInputPending）、把重计算移入 Worker、减少一次交互中的强制同步布局与大规模 DOM 更新。\n\n**3. CLS 的来源与修复**：无尺寸的图片与 iframe、动态插入的广告与公告条、字体切换导致的 FOUT、异步渲染的骨架屏比例不一致。修复手段是给媒体元素写死宽高比（aspect-ratio 或 width/height 属性）、为动态区域预留占位、用 font-size-adjust 与字体预加载减少抖动、动画只用 transform。\n\n**4. 数据体系**：实验室用 Lighthouse 与 Performance 面板定位具体瓶颈，可复现但不代表真实分布；RUM 用 web-vitals 库在页面隐藏时通过 sendBeacon 上报，按设备、网络、地区分维度看 P75，两者结合才能既定位原因又验证收益。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 193 MINUTE), 1),
  (594, 4, 'PerformanceObserver 与长任务、自定义性能打点', '请说明 PerformanceObserver 相比 performance.getEntries 的优势，以及如何使用它监控长任务、资源加载与自定义耗时。\n\n```js\nnew PerformanceObserver(list => {\n  list.getEntries().forEach(e => console.log(e.duration, e.attribution));\n}).observe({ type: "longtask", buffered: true });\n```\n\n请回答：长任务（long task）的判定阈值是多少？为什么主线程长任务会伤害 INP？如何用 performance.mark/measure 给业务关键路径打点，并在上报时避免数据量爆炸？', '**结论**：PerformanceObserver 是回调式订阅，能在条目产生时实时收到通知且开销低；getEntries 是快照式查询，高频轮询会带来性能负担，也可能因缓冲区满而丢数据。\n\n**1. 可观测的条目类型**：navigation（导航与重定向耗时）、resource（每个静态资源的各阶段耗时）、paint（FP/FCP）、largest-contentful-paint、layout-shift、longtask、event（交互延迟）、element（元素渲染时间）。用 `buffered: true` 可拿到订阅之前的条目，这对在页面加载后才注入的监控脚本很关键。\n\n**2. 长任务**：超过 50ms 的主线程任务被判定为 longtask，条目里带有 attribution 指明归属的容器与脚本。它直接阻塞输入响应与渲染，因此是 INP 与卡顿的主因；优化方向是拆分任务、让出主线程、把计算搬到 Worker。\n\n**3. 自定义打点**：\n\n```js\ntry {\n  performance.mark("list-start");\n  renderList(data);\n} finally {\n  performance.mark("list-end");\n  performance.measure("render-list", "list-start", "list-end");\n}\n```\n\nmeasure 的结果也会出现在 resource 之外的自定义条目里，可被 Observer 捕获。打点要围绕用户可感知的阶段（首屏、可交互、关键操作），不要给每个函数都加。\n\n**4. 上报控制**：一是采样，按用户或会话比例采；二是聚合，客户端算分位数与直方图再上报，而不是逐条上报；三是限制条目数量，长任务只取 Top N 与总时长；四是使用 sendBeacon 在 pagehide 时批量发送，避免因页面销毁丢数据。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 194 MINUTE), 1),
  (595, 4, 'preload、prefetch、preconnect 与 dns-prefetch 的取舍', '请说明 preload、prefetch、preconnect、dns-prefetch、modulepreload 五者的作用时机与优先级差异，并指出常见误用。\n\n```html\n<link rel="preconnect" href="https://cdn.example.com" crossorigin>\n<link rel="preload" href="/hero.avif" as="image" fetchpriority="high">\n<link rel="prefetch" href="/next-route.js">\n```\n\n请回答：preload 与 prefetch 的优先级和缓存策略有什么不同？preload 的资源没被使用会怎样？为什么 preconnect 通常只对 1 到 2 个域名使用？', '**结论**：preload 是"当前页面马上要用，请以高优先级提前下载"；prefetch 是"下一个页面可能要用，空闲时低优先级下载"；preconnect 提前完成 DNS + TCP + TLS；dns-prefetch 只做 DNS 解析；modulepreload 专门预加载 ESM 模块并解析依赖图。\n\n**1. 时机与优先级**：\n\n| 指令 | 时机 | 优先级 |\n| --- | --- | --- |\n| preload | 当前页面，立即 | 高（可被 fetchpriority 调整） |\n| prefetch | 空闲时，供未来导航 | 最低 |\n| preconnect | 立即建连，保持若干秒 | 中 |\n| dns-prefetch | 仅解析域名 | 低 |\n| modulepreload | 当前页，预取并解析模块图 | 中高 |\n\n**2. 关键差别**：preload 的响应进入 HTTP 缓存与内存缓存，脚本/样式可被后续直接复用；prefetch 的资源通常进独立的预取缓存，跨页面可用但可能被清理，且 Safari 支持不完整。preload 必须写对 as 与 crossorigin，否则会与真实请求不匹配造成二次下载——这是最常见的误用。\n\n**3. preload 未使用的代价**：Chrome 会在 onload 后约 3 秒打印未使用警告，并可能因抢占带宽而推迟真正关键的资源，反而拉高 LCP。因此应只为首屏关键资源（主图、字体、关键 CSS）使用，并配合 `media` 或 `imagesrcset` 做条件预载。\n\n**4. preconnect 的数量**：每次预连接都占用一个连接与后台资源，过多会拖慢真正关键域名的建连。经验是只对 1 到 2 个确定会用且跨域的域名使用，且必须与 crossorigin 属性一致，否则会建立两次连接。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 195 MINUTE), 1),
  (596, 4, '图片格式选择、srcset 与懒加载实践', '请为一张同时用于首屏 banner、列表缩略图、详情大图的图片设计加载方案，说明格式、尺寸、优先级与懒加载策略。\n\n```html\n<img src="small.jpg" srcset="m.jpg 800w, l.jpg 1600w" sizes="(max-width: 600px) 100vw, 50vw" loading="lazy" width="1200" height="800" alt="示例">\n```\n\n请回答：srcset 的 w 描述符与 x 描述符分别适用什么场景？sizes 的作用是什么？为什么必须写 width/height？首屏图为什么不能加 loading="lazy"？AVIF、WebP、JPEG 如何降级？', '**结论**：格式上优先 AVIF，其次 WebP，JPEG 兜底；尺寸上用 srcset + sizes 让浏览器按视口与 DPR 选择合适资源；首屏图用 `fetchpriority="high"` 且不加 lazy，视口外图用 `loading="lazy"`，并用 width/height 或 aspect-ratio 预留空间避免 CLS。\n\n**1. 格式取舍**：AVIF 压缩率最好但编码慢、Safari 支持较晚；WebP 兼容与体积平衡最好；JPEG 适合照片兜底；PNG 留给需要无损与透明的小图；SVG 用于图标。降级用 `<picture>` 配合 `<source type="image/avif">`，让浏览器按支持情况选择，不要用 JS 嗅探。\n\n**2. srcset 与 sizes**：w 描述符表示图片固有宽度，浏览器结合 sizes 给出的显示宽度与设备像素比算出所需像素，再选最接近的资源；x 描述符用于固定显示尺寸的 1x/2x 资源（如 logo）。sizes 必须与实际 CSS 布局一致，写错会导致下载过大的图。\n\n**3. 尺寸与 CLS**：没有宽高比的图片在加载完成时会撑开布局，造成明显偏移。写 width/height 属性配合 CSS `max-width: 100%; height: auto` 可在加载前就占好位置，是现代浏览器计算宽高比的首选做法。\n\n**4. 懒加载**：`loading="lazy"` 由浏览器在接近视口时才加载，简单可靠，但对首屏图会造成 LCP 恶化（因为延迟发现），首屏图应显式声明 eager 与高优先级。需要更精细控制（提前 200px 预加载、失败重试、占位模糊图）时用 IntersectionObserver 自行实现。另外注意懒加载图片要保留 alt 与占位背景，避免布局跳动。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 196 MINUTE), 1),
  (597, 4, 'Web 字体加载与 FOIT/FOUT 的取舍', '请解释 FOIT 与 FOUT 的成因，并说明 font-display 各取值的语义差异。\n\n```css\n@font-face {\n  font-family: "Brand";\n  src: url("/brand.woff2") format("woff2");\n  font-display: swap;\n  unicode-range: U+4E00-9FFF;\n}\n```\n\n请回答：为什么自定义字体会导致文字闪烁或长时间不可见？浏览器何时发现字体请求？`preload` 字体需要注意什么？中文字体为什么通常要做子集化，unicode-range 起什么作用？', '**结论**：字体是 CSS 触发才被发现的资源，加载期间浏览器要么隐藏文字（FOIT），要么先用回退字体渲染再替换（FOUT）；font-display 就是这两者之间的显式取舍开关。\n\n**1. 各取值的语义**：\n\n| 取值 | 行为 |\n| --- | --- |\n| auto | 浏览器默认，通常接近 block |\n| block | 短阻塞期（约 3s）文字不可见，之后 swap |\n| swap | 立即用回退字体，字体到达后替换，几乎无 FOIT |\n| fallback | 极短阻塞期（约 100ms），之后进入约 3s 的 swap 期 |\n| optional | 极短阻塞期，若字体未及时到达则本次导航不再使用 |\n\n**2. 权衡**：品牌标题为了视觉一致可用 block 或 preload 配合；正文强烈建议 swap 或 optional，因为可读性优先于字形；optional 能彻底消除抖动，代价是弱网下可能一直用回退字体。\n\n**3. preload 字体**：字体在 CSSOM 解析到 @font-face 且页面用到该字体时才发起请求，容易推迟。用 `<link rel="preload" as="font" type="font/woff2" crossorigin>` 可提前，crossorigin 必须写，因为字体请求是 CORS 模式，否则会重复下载。\n\n**4. 中文字体与 CLS**：中文字体动辄数 MB，全量加载会让首屏文字长时间空白。做法是子集化（只保留常用字或用到的字形，工具如 fontmin、subset-font），并把字体切成多个 unicode-range 分片按需加载。此外可用 `size-adjust`、`ascent-override` 让回退字体的度量接近自定义字体，减小替换时的位移。最后要确保字体加载失败也有可读回退，不要依赖单一字体。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 197 MINUTE), 1),
  (598, 4, 'IntersectionObserver 做懒加载与曝光埋点', '请用 IntersectionObserver 实现图片懒加载与元素曝光统计，并说明它与滚动监听相比的优势。\n\n```js\nconst io = new IntersectionObserver((entries) => {\n  entries.forEach(e => {\n    if (e.isIntersecting) { load(e.target); io.unobserve(e.target); }\n  });\n}, { rootMargin: "200px", threshold: 0.1 });\n```\n\n请回答：rootMargin 与 threshold 的区别？为什么曝光埋点需要 ratio 与停留时长两个条件？单页应用切换路由后 observer 需要怎么处理？它与 scroll 事件在性能上的本质差别是什么？', '**结论**：IntersectionObserver 由浏览器在渲染阶段异步计算目标与根的交集，回调在空闲时批量触发，不需要监听滚动事件，因此没有主线程高频计算与布局抖动的开销。\n\n**1. 参数语义**：root 指定参照容器（默认视口），rootMargin 扩大或收缩判定边界（单位同 margin，支持负值），threshold 是交集比例的触发阈值数组（0 表示刚接触，1 表示完全可见）。懒加载常用 `rootMargin: "200px"` 提前加载，曝光埋点常用 `threshold: 0.5` 表示过半可见。\n\n**2. 曝光统计的正确姿势**：仅有 isIntersecting 会误报——用户快速滑过、元素只露 1px 都算。通常要求可见比例超过阈值且连续停留超过 500ms 才计一次曝光，并用 WeakSet 去重。同时要处理页面隐藏（visibilitychange）时暂停计时，避免切后台产生假曝光。\n\n**3. SPA 中的生命周期**：路由切换后旧元素被移除但仍被 observer 引用会造成泄漏，必须在组件卸载时 unobserve 或 disconnect；新的列表项渲染完后需重新 observe；虚拟列表场景元素复用，要注意在复用时刻重置"已曝光"标记。\n\n**4. 与 scroll 的对比**：scroll 监听在主线程触发，需要读 getBoundingClientRect，容易与写样式交替形成布局抖动，且高频触发需要节流；IntersectionObserver 的计算在浏览器内部完成，回调合并触发，既不阻塞滚动也不受节流误差影响。唯一的限制是不能精确拿到滚动位置，需要精确视差效果时仍要用 rAF 读取。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 198 MINUTE), 1),
  (599, 4, '跨标签页通信的几种方案与选型', '请对比 storage 事件、BroadcastChannel、SharedWorker、Service Worker、postMessage 五种跨标签页通信方式，并给出登录态同步与多标签页防重复请求两个场景的方案。\n\n```js\nconst bc = new BroadcastChannel("auth");\nbc.onmessage = (e) => syncToken(e.data);\nbc.postMessage({ type: "logout" });\n```\n\n请回答：storage 事件在同一个标签页内会触发吗？BroadcastChannel 能否跨域？标签页被关闭时如何通知其他页面？为什么 localStorage 轮询是下策？', '**结论**：同源标签页之间首选 BroadcastChannel（简单、结构化数据、低延迟），需要兼容老浏览器时退回 storage 事件；跨窗口引用可用 postMessage；需要集中状态或串行调度时用 SharedWorker；Service Worker 适合做离线与推送，通信本身较弱。\n\n**1. 各方案对比**：\n\n| 方案 | 同源限制 | 数据能力 | 适用 |\n| --- | --- | --- | --- |\n| storage 事件 | 是 | 仅字符串 | 兼容性要求高的简单同步 |\n| BroadcastChannel | 是 | 结构化克隆 | 首选，广播类 |\n| SharedWorker | 是 | 任意（含引用） | 需要单例调度 |\n| postMessage | 可跨源（受 origin 校验） | 结构化克隆 + Transferable | 有窗口引用（iframe、window.open） |\n| Service Worker | 是 | 消息通道 | 离线、推送、缓存协调 |\n\n**2. storage 事件的细节**：它只在其他同源窗口触发，写入的标签页本身收不到，因此不能用于自发自收；值必须序列化为字符串；隐私模式与部分场景下不可靠。这也是 localStorage 轮询被诟病的原因：轮询有延迟、耗电、且无法精确感知删除。\n\n**3. 场景一：登录态同步**：登录成功或登出时通过 BroadcastChannel 广播，其他标签页据此刷新 token 或跳转登录页；同时以 Cookie 或 localStorage 中的版本号作为兜底校验，防止广播丢失。标签页关闭无法直接广播，可在 pagehide 时发送离线消息，或让服务端维护心跳。\n\n**4. 场景二：防重复请求**：多个标签页同时刷新 token 会互相顶掉。做法是用 Web Locks API 或 SharedWorker 选主，只有一个标签页发起刷新，完成后广播新 token；也可用 localStorage 加时间戳做简易锁，但要处理写入竞态与死锁超时。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 199 MINUTE), 1),
  (600, 4, '前端路由的 hash 与 history 模式及其服务端配合', '请说明 hash 模式与 history 模式的实现原理差异，并解释 history 模式下刷新子路由为什么会 404。\n\n```js\nhistory.pushState({ page: 1 }, "", "/detail/1");\nwindow.addEventListener("popstate", onPop);\n```\n\n请回答：pushState 会触发 popstate 吗？pushState 与 location.hash 赋值在触发事件上有什么不同？如何监听 pushState 这类不会触发事件的行为？服务端需要怎样配置？HashRouter 在什么场景下仍是必要选择？', '**结论**：hash 模式靠 URL 的 # 片段变化驱动，浏览器不会把 # 之后发给服务端，刷新永远命中同一个 HTML；history 模式用 History API 改写真实路径，视觉上更干净，但要求服务端把所有前端路由回退到入口 HTML。\n\n**1. 事件差异**：hash 变化会触发 hashchange 与 popstate；`pushState/replaceState` 不触发 popstate，只改变历史栈；只有浏览器前进后退（或调用 history.back）才触发 popstate。因此用 pushState 做路由时需要自己通知路由更新，或统一封装在 router 的导航方法里。\n\n**2. 为什么刷新 404**：history 模式下 `/detail/1` 是一个真实路径，刷新时浏览器直接向服务端请求它；若服务端没有对应资源就 404。修复方式是 Nginx 的 `try_files $uri $uri/ /index.html`，或 Node 层做通配回退，同时保证静态资源路径不被误回退。\n\n**3. 监听 pushState**：原生无法监听，常见做法是 monkey patch `history.pushState` 与 `replaceState` 派发自定义事件，这也是很多埋点与微前端框架的做法；Vue Router 与 React Router 内部自行维护状态，不依赖事件。\n\n**4. 选型与坑**：hash 模式无需服务端配置，适合静态托管、File 协议、老式后台；history 模式 SEO 与分享更友好。history 模式下要处理 base 路径（部署在子目录）、锚点滚动、以及 iOS 微信等环境的返回缓存；还要注意 pushState 的频率限制（部分浏览器约 100 次/30 秒会抛异常）。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 200 MINUTE), 1),
  (601, 4, 'SameSite、第三方 Cookie 与存储分区的影响', '请说明 SameSite 的三个取值语义，以及浏览器逐步禁用第三方 Cookie 后，前端嵌入场景（iframe 内登录、跨站埋点、OAuth 回调）受到的影响与替代方案。\n\n```http\nSet-Cookie: sid=abc; SameSite=None; Secure; HttpOnly; Partitioned\n```\n\n请回答：Lax 与 Strict 在顶级导航上的行为差异？为什么 SameSite=None 必须配 Secure？CHIPS 的 Partitioned 解决什么问题？跨站场景下还有哪些可用的存储替代？', '**结论**：SameSite 控制 Cookie 是否随跨站请求发送：Strict 完全不发送，Lax 允许顶级 GET 导航携带，None 允许跨站携带但必须 Secure。第三方 Cookie 被限制后，未分区存储在同一站点被嵌入不同顶级站点时会共享，造成跟踪面；CHIPS 用 Partitioned 把 Cookie 按顶级站点分区，兼顾功能与隐私。\n\n**1. 三值对比**：\n\n| 取值 | 跨站子资源 | 顶级导航 GET | 顶级导航 POST |\n| --- | --- | --- | --- |\n| Strict | 不发 | 不发 | 不发 |\n| Lax（默认） | 不发 | 发 | 不发 |\n| None | 发（需 Secure） | 发 | 发 |\n\nLax 是 Chrome 的默认值，这解释了为什么从外部链接跳回站点时登录态还在，但 iframe 与跨站 POST 表单会丢 Cookie，也是 CSRF 防护的第一道默认防线。\n\n**2. 强制 Secure 的原因**：SameSite=None 意味着 Cookie 可随任意跨站请求发出，若允许明文 HTTP，攻击者可在中间人链路上窃取，因此规范要求必须同时具备 Secure，否则浏览器直接丢弃。\n\n**3. CHIPS 与分区**：`Partitioned` 让 Cookie 的键包含顶级站点，A 站嵌入 B 站组件时，B 在 A 下与 C 下拿到的是不同分区，无法互相识别，从而阻断跨站跟踪，同时保留 iframe 内会话能力。它要求 Secure，且只在支持分区的浏览器生效。\n\n**4. 替代方案**：跨站 iframe 场景可用 Storage Access API 申请用户授权后访问未分区存储；OAuth 回调改用顶级导航加 state 校验，避免依赖第三方 Cookie；前端尽量把身份通过 Bearer Token 放在内存或分区存储中，并配合服务端会话；埋点改用无 Cookie 的服务端标识或 Privacy Sandbox 的主题与归因 API。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 201 MINUTE), 1),
  (602, 4, 'CSP 内容安全策略的落地与绕过风险', '请说明 CSP 的核心指令与两种下发方式，并给出一份既能防 XSS 又不至于阻碍业务的策略。\n\n```http\nContent-Security-Policy: default-src "self"; script-src "self" "nonce-r4nd0m"; object-src "none"; base-uri "self"\n```\n\n请回答：nonce 与 hash 白名单相比域名白名单有什么优势？为什么 script-src 允许 unsafe-inline 就几乎失效？report-only 模式怎么用？CSP 能否完全防住 XSS，还有哪些绕过手法？', '**结论**：CSP 通过白名单限制资源加载与执行来源，最有效的用法是 script-src 只允许带 nonce 或 hash 的内联脚本，配合 default-src 收口与 object-src、base-uri 加固；但它防的是"注入的脚本被执行"，不能修复已有的 DOM XSS 逻辑。\n\n**1. 关键指令**：default-src 兜底；script-src 管脚本；style-src 管样式；img-src、connect-src 管图片与请求；frame-ancestors 防点击劫持；form-action 限制表单提交目标；base-uri 防止 base 标签劫持相对路径；report-uri / report-to 收集违规。下发方式有响应头与 meta 标签，响应头优先级更高，frame-ancestors 等指令在 meta 中无效。\n\n**2. nonce 的优势**：域名白名单依赖 CDN 与第三方域，一旦这些域存在 JSONP 或可控上传，攻击者就能在其下托管脚本绕过；nonce 每次响应随机生成，只有服务端注入的脚本带正确 nonce 才能执行，攻击者注入的内联脚本无法猜测。hash 适合固定的内联脚本，非动态场景更方便。\n\n**3. unsafe-inline 的问题**：它允许所有内联脚本，而 XSS 的主要注入形态正是内联脚本与事件属性，等于把防线全撤。若必须过渡，可用 `strict-dynamic` 配合 nonce，让受信任脚本动态加载的脚本也被信任。\n\n**4. 落地与边界**：先用 `Content-Security-Policy-Report-Only` 观察违规上报，逐步扩白名单再切强制模式；注意内联事件属性、eval（需 unsafe-eval）、内联样式都要改造。CSP 无法阻止 DOM XSS 中的 innerHTML 注入（若不加 Trusted Types）、无法防数据泄露类攻击，仍需输出编码与输入校验配合；另外若存在开放重定向或同域上传，仍可能被绕过。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 202 MINUTE), 1),
  (603, 4, '线上报错堆栈还原与 sourcemap 管理', '请说明生产环境如何采集 JS 错误并还原成源码位置，给出完整链路设计。\n\n```js\nwindow.addEventListener("error", e => report({ msg: e.message, stack: e.error?.stack }));\nwindow.addEventListener("unhandledrejection", e => report({ msg: String(e.reason) }));\n```\n\n请回答：压缩后的堆栈长什么样？为什么 sourcemap 绝对不能发布到 CDN？如何用 source-map 库做映射？跨域脚本的错误为什么只有 Script error.？资源加载错误如何捕获？', '**结论**：压缩后的堆栈只有行列号与混淆后的变量名，必须依赖构建时产出的 sourcemap，在服务端（或监控平台）用原始映射表把行列号还原成源文件、函数名与源码片段。\n\n**1. 采集要点**：error 事件拿 `e.error.stack`（跨域脚本拿不到）；unhandledrejection 拿 Promise 未捕获的拒绝；`e.target` 存在时是资源加载失败（img、script），此时无 message，需要单独处理。还要补上 Vue 的 errorHandler、React 的 ErrorBoundary、路由切换的上下文（用户 id、页面路径、版本号、设备信息），否则堆栈还原了也无法定位场景。\n\n**2. Script error. 的原因**：跨域脚本未带 CORS 头时，浏览器出于安全把错误信息脱敏为 Script error.。解决方式是 script 标签加 crossorigin="anonymous"，并在 CDN 返回 Access-Control-Allow-Origin。\n\n**3. sourcemap 安全**：sourcemap 包含完整源码，等同泄露业务逻辑与潜在密钥。绝不能上传到公网静态目录，也不要在产物末尾保留 sourceMappingURL 注释；应在构建时生成 hidden-source-map，上传到私有存储，仅监控服务端可读，并在发布后按版本号关联。\n\n**4. 还原实现**：用 mozilla 的 source-map 库消费 .map 文件，按 version 建立映射缓存，对每帧调用 originalPositionFor 得到源文件与行列，再配合 sourcesContent 截取上下文代码。注意堆栈里的行列是 1-based、而映射 API 是 0-based，容易差一。最后做聚合去重：按错误指纹（消息 + 顶层业务帧）归并，避免同一错误刷爆告警。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 203 MINUTE), 1),
  (604, 4, '页面卸载时的数据上报与 sendBeacon', '请说明页面关闭时为什么普通上报容易丢数据，以及 sendBeacon、fetch keepalive、图片打点三者的差异与选型。\n\n```js\nwindow.addEventListener("pagehide", () => {\n  navigator.sendBeacon("/log", new Blob([JSON.stringify(payload)], { type: "application/json" }));\n});\n```\n\n请回答：为什么用 beforeunload 而不是 unload？sendBeacon 的返回值和大小限制是什么？keepalive 与 sendBeacon 的关系？SPA 里没有真正的卸载，上报时机怎么设计？', '**结论**：页面卸载时 XHR 会被浏览器中断，普通 fetch 也可能被取消；sendBeacon 把请求交给浏览器进程异步发送，不阻塞卸载，是埋点与日志的首选。\n\n**1. 三方案对比**：\n\n| 方案 | 是否阻塞卸载 | 限制 | 备注 |\n| --- | --- | --- | --- |\n| sendBeacon | 否 | 约 64KB，POST | 返回布尔，无响应可读 |\n| fetch keepalive | 否 | 总 keepalive 体积约 64KB | 可设请求头、可读状态 |\n| img src | 否 | URL 长度限制，仅 GET | 兼容性最好，无法带 body |\n\nsendBeacon 本质就是带 keepalive 的 POST，无法自定义请求头（Content-Type 由 Blob 决定），也拿不到响应，因此只适合单向日志，不适合需要重试确认的业务接口。\n\n**2. 时机选择**：unload 在部分浏览器（尤其移动端与 bfcache 场景）不可靠且会禁用往返缓存，pagehide 是更推荐的替代；visibilitychange 到 hidden 时也应触发一次，因为移动端切后台可能不再触发 pagehide。若页面进入 bfcache 后又恢复，需用 pageshow 的 persisted 标记撤回过早的"会话结束"。\n\n**3. SPA 的处理**：路由切换不卸载文档，应在路由守卫里上报页面停留时长；同时仍在 pagehide 时兜底上报未发送的队列。上报队列要设上限并做本地暂存，下次进入时补发，形成至少一次（at-least-once）语义，服务端按事件 id 幂等去重。\n\n**4. 可靠性设计**：合并批量发送（减少请求数）、失败落盘（localStorage 或 IndexedDB）、限制单条体积、采样与开关（支持远程降级），并在隐私合规上避免上报敏感字段。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 204 MINUTE), 1),
  (605, 4, '虚拟滚动实现超长列表的核心难点', '请设计一个支持 10 万条数据的虚拟滚动列表，说明可视区计算、缓冲区、动态行高三种情况的处理方式。\n\n```js\nconst start = Math.floor(scrollTop / itemHeight);\nconst visible = Math.ceil(viewportHeight / itemHeight) + buffer;\nconst slice = data.slice(start, start + visible);\n```\n\n请回答：为什么不能直接渲染 10 万个节点？固定行高的实现关键是什么？动态行高如何测量与缓存？快速滚动时出现白屏怎么解决？如何处理滚动位置恢复与键盘可访问性？', '**结论**：虚拟滚动只渲染视口内加少量缓冲区的节点，用绝对定位或 transform 把列表撑到总高度，从而把 DOM 数量从 O(n) 降到 O(视口)。\n\n**1. 不渲染全量的原因**：每个节点都是布局与绘制的成本，10 万节点会造成初始渲染数秒、内存暴涨、滚动时每帧重排，浏览器甚至直接卡死。虚拟化后常驻节点约 20 到 50 个，帧率可稳定在 60fps。\n\n**2. 固定行高**：关键是用 `scrollTop / itemHeight` 算出起始索引，容器高度设为 `total * itemHeight` 撑出滚动条，再用 `translateY(start * itemHeight)` 或绝对定位偏移内容。要点是不要用 top 做动画属性，用 transform 可走合成层；滚动监听要用 passive 并做 rAF 节流。\n\n**3. 动态行高**：常用两种策略——预估加测量校正（先用估算值占位，渲染后用 ResizeObserver 量出真实高度写入缓存并调整累计偏移），或用二分查找在偏移数组里定位起始索引；更简单的方案是要求列表项高度一致，或使用 content-visibility: auto 让浏览器跳过视口外渲染（适合中等规模）。\n\n**4. 白屏与体验**：快速滚动时渲染跟不上会出现空白，解决办法是增大缓冲区（overscan）、用骨架占位、或在滚动停止前只渲染占位块；滚动位置恢复需要在数据加载前就确定偏移，因此要缓存锚点项与偏移量。可访问性方面要给容器正确的 role 与 aria-rowcount，并支持键盘上下移动焦点，否则屏幕阅读器读到的是残缺列表。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 205 MINUTE), 1),
  (606, 4, '滚动卡顿的成因与合成层优化', '请解释滚动为什么通常由合成器线程驱动，以及在什么情况下滚动会退化为卡顿。\n\n```css\n.card { will-change: transform; transform: translateZ(0); }\n```\n\n请回答：will-change 滥用会带来什么问题？为什么说"提升为合成层"不等于"性能更好"？滚动监听里读 scrollTop 再改样式为什么危险？position: sticky 与 background-attachment: fixed 为什么会掉帧？', '**结论**：滚动本身由合成器线程处理，不依赖主线程；但一旦页面存在滚动联动效果（滚动监听改样式、sticky 计算、fixed 背景），主线程的卡顿就会直接反映为滚动掉帧。\n\n**1. 合成器线程的作用**：合成线程持有各图层的变换信息，滚动与 transform/opacity 动画可以在不询问主线程的情况下推进，即使主线程在跑长任务，页面仍能滚动（只是内容不更新）。这就是"滚动不卡但内容不动"的现象来源。\n\n**2. 合成层的代价**：每个图层都要占用显存并单独光栅化，层数过多会导致层爆炸、内存上升、合成开销变大，反而更慢。will-change 应当只在即将动画的元素上短时声明，动画结束移除；长期挂在大量元素上是典型误用。判断是否真正提升可用 DevTools 的 Layers 面板与 Rendering 的 Layer borders。\n\n**3. 滚动监听的陷阱**：滚动事件在主线程触发，若回调里读 scrollTop 再写样式，会形成读-写-读-写，触发强制同步布局；同时高频事件本身消耗主线程。正确做法是用 rAF 合并、只读一次、写操作批量提交，或改用 IntersectionObserver / CSS scroll-driven animations 把联动交给合成线程。\n\n**4. sticky 与 fixed 背景**：sticky 在滚动时需要重新计算位置，浏览器要把它提升为特殊图层并可能触发主线程重算，父容器 overflow 或 transform 会破坏其行为；background-attachment: fixed 在多数浏览器中会导致整段重绘而非合成，长页面滚动时明显掉帧，可用固定定位的伪元素替代。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 206 MINUTE), 1),
  (607, 4, '原型污染攻击的原理与防御', '请解释原型污染（prototype pollution）的成因，并说明为什么它在 Node 服务端比浏览器更危险。\n\n```js\nfunction merge(target, source) {\n  for (const k in source) {\n    if (typeof source[k] === "object") merge(target[k] = target[k] || {}, source[k]);\n    else target[k] = source[k];\n  }\n}\nmerge({}, JSON.parse(''{"__proto__":{"isAdmin":true}}''));\n```\n\n请回答：上面代码如何污染 Object.prototype？为什么 `for...in` 会放大风险？`Object.freeze(Object.prototype)` 是否可行？如何写出安全的深合并？', '**结论**：原型污染源于把用户可控的键名直接写进对象，当键为 `__proto__`、`constructor`、`prototype` 时会沿原型链赋值到 Object.prototype。\n\n**1. 攻击路径**：`merge` 递归时以 `source[k]` 为对象继续递归，k 为 `__proto__` 时 `target["__proto__"]` 取到的是 Object.prototype，于是把 isAdmin 写进了全局原型。此后任意 `{}` 都带 isAdmin，权限判断会被绕过。`for...in` 会遍历原型链上的可枚举属性。\n\n**2. 服务端更危险**：Node 所有模块共享同一 realm，可导致鉴权绕过、RCE、拒绝服务。\n\n**3. 防御手段**：一是拒绝危险键，用 hasOwnProperty 配合白名单，禁止 `__proto__`、constructor、prototype；二是用 `Object.create(null)` 创建无原型对象接收数据；三是用 `Object.defineProperty` 而不用赋值；四是改用结构化克隆；五是依赖库升级到已修复版本（lodash 曾多次修此类漏洞）。\n\n```js\nconst DANGEROUS = new Set(["__proto__", "constructor", "prototype"]);\nfunction safeMerge(target, source) {\n  for (const k of Object.keys(source)) {\n    if (DANGEROUS.has(k)) continue;\n    const v = source[k];\n    if (v && typeof v === "object") { target[k] = target[k] || {}; safeMerge(target[k], v); }\n    else target[k] = v;\n  }\n  return target;\n}\n```\n\n**4. 冻结原型的取舍**：`Object.freeze(Object.prototype)` 能阻断污染，但可能破坏依赖库改写原型的行为，也防不住 constructor.prototype 路径，只能作为纵深防御的一层。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 207 MINUTE), 1),
  (608, 4, 'Service Worker 生命周期与离线缓存策略', '请说明 Service Worker 的安装、等待、激活三个状态，以及 skipWaiting 与 clientsClaim 的作用与风险。\n\n```js\nself.addEventListener("fetch", (e) => {\n  e.respondWith(caches.match(e.request).then(r => r || fetch(e.request)));\n});\n```\n\n请回答：为什么新版本 SW 安装后不会立即接管页面？如何避免用户看到新旧资源混用？Cache First、Network First、Stale While Revalidate 各适合什么资源？缓存版本升级时如何清理旧缓存？', '**结论**：Service Worker 是独立于页面的后台脚本，生命周期为 install、waiting、activate 三段；默认在新 SW 激活前保留旧 SW 服务现有页面，以保证同一次会话内资源版本一致。\n\n**1. 生命周期细节**：install 阶段适合预缓存核心资源（失败则整个 SW 安装失败）；安装成功后进入 waiting，直到所有受控页面关闭才 activate；activate 阶段清理旧版本缓存并调用 clients.claim() 接管已打开的页面。`skipWaiting()` 让 waiting 的 SW 立即激活，`clientsClaim()` 让新 SW 立即控制现有客户端，二者常一起用，但风险是页面已加载的旧 HTML 与新资源不匹配，可能运行时报错。\n\n**2. 更新策略**：常见做法是提示用户"有新版本，点击刷新"，在用户确认后再 skipWaiting 并 reload，避免静默替换造成状态丢失。同时要处理 controllerchange 事件防止多次刷新。\n\n**3. 缓存策略选型**：\n\n| 策略 | 适合 | 代价 |\n| --- | --- | --- |\n| Cache First | 静态资源、字体、图片 | 更新滞后 |\n| Network First | 接口、HTML | 弱网首屏慢 |\n| Stale While Revalidate | 不常变的列表、头像 | 首次可能旧 |\n| Network Only | 支付、登录 | 无离线能力 |\n\n**4. 版本与清理**：给缓存名加版本号（如 `v2-static`），在 activate 里遍历 `caches.keys()` 删除非当前版本；不要把 index.html 长期缓存，否则用户永远拿不到新版本；最后一定要处理 scope 与 HTTPS 限制（localhost 例外），并注意 SW 无法访问 DOM，通信要用 postMessage。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 208 MINUTE), 1),
  (609, 4, 'SSE 与 WebSocket 的选型依据', '请对比 Server-Sent Events 与 WebSocket 在协议、方向、重连、代理兼容性上的差异，并说明 AI 流式对话、实时行情、协同编辑三个场景各自该选哪个。\n\n```js\nconst es = new EventSource("/stream");\nes.onmessage = (e) => append(e.data);\n```\n\n请回答：SSE 基于什么协议？为什么它能自动重连而我们常要自己做心跳？SSE 在 HTTP/1.1 下有什么并发限制？WebSocket 握手后如何携带鉴权信息？', '**结论**：SSE 是单向的服务器推送，基于普通 HTTP 长连接，天然支持断线重连与文本流；WebSocket 是全双工独立协议，适合高频双向交互，但需要自行管理重连、心跳与鉴权。\n\n**1. 对比**：\n\n| 维度 | SSE | WebSocket |\n| --- | --- | --- |\n| 方向 | 服务端到客户端单向 | 双向 |\n| 协议 | HTTP（text/event-stream） | ws/wss，握手后升级 |\n| 数据 | 仅文本（可 base64 传二进制） | 文本与二进制 |\n| 重连 | 浏览器自动，带 Last-Event-ID | 需自己实现 |\n| 代理/CDN | 兼容好 | 部分代理不支持升级 |\n\n**2. 场景选型**：AI 流式对话本质是"一问一答的增量输出"，用 fetch 的 ReadableStream 或 SSE 即可，无需全双工；实时行情若只是服务端高频推送，SSE 足够，若需要客户端高频下单则用 WebSocket；协同编辑需要双向低延迟与二进制（如 Yjs 的更新包），WebSocket 更合适，也可用 WebRTC 做 P2P。\n\n**3. SSE 的限制**：HTTP/1.1 下浏览器对同域并发连接数约 6 个，多个 SSE 会占满配额，因此应复用一条连接并通过事件类型区分业务，或升级到 HTTP/2（多路复用）；Nginx 需关闭 buffering 否则消息被攒着不发；还要设置较长的读超时。\n\n**4. WebSocket 鉴权**：浏览器 WebSocket API 不能自定义请求头，常见做法是握手时用 Cookie（受 SameSite 限制）、或用一次性 ticket 放在 URL query 中由服务端校验后立即失效，或先建立连接再发首帧 token 认证。心跳用 ping/pong 保活并检测半开连接，重连要指数退避并做消息补偿。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 209 MINUTE), 1),
  (610, 4, 'ref 与 reactive 的选择及响应式丢失场景', '请说明 Vue 3 中 ref 与 reactive 的底层差异，并解释下面变量为什么会丢失响应式。\n\n```js\nconst state = reactive({ a: 1, b: { c: 2 } });\nlet { a } = state;\nconst copy = { ...state };\n```\n\n请回答：为什么 reactive 只对对象有效？解构与展开为什么会断链？`ref` 在模板中为什么不需要 .value？把 ref 放进 reactive 对象里会自动解包吗？数组与 Map 场景该如何选？', '**结论**：ref 用 RefImpl 包装任意类型并通过 get value / set value 拦截，reactive 用 Proxy 代理对象本身；reactive 的响应式依附于属性访问，一旦复制或解构出原始值，代理链就断了。\n\n**1. 底层差异**：reactive 返回 Proxy，深层对象懒代理（访问时才创建子代理），因此对 Map/Set 需要特殊处理；ref 用一个带 value 的访问器对象，内部若 value 是对象则再调 reactive，所以 `ref({})` 实际是浅层包装加深层代理。\n\n**2. 丢失场景**：`let { a } = state` 把 a 的当前值复制给局部变量，之后与代理无关；`{ ...state }` 同理。修复方式：保持 `state.a` 访问、用 `toRefs(state)` 得到一组 ref、或用 `const a = computed(() => state.a)`。函数传参时把整个 reactive 对象传进去而不是传字段，也能规避。\n\n**3. 模板与解包规则**：模板中 ref 会自动解包，所以写 `{{ count }}`；在 setup 返回对象与 reactive 对象内部，ref 也会自动解包（数组与 Map 中不会）。这与"ref 需要 .value"并不矛盾——后者只针对 JS 代码中的直接访问。把 ref 赋给另一个变量会丢失响应性，因为它复制的是同一个 ref 引用吗？不是，ref 本身仍是响应式的，丢失的是"值"的追踪。\n\n**4. 选型建议**：单一原始值用 ref；成组状态用 reactive；需要整体替换对象时用 ref（`state.value = newObj` 才有效，reactive 直接赋值会断开代理）；需要解构给模板用 toRefs；大型只读数据用 shallowRef 减少代理开销。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 210 MINUTE), 1),
  (611, 4, 'Vue 3 编译优化：静态提升、patchFlag 与 Block Tree', '请说明 Vue 3 模板编译阶段做了哪些优化，并解释为什么它比 Vue 2 的运行时 diff 更快。\n\n```html\n<div>\n  <p class="static">hello</p>\n  <span>{{ msg }}</span>\n</div>\n```\n\n请回答：静态提升（hoistStatic）具体提升了什么？patchFlag 记录了哪些信息？Block Tree 如何把动态节点的收集从递归变成线性？`v-if` 与 `v-for` 为什么会产生独立的 block？这对 diff 的复杂度意味着什么？', '**结论**：Vue 3 把"运行时全量递归 diff"改为"编译期标记 + 运行期只比对动态节点"，核心手段是静态提升、patchFlag、Block Tree 与缓存事件处理函数。\n\n**1. 静态提升**：编译时把不依赖响应式数据的 VNode 与静态属性提取到 render 函数外，只创建一次并复用，避免每次更新都重新生成对象。连续静态节点还会被合并为一个静态 VNode（static 提升），进一步减少创建与比对开销。\n\n**2. patchFlag**：编译期给每个动态节点打上位标记，标明它到底哪部分会变——文本（1）、class（2）、style（4）、props（8）、完整 props（16）等。运行时 diff 看到标记就只比对对应部分，甚至动态文本可以直接走 `el.textContent = x` 的快路径，不必走完整 patchProps。\n\n**3. Block Tree**：带有 v-if、v-for 或插槽的节点会成为 block，其内部的动态后代在创建时被收集进该 block 的 dynamicChildren 数组。更新时只遍历这个扁平数组，跳过了大量静态子树，于是复杂度从"整棵树"降到"动态节点数"，与模板总规模基本无关。\n\n**4. 关于上面模板**：p 是纯静态，被提升；span 的文本被打上 TEXT 标记并进入父 block 的 dynamicChildren，更新时只处理它一个节点。`v-if` 与 `v-for` 会产生带 key 的 Fragment block，保证列表增删时能正确对齐，但也意味着编译器无法静态确定结构，仍需完整 diff 这一层。\n\n**5. 边界**：手写 render 函数或使用 JSX 时没有模板编译器，优化失效；动态绑定过多会让 block 失去意义；这也是官方建议优先用模板而非 h 函数的原因之一。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 211 MINUTE), 1),
  (612, 4, 'defineModel 与自定义组件 v-model 的实现', '请说明 Vue 3 中 `v-model` 在组件上的展开规则，并用 defineModel 与 props/emit 两种方式实现一个受控输入组件。\n\n```html\n<MyInput v-model="text" v-model:title.trim="title" />\n```\n\n请回答：上面写法编译成什么 props 与事件？为什么子组件不能直接修改 props？defineModel 的 local 模式与修饰符如何处理？多个 v-model 的参数如何区分？', '**结论**：组件上的 v-model 是 `:modelValue` 加 `@update:modelValue` 的语法糖，带参数时变成 `:title` 加 `@update:title`，修饰符通过 `modelModifiers` 或 `xxxModifiers` prop 传入。\n\n**1. 展开规则**：`v-model="text"` 等价于 `:modelValue="text" @update:modelValue="text = $event"`；`v-model:title.trim="title"` 等价于 `:title="title" :titleModifiers="{ trim: true }" @update:title="..."`。多个 v-model 就是多组 prop 与事件的组合，互不干扰。\n\n**2. props/emit 写法**：\n\n```js\nconst props = defineProps({ modelValue: String });\nconst emit = defineEmits(["update:modelValue"]);\nconst onInput = (e) => emit("update:modelValue", e.target.value);\n```\n\n子组件不能改 props，因为单向数据流保证父级是唯一数据源，直接改会让父组件状态与视图不一致且难以追踪；正确做法是 emit 让父级更新。\n\n**3. defineModel 写法**：`const model = defineModel({ type: String })` 返回一个 ref，读 model.value 取父值，赋值 `model.value = x` 会自动 emit update。需要本地缓冲时用 `defineModel({ local: true })`；修饰符可用 `defineModel({ set(v) { return v.trim(); } })` 或读取 `modelModifiers` 实现。\n\n**4. 设计建议**：受控组件要区分"用户输入"与"父级回传"，避免输入光标跳动；表单组件同时支持 v-model 与 change 事件；不要在子组件内缓存父值又不同步，否则双源真相。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 212 MINUTE), 1),
  (613, 4, 'provide/inject 的依赖注入与响应式传递', '请说明 provide/inject 相比 props 逐层传递的优势与代价，并解释为什么直接 provide 一个 reactive 对象在祖先更新后子孙仍能拿到新值，而 provide 一个普通值不行。\n\n```js\nprovide("cfg", readonly(config));\ninject("cfg", defaultCfg);\n```\n\n请回答：inject 的第二个参数有什么用？为什么推荐 provide readonly 或 ref？Symbol 作为 key 有什么好处？它能否替代 Pinia？子孙组件如何反向修改祖先状态？', '**结论**：provide/inject 建立了一条跨层级的依赖通道，避免了 props 逐层透传；但注入的值本身是否响应式取决于你提供的是什么——提供 reactive/ref 时，读取发生在子组件渲染期间，依赖会被子组件的副作用收集，因此能更新；提供普通值则是一次性快照。\n\n**1. 机制**：provide 把值写入当前组件实例的 provides 对象，inject 沿父链查找（原型链式继承），因此就近覆盖生效。注入不是响应式系统的一部分，它只是"把引用传下去"。\n\n**2. 关键细节**：`inject` 的默认值在未提供时使用，且默认值可以是工厂函数以避免共享引用；key 用 Symbol 可避免命名冲突并便于 TS 类型推断；提供方应在 setup 同步阶段调用 provide，异步后提供对已挂载的子树无效。\n\n**3. 响应式与只读**：provide 一个 reactive 对象时，子组件访问其属性会建立依赖；但如果子组件把整个对象解构或存到本地变量，仍会丢失。用 `readonly()` 包裹可防止子组件直接改祖先状态，同时不破坏读取追踪；要修改则通过 provide 一个方法（如 `updateUser`）或提供 ref 让子组件写 value。\n\n**4. 与 Pinia 的边界**：inject 适合组件树内的局部共享（表单上下文、主题、i18n、表格的行配置），生命周期随组件树，天然支持多实例隔离；Pinia 是全局单例 store，适合跨路由共享的业务状态，有 devtools、插件与 SSR 友好。二者不冲突，常见做法是库内部用 inject 暴露 API（如 Element Plus 的 form context）。\n\n**5. 代价**：依赖关系隐式化，阅读组件时看不出数据来源；重构时容易漏改。应在文档中标注注入契约，并为 key 提供类型定义。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 213 MINUTE), 1),
  (614, 4, 'Vue 3 生命周期在 SSR 与 KeepAlive 下的差异', '请说明 Vue 3 组合式 API 中 onMounted、onActivated、onServerPrefetch 的执行时机，并解释为什么 SSR 场景下不能在 setup 顶层访问 window。\n\n```js\nonMounted(() => initChart());\nonUnmounted(() => disposeChart());\n```\n\n请回答：服务端渲染时会执行哪些钩子？onMounted 在 SSR 中会执行吗？KeepAlive 缓存组件时 mounted 与 activated 的触发顺序是什么？同一组件被缓存后再次进入，哪些钩子不会再执行？SSR 中如何预取数据？', '**结论**：服务端只执行 beforeCreate 与 created（组合式 API 中即 setup 本身），mounted 及之后的所有钩子都依赖 DOM，在 SSR 中不会执行；因此任何访问 window、document、localStorage 的逻辑都必须放到 onMounted 内或做环境判断。\n\n**1. 钩子时序（客户端）**：setup → beforeMount → onMounted（子先于父）→ onActivated（若在 KeepAlive 内）→ 更新时 onBeforeUpdate → onUpdated → onDeactivated / onBeforeUnmount → onUnmounted。父组件的 mounted 在子组件之后触发，这解释了为什么父 mounted 里能拿到子组件暴露的 DOM。\n\n**2. SSR 相关**：`onServerPrefetch` 只在服务端执行，用于在渲染前 await 数据；服务端没有 DOM，`onMounted`、`onUpdated`、`onUnmounted` 全部跳过。所以图表、地图、编辑器这类依赖 DOM 的库只能在 onMounted 里初始化，并且要在 onUnmounted 里销毁以防泄漏。\n\n**3. 常见报错**：`window is not defined`、`document is not defined`，以及第三方库在模块顶层读 navigator。解决方式是用 `<ClientOnly>` 包裹、动态 import 并在 onMounted 中加载、或用 `typeof window !== "undefined"` 守卫；注意守卫只能避免报错，不能解决 hydration 内容不一致。\n\n**4. KeepAlive 的钩子**：首次进入执行 mounted 再 activated；切走执行 deactivated（不执行 unmounted，DOM 保留）；再次进入只执行 activated，mounted 不再触发。因此缓存组件要把"每次进入都要刷新"的逻辑放 activated，把一次性初始化放 mounted，定时器与监听在 deactivated 里暂停、activated 里恢复。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 214 MINUTE), 1),
  (615, 4, '组合式函数（composable）的设计与复用边界', '请设计一个 useRequest 组合式函数，要求支持立即执行、手动触发、取消、轮询与错误重试，并说明它与 mixin、工具函数的区别。\n\n```js\nconst { data, loading, error, run, cancel } = useRequest(fetcher, { immediate: true });\n```\n\n请回答：composable 内部如何安全地管理副作用清理？为什么它必须在 setup 同步阶段调用？如何避免多个组件共享同一个 composable 状态？它相比 mixin 解决了哪些问题？', '**结论**：composable 是利用组合式 API 把"带状态与副作用的逻辑"封装成可复用函数，返回响应式状态与方法；它在 setup 中调用以获得当前组件实例，从而能注册清理，每个调用产生独立状态。\n\n**1. 设计要点**：内部用 ref 保存 data/loading/error，用 AbortController 管理取消；immediate 为 true 时在 setup 内触发首次请求；轮询用递归 setTimeout 避免堆积；所有定时器、监听、控制器都在 onScopeDispose 里清理。\n\n```js\nexport function useRequest(fetcher, opts = {}) {\n  const data = ref(null), loading = ref(false), error = ref(null);\n  let ctrl = null;\n  async function run(...args) {\n    ctrl?.abort(); ctrl = new AbortController();\n    loading.value = true;\n    try { data.value = await fetcher(...args, ctrl.signal); }\n    catch (e) { if (e.name !== "AbortError") error.value = e; }\n    finally { loading.value = false; }\n  }\n  if (opts.immediate) run();\n  onScopeDispose(() => ctrl?.abort());\n  return { data, loading, error, run };\n}\n```\n\n**2. 必须同步调用**：这类钩子依赖 currentInstance，只有 setup 同步执行期间才有值；await 之后调用会丢失实例，清理不生效，需要异步创建时改用 effectScope。\n\n**3. 状态隔离**：默认每次调用生成新 ref，天然隔离；若要全局共享，应把状态放在模块顶层（模块级单例）并在文档中说明。\n\n**4. 与 mixin 的差异**：mixin 来源不透明、多个 mixin 易冲突、与选项式结构强绑定；composable 显式导入与返回、类型友好、可参数化。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 215 MINUTE), 1),
  (616, 4, 'Vue 3 渲染性能优化：shallowRef、markRaw 与 v-memo', '请说明在什么场景下应使用 shallowRef、shallowReactive、markRaw 与 v-memo，并各举一个能实际降低开销的例子。\n\n```js\nconst chart = shallowRef(null);\nconst raw = markRaw(new HeavyLib());\n```\n\n请回答：shallowRef 与 ref 在更新触发上的差异是什么？为什么把第三方实例放进 reactive 会出问题？v-memo 的依赖数组如何影响正确性？`v-once` 与 v-memo 的区别？过度使用这些 API 会带来什么维护风险？', '**结论**：这四个 API 都是"缩小响应式范围"的手段：shallowRef 只追踪 .value 整体替换，markRaw 让对象永不被代理，v-memo 让子树在依赖未变时跳过更新，v-once 则彻底静态化。\n\n**1. shallowRef**：ref 会对对象做深层 reactive 代理，而 shallowRef 只把 value 当作普通值，只有整体赋值才触发更新。适合大数组、图表实例、编辑器实例、只读配置——这些对象深层属性变化频繁但不需要驱动视图。典型收益是把一次 5000 条数据的深层代理开销降为 0，同时避免代理破坏第三方库的内部判断（如 `instanceof`、私有字段访问）。\n\n**2. markRaw 与代理的冲突**：Proxy 包裹后对象身份改变，第三方库用 WeakMap 缓存、用 === 比较、或访问内部槽时会出错；给对象打上 markRaw 后 reactive 会跳过它。适用于地图、图表、WebGL、富文本实例。与 shallowRef 配合最常见。\n\n**3. v-memo**：`v-memo="[a, b]"` 表示仅当数组内任一依赖变化时才重新渲染该子树，常用于超大 v-for 列表的行级缓存。风险是依赖必须完整——漏掉依赖会导致视图不更新，且编译器无法校验，因此只建议在实测有性能收益的热点使用。注意 v-memo 在 v-for 上要写在同一个元素上。\n\n**4. v-once 与边界**：v-once 只渲染一次，之后永不更新，适合纯静态区块（如页脚、条款文本）；v-memo 依赖变化仍会更新。这两者都属于"用正确性换性能"，在组件里滥用会让后来者难以判断数据为何不刷新，务必加注释说明。优先考虑用 computed 缓存计算、拆分组件缩小更新范围、用 key 控制复用，再考虑这些底层开关。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 216 MINUTE), 1),
  (617, 4, 'Vue Router 导航守卫与前端权限控制', '请说明 Vue Router 的全局守卫、路由独享守卫、组件内守卫的执行顺序，并设计一套基于角色的动态路由方案。\n\n```js\nrouter.beforeEach(async (to) => {\n  if (!store.token && to.meta.auth) return { name: "login", query: { redirect: to.fullPath } };\n});\n```\n\n请回答：返回 false、返回路由对象、返回 undefined 分别意味着什么？异步守卫里如何避免死循环重定向？动态 addRoute 后为什么要 next(to.fullPath) 或重新导航？按钮级权限如何实现？前端权限能替代后端校验吗？', '**结论**：执行顺序为 全局 beforeEach → 路由独享 beforeEnter → 组件内 beforeRouteEnter → 全局 beforeResolve → 导航确认 → 全局 afterEach；组件内的 beforeRouteLeave 在离开旧组件时最先触发。\n\n**1. 返回值语义**：返回 false 取消导航并留在原地（URL 可能已变，需处理）；返回路由对象或 `{ path }` 表示重定向到新目标，会重新走一遍完整守卫链；返回 undefined 或 true 表示放行。Vue Router 4 支持 async 守卫直接 return，比 next 回调更不易出错。\n\n**2. 死循环防护**：重定向到 login 时必须判断当前目标不是 login，否则无限循环；用 meta 标记 `public: true` 白名单；在守卫里捕获异常并跳错误页；对 401 与 403 分别处理（未登录 vs 无权限），不要都跳登录页。\n\n**3. 动态路由**：登录后按角色过滤路由表并 `router.addRoute`，随后必须 `return to.fullPath` 触发一次重新匹配，否则首次导航会命中 404 通配；退出登录时用返回的函数移除路由并重置状态。还要处理刷新丢失（把路由表存在 store 并在 beforeEach 中重建）以及多级嵌套路由的父子关系。\n\n**4. 按钮级权限**：用自定义指令 `v-permission="[''admin'']"` 在 mounted 时移除无权限节点，或用函数式判断控制渲染；更稳妥的是由后端下发权限码，前端只做展示层控制。关键结论：前端权限只是体验优化，所有接口必须在后端校验，前端隐藏按钮不构成任何安全保证。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 217 MINUTE), 1),
  (618, 4, 'webpack 构建流程与 loader、plugin 的区别', '请描述 webpack 从读取配置到输出产物的一次完整构建流程，并说明 loader 与 plugin 在其中的作用位置。\n\n```js\nmodule.exports = {\n  module: { rules: [{ test: /[.]css$/, use: ["style-loader", "css-loader"] }] },\n  plugins: [new HtmlWebpackPlugin()]\n};\n```\n\n请回答：loader 为什么从右往左执行？loader 与 plugin 各能解决什么问题？Hooks 的 tapable 是什么？为什么说 webpack 慢、Vite 快？如何用 SplitChunks 做合理的缓存分组？', '**结论**：webpack 的构建流程是 初始化参数 → 创建 Compiler → 加载 plugin 并注册 hooks → 从 entry 开始递归构建依赖图（resolve、load 与 loader 转换、parse、收集依赖）→ 生成 chunk → 通过 template 输出文件 → 触发 done；loader 作用于单个模块的源码转换，plugin 借助 hooks 介入整个构建生命周期。\n\n**1. loader 的方向**：`use` 数组从右到左、从下到上执行，因为它是函数式组合——先由 css-loader 把 CSS 转成模块，再由 style-loader 把结果注入为 script。pipe 的语义决定了顺序，写反了会直接报错。loader 应保持单一职责、可链式、无副作用。\n\n**2. plugin 的能力**：通过 tapable 的 Sync/Async Hook 在特定时机介入，如 emit、afterEmit、optimizeChunks，能做资源生成、产物压缩、环境变量注入、按需拷贝。HtmlWebpackPlugin 就是在 emit 阶段改写产物列表。tapable 是 webpack 自己实现的发布订阅库，支持同步/异步、串行/并行多种钩子类型。\n\n**3. webpack 慢的原因**：入口前要先把整个依赖图构建完才能给出可用产物，开发时即使只改一个文件也要维护完整模块图；Vite 则利用浏览器原生 ESM，开发时按需编译单个模块，冷启动只做依赖预构建，因此启动快。生产构建 Vite 用 Rollup，两者在产物优化上思路接近。\n\n**4. 缓存分组**：用 SplitChunks 把 node_modules 与业务代码分开、把长期不变的库（如 vue、lodash）打为 vendor chunk，配合 contenthash 命名，使业务改动不影响第三方包的缓存命中率；同时控制 chunk 数量避免请求过多，并给路由级异步 chunk 设置合理的 maxSize。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 218 MINUTE), 1),
  (619, 4, 'pnpm 的硬链接机制与幽灵依赖治理', '请说明 pnpm 如何通过内容寻址存储与硬链接节省磁盘，并解释为什么它能避免幽灵依赖（phantom dependency）。\n\n```bash\npnpm add lodash\nls node_modules/.pnpm\n```\n\n请回答：npm 的扁平化提升为什么会产生幽灵依赖？pnpm 的 node_modules 结构长什么样？为什么 pnpm 下某些库会找不到依赖而报错？硬链接与软链接分别用在哪一层？monorepo 中 workspace 协议起什么作用？', '**结论**：pnpm 把所有包按内容哈希存到全局 store，再通过硬链接放进虚拟存储 `node_modules/.pnpm`，项目里只创建指向具体版本的软链接，因此同一版本在磁盘上只存一份；同时依赖树保持严格嵌套，只有声明过的依赖才能被解析。\n\n**1. 幽灵依赖的成因**：npm 与 yarn 1 为了减少重复会把依赖提升到顶层 node_modules，导致未在 package.json 声明的包也能被 import。一旦某个间接依赖升级或移除，代码就突然报错，这类隐患在发布或换包管理器时集中爆发。\n\n**2. pnpm 的结构**：`node_modules/<pkg>` 是指向 `.pnpm/<pkg>@<version>/node_modules/<pkg>` 的软链接，该目录内再以硬链接指向全局 store 的文件。硬链接保证不同项目共享同一份物理文件，软链接保证模块解析路径正确。因为顶层只有直接依赖，间接依赖不能被随意 import，幽灵依赖被消除。\n\n**3. 报错与修复**：库自身漏声明依赖时，pnpm 会如实报 Cannot find module，这其实是暴露了上游问题；可用 `public-hoist-pattern` 或 `shamefully-hoist` 临时放宽，但应作为兜底而非默认。另外 `node-linker=hoisted` 可用于兼容不支持符号链接的环境（如某些 Docker 卷或 Windows 旧版本）。\n\n**4. monorepo 与 workspace**：`pnpm-workspace.yaml` 声明包目录，包之间用 `workspace:*` 协议互相引用，发布时被替换为真实版本号，本地开发则直接软链源码，改完即生效；配合 `--filter` 可以只对受影响的包执行构建与测试。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 219 MINUTE), 1),
  (620, 4, '大文件分片上传、断点续传与秒传', '请设计一个支持 2GB 视频上传的方案，涵盖分片、并发控制、断点续传、秒传与完整性校验。\n\n```js\nconst size = 5 * 1024 * 1024;\nconst chunks = Math.ceil(file.size / size);\nconst hash = await computeHash(file); // 抽样或全量\n```\n\n请回答：分片大小如何选择？如何计算文件指纹而不阻塞主线程？上传中断后如何续传？秒传的原理与风险是什么？合并阶段为什么容易出错，怎样保证一致性？', '**结论**：整体思路是前端切片并计算文件指纹，服务端按指纹查重实现秒传，按已上传分片列表实现续传，客户端控制并发与重试，最后由服务端按序号合并并校验整体哈希。\n\n**1. 分片策略**：常见 2MB 到 10MB。太小会导致请求数暴增、连接开销大于传输收益；太大则单请求失败重传成本高、并发粒度粗。可按文件大小动态调整（小文件单片，大文件 8MB），并让服务端在初始化接口返回建议分片大小。\n\n**2. 指纹计算**：全量 MD5 在大文件上要读几百 MB 并阻塞主线程，通常用抽样哈希（头部、中部、尾部各取若干字节加文件大小与修改时间）或分片增量哈希；计算放进 Web Worker，用 FileReader 或 file.stream() 读取避免一次性载入内存。注意哈希要在 Worker 里用支持流式的实现，否则同样卡顿。\n\n**3. 续传与并发**：初始化时把指纹发给服务端，返回已存在的分片索引，前端只补传缺失部分；并发数控制在 3 到 6，避免占满带宽导致页面卡顿；每个分片失败按指数退避重试并记录，全部完成后调用合并接口，前端轮询或等待合并结果。\n\n**4. 秒传与一致性**：秒传靠服务端已有的同指纹文件直接建立引用，节省带宽与时间；风险是不同内容可能碰撞（概率极低但存在）、以及被用于探测服务端是否存有某文件，因此要结合用户权限校验。合并阶段要在服务端事务中完成，校验分片数量与每片哈希，全部一致才落盘，否则清理临时文件并返回可重试错误；最后返回文件 id 与访问 URL。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 220 MINUTE), 1),
  (621, 4, '微前端方案选型与 Module Federation 的落地难点', '请对比 iframe、qiankun 类框架、Module Federation 三种微前端方案，并说明样式隔离与 JS 沙箱的实现原理。\n\n```js\nnew ModuleFederationPlugin({\n  name: "host",\n  remotes: { shop: "shop@https://cdn.example.com/remoteEntry.js" },\n  shared: { vue: { singleton: true } }\n});\n```\n\n请回答：qiankun 的 Proxy 沙箱如何隔离 window？样式隔离有哪几种手段，各自缺陷是什么？共享依赖的 singleton 为什么重要？子应用与主应用的路由如何协调？微前端最大的长期成本是什么？', '**结论**：iframe 隔离最彻底但体验与通信差；qiankun 类方案用 JS 沙箱加样式隔离换取接近单页的体验；Module Federation 在构建期共享模块、运行期加载远程模块，是"模块级"而非"应用级"的集成，适合技术栈统一的团队。\n\n**1. 三者对比**：\n\n| 方案 | 隔离性 | 体验 | 改造成本 |\n| --- | --- | --- | --- |\n| iframe | 完全隔离 | 弹窗、路由、历史记录割裂 | 低 |\n| qiankun | JS 沙箱 + 样式隔离 | 接近单页 | 中，需暴露生命周期 |\n| Module Federation | 共享运行时，隔离弱 | 好 | 高，需统一构建体系 |\n\n**2. 沙箱与样式**：Proxy 沙箱在子应用执行时把 window 替换为代理对象，记录所有读写，卸载时还原快照；快照沙箱则在挂载时复制 window 并在卸载时回滚，只能支持单实例。样式隔离常用 Shadow DOM（隔离彻底但弹窗挂载、全局主题穿透困难）、scoped 前缀改写（运行时给选择器加前缀）、或 CSS Module 构建期隔离；qiankun 的 experimentalStyleIsolation 属于前缀方案，仍可能影响 body 级样式。\n\n**3. 共享依赖**：`singleton: true` 保证 host 与 remote 使用同一份 Vue 实例，否则响应式系统、provide/inject、全局配置会出现两套，导致组件无法识别、事件总线失效。同时要约定 shared 的版本范围与 eager 加载策略，避免循环依赖与首屏阻塞。\n\n**4. 路由与成本**：主应用用 base 与 activeRule 分配前缀，子应用接管自己的子路由，跳转优先用主应用路由以避免历史栈错乱。长期成本主要在版本兼容（子应用独立发布导致 API 漂移）、调试链路变长、样式与全局状态的隐性耦合，因此应先评估是否真的需要微前端，很多时候拆包加路由懒加载就足够。', 3, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 221 MINUTE), 1),
  (622, 4, '移动端适配方案与 1px 边框问题', '请说明 rem、vw、vw 加 rem 混合三种移动端适配方案的原理与取舍，并解释 1px 边框在各方案下为什么会变粗。\n\n```css\nhtml { font-size: calc(100vw / 3.75); }\n.box { width: 1rem; }\n```\n\n请回答：设备像素比 DPR 与物理像素的关系？viewport 的 initial-scale 如何影响布局宽度？为什么现在更推荐 vw 而不用 JS 动态设 font-size？0.5px 边框在什么情况下失效？安全区（刘海屏）与横屏如何适配？', '**结论**：rem 以根元素字号为基准，配合 JS 按视口宽度动态设置 font-size 实现等比缩放；vw 直接按视口宽度百分比布局，无需 JS；混合方案用 vw 计算根字号，兼顾设计稿换算与无 JS 场景。\n\n**1. DPR 与 1px**：CSS 像素与物理像素的比值即 DPR（常见 2 或 3）。写 1px 时浏览器映射到 DPR 个物理像素，视觉上比设计稿的细线粗。解决办法有：`transform: scaleY(0.5)` 伪元素方案（兼容好但需处理定位）、`border-image` 渐变、`box-shadow` 模拟、以及媒体查询 `min-resolution` 下用 0.5px（仅部分设备与浏览器支持，iOS 上曾被舍入为 1px）。\n\n**2. 各方案取舍**：\n\n| 方案 | 原理 | 问题 |\n| --- | --- | --- |\n| rem + JS | 动态设 html font-size | 首屏抖动、需内联脚本 |\n| 纯 vw | 1vw = 视口宽度 1% | 极端宽屏字号过大，需 clamp |\n| vw + rem | 根字号由 vw 计算 | 兼顾换算与性能，推荐 |\n\n**3. viewport 的作用**：`width=device-width` 让布局视口等于设备宽度，`initial-scale=1` 保证缩放为 1，否则移动端默认 980px 布局视口会导致元素被缩小。若不写 meta，rem 与 vw 的计算基准都会失真。\n\n**4. 边界**：安全区用 `env(safe-area-inset-bottom)` 配合 `viewport-fit=cover`；横屏可用媒体查询单独布局；字体不宜完全随 vw 缩放，应用 clamp 限制上下限保证可读性；触控目标至少 44px，`user-scalable=no` 会损害无障碍，应谨慎。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 222 MINUTE), 1),
  (623, 4, 'CSR、SSR、SSG 与 ISR 的选型与代价', '请对比 CSR、SSR、SSG、ISR 四种渲染模式的首屏性能、SEO、服务端成本与一致性风险，并为后台管理系统、营销落地页、电商商品详情页分别给出选型。\n\n```js\n// SSR 与 CSR 的 hydration 分界\nexport default defineComponent({ setup() { return { data } } });\n```\n\n请回答：SSR 为什么能改善首屏但可能拖慢 TTFB？hydration 不匹配（mismatch）的典型原因有哪些？流式 SSR 解决了什么？SSG 在内容频繁更新时如何处理？', '**结论**：CSR 首屏依赖 JS 下载与执行，SEO 弱但服务端成本最低；SSR 服务端直出 HTML，首屏与 SEO 好但需服务端算力且 TTFB 受影响；SSG 构建期生成静态页，最快最省但内容更新需重新构建；ISR 折中，静态页按需或定时再生成。\n\n**1. 四种模式**：\n\n| 模式 | 首屏 | SEO | 成本 | 数据实时性 |\n| --- | --- | --- | --- | --- |\n| CSR | 慢（等 JS） | 差 | 低 | 高 |\n| SSR | 快（HTML 直出） | 好 | 高（每次请求渲染） | 高 |\n| SSG | 最快（CDN） | 好 | 最低 | 低 |\n| ISR | 快 | 好 | 低 | 中（后台再生成） |\n\n**2. 选型**：后台管理系统不需要 SEO、登录后才可见，用 CSR 最省；营销落地页内容稳定、追求极致首屏与 SEO，用 SSG 加 CDN；商品详情页数量巨大又要求价格库存实时，可用 SSR 加缓存，或 ISR 配合按需 revalidate。\n\n**3. SSR 的代价与风险**：服务端要执行组件代码，任何依赖 window 的逻辑都会报错；每个请求都要渲染，QPS 高时 CPU 成为瓶颈，需加缓存或降级为 CSR 兜底；TTFB 包含服务端数据请求时间，需要通过并行取数、流式渲染（先吐 head 与骨架，再逐块 flush）改善。hydration mismatch 常见于服务端与客户端数据不一致、随机数或时间戳、`typeof window` 分支渲染不同结构、浏览器插件改写 DOM。\n\n**4. 落地建议**：按路由混用模式（Next 与 Nuxt 都支持），静态页走 CDN、个性化区块用客户端渲染；监控要同时看 TTFB、FCP 与 hydration 耗时；SSG 内容频繁更新时用增量构建或 webhook 触发重建，避免全量构建时间线性增长。', 2, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 223 MINUTE), 1),
  (624, 4, 'Vitest 单元测试的组织与覆盖率取舍', '请说明如何为一个包含异步请求与定时器的工具函数编写单元测试，并解释 mock 的边界应该划在哪里。\n\n```js\nimport { vi, describe, it, expect, beforeEach } from "vitest";\nvi.useFakeTimers();\n```\n\n请回答：vi.mock 与 vi.spyOn 的区别？为什么 fake timers 要配合 advanceTimersByTime？覆盖率 100% 有什么问题？如何测试一个依赖 Date.now 的函数？快照测试适合什么场景、不适合什么场景？', '**结论**：单元测试应围绕行为而非实现，mock 只切断"外部不可控依赖"（网络、时间、随机数、浏览器 API），业务逻辑本身要被真实执行；覆盖率是发现盲区的工具，不是目标。\n\n**1. mock 的层次**：`vi.mock` 在模块级别替换整个导入，适合第三方 SDK；`vi.spyOn` 保留原实现只包裹单个方法并可断言调用参数，适合局部打桩后恢复。优先用依赖注入把不可控依赖作为参数传入，这样大多数测试不需要 mock 框架。\n\n**2. 异步与定时器**：`vi.useFakeTimers()` 接管 setTimeout/setInterval/Date，测试中必须显式 `vi.advanceTimersByTime(1000)` 或 `await vi.runAllTimersAsync()` 推进虚拟时间，否则回调永远不会执行；异步请求用 `vi.stubGlobal("fetch", vi.fn().mockResolvedValue(...))` 或 msw 拦截网络层，后者更接近真实。记得在 afterEach 中 `vi.useRealTimers()` 与 `vi.restoreAllMocks()`，避免用例间污染。\n\n**3. 覆盖率与快照**：行覆盖 100% 不代表逻辑正确，分支与边界（空数组、异常分支、并发）才是 bug 高发区，应关注分支覆盖并显式补边界用例；对 Date.now 这类依赖，用 `vi.setSystemTime` 固定时间，或把时钟作为参数注入。快照测试适合稳定的序列化输出（组件结构、配置对象），不适合频繁变动的 UI 与含随机值的数据，否则会变成无脑更新快照，失去发现回归的意义。\n\n**4. 工程实践**：测试文件与被测代码同目录便于维护；用 `test.each` 覆盖参数组合；CI 中对新增代码设覆盖率门槛而非全量阈值；把测试当作设计反馈——如果一个函数难以测试，通常是耦合过重，应拆分职责。', 1, 1, '扩展题库', 0, 0, DATE_ADD(NOW(3), INTERVAL 224 MINUTE), 1);

